// CSS tokenizer following CSS Syntax Level 3.

#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IDHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number { has_sign: bool, value: f32, int_value: Option<i32> },
    Percentage { has_sign: bool, unit_value: f32, int_value: Option<i32> },
    Dimension { has_sign: bool, value: f32, int_value: Option<i32>, unit: String },
    WhiteSpace(String),
    Comment(String),
    Colon,
    Semicolon,
    Comma,
    IncludeMatch,
    DashMatch,
    PrefixMatch,
    SuffixMatch,
    SubstringMatch,
    CDO,
    CDC,
    Function(String),
    ParenthesisBlock,
    SquareBracketBlock,
    CurlyBracketBlock,
    BadUrl(String),
    BadString(String),
    CloseParenthesis,
    CloseSquareBracket,
    CloseCurlyBracket,
}

impl Token {
    pub fn is_block_open(&self) -> bool {
        matches!(self, Token::Function(_) | Token::ParenthesisBlock | Token::SquareBracketBlock | Token::CurlyBracketBlock)
    }
    pub fn is_ws(&self) -> bool {
        matches!(self, Token::WhiteSpace(_))
    }
}

#[derive(Clone, Debug)]
pub struct Tok {
    pub token: Token,
    pub line: u32,
    pub col: u32,
    pub start: usize,
    pub end: usize,
    /// For block-opening tokens: index of matching close token (or tokens.len() if unclosed)
    pub close: usize,
}

pub struct Tokenizer<'a> {
    s: &'a [u8],
    src: &'a str,
    pos: usize,
    line: u32,
    line_start: usize,
}

fn is_name_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_' || c >= 0x80
}
fn is_name(c: u8) -> bool {
    is_name_start(c) || c.is_ascii_digit() || c == b'-'
}
fn is_ws(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0C
}

impl<'a> Tokenizer<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokenizer { s: src.as_bytes(), src, pos: 0, line: 0, line_start: 0 }
    }

    fn peek(&self, off: usize) -> Option<u8> {
        self.s.get(self.pos + off).copied()
    }

    fn col(&self) -> u32 {
        // 1-based column counted in UTF-16 units
        let slice = &self.src[self.line_start..self.pos];
        let mut n = 0u32;
        for ch in slice.chars() {
            n += ch.len_utf16() as u32;
        }
        n + 1
    }

    fn newline_at(&mut self) {
        // pos currently at a newline char; consume it
        let c = self.s[self.pos];
        if c == b'\r' && self.peek(1) == Some(b'\n') {
            self.pos += 2;
        } else {
            self.pos += 1;
        }
        self.line += 1;
        self.line_start = self.pos;
    }

    fn valid_escape_at(&self, off: usize) -> bool {
        self.peek(off) == Some(b'\\') && !matches!(self.peek(off + 1), Some(b'\n') | Some(b'\r') | Some(0x0C) | None)
    }

    fn would_start_ident(&self, off: usize) -> bool {
        match self.peek(off) {
            Some(b'-') => match self.peek(off + 1) {
                Some(c) if is_name_start(c) || c == b'-' => true,
                Some(b'\\') => self.valid_escape_at(off + 1),
                _ => false,
            },
            Some(c) if is_name_start(c) => true,
            Some(b'\\') => self.valid_escape_at(off),
            _ => false,
        }
    }

    fn would_start_number(&self, off: usize) -> bool {
        match self.peek(off) {
            Some(b'+') | Some(b'-') => match self.peek(off + 1) {
                Some(c) if c.is_ascii_digit() => true,
                Some(b'.') => matches!(self.peek(off + 2), Some(c) if c.is_ascii_digit()),
                _ => false,
            },
            Some(b'.') => matches!(self.peek(off + 1), Some(c) if c.is_ascii_digit()),
            Some(c) if c.is_ascii_digit() => true,
            _ => false,
        }
    }

    fn next_char(&mut self) -> char {
        let ch = self.src[self.pos..].chars().next().unwrap();
        self.pos += ch.len_utf8();
        ch
    }

    fn consume_escape(&mut self) -> char {
        // assumes '\\' already consumed
        match self.peek(0) {
            None => '\u{FFFD}',
            Some(c) if c.is_ascii_hexdigit() => {
                let mut v: u32 = 0;
                let mut n = 0;
                while n < 6 {
                    match self.peek(0) {
                        Some(c) if c.is_ascii_hexdigit() => {
                            v = v * 16 + (c as char).to_digit(16).unwrap();
                            self.pos += 1;
                            n += 1;
                        }
                        _ => break,
                    }
                }
                match self.peek(0) {
                    Some(b' ') | Some(b'\t') => self.pos += 1,
                    Some(b'\n') | Some(b'\r') | Some(0x0C) => self.newline_at(),
                    _ => {}
                }
                if v == 0 || (0xD800..=0xDFFF).contains(&v) || v > 0x10FFFF {
                    '\u{FFFD}'
                } else {
                    char::from_u32(v).unwrap_or('\u{FFFD}')
                }
            }
            Some(0) => {
                self.pos += 1;
                '\u{FFFD}'
            }
            _ => self.next_char(),
        }
    }

    fn consume_name(&mut self) -> String {
        let mut out = String::new();
        loop {
            match self.peek(0) {
                Some(c) if is_name(c) => {
                    if c < 0x80 {
                        out.push(c as char);
                        self.pos += 1;
                    } else {
                        let ch = self.next_char();
                        out.push(ch);
                    }
                }
                Some(0) => {
                    self.pos += 1;
                    out.push('\u{FFFD}');
                }
                Some(b'\\') if self.valid_escape_at(0) => {
                    self.pos += 1;
                    out.push(self.consume_escape());
                }
                _ => break,
            }
        }
        out
    }

    fn consume_number(&mut self) -> (bool, f64, bool) {
        // returns (has_sign, value, is_integer)
        let start = self.pos;
        let mut has_sign = false;
        let mut is_int = true;
        if matches!(self.peek(0), Some(b'+') | Some(b'-')) {
            has_sign = true;
            self.pos += 1;
        }
        while matches!(self.peek(0), Some(c) if c.is_ascii_digit()) {
            self.pos += 1;
        }
        if self.peek(0) == Some(b'.') && matches!(self.peek(1), Some(c) if c.is_ascii_digit()) {
            is_int = false;
            self.pos += 1;
            while matches!(self.peek(0), Some(c) if c.is_ascii_digit()) {
                self.pos += 1;
            }
        }
        if matches!(self.peek(0), Some(b'e') | Some(b'E')) {
            let ok = match self.peek(1) {
                Some(c) if c.is_ascii_digit() => true,
                Some(b'+') | Some(b'-') => matches!(self.peek(2), Some(c) if c.is_ascii_digit()),
                _ => false,
            };
            if ok {
                is_int = false;
                self.pos += 2;
                while matches!(self.peek(0), Some(c) if c.is_ascii_digit()) {
                    self.pos += 1;
                }
            }
        }
        let text = &self.src[start..self.pos];
        let v: f64 = text.parse().unwrap_or(0.0);
        (has_sign, v, is_int)
    }

    fn consume_numeric(&mut self) -> Token {
        let (has_sign, v, is_int) = self.consume_number();
        let int_value = if is_int {
            Some(if v >= i32::MAX as f64 { i32::MAX } else if v <= i32::MIN as f64 { i32::MIN } else { v as i32 })
        } else {
            None
        };
        let fv = to_f32(v);
        if self.peek(0) == Some(b'%') {
            self.pos += 1;
            return Token::Percentage { has_sign, unit_value: to_f32(v / 100.0), int_value };
        }
        if self.would_start_ident(0) {
            let unit = self.consume_name();
            return Token::Dimension { has_sign, value: fv, int_value, unit };
        }
        Token::Number { has_sign, value: fv, int_value }
    }

    fn consume_string(&mut self, q: u8) -> Token {
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.peek(0) {
                None => return Token::QuotedString(out),
                Some(c) if c == q => {
                    self.pos += 1;
                    return Token::QuotedString(out);
                }
                Some(b'\n') | Some(b'\r') | Some(0x0C) => {
                    return Token::BadString(out);
                }
                Some(b'\\') => {
                    match self.peek(1) {
                        None => {
                            self.pos += 1;
                        }
                        Some(b'\n') | Some(b'\r') | Some(0x0C) => {
                            self.pos += 1;
                            self.newline_at();
                        }
                        _ => {
                            self.pos += 1;
                            out.push(self.consume_escape());
                        }
                    }
                }
                Some(0) => {
                    self.pos += 1;
                    out.push('\u{FFFD}');
                }
                Some(c) => {
                    if c < 0x80 {
                        out.push(c as char);
                        self.pos += 1;
                    } else {
                        out.push(self.next_char());
                    }
                }
            }
        }
    }

    fn consume_ident_like(&mut self) -> Token {
        let name = self.consume_name();
        if self.peek(0) == Some(b'(') {
            if name.eq_ignore_ascii_case("url") {
                // look ahead past whitespace
                let mut off = 1;
                while matches!(self.peek(off), Some(c) if is_ws(c)) {
                    off += 1;
                }
                match self.peek(off) {
                    Some(b'"') | Some(b'\'') => {
                        self.pos += 1;
                        return Token::Function(name);
                    }
                    _ => {
                        self.pos += 1;
                        return self.consume_url();
                    }
                }
            }
            self.pos += 1;
            return Token::Function(name);
        }
        Token::Ident(name)
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek(0) {
            if c == b'\n' || c == b'\r' || c == 0x0C {
                self.newline_at();
            } else if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn consume_url(&mut self) -> Token {
        self.skip_ws();
        let mut out = String::new();
        loop {
            match self.peek(0) {
                None => return Token::UnquotedUrl(out),
                Some(b')') => {
                    self.pos += 1;
                    return Token::UnquotedUrl(out);
                }
                Some(c) if is_ws(c) => {
                    self.skip_ws();
                    match self.peek(0) {
                        None => return Token::UnquotedUrl(out),
                        Some(b')') => {
                            self.pos += 1;
                            return Token::UnquotedUrl(out);
                        }
                        _ => {
                            return self.consume_bad_url(out);
                        }
                    }
                }
                Some(b'"') | Some(b'\'') | Some(b'(') => return self.consume_bad_url(out),
                Some(c) if c < 0x20 && c != b'\t' || c == 0x7F => return self.consume_bad_url(out),
                Some(b'\\') => {
                    if self.valid_escape_at(0) {
                        self.pos += 1;
                        out.push(self.consume_escape());
                    } else {
                        return self.consume_bad_url(out);
                    }
                }
                Some(c) => {
                    if c < 0x80 {
                        out.push(c as char);
                        self.pos += 1;
                    } else {
                        out.push(self.next_char());
                    }
                }
            }
        }
    }

    fn consume_bad_url(&mut self, mut out: String) -> Token {
        loop {
            match self.peek(0) {
                None => break,
                Some(b')') => {
                    self.pos += 1;
                    break;
                }
                Some(b'\\') if self.valid_escape_at(0) => {
                    self.pos += 1;
                    out.push(self.consume_escape());
                }
                Some(b'\n') | Some(b'\r') | Some(0x0C) => self.newline_at(),
                Some(_) => {
                    out.push(self.next_char());
                }
            }
        }
        Token::BadUrl(out)
    }

    pub fn next_token(&mut self) -> Option<Token> {
        let c = self.peek(0)?;
        let tok = match c {
            b' ' | b'\t' | b'\n' | b'\r' | 0x0C => {
                let start = self.pos;
                self.skip_ws();
                Token::WhiteSpace(self.src[start..self.pos].to_string())
            }
            b'"' | b'\'' => self.consume_string(c),
            b'#' => {
                if matches!(self.peek(1), Some(c) if is_name(c)) || self.valid_escape_at(1) {
                    self.pos += 1;
                    let is_id = self.would_start_ident(0);
                    let name = self.consume_name();
                    if is_id { Token::IDHash(name) } else { Token::Hash(name) }
                } else {
                    self.pos += 1;
                    Token::Delim('#')
                }
            }
            b'$' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::SuffixMatch } else { self.pos += 1; Token::Delim('$') }
            }
            b'(' => { self.pos += 1; Token::ParenthesisBlock }
            b')' => { self.pos += 1; Token::CloseParenthesis }
            b'*' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::SubstringMatch } else { self.pos += 1; Token::Delim('*') }
            }
            b'+' => {
                if self.would_start_number(0) { self.consume_numeric() } else { self.pos += 1; Token::Delim('+') }
            }
            b',' => { self.pos += 1; Token::Comma }
            b'-' => {
                if self.would_start_number(0) {
                    self.consume_numeric()
                } else if self.peek(1) == Some(b'-') && self.peek(2) == Some(b'>') {
                    self.pos += 3;
                    Token::CDC
                } else if self.would_start_ident(0) {
                    self.consume_ident_like()
                } else {
                    self.pos += 1;
                    Token::Delim('-')
                }
            }
            b'.' => {
                if self.would_start_number(0) { self.consume_numeric() } else { self.pos += 1; Token::Delim('.') }
            }
            b'/' => {
                if self.peek(1) == Some(b'*') {
                    let start = self.pos;
                    self.pos += 2;
                    loop {
                        match self.peek(0) {
                            None => break,
                            Some(b'*') if self.peek(1) == Some(b'/') => {
                                self.pos += 2;
                                break;
                            }
                            Some(b'\n') | Some(b'\r') | Some(0x0C) => self.newline_at(),
                            Some(_) => { self.next_char(); }
                        }
                    }
                    let text = &self.src[start + 2..self.pos];
                    let text = text.strip_suffix("*/").unwrap_or(text);
                    Token::Comment(text.to_string())
                } else {
                    self.pos += 1;
                    Token::Delim('/')
                }
            }
            b'0'..=b'9' => self.consume_numeric(),
            b':' => { self.pos += 1; Token::Colon }
            b';' => { self.pos += 1; Token::Semicolon }
            b'<' => {
                if self.peek(1) == Some(b'!') && self.peek(2) == Some(b'-') && self.peek(3) == Some(b'-') {
                    self.pos += 4;
                    Token::CDO
                } else {
                    self.pos += 1;
                    Token::Delim('<')
                }
            }
            b'@' => {
                if self.would_start_ident(1) {
                    self.pos += 1;
                    Token::AtKeyword(self.consume_name())
                } else {
                    self.pos += 1;
                    Token::Delim('@')
                }
            }
            b'[' => { self.pos += 1; Token::SquareBracketBlock }
            b'\\' => {
                if self.valid_escape_at(0) { self.consume_ident_like() } else { self.pos += 1; Token::Delim('\\') }
            }
            b']' => { self.pos += 1; Token::CloseSquareBracket }
            b'^' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::PrefixMatch } else { self.pos += 1; Token::Delim('^') }
            }
            b'{' => { self.pos += 1; Token::CurlyBracketBlock }
            b'}' => { self.pos += 1; Token::CloseCurlyBracket }
            b'|' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::DashMatch } else { self.pos += 1; Token::Delim('|') }
            }
            b'~' => {
                if self.peek(1) == Some(b'=') { self.pos += 2; Token::IncludeMatch } else { self.pos += 1; Token::Delim('~') }
            }
            0 => { self.pos += 1; Token::Delim('\u{FFFD}') }
            c if is_name_start(c) => self.consume_ident_like(),
            _ => {
                let ch = self.next_char();
                Token::Delim(ch)
            }
        };
        Some(tok)
    }
}

pub fn to_f32(v: f64) -> f32 {
    let f = v as f32;
    if f.is_infinite() {
        if f > 0.0 { f32::MAX } else { f32::MIN }
    } else {
        f
    }
}

pub fn tokenize(src: &str) -> Vec<Tok> {
    let mut t = Tokenizer::new(src);
    let mut out: Vec<Tok> = Vec::new();
    let mut stack: Vec<(usize, u8)> = Vec::new();
    loop {
        let start = t.pos;
        let line = t.line;
        let col = t.col();
        let tok = match t.next_token() {
            Some(tok) => tok,
            None => break,
        };
        let idx = out.len();
        let closer = match &tok {
            Token::Function(_) | Token::ParenthesisBlock => Some(b')'),
            Token::SquareBracketBlock => Some(b']'),
            Token::CurlyBracketBlock => Some(b'}'),
            _ => None,
        };
        let is_close = match &tok {
            Token::CloseParenthesis => Some(b')'),
            Token::CloseSquareBracket => Some(b']'),
            Token::CloseCurlyBracket => Some(b'}'),
            _ => None,
        };
        out.push(Tok { token: tok, line, col, start, end: t.pos, close: 0 });
        if let Some(c) = closer {
            stack.push((idx, c));
        } else if let Some(c) = is_close {
            if let Some(&(open, oc)) = stack.last() {
                if oc == c {
                    stack.pop();
                    out[open].close = idx;
                }
            }
        }
    }
    let n = out.len();
    for (open, _) in stack {
        out[open].close = n;
    }
    out
}
