            let c = bytes[i];
            if c == b'\n' || c == 0x0C || (c == b'\r' && bytes.get(i + 1) != Some(&b'\n')) {
                line += 1;
                col = 1;
            } else if c == b'\r' {
            } else if c & 0xC0 != 0x80 {
                col += if c >= 0xF0 { 2 } else { 1 };
            }
