        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::QuotedString(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_ident_or_string(&mut self) -> PResult<&'t str> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::QuotedString(s) | Token::Ident(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
