        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Percentage { unit_value, .. } => Ok(*unit_value),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_colon(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Colon => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_comma(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Comma => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
