    }

    pub fn err(&self, kind: ErrorKind) -> ParseError {
        let (line, col) = self.location();
        ParseError { kind, line, col }
    }
    pub fn err_at(&self, kind: ErrorKind, loc: (u32, u32)) -> ParseError {
        ParseError { kind, line: loc.0, col: loc.1 }
    }
    pub fn new_error_for_next_token<T>(&mut self) -> PResult<T> {
        let loc = self.location();
        match self.next() {
            Ok(t) => {
                let t = t.clone();
                Err(self.err_at(ErrorKind::UnexpectedToken(t), loc))
            }
            Err(e) => Err(e),
        }
    }

    pub fn invalid<T>(&self) -> PResult<T> {
        Err(self.err(ErrorKind::InvalidValue))
    }

    fn at_end(&self) -> bool {
        if self.pos >= self.end {
            return true;
        }
        let t = &self.toks[self.pos].token;
        self.stop != 0 && (delim_of(t) & self.stop) != 0
    }

    pub fn is_exhausted(&mut self) -> bool {
        let s = self.state();
        let r = self.next().is_err();
        self.reset(s);
        r
    }

    pub fn eof_error(&self) -> ParseError {
        let (line, col) = self.location();
        ParseError { kind: ErrorKind::EndOfInput, line, col }
    }

    pub fn next_including_whitespace_and_comments(&mut self) -> PResult<&'t Token> {
        if self.at_end() {
            return Err(self.eof_error());
        }
        let i = self.pos;
        let t = &self.toks[i];
        if t.token.is_block_open() {
            self.last_block = Some((i + 1, t.close));
            self.pos = if t.close >= self.toks.len() { self.toks.len() } else { t.close + 1 };
            if self.pos > self.end {
                self.pos = self.end;
            }
        } else {
            self.last_block = None;
            self.pos += 1;
        }
        Ok(&t.token)
    }

    pub fn next_including_whitespace(&mut self) -> PResult<&'t Token> {
        loop {
            let t = self.next_including_whitespace_and_comments()?;
            if let Token::Comment(_) = t {
                continue;
            }
            return Ok(t);
        }
    }

    pub fn next(&mut self) -> PResult<&'t Token> {
        loop {
            let t = self.next_including_whitespace_and_comments()?;
            match t {
                Token::Comment(_) | Token::WhiteSpace(_) => continue,
                _ => return Ok(t),
            }
        }
    }

    pub fn skip_whitespace(&mut self) {
        while self.pos < self.end {
            match &self.toks[self.pos].token {
                Token::WhiteSpace(_) | Token::Comment(_) => self.pos += 1,
                _ => break,
            }
        }
    }

    pub fn peek(&mut self) -> Option<&'t Token> {
        let s = self.state();
        let r = self.next().ok();
        self.reset(s);
        r
    }

    pub fn try_parse<T, F: FnOnce(&mut Parser<'t>) -> PResult<T>>(&mut self, f: F) -> PResult<T> {
        let s = self.state();
        let r = f(self);
        if r.is_err() {
            self.reset(s);
        }
        r
    }

    pub fn expect_exhausted(&mut self) -> PResult<()> {
        let s = self.state();
        let loc = { self.skip_whitespace(); self.location() };
        let r = match self.next() {
            Err(_) => Ok(()),
            Ok(t) => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        };
        self.reset(s);
        r
    }

    pub fn parse_entirely<T, F: FnOnce(&mut Parser<'t>) -> PResult<T>>(&mut self, f: F) -> PResult<T> {
        let r = f(self)?;
        self.expect_exhausted()?;
        Ok(r)
    }

    pub fn has_block(&self) -> bool {
        self.last_block.is_some()
    }

    pub fn parse_nested_block<T, F: FnOnce(&mut Parser<'t>) -> PResult<T>>(&mut self, f: F) -> PResult<T> {
        let (start, close) = self.last_block.take().expect("parse_nested_block called without block");
        let end = close.min(self.toks.len());
        let mut sub = Parser {
            toks: self.toks,
            src: self.src,
            pos: start,
            end,
            stop: 0,
            last_block: None,
            eof_line: self.eof_line,
            eof_col: self.eof_col,
        };
        if close < self.toks.len() {
            sub.eof_line = self.toks[close].line;
            sub.eof_col = self.toks[close].col;
        }
        sub.parse_entirely(f)
    }

    /// Position (byte offset) of next token
    pub fn byte_pos(&self) -> usize {
        if self.pos < self.toks.len() { self.toks[self.pos].start } else { self.src.len() }
    }

    fn skip_to_delim(&mut self, delims: u8) {
        // skip tokens until at a delimiter of `delims` or at end
        while self.pos < self.end {
            let t = &self.toks[self.pos];
            if (delim_of(&t.token) & (delims | self.stop)) != 0 {
                break;
            }
            if t.token.is_block_open() {
                self.pos = if t.close >= self.toks.len() { self.toks.len() } else { t.close + 1 };
                if self.pos > self.end { self.pos = self.end; }
            } else {
                self.pos += 1;
            }
        }
        self.last_block = None;
    }

    pub fn parse_until_before<T, F: FnOnce(&mut Parser<'t>) -> PResult<T>>(&mut self, delims: u8, f: F) -> PResult<T> {
        let mut sub = self.clone();
        sub.stop = self.stop | delims;
        sub.last_block = None;
        let r = sub.parse_entirely(f);
        sub.skip_to_delim(delims);
        self.pos = sub.pos;
        self.last_block = None;
        r
    }

    pub fn parse_until_after<T, F: FnOnce(&mut Parser<'t>) -> PResult<T>>(&mut self, delims: u8, f: F) -> PResult<T> {
        let r = self.parse_until_before(delims, f);
        // consume the delimiter
        if self.pos < self.end {
            let t = &self.toks[self.pos];
            if (delim_of(&t.token) & delims) != 0 && (delim_of(&t.token) & self.stop) == 0 {
                if t.token.is_block_open() {
                    self.pos = if t.close >= self.toks.len() { self.toks.len() } else { t.close + 1 };
                    if self.pos > self.end { self.pos = self.end; }
                } else {
                    self.pos += 1;
                }
            }
        }
        r
    }

    // Helpers
    pub fn expect_ident(&mut self) -> PResult<&'t str> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Ident(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_ident_cloned(&mut self) -> PResult<String> {
        self.expect_ident().map(|s| s.to_string())
    }
    pub fn expect_ident_matching(&mut self, name: &str) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Ident(s) if s.eq_ignore_ascii_case(name) => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_string(&mut self) -> PResult<&'t str> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::QuotedString(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_ident_or_string(&mut self) -> PResult<&'t str> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::QuotedString(s) | Token::Ident(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_url_or_string(&mut self) -> PResult<String> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::QuotedString(s) | Token::UnquotedUrl(s) => Ok(s.clone()),
            Token::Function(name) if name.eq_ignore_ascii_case("url") => {
                self.parse_nested_block(|p| Ok(p.expect_string()?.to_string()))
            }
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_url(&mut self) -> PResult<String> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::UnquotedUrl(s) => Ok(s.clone()),
            Token::Function(name) if name.eq_ignore_ascii_case("url") => {
                self.parse_nested_block(|p| Ok(p.expect_string()?.to_string()))
            }
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_number(&mut self) -> PResult<f32> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Number { value, .. } => Ok(*value),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_integer(&mut self) -> PResult<i32> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Number { int_value: Some(v), .. } => Ok(*v),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_percentage(&mut self) -> PResult<f32> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Percentage { unit_value, .. } => Ok(*unit_value),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_colon(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Colon => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_comma(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Comma => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_semicolon(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Semicolon => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_delim(&mut self, c: char) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Delim(d) if *d == c => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_function(&mut self) -> PResult<&'t str> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Function(s) => Ok(s.as_str()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_function_matching(&mut self, name: &str) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::Function(s) if s.eq_ignore_ascii_case(name) => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_parenthesis_block(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::ParenthesisBlock => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_curly_block(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::CurlyBracketBlock => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn expect_square_block(&mut self) -> PResult<()> {
        let loc = { self.skip_whitespace(); self.location() };
        match self.next()? {
            Token::SquareBracketBlock => Ok(()),
            t => Err(self.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }
    pub fn try_ident_matching(&mut self, name: &str) -> bool {
        self.try_parse(|p| p.expect_ident_matching(name)).is_ok()
    }
    pub fn try_delim(&mut self, c: char) -> bool {
        self.try_parse(|p| p.expect_delim(c)).is_ok()
    }
    pub fn try_comma(&mut self) -> bool {
        self.try_parse(|p| p.expect_comma()).is_ok()
    }
}
