    }

    pub fn add_mapping(&mut self, line: u32, col: u32) {
        let m = (self.line, self.col, self.source_index, line, col);
        if let Some(last) = self.mappings.last() {
            if last.0 == m.0 && last.1 == m.1 {
                return;
            }
        }
        self.mappings.push(m);
    }

    pub fn write_ident(&mut self, s: &str) {
        let mut o = String::new();
        serialize_identifier(s, &mut o);
        self.write_str(&o);
    }

    pub fn write_dashed_ident(&mut self, s: &str) {
        // s starts with --
        self.write_str("--");
        let mut o = String::new();
        serialize_name(&s[2..], &mut o);
        self.write_str(&o);
    }

    pub fn write_string(&mut self, s: &str) {
        let mut o = String::new();
        serialize_string(s, &mut o);
        self.write_str(&o);
    }

    pub fn write_num(&mut self, v: f32) {
        let s = fmt_num(v);
        self.write_str(&s);
    }
}

fn hex_escape(c: u32, out: &mut String) {
    out.push_str(&format!("\\{:x} ", c));
}

pub fn serialize_name(s: &str, out: &mut String) {
    for ch in s.chars() {
        let c = ch as u32;
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' || c >= 0x80 {
            out.push(ch);
        } else if c == 0 {
            out.push('\u{FFFD}');
        } else if c < 0x20 || c == 0x7F {
            hex_escape(c, out);
        } else {
            out.push('\\');
            out.push(ch);
        }
    }
}

pub fn serialize_identifier(s: &str, out: &mut String) {
    if s.is_empty() {
        return;
    }
    if let Some(rest) = s.strip_prefix("--") {
        out.push_str("--");
        serialize_name(rest, out);
        return;
    }
    if s == "-" {
        out.push_str("\\-");
        return;
    }
    let mut rest = s;
    if let Some(r) = rest.strip_prefix('-') {
        out.push('-');
        rest = r;
    }
    if let Some(ch) = rest.chars().next() {
        if ch.is_ascii_digit() {
            hex_escape(ch as u32, out);
            rest = &rest[1..];
        }
    }
    serialize_name(rest, out);
}

pub fn serialize_string(s: &str, out: &mut String) {
    out.push('"');
    for ch in s.chars() {
        let c = ch as u32;
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\0' => out.push('\u{FFFD}'),
            _ if c < 0x20 || c == 0x7F => hex_escape(c, out),
            _ => out.push(ch),
        }
    }
    out.push('"');
}

/// Format a number like dtoa-short with 6 digits precision, stripping leading zero.
pub fn fmt_num(v: f32) -> String {
    if v == 0.0 || v.is_nan() {
        return "0".to_string();
    }
    let neg = v < 0.0;
    let a = v.abs();
    let a = if a.is_infinite() { f32::MAX } else { a };
    let e = format!("{:e}", a);
    let (mant, exp) = e.split_once('e').unwrap();
    let mut exp: i32 = exp.parse().unwrap();
    let mut digits: Vec<u8> = mant.bytes().filter(|b| b.is_ascii_digit()).map(|b| b - b'0').collect();
    if digits.len() > 6 {
        let round_up = digits[6] >= 5;
        digits.truncate(6);
        if round_up {
            let mut i = 5i32;
            loop {
                if i < 0 {
                    digits.insert(0, 1);
                    digits.truncate(6);
                    exp += 1;
                    break;
                }
                if digits[i as usize] == 9 {
                    digits[i as usize] = 0;
                    i -= 1;
                } else {
                    digits[i as usize] += 1;
                    break;
                }
            }
        }
    }
    while digits.len() > 1 && *digits.last().unwrap() == 0 {
        digits.pop();
    }
    let k = digits.len() as i32;
    let n = exp + 1;
    let ds: String = digits.iter().map(|d| (b'0' + d) as char).collect();
    let mut s = String::new();
    if neg {
        s.push('-');
    }
    if k <= n && n <= 21 {
        s.push_str(&ds);
        for _ in 0..(n - k) {
            s.push('0');
        }
    } else if 0 < n && n <= 21 {
        s.push_str(&ds[..n as usize]);
        s.push('.');
        s.push_str(&ds[n as usize..]);
    } else if -6 < n && n <= 0 {
        s.push('.');
        for _ in 0..(-n) {
            s.push('0');
        }
        s.push_str(&ds);
    } else {
        s.push_str(&ds[..1]);
        if k > 1 {
            s.push('.');
            s.push_str(&ds[1..]);
        }
        s.push('e');
        s.push_str(&(n - 1).to_string());
    }
    s
}
