// Numeric values, units, and calc() engine.
use crate::parser::*;
use crate::printer::{fmt_num, Printer};
use crate::tokenizer::Token;
use std::cmp::Ordering;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cat {
    Number,
    Percent,
    Length,
    Angle,
    Time,
    Resolution,
}

pub const C_NUM: u8 = 1;
pub const C_PCT: u8 = 2;
pub const C_LEN: u8 = 4;
pub const C_ANG: u8 = 8;
pub const C_TIME: u8 = 16;
pub const C_RES: u8 = 32;

pub const LENGTH_UNITS: &[&str] = &[
    "px", "in", "cm", "mm", "q", "pt", "pc", "em", "rem", "ex", "rex", "ch", "rch", "cap", "rcap", "ic", "ric", "lh",
    "rlh", "vw", "lvw", "svw", "dvw", "cqw", "vh", "lvh", "svh", "dvh", "cqh", "vi", "svi", "lvi", "dvi", "cqi", "vb",
    "svb", "lvb", "dvb", "cqb", "vmin", "svmin", "lvmin", "dvmin", "cqmin", "vmax", "svmax", "lvmax", "dvmax", "cqmax",
];

pub fn unit_cat(u: &str) -> Option<Cat> {
    if u.is_empty() {
        return Some(Cat::Number);
    }
    if u == "%" {
        return Some(Cat::Percent);
    }
    if LENGTH_UNITS.contains(&u) {
        return Some(Cat::Length);
    }
    match u {
        "deg" | "rad" | "grad" | "turn" => Some(Cat::Angle),
        "s" | "ms" => Some(Cat::Time),
        "dpi" | "dpcm" | "dppx" | "x" => Some(Cat::Resolution),
        _ => None,
    }
}

fn cat_bit(c: Cat) -> u8 {
    match c {
        Cat::Number => C_NUM,
        Cat::Percent => C_PCT,
        Cat::Length => C_LEN,
        Cat::Angle => C_ANG,
        Cat::Time => C_TIME,
        Cat::Resolution => C_RES,
    }
}

/// Factor to convert absolute units to canonical (px, deg, ms, dppx)
pub fn abs_factor(u: &str) -> Option<f32> {
    Some(match u {
        "px" => 1.0,
        "in" => 96.0,
        "cm" => 96.0 / 2.54,
        "mm" => 96.0 / 25.4,
        "q" => 96.0 / 101.6,
        "pt" => 96.0 / 72.0,
        "pc" => 16.0,
        "deg" => 1.0,
        "rad" => 180.0 / std::f32::consts::PI,
        "grad" => 180.0 / 200.0,
        "turn" => 360.0,
        "s" => 1000.0,
        "ms" => 1.0,
        "dppx" | "x" => 1.0,
        "dpi" => 1.0 / 96.0,
        "dpcm" => 2.54 / 96.0,
        _ => return None,
    })
}

pub fn canonical_unit(c: Cat) -> &'static str {
    match c {
        Cat::Length => "px",
        Cat::Angle => "deg",
        Cat::Time => "ms",
        Cat::Resolution => "dppx",
        Cat::Percent => "%",
        Cat::Number => "",
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Dim {
    pub v: f32,
    pub unit: String, // lowercase. "" = number, "%" = percentage (v is fraction)
}

impl Dim {
    pub fn new(v: f32, unit: &str) -> Dim {
        Dim { v, unit: unit.to_string() }
    }
    pub fn px(v: f32) -> Dim {
        Dim::new(v, "px")
    }
    pub fn pct(v: f32) -> Dim {
        Dim::new(v, "%")
    }
    pub fn num(v: f32) -> Dim {
        Dim::new(v, "")
    }
    pub fn cat(&self) -> Cat {
        unit_cat(&self.unit).unwrap_or(Cat::Length)
    }
    pub fn is_zero(&self) -> bool {
        self.v == 0.0
    }
    pub fn try_add(&self, o: &Dim) -> Option<Dim> {
        if self.unit == o.unit {
            return Some(Dim { v: self.v + o.v, unit: self.unit.clone() });
        }
        if self.cat() != o.cat() {
            return None;
        }
        let (fa, fb) = (abs_factor(&self.unit)?, abs_factor(&o.unit)?);
        let c = self.cat();
        let cu = canonical_unit(c);
        let v = self.v * fa + o.v * fb;
        // time: prefer seconds? keep canonical then convert
        Some(Dim { v, unit: cu.to_string() })
    }
    pub fn to_canonical(&self) -> Option<f32> {
        if self.unit.is_empty() || self.unit == "%" {
            return Some(self.v);
        }
        Some(self.v * abs_factor(&self.unit)?)
    }
    pub fn partial_cmp(&self, o: &Dim) -> Option<Ordering> {
        if self.unit == o.unit {
            return self.v.partial_cmp(&o.v);
        }
        if self.cat() != o.cat() {
            return None;
        }
        let a = self.to_canonical()?;
        let b = o.to_canonical()?;
        if abs_factor(&self.unit).is_none() || abs_factor(&o.unit).is_none() {
            return None;
        }
        a.partial_cmp(&b)
    }
    pub fn mul(&self, f: f32) -> Dim {
        Dim { v: self.v * f, unit: self.unit.clone() }
    }

    pub fn to_css(&self, d: &mut Printer) {
        self.to_css_ctx(d, false)
    }

    pub fn to_css_ctx(&self, d: &mut Printer, in_calc: bool) {
        match self.cat() {
            Cat::Number => d.write_num(self.v),
            Cat::Percent => {
                d.write_num(self.v * 100.0);
                d.write_char('%');
            }
            Cat::Length => {
                if self.v == 0.0 && !in_calc {
                    d.write_char('0');
                } else {
                    write_dimension(d, self.v, &self.unit);
                }
            }
            Cat::Angle => write_angle(d, self.v, &self.unit, false),
            Cat::Time => write_time(d, self.v, &self.unit),
            Cat::Resolution => write_resolution(d, self.v, &self.unit),
        }
    }
}

pub fn write_dimension(d: &mut Printer, v: f32, unit: &str) {
    if v == 0.0 && v.is_sign_negative() {
        d.write_str("-0");
    } else {
        d.write_num(v);
    }
    d.write_ident_unit(unit);
}

impl Printer {
    pub fn write_ident_unit(&mut self, unit: &str) {
        // units are identifiers; 'e' as unit start could be confused with exponent
        let mut o = String::new();
        let first = unit.chars().next();
        if matches!(first, Some('e') | Some('E')) && unit.len() > 1 {
            // e.g. "1em" is fine since the tokenizer handles "1em". Only escape if followed by digit
            let second = unit.chars().nth(1).unwrap();
            if second.is_ascii_digit() || second == '-' || second == '+' {
                o.push_str("\\65 ");
                crate::printer::serialize_name(&unit[1..], &mut o);
                self.write_str(&o);
                return;
            }
        }
        crate::printer::serialize_name(unit, &mut o);
        self.write_str(&o);
    }
}

pub fn write_angle(d: &mut Printer, v: f32, unit: &str, unitless_zero: bool) {
    if v == 0.0 && unitless_zero {
        d.write_char('0');
        return;
    }
    match unit {
        "rad" => {
            let deg = v * 180.0 / std::f32::consts::PI;
            write_dimension(d, deg, "deg");
        }
        _ => write_dimension(d, v, unit),
    }
}

pub fn write_time(d: &mut Printer, v: f32, unit: &str) {
    match unit {
        "ms" => {
            if v == 0.0 || v >= 100.0 {
                write_dimension(d, v / 1000.0, "s");
            } else {
                write_dimension(d, v, "ms");
            }
        }
        _ => write_dimension(d, v, unit),
    }
}

pub fn write_resolution(d: &mut Printer, v: f32, unit: &str) {
    match unit {
        "dppx" | "x" => write_dimension(d, v, "x"),
        _ => write_dimension(d, v, unit),
    }
}

// ---------------- Calc ----------------

#[derive(Clone, Debug, PartialEq)]
pub enum Calc {
    Value(Dim),
    Number(f32),
    Sum(Box<Calc>, Box<Calc>),
    Product(f32, Box<Calc>),
    Func(Box<MathFn>),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum RoundStrategy {
    Nearest,
    Up,
    Down,
    ToZero,
}

#[derive(Clone, Debug, PartialEq)]
pub enum MathFn {
    Calc(Calc),
    Min(Vec<Calc>),
    Max(Vec<Calc>),
    Clamp(Calc, Calc, Calc),
    Round(RoundStrategy, Calc, Calc),
    Rem(Calc, Calc),
    Mod(Calc, Calc),
    Abs(Calc),
    Sign(Calc),
    Hypot(Vec<Calc>),
}

impl Calc {
    pub fn is_sign_negative(&self) -> bool {
        match self {
            Calc::Value(d) => d.v < 0.0 || (d.v == 0.0 && d.v.is_sign_negative()),
            Calc::Number(n) => *n < 0.0,
            Calc::Product(n, c) => {
                let a = *n < 0.0;
                let b = c.is_sign_negative();
                a != b
            }
            _ => false,
        }
    }
    pub fn is_sign_positive(&self) -> bool {
        match self {
            Calc::Value(d) => d.v > 0.0 || (d.v == 0.0 && d.v.is_sign_positive()),
            Calc::Number(n) => *n >= 0.0,
            Calc::Product(n, c) => {
                let a = *n >= 0.0;
                let b = c.is_sign_positive();
                a == b
            }
            _ => false,
        }
    }
    pub fn is_zero(&self) -> bool {
        match self {
            Calc::Value(d) => d.v == 0.0,
            Calc::Number(n) => *n == 0.0,
            _ => false,
        }
    }

    pub fn mul(self, f: f32) -> Calc {
        if f == 1.0 {
            return self;
        }
        match self {
            Calc::Value(d) => Calc::Value(d.mul(f)),
            Calc::Number(n) => Calc::Number(n * f),
            Calc::Sum(a, b) => Calc::Sum(Box::new(a.mul(f)), Box::new(b.mul(f))),
            Calc::Product(n, c) => {
                let p = n * f;
                if p == 1.0 {
                    *c
                } else {
                    Calc::Product(p, c)
                }
            }
            Calc::Func(fun) => match *fun {
                MathFn::Calc(c) => c.mul(f),
                other => Calc::Product(f, Box::new(Calc::Func(Box::new(other)))),
            },
        }
    }

    fn add_recursive(&self, other: &Calc) -> Option<Calc> {
        match (self, other) {
            (Calc::Value(a), Calc::Value(b)) => a.try_add(b).map(Calc::Value),
            (Calc::Number(a), Calc::Number(b)) => Some(Calc::Number(a + b)),
            (Calc::Sum(a, b), other) => {
                if let Some(r) = a.add_recursive(other) {
                    return Some(Calc::Sum(Box::new(r), b.clone()));
                }
                if let Some(r) = b.add_recursive(other) {
                    return Some(Calc::Sum(a.clone(), Box::new(r)));
                }
                None
            }
            (other, Calc::Sum(a, b)) => {
                if let Some(r) = other.add_recursive(a) {
                    return Some(Calc::Sum(Box::new(r), b.clone()));
                }
                if let Some(r) = other.add_recursive(b) {
                    return Some(Calc::Sum(a.clone(), Box::new(r)));
                }
                None
            }
            _ => None,
        }
    }

    pub fn add(self, other: Calc) -> Calc {
        if let Some(r) = self.add_recursive(&other) {
            return r;
        }
        let (mut a, mut b) = (self, other);
        if a.is_zero() && matches!(a, Calc::Value(_)) && !matches!(b, Calc::Number(_)) {
            return b;
        }
        if b.is_zero() && matches!(b, Calc::Value(_)) && !matches!(a, Calc::Number(_)) {
            return a;
        }
        if a.is_sign_negative() && b.is_sign_positive() && is_simple(&a) && is_simple(&b) {
            std::mem::swap(&mut a, &mut b);
        }
        Calc::Sum(Box::new(a), Box::new(b))
    }

    pub fn partial_cmp(&self, other: &Calc) -> Option<Ordering> {
        match (self, other) {
            (Calc::Value(a), Calc::Value(b)) => a.partial_cmp(b),
            (Calc::Number(a), Calc::Number(b)) => a.partial_cmp(b),
            _ => None,
        }
    }

    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Calc::Value(v) => v.to_css_ctx(d, true),
            Calc::Number(n) => d.write_num(*n),
            Calc::Sum(a, b) => {
                a.to_css(d);
                if b.is_sign_negative() {
                    d.write_str(" - ");
                    let nb = (**b).clone().mul(-1.0);
                    nb.to_css(d);
                } else {
                    d.write_str(" + ");
                    b.to_css(d);
                }
            }
            Calc::Product(n, c) => {
                if n.abs() < 1.0 && *n != 0.0 {
                    let div = 1.0 / n;
                    c.to_css(d);
                    d.delim('/', true);
                    d.write_num(div);
                } else {
                    d.write_num(*n);
                    d.delim('*', true);
                    c.to_css(d);
                }
            }
            Calc::Func(f) => f.to_css(d),
        }
    }

    /// Print as a top-level value (wrapping in calc() when needed)
    pub fn to_css_top(&self, d: &mut Printer) {
        match self {
            Calc::Func(f) => f.to_css(d),
            Calc::Value(v) => v.to_css(d),
            Calc::Number(n) => d.write_num(*n),
            _ => {
                d.write_str("calc(");
                self.to_css(d);
                d.write_char(')');
            }
        }
    }
}

fn is_simple(c: &Calc) -> bool {
    matches!(c, Calc::Value(_) | Calc::Number(_))
}

impl MathFn {
    pub fn to_css(&self, d: &mut Printer) {
        let list = |d: &mut Printer, name: &str, args: &[&Calc]| {
            d.write_str(name);
            d.write_char('(');
            for (i, a) in args.iter().enumerate() {
                if i > 0 {
                    d.delim(',', false);
                }
                a.to_css(d);
            }
            d.write_char(')');
        };
        match self {
            MathFn::Calc(c) => {
                d.write_str("calc(");
                c.to_css(d);
                d.write_char(')');
            }
            MathFn::Min(v) => list(d, "min", &v.iter().collect::<Vec<_>>()),
            MathFn::Max(v) => list(d, "max", &v.iter().collect::<Vec<_>>()),
            MathFn::Clamp(a, b, c) => list(d, "clamp", &[a, b, c]),
            MathFn::Round(s, a, b) => {
                d.write_str("round(");
                match s {
                    RoundStrategy::Nearest => {}
                    RoundStrategy::Up => {
                        d.write_str("up");
                        d.delim(',', false);
                    }
                    RoundStrategy::Down => {
                        d.write_str("down");
                        d.delim(',', false);
                    }
                    RoundStrategy::ToZero => {
                        d.write_str("to-zero");
                        d.delim(',', false);
                    }
                }
                a.to_css(d);
                d.delim(',', false);
                b.to_css(d);
                d.write_char(')');
            }
            MathFn::Rem(a, b) => list(d, "rem", &[a, b]),
            MathFn::Mod(a, b) => list(d, "mod", &[a, b]),
            MathFn::Abs(a) => list(d, "abs", &[a]),
            MathFn::Sign(a) => list(d, "sign", &[a]),
            MathFn::Hypot(v) => list(d, "hypot", &v.iter().collect::<Vec<_>>()),
        }
    }
}

// ------------- Parsing -------------

pub struct CalcCtx {
    pub allowed: u8, // categories allowed for leaf dims (excluding numbers which are always allowed as factors)
}

fn parse_dim_token(t: &Token, allowed: u8) -> Option<Dim> {
    match t {
        Token::Dimension { value, unit, .. } => {
            let u = unit.to_ascii_lowercase();
            let c = unit_cat(&u)?;
            if c == Cat::Number || c == Cat::Percent {
                return None;
            }
            if allowed & cat_bit(c) == 0 {
                return None;
            }
            Some(Dim { v: *value, unit: u })
        }
        Token::Percentage { unit_value, .. } if allowed & C_PCT != 0 => Some(Dim { v: *unit_value, unit: "%".into() }),
        _ => None,
    }
}

pub fn is_math_fn(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "calc" | "min" | "max" | "clamp" | "round" | "rem" | "mod" | "abs" | "sign" | "hypot" | "sin" | "cos" | "tan"
            | "asin" | "acos" | "atan" | "atan2" | "pow" | "sqrt" | "log" | "exp"
    )
}

pub fn parse_math_function(p: &mut Parser, name: &str, allowed: u8) -> PResult<Calc> {
    let lname = name.to_ascii_lowercase();
    let r = p.parse_nested_block(|p| parse_fn_body(p, &lname, allowed))?;
    Ok(r)
}

fn parse_fn_body(p: &mut Parser, lname: &str, allowed: u8) -> PResult<Calc> {
    match lname {
        "calc" => {
            let c = parse_sum(p, allowed)?;
            Ok(match c {
                Calc::Value(_) | Calc::Number(_) | Calc::Func(_) => c,
                c => Calc::Func(Box::new(MathFn::Calc(c))),
            })
        }
        "min" | "max" => {
            let mut args: Vec<Calc> = Vec::new();
            loop {
                let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
                let mut merged = false;
                for existing in args.iter_mut() {
                    if let Some(ord) = existing.partial_cmp(&a) {
                        merged = true;
                        let replace = if lname == "min" { ord == Ordering::Greater } else { ord == Ordering::Less };
                        if replace {
                            *existing = a.clone();
                        }
                        break;
                    }
                }
                if !merged {
                    args.push(a);
                }
                if !p.try_comma() {
                    break;
                }
            }
            if args.len() == 1 {
                return Ok(args.pop().unwrap());
            }
            Ok(Calc::Func(Box::new(if lname == "min" { MathFn::Min(args) } else { MathFn::Max(args) })))
        }
        "clamp" => {
            let min = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            p.expect_comma()?;
            let center = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            p.expect_comma()?;
            let max = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            // reduce
            let mut min = Some(min);
            let mut max = Some(max);
            let mut center = center;
            if let Some(mx) = &max {
                if let Some(ord) = center.partial_cmp(mx) {
                    if ord != Ordering::Less {
                        center = mx.clone();
                    }
                    max = None;
                }
            }
            if let Some(mn) = &min {
                if let Some(ord) = center.partial_cmp(mn) {
                    if ord == Ordering::Less {
                        center = mn.clone();
                    }
                    min = None;
                }
            }
            Ok(match (min, max) {
                (None, None) => center,
                (Some(mn), None) => Calc::Func(Box::new(MathFn::Max(vec![mn, center]))),
                (None, Some(mx)) => Calc::Func(Box::new(MathFn::Min(vec![center, mx]))),
                (Some(mn), Some(mx)) => Calc::Func(Box::new(MathFn::Clamp(mn, center, mx))),
            })
        }
        "round" => {
            let strat = p
                .try_parse(|p| {
                    let s = p.expect_ident()?.to_ascii_lowercase();
                    let r = match s.as_str() {
                        "nearest" => RoundStrategy::Nearest,
                        "up" => RoundStrategy::Up,
                        "down" => RoundStrategy::Down,
                        "to-zero" => RoundStrategy::ToZero,
                        _ => return p.invalid(),
                    };
                    p.expect_comma()?;
                    Ok(r)
                })
                .unwrap_or(RoundStrategy::Nearest);
            let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            let b = if p.try_comma() {
                p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?
            } else {
                // step defaults to 1 for numbers
                if matches!(a, Calc::Number(_)) { Calc::Number(1.0) } else { return p.invalid(); }
            };
            if let Some((x, y, unit)) = same_unit(&a, &b) {
                let r = round_val(strat, x, y);
                return Ok(mk_val(r, unit));
            }
            Ok(Calc::Func(Box::new(MathFn::Round(strat, a, b))))
        }
        "rem" | "mod" => {
            let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            p.expect_comma()?;
            let b = p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?;
            if let Some((x, y, unit)) = same_unit(&a, &b) {
                let r = if lname == "rem" { x % y } else { ((x % y) + y) % y };
                return Ok(mk_val(r, unit));
            }
            Ok(Calc::Func(Box::new(if lname == "rem" { MathFn::Rem(a, b) } else { MathFn::Mod(a, b) })))
        }
        "abs" => {
            let a = parse_sum(p, allowed)?;
            match &a {
                Calc::Value(d) => Ok(Calc::Value(Dim { v: d.v.abs(), unit: d.unit.clone() })),
                Calc::Number(n) => Ok(Calc::Number(n.abs())),
                _ => Ok(Calc::Func(Box::new(MathFn::Abs(a)))),
            }
        }
        "sign" => {
            let a = parse_sum(p, allowed | C_NUM | C_LEN | C_PCT | C_ANG | C_TIME | C_RES)?;
            match &a {
                Calc::Value(d) if d.cat() != Cat::Percent => Ok(Calc::Number(sign_of(d.v))),
                Calc::Number(n) => Ok(Calc::Number(sign_of(*n))),
                _ => Ok(Calc::Func(Box::new(MathFn::Sign(a)))),
            }
        }
        "hypot" => {
            let mut args = Vec::new();
            loop {
                args.push(p.parse_until_before(D_COMMA, |p| parse_sum(p, allowed))?);
                if !p.try_comma() {
                    break;
                }
            }
            // reduce if all same unit
            let first_unit = match &args[0] {
                Calc::Value(d) => Some(d.unit.clone()),
                Calc::Number(_) => Some(String::new()),
                _ => None,
            };
            if let Some(u) = first_unit {
                let mut sum = 0.0f32;
                let mut ok = true;
                for a in &args {
                    match a {
                        Calc::Value(d) if d.unit == u => sum += d.v * d.v,
                        Calc::Number(n) if u.is_empty() => sum += n * n,
                        _ => {
                            ok = false;
                            break;
                        }
                    }
                }
                if ok {
                    return Ok(mk_val(sum.sqrt(), &u));
                }
            }
            Ok(Calc::Func(Box::new(MathFn::Hypot(args))))
        }
        "sin" | "cos" | "tan" => {
            let a = parse_sum(p, C_ANG | C_NUM)?;
            let rad = match a {
                Calc::Number(n) => n,
                Calc::Value(d) if d.cat() == Cat::Angle => d.to_canonical().unwrap() * std::f32::consts::PI / 180.0,
                _ => return p.invalid(),
            };
            let v = match lname {
                "sin" => rad.sin(),
                "cos" => rad.cos(),
                _ => rad.tan(),
            };
            Ok(Calc::Number(round_trig(v)))
        }
        "asin" | "acos" | "atan" => {
            let a = parse_sum(p, C_NUM)?;
            let n = match a {
                Calc::Number(n) => n,
                _ => return p.invalid(),
            };
            let v = match lname {
                "asin" => n.asin(),
                "acos" => n.acos(),
                _ => n.atan(),
            };
            Ok(Calc::Value(Dim::new(v.to_degrees(), "deg")))
        }
        "atan2" => {
            let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM | C_LEN | C_ANG | C_TIME | C_PCT))?;
            p.expect_comma()?;
            let b = p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM | C_LEN | C_ANG | C_TIME | C_PCT))?;
            if let Some((x, y, _)) = same_unit(&a, &b) {
                return Ok(Calc::Value(Dim::new(x.atan2(y).to_degrees(), "deg")));
            }
            p.invalid()
        }
        "pow" => {
            let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM))?;
            p.expect_comma()?;
            let b = p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM))?;
            match (a, b) {
                (Calc::Number(x), Calc::Number(y)) => Ok(Calc::Number(x.powf(y))),
                _ => p.invalid(),
            }
        }
        "sqrt" => match parse_sum(p, C_NUM)? {
            Calc::Number(x) => Ok(Calc::Number(x.sqrt())),
            _ => p.invalid(),
        },
        "exp" => match parse_sum(p, C_NUM)? {
            Calc::Number(x) => Ok(Calc::Number(x.exp())),
            _ => p.invalid(),
        },
        "log" => {
            let a = p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM))?;
            let x = match a {
                Calc::Number(x) => x,
                _ => return p.invalid(),
            };
            if p.try_comma() {
                match p.parse_until_before(D_COMMA, |p| parse_sum(p, C_NUM))? {
                    Calc::Number(b) => Ok(Calc::Number(x.log(b))),
                    _ => p.invalid(),
                }
            } else {
                Ok(Calc::Number(x.ln()))
            }
        }
        _ => p.invalid(),
    }
}

fn round_trig(v: f32) -> f32 {
    // Round very small errors
    let r = (v * 1e6).round() / 1e6;
    if (r - v).abs() < 1e-6 { r } else { v }
}

fn sign_of(v: f32) -> f32 {
    if v > 0.0 {
        1.0
    } else if v < 0.0 {
        -1.0
    } else {
        v
    }
}

fn same_unit(a: &Calc, b: &Calc) -> Option<(f32, f32, String)> {
    match (a, b) {
        (Calc::Number(x), Calc::Number(y)) => Some((*x, *y, String::new())),
        (Calc::Value(x), Calc::Value(y)) => {
            if x.unit == y.unit {
                Some((x.v, y.v, x.unit.clone()))
            } else if x.cat() == y.cat() {
                let fx = abs_factor(&x.unit)?;
                let fy = abs_factor(&y.unit)?;
                Some((x.v * fx, y.v * fy, canonical_unit(x.cat()).to_string()))
            } else {
                None
            }
        }
        _ => None,
    }
}

fn mk_val(v: f32, unit: &str) -> Calc {
    if unit.is_empty() {
        Calc::Number(v)
    } else {
        Calc::Value(Dim::new(v, unit))
    }
}

fn round_val(s: RoundStrategy, x: f32, y: f32) -> f32 {
    if y == 0.0 {
        return f32::NAN;
    }
    let q = x / y;
    let r = match s {
        RoundStrategy::Nearest => {
            let f = q.floor();
            if q - f >= 0.5 { f + 1.0 } else { f }
        }
        RoundStrategy::Up => q.ceil(),
        RoundStrategy::Down => q.floor(),
        RoundStrategy::ToZero => q.trunc(),
    };
    r * y
}

pub fn parse_sum(p: &mut Parser, allowed: u8) -> PResult<Calc> {
    let mut cur = parse_product(p, allowed)?;
    loop {
        let st = p.state();
        match p.next_including_whitespace() {
            Ok(Token::WhiteSpace(_)) => {
                if p.is_exhausted() {
                    break;
                }
                match p.next() {
                    Ok(Token::Delim('+')) => {
                        // require whitespace after
                        match p.next_including_whitespace() {
                            Ok(Token::WhiteSpace(_)) => {}
                            _ => return p.invalid(),
                        }
                        let rhs = parse_product(p, allowed)?;
                        cur = cur.add(rhs);
                    }
                    Ok(Token::Delim('-')) => {
                        match p.next_including_whitespace() {
                            Ok(Token::WhiteSpace(_)) => {}
                            _ => return p.invalid(),
                        }
                        let rhs = parse_product(p, allowed)?;
                        cur = cur.add(rhs.mul(-1.0));
                    }
                    _ => return p.invalid(),
                }
            }
            _ => {
                p.reset(st);
                break;
            }
        }
    }
    // type check: a sum mixing number with dims is invalid
    if !sum_types_ok(&cur) {
        return p.invalid();
    }
    Ok(cur)
}

fn sum_types_ok(c: &Calc) -> bool {
    fn kind(c: &Calc) -> Option<bool> {
        // Some(true) = number, Some(false) = dimension, None = unknown/mixed ok
        match c {
            Calc::Number(_) => Some(true),
            Calc::Value(_) => Some(false),
            Calc::Product(_, c) => kind(c),
            Calc::Sum(a, b) => {
                let ka = kind(a);
                let kb = kind(b);
                match (ka, kb) {
                    (Some(x), Some(y)) if x != y => Some(true), // flag mismatch handled below
                    (Some(x), _) => Some(x),
                    (_, y) => y,
                }
            }
            Calc::Func(_) => None,
        }
    }
    fn check(c: &Calc) -> bool {
        match c {
            Calc::Sum(a, b) => {
                let ka = kind(a);
                let kb = kind(b);
                if let (Some(x), Some(y)) = (ka, kb) {
                    if x != y {
                        return false;
                    }
                }
                check(a) && check(b)
            }
            _ => true,
        }
    }
    check(c)
}

fn parse_product(p: &mut Parser, allowed: u8) -> PResult<Calc> {
    let mut node = parse_calc_value(p, allowed)?;
    loop {
        let st = p.state();
        match p.next() {
            Ok(Token::Delim('*')) => {
                let rhs = parse_calc_value(p, allowed)?;
                if let Calc::Number(n) = rhs {
                    node = node.mul(n);
                } else if let Calc::Number(n) = node {
                    node = rhs.mul(n);
                } else {
                    return p.invalid();
                }
            }
            Ok(Token::Delim('/')) => {
                let rhs = parse_calc_value(p, allowed)?;
                if let Calc::Number(n) = rhs {
                    if n == 0.0 {
                        return p.invalid();
                    }
                    node = node.mul(1.0 / n);
                } else {
                    return p.invalid();
                }
            }
            _ => {
                p.reset(st);
                break;
            }
        }
    }
    Ok(node)
}

fn parse_calc_value(p: &mut Parser, allowed: u8) -> PResult<Calc> {
    let loc = p.location();
    let t = p.next()?;
    if let Some(d) = parse_dim_token(t, allowed) {
        return Ok(Calc::Value(d));
    }
    match t {
        Token::Number { value, .. } => Ok(Calc::Number(*value)),
        Token::Ident(name) => {
            let v = match name.to_ascii_lowercase().as_str() {
                "e" => std::f32::consts::E,
                "pi" => std::f32::consts::PI,
                "infinity" => f32::INFINITY,
                "-infinity" => f32::NEG_INFINITY,
                "nan" => f32::NAN,
                _ => return Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
            };
            Ok(Calc::Number(v))
        }
        Token::ParenthesisBlock => p.parse_nested_block(|p| parse_sum(p, allowed)),
        Token::Function(name) if is_math_fn(name) => {
            let name = name.clone();
            let c = parse_math_function(p, &name, allowed)?;
            Ok(match c {
                Calc::Func(f) => match *f {
                    MathFn::Calc(inner) => inner,
                    other => Calc::Func(Box::new(other)),
                },
                c => c,
            })
        }
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
    }
}

// ------------- Typed numeric value -------------

/// A numeric value that may be a calc expression.
#[derive(Clone, Debug, PartialEq)]
pub enum NumVal {
    D(Dim),
    Calc(Box<Calc>),
}

impl NumVal {
    pub fn zero_px() -> NumVal {
        NumVal::D(Dim::px(0.0))
    }
    pub fn px(v: f32) -> NumVal {
        NumVal::D(Dim::px(v))
    }
    pub fn pct(v: f32) -> NumVal {
        NumVal::D(Dim::pct(v))
    }
    pub fn num(v: f32) -> NumVal {
        NumVal::D(Dim::num(v))
    }
    pub fn is_zero(&self) -> bool {
        matches!(self, NumVal::D(d) if d.v == 0.0)
    }
    pub fn dim(&self) -> Option<&Dim> {
        match self {
            NumVal::D(d) => Some(d),
            _ => None,
        }
    }
    pub fn from_calc(c: Calc) -> NumVal {
        match c {
            Calc::Value(d) => NumVal::D(d),
            Calc::Number(n) => NumVal::D(Dim::num(n)),
            c => NumVal::Calc(Box::new(c)),
        }
    }
    pub fn to_calc(&self) -> Calc {
        match self {
            NumVal::D(d) if d.unit.is_empty() => Calc::Number(d.v),
            NumVal::D(d) => Calc::Value(d.clone()),
            NumVal::Calc(c) => (**c).clone(),
        }
    }
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            NumVal::D(x) => x.to_css(d),
            NumVal::Calc(c) => c.to_css_top(d),
        }
    }
    pub fn mul(&self, f: f32) -> NumVal {
        NumVal::from_calc(self.to_calc().mul(f))
    }
    pub fn add(&self, o: &NumVal) -> NumVal {
        NumVal::from_calc(self.to_calc().add(o.to_calc()))
    }
    pub fn is_calc(&self) -> bool {
        matches!(self, NumVal::Calc(_))
    }
}

/// Parse a numeric value of given categories. `unitless_zero` allows a bare 0 for lengths.
pub fn parse_numval(p: &mut Parser, allowed: u8, unitless_zero: bool) -> PResult<NumVal> {
    let loc = p.location();
    let st = p.state();
    let t = p.next()?;
    if let Some(d) = parse_dim_token(t, allowed) {
        return Ok(NumVal::D(d));
    }
    match t {
        Token::Number { value, .. } => {
            if allowed & C_NUM != 0 {
                return Ok(NumVal::D(Dim::num(*value)));
            }
            if unitless_zero && *value == 0.0 && allowed & C_LEN != 0 {
                return Ok(NumVal::D(Dim::px(0.0)));
            }
            if unitless_zero && *value == 0.0 && allowed & C_ANG != 0 {
                return Ok(NumVal::D(Dim::new(0.0, "deg")));
            }
            Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc))
        }
        Token::Function(name) if is_math_fn(name) => {
            let name = name.clone();
            let c = parse_math_function(p, &name, allowed)?;
            // type check result
            if !calc_type_ok(&c, allowed) {
                p.reset(st);
                return Err(p.err_at(ErrorKind::InvalidValue, loc));
            }
            Ok(NumVal::from_calc(c))
        }
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
    }
}

fn calc_type_ok(c: &Calc, allowed: u8) -> bool {
    // the overall result must not be a bare number unless numbers allowed
    fn is_number(c: &Calc) -> Option<bool> {
        match c {
            Calc::Number(_) => Some(true),
            Calc::Value(_) => Some(false),
            Calc::Product(_, c) => is_number(c),
            Calc::Sum(a, b) => is_number(a).or(is_number(b)),
            Calc::Func(f) => match &**f {
                MathFn::Calc(c) | MathFn::Abs(c) => is_number(c),
                MathFn::Sign(_) => Some(true),
                MathFn::Min(v) | MathFn::Max(v) | MathFn::Hypot(v) => v.iter().find_map(is_number),
                MathFn::Clamp(a, b, c) => is_number(a).or(is_number(b)).or(is_number(c)),
                MathFn::Round(_, a, b) | MathFn::Rem(a, b) | MathFn::Mod(a, b) => is_number(a).or(is_number(b)),
            },
        }
    }
    match is_number(c) {
        Some(true) => allowed & C_NUM != 0,
        Some(false) => true,
        None => true,
    }
}

// Convenience parsers
pub fn parse_length(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_LEN, true)
}
pub fn parse_length_percentage(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_LEN | C_PCT, true)
}
pub fn parse_number(p: &mut Parser) -> PResult<f32> {
    match parse_numval(p, C_NUM, false)? {
        NumVal::D(d) => Ok(d.v),
        NumVal::Calc(_) => p.invalid(),
    }
}
pub fn parse_number_val(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_NUM, false)
}
pub fn parse_angle(p: &mut Parser, unitless_zero: bool) -> PResult<NumVal> {
    parse_numval(p, C_ANG, unitless_zero)
}
pub fn parse_time(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_TIME, false)
}
pub fn parse_percentage(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_PCT, false)
}
pub fn parse_integer(p: &mut Parser) -> PResult<i32> {
    let loc = p.location();
    let t = p.next()?;
    match t {
        Token::Number { int_value: Some(v), .. } => Ok(*v),
        Token::Function(name) if is_math_fn(name) => {
            let name = name.clone();
            match parse_math_function(p, &name, C_NUM)? {
                Calc::Number(n) => Ok(n.round() as i32),
                _ => p.invalid(),
            }
        }
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
    }
}

/// Number or percentage, percentage converted to number (e.g. opacity)
pub fn parse_number_or_percentage(p: &mut Parser) -> PResult<f32> {
    match parse_numval(p, C_NUM | C_PCT, false)? {
        NumVal::D(d) => Ok(d.v),
        NumVal::Calc(_) => p.invalid(),
    }
}

pub fn fmt_f32(v: f32) -> String {
    fmt_num(v)
}
