];

const D50_WHITE: [f32; 3] = [0.3457 / 0.3585, 1.0, (1.0 - 0.3457 - 0.3585) / 0.3585];

fn xyz_d50_to_lab(c: [f32; 3]) -> [f32; 3] {
    let e: f32 = 216.0 / 24389.0;
    let k: f32 = 24389.0 / 27.0;
    let x = [c[0] / D50_WHITE[0], c[1] / D50_WHITE[1], c[2] / D50_WHITE[2]];
    let f = |v: f32| if v > e { v.cbrt() } else { (k * v + 16.0) / 116.0 };
    let f0 = f(x[0]);
    let f1 = f(x[1]);
    let f2 = f(x[2]);
    [116.0 * f1 - 16.0, 500.0 * (f0 - f1), 200.0 * (f1 - f2)]
}

fn lab_to_xyz_d50(c: [f32; 3]) -> [f32; 3] {
    let k: f32 = 24389.0 / 27.0;
    let e: f32 = 216.0 / 24389.0;
    let f1 = (c[0] + 16.0) / 116.0;
    let f0 = c[1] / 500.0 + f1;
    let f2 = f1 - c[2] / 200.0;
    let x = if f0.powi(3) > e { f0.powi(3) } else { (116.0 * f0 - 16.0) / k };
    let y = if c[0] > k * e { ((c[0] + 16.0) / 116.0).powi(3) } else { c[0] / k };
    let z = if f2.powi(3) > e { f2.powi(3) } else { (116.0 * f2 - 16.0) / k };
    [x * D50_WHITE[0], y * D50_WHITE[1], z * D50_WHITE[2]]
}

fn to_polar(c: [f32; 3]) -> [f32; 3] {
    let h = c[2].atan2(c[1]).to_degrees();
    let h = if h < 0.0 { h + 360.0 } else { h };
    let ch = (c[1] * c[1] + c[2] * c[2]).sqrt();
    [c[0], ch, h]
}
fn from_polar(c: [f32; 3]) -> [f32; 3] {
    let h = c[2].to_radians();
    [c[0], c[1] * h.cos(), c[1] * h.sin()]
}

fn prophoto_lin(v: f32) -> f32 {
    let et2: f32 = 16.0 / 512.0;
    let a = v.abs();
    if a <= et2 { v / 16.0 } else { v.signum() * a.powf(1.8) }
}
fn prophoto_gam(v: f32) -> f32 {
    let et: f32 = 1.0 / 512.0;
    let a = v.abs();
    if a >= et { v.signum() * a.powf(1.0 / 1.8) } else { 16.0 * v }
}
fn a98_lin(v: f32) -> f32 {
    v.signum() * v.abs().powf(563.0 / 256.0)
}
fn a98_gam(v: f32) -> f32 {
    v.signum() * v.abs().powf(256.0 / 563.0)
}
fn rec2020_lin(v: f32) -> f32 {
    let a: f32 = 1.09929682680944;
    let b: f32 = 0.018053968510807;
    let x = v.abs();
    if x < b * 4.5 { v / 4.5 } else { v.signum() * ((x + a - 1.0) / a).powf(1.0 / 0.45) }
}
fn rec2020_gam(v: f32) -> f32 {
    let a: f32 = 1.09929682680944;
    let b: f32 = 0.018053968510807;
    let x = v.abs();
    if x > b { v.signum() * (a * x.powf(0.45) - (a - 1.0)) } else { 4.5 * v }
}

fn map3(c: [f32; 3], f: fn(f32) -> f32) -> [f32; 3] {
    [f(c[0]), f(c[1]), f(c[2])]
}

/// Convert to XYZ D65
fn to_xyz65(sp: Space, c: [f32; 3]) -> [f32; 3] {
    match sp {
        Space::Srgb => mul3(&LIN_SRGB_TO_XYZ, map3(c, lin_srgb)),
        Space::SrgbLinear => mul3(&LIN_SRGB_TO_XYZ, c),
        Space::DisplayP3 => mul3(&LIN_P3_TO_XYZ, map3(c, lin_srgb)),
        Space::A98 => mul3(&LIN_A98_TO_XYZ, map3(c, a98_lin)),
        Space::ProPhoto => mul3(&D50_TO_D65, mul3(&LIN_PROPHOTO_TO_XYZ_D50, map3(c, prophoto_lin))),
        Space::Rec2020 => mul3(&LIN_REC2020_TO_XYZ, map3(c, rec2020_lin)),
        Space::XyzD50 => mul3(&D50_TO_D65, c),
        Space::XyzD65 => c,
        Space::Lab => mul3(&D50_TO_D65, lab_to_xyz_d50(c)),
        Space::Lch => mul3(&D50_TO_D65, lab_to_xyz_d50(from_polar(c))),
        Space::Oklab => oklab_to_xyz(c),
        Space::Oklch => oklab_to_xyz(from_polar(c)),
        Space::Hsl => to_xyz65(Space::Srgb, hsl_to_srgb(c)),
        Space::Hwb => to_xyz65(Space::Srgb, hwb_to_srgb(c)),
    }
}

fn oklab_to_xyz(c: [f32; 3]) -> [f32; 3] {
    let lms = mul3(&OKLAB_TO_LMS, c);
    mul3(&LMS_TO_XYZ, [lms[0].powi(3), lms[1].powi(3), lms[2].powi(3)])
}
fn xyz_to_oklab(c: [f32; 3]) -> [f32; 3] {
    let lms = mul3(&XYZ_TO_LMS, c);
    mul3(&LMS_TO_OKLAB, [lms[0].cbrt(), lms[1].cbrt(), lms[2].cbrt()])
}

fn from_xyz65(sp: Space, x: [f32; 3]) -> [f32; 3] {
    match sp {
        Space::Srgb => map3(mul3(&XYZ_TO_LIN_SRGB, x), gam_srgb),
        Space::SrgbLinear => mul3(&XYZ_TO_LIN_SRGB, x),
        Space::DisplayP3 => map3(mul3(&XYZ_TO_LIN_P3, x), gam_srgb),
        Space::A98 => map3(mul3(&XYZ_TO_LIN_A98, x), a98_gam),
        Space::ProPhoto => map3(mul3(&XYZ_D50_TO_LIN_PROPHOTO, mul3(&D65_TO_D50, x)), prophoto_gam),
        Space::Rec2020 => map3(mul3(&XYZ_TO_LIN_REC2020, x), rec2020_gam),
        Space::XyzD50 => mul3(&D65_TO_D50, x),
        Space::XyzD65 => x,
        Space::Lab => xyz_d50_to_lab(mul3(&D65_TO_D50, x)),
        Space::Lch => to_polar(xyz_d50_to_lab(mul3(&D65_TO_D50, x))),
        Space::Oklab => xyz_to_oklab(x),
        Space::Oklch => to_polar(xyz_to_oklab(x)),
        Space::Hsl => srgb_to_hsl(from_xyz65(Space::Srgb, x)),
        Space::Hwb => srgb_to_hwb(from_xyz65(Space::Srgb, x)),
    }
}

pub fn convert(from: Space, c: [f32; 3], to: Space) -> [f32; 3] {
    if from == to {
        return c;
    }
    let c0 = c;
    let c = resolve_none(c);
    // fast paths that keep precision
    let r = match (from, to) {
        (Space::Lab, Space::Lch) => to_polar(c),
        (Space::Lch, Space::Lab) => from_polar(c),
        (Space::Oklab, Space::Oklch) => to_polar(c),
        (Space::Oklch, Space::Oklab) => from_polar(c),
        (Space::Srgb, Space::Hsl) => srgb_to_hsl(c),
        (Space::Srgb, Space::Hwb) => srgb_to_hwb(c),
        (Space::Hsl, Space::Srgb) => hsl_to_srgb(c),
        (Space::Hwb, Space::Srgb) => hwb_to_srgb(c),
        _ => from_xyz65(to, to_xyz65(from, c)),
    };
    let _ = c0;
    r
}

fn in_gamut(c: [f32; 3]) -> bool {
    let e = 0.00001;
    c.iter().all(|v| *v >= -e && *v <= 1.0 + e)
}

fn clip(c: [f32; 3]) -> [f32; 3] {
    [c[0].clamp(0.0, 1.0), c[1].clamp(0.0, 1.0), c[2].clamp(0.0, 1.0)]
}

fn delta_eok(a: [f32; 3], b: [f32; 3]) -> f32 {
    // a, b in oklab
    let dl = a[0] - b[0];
    let da = a[1] - b[1];
    let db = a[2] - b[2];
    (dl * dl + da * da + db * db).sqrt()
}

/// Gamut map color in `sp` to rgb-like space `dest` per CSS Color 4.
pub fn gamut_map(sp: Space, c: [f32; 3], dest: Space) -> [f32; 3] {
    let conv = convert(sp, c, dest);
    if in_gamut(conv) {
        return conv;
    }
    let mut cur = convert(sp, c, Space::Oklch);
    if cur[0] >= 1.0 {
        return [1.0, 1.0, 1.0];
    }
    if cur[0] <= 0.0 {
        return [0.0, 0.0, 0.0];
    }
    let jnd = 0.02;
    let eps = 0.0001;
    let mut min = 0.0f32;
    let mut max = cur[1];
    let mut min_in_gamut = true;
    let to_dest = |c: [f32; 3]| convert(Space::Oklch, c, dest);
    let ok_of_dest = |c: [f32; 3]| convert(dest, c, Space::Oklab);
    let mut clipped = clip(to_dest(cur));
    let e = delta_eok(ok_of_dest(clipped), convert(Space::Oklch, cur, Space::Oklab));
    if e < jnd {
        return clipped;
    }
    while max - min > eps {
        let chroma = (min + max) / 2.0;
        cur[1] = chroma;
        let converted = to_dest(cur);
        if min_in_gamut && in_gamut(converted) {
            min = chroma;
            continue;
        }
        clipped = clip(converted);
        let e = delta_eok(ok_of_dest(clipped), convert(Space::Oklch, cur, Space::Oklab));
        if e < jnd {
            if jnd - e < eps {
                return clipped;
            }
            min_in_gamut = false;
            min = chroma;
        } else {
            max = chroma;
        }
    }
    clipped
}
