// CSS colors: parsing, conversion, serialization.
use crate::named_colors;
use crate::parser::*;
use crate::printer::Printer;
use crate::tokenizer::Token;
use crate::values::*;
use std::cell::RefCell;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Space {
    Srgb,
    SrgbLinear,
    DisplayP3,
    A98,
    ProPhoto,
    Rec2020,
    XyzD50,
    XyzD65,
    Lab,
    Lch,
    Oklab,
    Oklch,
    Hsl,
    Hwb,
}

impl Space {
    pub fn predefined_name(&self) -> &'static str {
        match self {
            Space::Srgb => "srgb",
            Space::SrgbLinear => "srgb-linear",
            Space::DisplayP3 => "display-p3",
            Space::A98 => "a98-rgb",
            Space::ProPhoto => "prophoto-rgb",
            Space::Rec2020 => "rec2020",
            Space::XyzD50 => "xyz-d50",
            Space::XyzD65 => "xyz",
            _ => "",
        }
    }
    pub fn is_polar(&self) -> bool {
        matches!(self, Space::Lch | Space::Oklch | Space::Hsl | Space::Hwb)
    }
    pub fn hue_index(&self) -> usize {
        match self {
            Space::Lch | Space::Oklch => 2,
            Space::Hsl | Space::Hwb => 0,
            _ => 99,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum CssColor {
    CurrentColor,
    Rgba(u8, u8, u8, u8),
    /// lab, lch, oklab, oklch, and predefined spaces. components may be NaN for none.
    Space(Space, [f32; 3], f32),
    LightDark(Box<CssColor>, Box<CssColor>),
    System(String),
}

thread_local! {
    pub static HEX_ALPHA_SUPPORTED: RefCell<bool> = RefCell::new(true);
}

pub fn is_none(v: f32) -> bool {
    v.is_nan()
}

impl CssColor {
    pub fn transparent() -> CssColor {
        CssColor::Rgba(0, 0, 0, 0)
    }
    pub fn black() -> CssColor {
        CssColor::Rgba(0, 0, 0, 255)
    }

    pub fn parse(p: &mut Parser) -> PResult<CssColor> {
        let loc = p.location();
        let t = p.next()?;
        match t {
            Token::Hash(h) | Token::IDHash(h) => parse_hash(h).ok_or_else(|| p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
            Token::Ident(name) => {
                let l = name.to_ascii_lowercase();
                if l == "currentcolor" {
                    return Ok(CssColor::CurrentColor);
                }
                if l == "transparent" {
                    return Ok(CssColor::Rgba(0, 0, 0, 0));
                }
                if let Some((r, g, b)) = named_colors::lookup(&l) {
                    return Ok(CssColor::Rgba(r, g, b, 255));
                }
                if named_colors::SYSTEM_COLORS.contains(&l.as_str()) {
                    return Ok(CssColor::System(l));
                }
                Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc))
            }
            Token::Function(name) => {
                let l = name.to_ascii_lowercase();
                p.parse_nested_block(|p| parse_color_function(p, &l))
            }
            _ => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }

    pub fn is_current_color(&self) -> bool {
        matches!(self, CssColor::CurrentColor)
    }

    pub fn to_css(&self, d: &mut Printer) {
        match self {
            CssColor::CurrentColor => d.write_str("currentColor"),
            CssColor::Rgba(r, g, b, a) => write_rgba(d, *r, *g, *b, *a),
            CssColor::System(s) => d.write_str(s),
            CssColor::LightDark(a, b) => {
                if crate::targets::should_compile_light_dark() {
                    d.write_str("var(--lightningcss-light");
                    d.delim(',', false);
                    a.to_css(d);
                    d.write_char(')');
                    d.whitespace();
                    d.write_str("var(--lightningcss-dark");
                    d.delim(',', false);
                    b.to_css(d);
                    d.write_char(')');
                } else {
                    d.write_str("light-dark(");
                    a.to_css(d);
                    d.delim(',', false);
                    b.to_css(d);
                    d.write_char(')');
                }
            }
            CssColor::Space(sp, c, alpha) => {
                match sp {
                    Space::Lab | Space::Lch | Space::Oklab | Space::Oklch => {
                        let name = match sp {
                            Space::Lab => "lab(",
                            Space::Lch => "lch(",
                            Space::Oklab => "oklab(",
                            _ => "oklch(",
                        };
                        d.write_str(name);
                        let lscale = if matches!(sp, Space::Oklab | Space::Oklch) { 100.0 } else { 1.0 };
                        if is_none(c[0]) {
                            d.write_str("none");
                        } else {
                            d.write_num(c[0] * lscale);
                            d.write_char('%');
                        }
                        d.write_char(' ');
                        write_comp(d, c[1]);
                        d.write_char(' ');
                        write_comp(d, c[2]);
                    }
                    Space::Hsl | Space::Hwb => {
                        // should not normally be printed; convert
                        let (r, g, b, a) = self.to_rgba_u8();
                        write_rgba(d, r, g, b, a);
                        return;
                    }
                    _ => {
                        d.write_str("color(");
                        d.write_str(sp.predefined_name());
                        d.write_char(' ');
                        write_comp(d, c[0]);
                        d.write_char(' ');
                        write_comp(d, c[1]);
                        d.write_char(' ');
                        write_comp(d, c[2]);
                    }
                }
                if is_none(*alpha) || *alpha != 1.0 {
                    d.delim('/', true);
                    write_comp(d, *alpha);
                }
                d.write_char(')');
            }
        }
    }

    /// Convert to sRGB float components (r,g,b in 0..1), alpha, with gamut mapping
    pub fn to_srgb_mapped(&self) -> Option<([f32; 3], f32)> {
        match self {
            CssColor::Rgba(r, g, b, a) => Some(([*r as f32 / 255.0, *g as f32 / 255.0, *b as f32 / 255.0], *a as f32 / 255.0)),
            CssColor::Space(sp, c, a) => {
                let c = resolve_none(*c);
                let rgb = gamut_map(*sp, c, Space::Srgb);
                Some((rgb, if a.is_nan() { 0.0 } else { *a }))
            }
            _ => None,
        }
    }

    pub fn to_rgba_u8(&self) -> (u8, u8, u8, u8) {
        match self.to_srgb_mapped() {
            Some((c, a)) => (to_u8(c[0]), to_u8(c[1]), to_u8(c[2]), to_u8(a)),
            None => (0, 0, 0, 0),
        }
    }

    pub fn to_rgba(&self) -> CssColor {
        match self {
            CssColor::Rgba(..) => self.clone(),
            CssColor::Space(..) => {
                let (r, g, b, a) = self.to_rgba_u8();
                CssColor::Rgba(r, g, b, a)
            }
            _ => self.clone(),
        }
    }

    /// Convert into given space (unmapped), returning components and alpha
    pub fn to_space(&self, target: Space) -> Option<([f32; 3], f32)> {
        let (sp, c, a) = match self {
            CssColor::Rgba(r, g, b, a) => (Space::Srgb, [*r as f32 / 255.0, *g as f32 / 255.0, *b as f32 / 255.0], *a as f32 / 255.0),
            CssColor::Space(sp, c, a) => (*sp, *c, *a),
            _ => return None,
        };
        Some((convert(sp, c, target), a))
    }

    pub fn to_lab(&self) -> CssColor {
        match self.to_space(Space::Lab) {
            Some((c, a)) => CssColor::Space(Space::Lab, c, a),
            None => self.clone(),
        }
    }
    pub fn to_p3(&self) -> CssColor {
        match self {
            CssColor::Space(sp, c, a) => {
                let c = resolve_none(*c);
                let m = gamut_map(*sp, c, Space::DisplayP3);
                CssColor::Space(Space::DisplayP3, m, *a)
            }
            _ => self.clone(),
        }
    }
}

fn to_u8(v: f32) -> u8 {
    let x = (v * 255.0).round();
    if x.is_nan() {
        0
    } else {
        x.clamp(0.0, 255.0) as u8
    }
}

fn resolve_none(c: [f32; 3]) -> [f32; 3] {
    [nz(c[0]), nz(c[1]), nz(c[2])]
}
fn nz(v: f32) -> f32 {
    if v.is_nan() { 0.0 } else { v }
}

fn write_comp(d: &mut Printer, v: f32) {
    if is_none(v) {
        d.write_str("none");
    } else {
        d.write_num(v);
    }
}

pub fn write_rgba(d: &mut Printer, r: u8, g: u8, b: u8, a: u8) {
    if a == 255 {
        let hex = hex_string(r, g, b, None);
        if let Some(name) = named_colors::name_for((r, g, b)) {
            if name.len() < hex.len() {
                d.write_str(name);
                return;
            }
        }
        d.write_str(&hex);
    } else {
        let hex_ok = HEX_ALPHA_SUPPORTED.with(|h| *h.borrow());
        if hex_ok {
            d.write_str(&hex_string(r, g, b, Some(a)));
        } else if r == 0 && g == 0 && b == 0 && a == 0 {
            d.write_str("transparent");
        } else {
            d.write_str("rgba(");
            d.write_str(&r.to_string());
            d.delim(',', false);
            d.write_str(&g.to_string());
            d.delim(',', false);
            d.write_str(&b.to_string());
            d.delim(',', false);
            let al = serialize_alpha(a);
            d.write_num(al);
            d.write_char(')');
        }
    }
}

pub fn serialize_alpha(a: u8) -> f32 {
    let alpha = a as f32 / 255.0;
    let mut rounded = (alpha * 100.0).round() / 100.0;
    if to_u8(rounded) != a {
        rounded = (alpha * 1000.0).round() / 1000.0;
    }
    rounded
}

fn hex_string(r: u8, g: u8, b: u8, a: Option<u8>) -> String {
    let short = |v: u8| v >> 4 == v & 0xF;
    let all_short = short(r) && short(g) && short(b) && a.map(short).unwrap_or(true);
    if all_short {
        match a {
            Some(a) => format!("#{:x}{:x}{:x}{:x}", r & 0xF, g & 0xF, b & 0xF, a & 0xF),
            None => format!("#{:x}{:x}{:x}", r & 0xF, g & 0xF, b & 0xF),
        }
    } else {
        match a {
            Some(a) => format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a),
            None => format!("#{:02x}{:02x}{:02x}", r, g, b),
        }
    }
}

fn parse_hash(h: &str) -> Option<CssColor> {
    let b = h.as_bytes();
    if !b.iter().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let hv = |c: u8| (c as char).to_digit(16).unwrap() as u8;
    match b.len() {
        3 => Some(CssColor::Rgba(hv(b[0]) * 17, hv(b[1]) * 17, hv(b[2]) * 17, 255)),
        4 => Some(CssColor::Rgba(hv(b[0]) * 17, hv(b[1]) * 17, hv(b[2]) * 17, hv(b[3]) * 17)),
        6 => Some(CssColor::Rgba(hv(b[0]) * 16 + hv(b[1]), hv(b[2]) * 16 + hv(b[3]), hv(b[4]) * 16 + hv(b[5]), 255)),
        8 => Some(CssColor::Rgba(
            hv(b[0]) * 16 + hv(b[1]),
            hv(b[2]) * 16 + hv(b[3]),
            hv(b[4]) * 16 + hv(b[5]),
            hv(b[6]) * 16 + hv(b[7]),
        )),
        _ => None,
    }
}

// ---------------- relative color channel bindings ----------------
thread_local! {
    pub static CHANNELS: RefCell<Vec<(String, Dim)>> = RefCell::new(Vec::new());
}

pub fn lookup_channel(name: &str) -> Option<Dim> {
    CHANNELS.with(|c| c.borrow().iter().rev().find(|(n, _)| n.eq_ignore_ascii_case(name)).map(|(_, d)| d.clone()))
}

struct ChannelGuard(usize);
impl Drop for ChannelGuard {
    fn drop(&mut self) {
        CHANNELS.with(|c| c.borrow_mut().truncate(self.0));
    }
}
fn bind_channels(v: Vec<(String, Dim)>) -> ChannelGuard {
    CHANNELS.with(|c| {
        let mut c = c.borrow_mut();
        let n = c.len();
        c.extend(v);
        ChannelGuard(n)
    })
}

/// Component kinds
#[derive(Clone, Copy)]
enum Comp {
    /// number with given percentage reference (100% = ref)
    NumPct(f32),
    Hue,
}

fn parse_component(p: &mut Parser, kind: Comp, allow_none: bool) -> PResult<f32> {
    if allow_none && p.try_ident_matching("none") {
        return Ok(f32::NAN);
    }
    match kind {
        Comp::NumPct(r) => {
            let v = parse_numval(p, C_NUM | C_PCT, false)?;
            match v {
                NumVal::D(d) if d.unit == "%" => Ok(d.v * r),
                NumVal::D(d) => Ok(d.v),
                _ => p.invalid(),
            }
        }
        Comp::Hue => {
            let v = parse_numval(p, C_NUM | C_ANG, false)?;
            match v {
                NumVal::D(d) if d.unit.is_empty() => Ok(d.v),
                NumVal::D(d) => Ok(d.to_canonical().unwrap_or(d.v)),
                _ => p.invalid(),
            }
        }
    }
}

fn parse_alpha(p: &mut Parser, allow_none: bool) -> PResult<f32> {
    parse_component(p, Comp::NumPct(1.0), allow_none)
}

fn parse_color_function(p: &mut Parser, name: &str) -> PResult<CssColor> {
    match name {
        "rgb" | "rgba" => parse_rgb(p),
        "hsl" | "hsla" => parse_hsl_hwb(p, Space::Hsl),
        "hwb" => parse_hsl_hwb(p, Space::Hwb),
        "lab" => parse_lab(p, Space::Lab),
        "lch" => parse_lab(p, Space::Lch),
        "oklab" => parse_lab(p, Space::Oklab),
        "oklch" => parse_lab(p, Space::Oklch),
        "color" => parse_color_fn(p),
        "color-mix" => parse_color_mix(p),
        "light-dark" => {
            let a = p.parse_until_before(D_COMMA, CssColor::parse)?;
            p.expect_comma()?;
            let b = CssColor::parse(p)?;
            Ok(CssColor::LightDark(Box::new(a), Box::new(b)))
        }
        _ => p.invalid(),
    }
}

fn parse_from(p: &mut Parser) -> PResult<Option<CssColor>> {
    if p.try_ident_matching("from") {
        let c = CssColor::parse(p)?;
        match c {
            CssColor::Rgba(..) | CssColor::Space(..) => Ok(Some(c)),
            _ => p.invalid(),
        }
    } else {
        Ok(None)
    }
}

fn parse_rgb(p: &mut Parser) -> PResult<CssColor> {
    let from = parse_from(p)?;
    let _g;
    if let Some(f) = &from {
        let (c, a) = f.to_space(Space::Srgb).unwrap();
        _g = bind_channels(vec![
            ("r".into(), Dim::num(c[0] * 255.0)),
            ("g".into(), Dim::num(c[1] * 255.0)),
            ("b".into(), Dim::num(c[2] * 255.0)),
            ("alpha".into(), Dim::num(a)),
        ]);
    }
    // detect legacy syntax: first component followed by comma
    let st = p.state();
    let first_is_pct;
    let r = {
        if p.try_ident_matching("none") {
            first_is_pct = None;
            f32::NAN
        } else {
            let v = parse_numval(p, C_NUM | C_PCT, false)?;
            match v {
                NumVal::D(d) if d.unit == "%" => {
                    first_is_pct = Some(true);
                    d.v * 255.0
                }
                NumVal::D(d) => {
                    first_is_pct = Some(false);
                    d.v
                }
                _ => return p.invalid(),
            }
        }
    };
    let _ = st;
    if from.is_none() && first_is_pct.is_some() && p.try_comma() {
        // legacy
        let pct = first_is_pct.unwrap();
        let comp = |p: &mut Parser| -> PResult<f32> {
            let v = parse_numval(p, if pct { C_PCT } else { C_NUM }, false)?;
            match v {
                NumVal::D(d) if d.unit == "%" => Ok(d.v * 255.0),
                NumVal::D(d) => Ok(d.v),
                _ => p.invalid(),
            }
        };
        let g = comp(p)?;
        p.expect_comma()?;
        let b = comp(p)?;
        let a = if p.try_comma() { parse_alpha(p, false)? } else { 1.0 };
        return Ok(rgba_from_f(r, g, b, a));
    }
    let g = parse_component(p, Comp::NumPct(255.0), true)?;
    let b = parse_component(p, Comp::NumPct(255.0), true)?;
    let a = if p.try_delim('/') { parse_alpha(p, true)? } else if from.is_some() { lookup_channel("alpha").map(|d| d.v).unwrap_or(1.0) } else { 1.0 };
    Ok(rgba_from_f(nz(r), nz(g), nz(b), nz(a)))
}

fn rgba_from_f(r: f32, g: f32, b: f32, a: f32) -> CssColor {
    let c = |v: f32| -> u8 {
        let x = v.round();
        if x.is_nan() { 0 } else { x.clamp(0.0, 255.0) as u8 }
    };
    CssColor::Rgba(c(r), c(g), c(b), to_u8(a.clamp(0.0, 1.0)))
}

fn parse_hsl_hwb(p: &mut Parser, sp: Space) -> PResult<CssColor> {
    let from = parse_from(p)?;
    let _g;
    if let Some(f) = &from {
        let (c, a) = f.to_space(sp).unwrap();
        let names: [&str; 3] = if sp == Space::Hsl { ["h", "s", "l"] } else { ["h", "w", "b"] };
        _g = bind_channels(vec![
            (names[0].into(), Dim::new(nz(c[0]), "deg")),
            (names[1].into(), Dim::pct(nz(c[1]))),
            (names[2].into(), Dim::pct(nz(c[2]))),
            ("alpha".into(), Dim::num(a)),
        ]);
    }
    let h = parse_component(p, Comp::Hue, true)?;
    let legacy = from.is_none() && sp == Space::Hsl && !h.is_nan() && p.try_comma();
    let (s, l, a);
    if legacy {
        s = parse_numval(p, C_PCT, false).and_then(|v| v.dim().map(|d| d.v).ok_or_else(|| p.err(ErrorKind::InvalidValue)))?;
        p.expect_comma()?;
        l = parse_numval(p, C_PCT, false).and_then(|v| v.dim().map(|d| d.v).ok_or_else(|| p.err(ErrorKind::InvalidValue)))?;
        a = if p.try_comma() { parse_alpha(p, false)? } else { 1.0 };
    } else {
        s = parse_component(p, Comp::NumPct(1.0), true).map(|v| v)?;
        l = parse_component(p, Comp::NumPct(1.0), true)?;
        a = if p.try_delim('/') { parse_alpha(p, true)? } else if from.is_some() { lookup_channel("alpha").map(|d| d.v).unwrap_or(1.0) } else { 1.0 };
    }
    // numbers in modern syntax are percentages (0-100)
    let fix = |v: f32, was_pct: bool| if was_pct { v } else { v };
    let _ = fix;
    let c = [nz(h), nz(s), nz(l)];
    let rgb = if sp == Space::Hsl { hsl_to_srgb(c) } else { hwb_to_srgb(c) };
    Ok(CssColor::Rgba(to_u8(rgb[0]), to_u8(rgb[1]), to_u8(rgb[2]), to_u8(nz(a).clamp(0.0, 1.0))))
}

fn parse_lab(p: &mut Parser, sp: Space) -> PResult<CssColor> {
    let from = parse_from(p)?;
    let _g;
    let ok = matches!(sp, Space::Oklab | Space::Oklch);
    if let Some(f) = &from {
        let (c, a) = f.to_space(sp).unwrap();
        let names: [&str; 3] = match sp {
            Space::Lab | Space::Oklab => ["l", "a", "b"],
            _ => ["l", "c", "h"],
        };
        let third = if sp.is_polar() { Dim::new(nz(c[2]), "deg") } else { Dim::num(nz(c[2])) };
        _g = bind_channels(vec![
            (names[0].into(), Dim::num(nz(c[0]))),
            (names[1].into(), Dim::num(nz(c[1]))),
            (names[2].into(), third),
            ("alpha".into(), Dim::num(a)),
        ]);
    }
    let lref = if ok { 1.0 } else { 100.0 };
    let l = parse_component(p, Comp::NumPct(lref), true)?;
    let (c1, c2);
    match sp {
        Space::Lab => {
            c1 = parse_component(p, Comp::NumPct(125.0), true)?;
            c2 = parse_component(p, Comp::NumPct(125.0), true)?;
        }
        Space::Oklab => {
            c1 = parse_component(p, Comp::NumPct(0.4), true)?;
            c2 = parse_component(p, Comp::NumPct(0.4), true)?;
        }
        Space::Lch => {
            c1 = parse_component(p, Comp::NumPct(150.0), true)?;
            c2 = parse_component(p, Comp::Hue, true)?;
        }
        _ => {
            c1 = parse_component(p, Comp::NumPct(0.4), true)?;
            c2 = parse_component(p, Comp::Hue, true)?;
        }
    }
    let a = if p.try_delim('/') { parse_alpha(p, true)? } else if from.is_some() { lookup_channel("alpha").map(|d| d.v).unwrap_or(1.0) } else { 1.0 };
    let l = if l.is_nan() { l } else { l.max(0.0) };
    let c1 = if sp.is_polar() && !c1.is_nan() { c1.max(0.0) } else { c1 };
    let a = if a.is_nan() { a } else { a.clamp(0.0, 1.0) };
    Ok(CssColor::Space(sp, [l, c1, c2], a))
}

fn parse_predefined_space(name: &str) -> Option<Space> {
    Some(match name.to_ascii_lowercase().as_str() {
        "srgb" => Space::Srgb,
        "srgb-linear" => Space::SrgbLinear,
        "display-p3" => Space::DisplayP3,
        "a98-rgb" => Space::A98,
        "prophoto-rgb" => Space::ProPhoto,
        "rec2020" => Space::Rec2020,
        "xyz-d50" => Space::XyzD50,
        "xyz" | "xyz-d65" => Space::XyzD65,
        _ => return None,
    })
}

fn parse_color_fn(p: &mut Parser) -> PResult<CssColor> {
    let from = parse_from(p)?;
    let sp = parse_predefined_space(p.expect_ident()?).ok_or_else(|| p.err(ErrorKind::InvalidValue))?;
    let _g;
    if let Some(f) = &from {
        let (c, a) = f.to_space(sp).unwrap();
        let names: [&str; 3] = if matches!(sp, Space::XyzD50 | Space::XyzD65) { ["x", "y", "z"] } else { ["r", "g", "b"] };
        _g = bind_channels(vec![
            (names[0].into(), Dim::num(nz(c[0]))),
            (names[1].into(), Dim::num(nz(c[1]))),
            (names[2].into(), Dim::num(nz(c[2]))),
            ("alpha".into(), Dim::num(a)),
        ]);
    }
    let a0 = parse_component(p, Comp::NumPct(1.0), true)?;
    let a1 = parse_component(p, Comp::NumPct(1.0), true)?;
    let a2 = parse_component(p, Comp::NumPct(1.0), true)?;
    let a = if p.try_delim('/') { parse_alpha(p, true)? } else if from.is_some() { lookup_channel("alpha").map(|d| d.v).unwrap_or(1.0) } else { 1.0 };
    let a = if a.is_nan() { a } else { a.clamp(0.0, 1.0) };
    Ok(CssColor::Space(sp, [a0, a1, a2], a))
}

#[derive(Clone, Copy, PartialEq)]
enum HueMethod {
    Shorter,
    Longer,
    Increasing,
    Decreasing,
}

fn parse_color_mix(p: &mut Parser) -> PResult<CssColor> {
    p.expect_ident_matching("in")?;
    let sname = p.expect_ident()?.to_ascii_lowercase();
    let sp = match sname.as_str() {
        "srgb" => Space::Srgb,
        "srgb-linear" => Space::SrgbLinear,
        "lab" => Space::Lab,
        "lch" => Space::Lch,
        "oklab" => Space::Oklab,
        "oklch" => Space::Oklch,
        "hsl" => Space::Hsl,
        "hwb" => Space::Hwb,
        "xyz" | "xyz-d65" => Space::XyzD65,
        "xyz-d50" => Space::XyzD50,
        _ => return p.invalid(),
    };
    let mut hm = HueMethod::Shorter;
    if sp.is_polar() {
        if let Ok(m) = p.try_parse(|p| {
            let m = match p.expect_ident()?.to_ascii_lowercase().as_str() {
                "shorter" => HueMethod::Shorter,
                "longer" => HueMethod::Longer,
                "increasing" => HueMethod::Increasing,
                "decreasing" => HueMethod::Decreasing,
                _ => return p.invalid(),
            };
            p.expect_ident_matching("hue")?;
            Ok(m)
        }) {
            hm = m;
        }
    }
    p.expect_comma()?;
    let parse_item = |p: &mut Parser| -> PResult<(CssColor, Option<f32>)> {
        let pct1 = p.try_parse(|p| parse_numval(p, C_PCT, false)).ok();
        let c = CssColor::parse(p)?;
        let pct = match pct1 {
            Some(v) => Some(v),
            None => p.try_parse(|p| parse_numval(p, C_PCT, false)).ok(),
        };
        let pct = match pct {
            Some(NumVal::D(d)) => Some(d.v),
            Some(_) => return p.invalid(),
            None => None,
        };
        Ok((c, pct))
    };
    let (c1, p1) = p.parse_until_before(D_COMMA, parse_item)?;
    p.expect_comma()?;
    let (c2, p2) = parse_item(p)?;
    // only concrete colors
    for c in [&c1, &c2] {
        if !matches!(c, CssColor::Rgba(..) | CssColor::Space(..)) {
            return p.invalid();
        }
    }
    if matches!(p1, Some(x) if !(0.0..=1.0).contains(&x)) || matches!(p2, Some(x) if !(0.0..=1.0).contains(&x)) {
        return p.invalid();
    }
    let (p1, p2) = match (p1, p2) {
        (None, None) => (0.5, 0.5),
        (Some(a), None) => (a, 1.0 - a),
        (None, Some(b)) => (1.0 - b, b),
        (Some(a), Some(b)) => (a, b),
    };
    let total = p1 + p2;
    if total == 0.0 {
        return p.invalid();
    }
    let alpha_mult = if total < 1.0 { total } else { 1.0 };
    let (w1, w2) = (p1 / total, p2 / total);
    let _ = w1;
    let (mut a, aa) = c1.to_space(sp).unwrap();
    let (mut b, ba) = c2.to_space(sp).unwrap();
    // handle none: missing components take the other's value
    for i in 0..3 {
        if a[i].is_nan() && !b[i].is_nan() {
            a[i] = b[i];
        } else if b[i].is_nan() && !a[i].is_nan() {
            b[i] = a[i];
        }
    }
    // achromatic hue handling for polar spaces
    let hi = sp.hue_index();
    if sp.is_polar() {
        fix_powerless(sp, &mut a);
        fix_powerless(sp, &mut b);
        if a[hi].is_nan() && !b[hi].is_nan() {
            a[hi] = b[hi];
        } else if b[hi].is_nan() && !a[hi].is_nan() {
            b[hi] = a[hi];
        }
    }
    let (aa, ba) = (nz(aa), nz(ba));
    // premultiply
    let premul = |c: &mut [f32; 3], al: f32| {
        for i in 0..3 {
            if i != hi {
                c[i] *= al;
            }
        }
    };
    premul(&mut a, aa);
    premul(&mut b, ba);
    if sp.is_polar() {
        let (h1, h2) = adjust_hue(nz(a[hi]), nz(b[hi]), hm);
        a[hi] = h1;
        b[hi] = h2;
    }
    let mut out = [0.0f32; 3];
    for i in 0..3 {
        out[i] = nz(a[i]) * w1 + nz(b[i]) * w2;
    }
    let mut alpha = aa * w1 + ba * w2;
    if alpha != 0.0 {
        for i in 0..3 {
            if i != hi {
                out[i] /= alpha;
            }
        }
    }
    alpha *= alpha_mult;
    if sp.is_polar() {
        out[hi] = out[hi].rem_euclid(360.0);
    }
    Ok(match sp {
        Space::Srgb | Space::Hsl | Space::Hwb => {
            let rgb = match sp {
                Space::Hsl => hsl_to_srgb(out),
                Space::Hwb => hwb_to_srgb(out),
                _ => out,
            };
            CssColor::Rgba(to_u8(rgb[0]), to_u8(rgb[1]), to_u8(rgb[2]), to_u8(alpha))
        }
        _ => CssColor::Space(sp, out, alpha),
    })
}

fn fix_powerless(sp: Space, c: &mut [f32; 3]) {
    match sp {
        Space::Hsl => {
            if c[1].abs() < 1e-5 {
                c[0] = f32::NAN;
            }
        }
        Space::Hwb => {
            if c[1] + c[2] >= 1.0 - 1e-5 {
                c[0] = f32::NAN;
            }
        }
        Space::Lch => {
            if c[1].abs() < 1e-4 {
                c[2] = f32::NAN;
            }
        }
        Space::Oklch => {
            if c[1].abs() < 1e-6 {
                c[2] = f32::NAN;
            }
        }
        _ => {}
    }
}

fn adjust_hue(mut h1: f32, mut h2: f32, m: HueMethod) -> (f32, f32) {
    h1 = h1.rem_euclid(360.0);
    h2 = h2.rem_euclid(360.0);
    let d = h2 - h1;
    match m {
        HueMethod::Shorter => {
            if d > 180.0 {
                h1 += 360.0;
            } else if d < -180.0 {
                h2 += 360.0;
            }
        }
        HueMethod::Longer => {
            if 0.0 < d && d < 180.0 {
                h1 += 360.0;
            } else if -180.0 < d && d <= 0.0 {
                h2 += 360.0;
            }
        }
        HueMethod::Increasing => {
            if d < 0.0 {
                h2 += 360.0;
            }
        }
        HueMethod::Decreasing => {
            if d > 0.0 {
                h1 += 360.0;
            }
        }
    }
    (h1, h2)
}

// ---------------- conversions ----------------

pub fn hsl_to_srgb(c: [f32; 3]) -> [f32; 3] {
    let h = c[0].rem_euclid(360.0);
    let s = c[1];
    let l = c[2];
    let f = |n: f32| {
        let k = (n + h / 30.0) % 12.0;
        let a = s * l.min(1.0 - l);
        l - a * (k - 3.0).min(9.0 - k).min(1.0).max(-1.0)
    };
    [f(0.0), f(8.0), f(4.0)]
}

pub fn hwb_to_srgb(c: [f32; 3]) -> [f32; 3] {
    let h = c[0];
    let mut w = c[1];
    let mut b = c[2];
    if w + b >= 1.0 {
        let gray = w / (w + b);
        return [gray, gray, gray];
    }
    let rgb = hsl_to_srgb([h, 1.0, 0.5]);
    let f = |x: f32| x * (1.0 - w - b) + w;
    let _ = (&mut w, &mut b);
    [f(rgb[0]), f(rgb[1]), f(rgb[2])]
}

pub fn srgb_to_hsl(c: [f32; 3]) -> [f32; 3] {
    let (r, g, b) = (c[0], c[1], c[2]);
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let mut h = f32::NAN;
    let mut s = 0.0;
    let l = (min + max) / 2.0;
    let d = max - min;
    if d != 0.0 {
        s = if l == 0.0 || l == 1.0 { 0.0 } else { (max - l) / l.min(1.0 - l) };
        h = if max == r {
            (g - b) / d + if g < b { 6.0 } else { 0.0 }
        } else if max == g {
            (b - r) / d + 2.0
        } else {
            (r - g) / d + 4.0
        };
        h *= 60.0;
    }
    if s < 0.0 {
        h += 180.0;
        s = s.abs();
    }
    if h >= 360.0 {
        h -= 360.0;
    }
    [h, s, l]
}

pub fn srgb_to_hwb(c: [f32; 3]) -> [f32; 3] {
    let hsl = srgb_to_hsl(c);
    let w = c[0].min(c[1]).min(c[2]);
    let b = 1.0 - c[0].max(c[1]).max(c[2]);
    [hsl[0], w, b]
}

fn lin_srgb(v: f32) -> f32 {
    let a = v.abs();
    if a <= 0.04045 {
        v / 12.92
    } else {
        v.signum() * ((a + 0.055) / 1.055).powf(2.4)
    }
}
fn gam_srgb(v: f32) -> f32 {
    let a = v.abs();
    if a > 0.0031308 {
        v.signum() * (1.055 * a.powf(1.0 / 2.4) - 0.055)
    } else {
        12.92 * v
    }
}

fn mul3(m: &[[f32; 3]; 3], v: [f32; 3]) -> [f32; 3] {
    [
        m[0][0] * v[0] + m[0][1] * v[1] + m[0][2] * v[2],
        m[1][0] * v[0] + m[1][1] * v[1] + m[1][2] * v[2],
        m[2][0] * v[0] + m[2][1] * v[1] + m[2][2] * v[2],
    ]
}

