// ---------------- Parsing ----------------

pub struct SelCtx {
    pub nested: bool, // nested inside style rule (relative / implicit &)
    pub css_modules: bool,
}

fn sel_err(p: &Parser, e: SelErr) -> ParseError {
    p.err(ErrorKind::SelectorError(e))
}

pub fn parse_selector_list(p: &mut Parser, nested: bool) -> PResult<SelectorList> {
    parse_list_impl(p, nested, false, false)
}

pub fn parse_relative_list(p: &mut Parser) -> PResult<SelectorList> {
    parse_list_impl(p, false, true, false)
}

fn parse_list_impl(p: &mut Parser, nested: bool, relative: bool, forgiving: bool) -> PResult<SelectorList> {
    let mut v = Vec::new();
    loop {
        let r = p.parse_until_before(D_COMMA, |p| parse_selector(p, nested, relative));
        match r {
            Ok(s) => v.push(s),
            Err(e) => {
                if forgiving {
                } else {
                    return Err(e);
                }
            }
        }
        if !p.try_comma() {
            break;
        }
    }
    Ok(SelectorList(v))
}

pub fn parse_selector(p: &mut Parser, nested: bool, relative: bool) -> PResult<Selector> {
    let mut comps: Vec<Comp> = Vec::new();
    p.skip_whitespace();
    // leading combinator (relative selectors or nesting)
    if relative || nested {
        let st = p.state();
        let lead = match p.next() {
            Ok(Token::Delim('>')) => Some(Combinator::Child),
            Ok(Token::Delim('+')) => Some(Combinator::NextSibling),
            Ok(Token::Delim('~')) => Some(Combinator::LaterSibling),
            _ => None,
        };
        match lead {
            Some(c) => comps.push(Comp::Comb(c)),
            None => p.reset(st),
        }
    }
    let mut after_pseudo_element = false;
    loop {
        // parse compound
        let n = parse_compound(p, &mut comps, &mut after_pseudo_element)?;
        if n == 0 {
            if comps.is_empty() || matches!(comps.last(), Some(Comp::Comb(_))) {
                if comps.is_empty() {
                    return Err(sel_err(p, SelErr::EmptySelector));
                }
                return Err(sel_err(p, SelErr::DanglingCombinator));
            }
        }
        // combinator
        let mut any_ws = false;
        let comb;
        loop {
            let st = p.state();
            match p.next_including_whitespace() {
                Err(_) => return Ok(Selector(comps)),
                Ok(Token::WhiteSpace(_)) => any_ws = true,
                Ok(Token::Delim('>')) => {
                    // check for >>>
                    let st2 = p.state();
                    if p.next_including_whitespace().ok() == Some(&Token::Delim('>')) {
                        if p.next_including_whitespace().ok() == Some(&Token::Delim('>')) {
                            comb = Combinator::Deep;
                            break;
                        }
                    }
                    p.reset(st2);
                    comb = Combinator::Child;
                    break;
                }
                Ok(Token::Delim('+')) => {
                    comb = Combinator::NextSibling;
                    break;
                }
                Ok(Token::Delim('~')) => {
                    comb = Combinator::LaterSibling;
                    break;
                }
                Ok(_) => {
                    p.reset(st);
                    if any_ws {
                        comb = Combinator::Descendant;
                        break;
                    } else {
                        return Ok(Selector(comps));
                    }
                }
            }
        }
        if after_pseudo_element && !matches!(comps.last(), Some(Comp::S(Simple::PseudoElement(_)))) {
            // combinator after pseudo element: allowed only for some; keep simple
        }
        after_pseudo_element = false;
        comps.push(Comp::Comb(comb));
        if comb == Combinator::Deep {
            p.skip_whitespace();
        }
    }
}

fn parse_ns_or_name(p: &mut Parser) -> PResult<Option<Simple>> {
    // type selector / universal with optional namespace
    let st = p.state();
    let t = match p.next_including_whitespace() {
        Ok(t) => t.clone(),
        Err(_) => {
            p.reset(st);
            return Ok(None);
        }
    };
    match t {
        Token::Ident(name) => {
            let st2 = p.state();
            if let Ok(Token::Delim('|')) = p.next_including_whitespace() {
                let ns = NsPrefix::Named(name.clone());
                return parse_after_ns(p, ns).map(Some);
            }
            p.reset(st2);
            Ok(Some(Simple::Type(None, name)))
        }
        Token::Delim('*') => {
            let st2 = p.state();
            if let Ok(Token::Delim('|')) = p.next_including_whitespace() {
                return parse_after_ns(p, NsPrefix::Any).map(Some);
            }
            p.reset(st2);
            Ok(Some(Simple::Universal(None)))
        }
        Token::Delim('|') => parse_after_ns(p, NsPrefix::None).map(Some),
        _ => {
            p.reset(st);
            Ok(None)
        }
    }
}

fn parse_after_ns(p: &mut Parser, ns: NsPrefix) -> PResult<Simple> {
    let loc = p.location();
    match p.next_including_whitespace()? {
        Token::Ident(n) => Ok(Simple::Type(Some(ns), n.clone())),
        Token::Delim('*') => Ok(Simple::Universal(Some(ns))),
        t => Err(p.err_at(ErrorKind::SelectorError(SelErr::ExplicitNamespaceUnexpectedToken(t.clone())), loc)),
    }
}

fn parse_compound(p: &mut Parser, comps: &mut Vec<Comp>, after_pe: &mut bool) -> PResult<usize> {
    let mut count = 0;
    if let Some(s) = parse_ns_or_name(p)? {
        comps.push(Comp::S(s));
        count += 1;
    }
    loop {
        let st = p.state();
        let loc = p.location();
        let t = match p.next_including_whitespace() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        match t {
            Token::IDHash(id) => {
                comps.push(Comp::S(Simple::Id(id)));
            }
            Token::Hash(_) => {
                return Err(p.err_at(ErrorKind::SelectorError(SelErr::UnexpectedSelectorAfterPseudoElement(t.clone())), loc));
            }
            Token::Delim('.') => {
                let loc2 = p.location();
                match p.next_including_whitespace()? {
                    Token::Ident(c) => comps.push(Comp::S(Simple::Class(c.clone()))),
                    t => return Err(p.err_at(ErrorKind::SelectorError(SelErr::ClassNeedsIdent(t.clone())), loc2)),
                }
            }
            Token::Delim('&') => {
                comps.push(Comp::S(Simple::Nesting));
            }
            Token::SquareBracketBlock => {
                let a = p.parse_nested_block(parse_attr)?;
                comps.push(Comp::S(a));
            }
            Token::Colon => {
                let st2 = p.state();
                let is_element = matches!(p.next_including_whitespace(), Ok(Token::Colon));
                if !is_element {
                    p.reset(st2);
                }
                let loc3 = p.location();
                let t2 = p.next_including_whitespace()?.clone();
                let s = match t2 {
                    Token::Ident(name) => {
                        if is_element {
                            parse_pseudo_element(p, &name, None, loc3)?
                        } else {
                            let lname = name.to_ascii_lowercase();
                            if !is_element && matches!(lname.as_str(), "before" | "after" | "first-line" | "first-letter") {
                                Simple::PseudoElement(lname)
                            } else {
                                parse_pseudo_class(p, &name, loc3)?
                            }
                        }
                    }
                    Token::Function(name) => {
                        if is_element {
                            parse_pseudo_element(p, &name, Some(()), loc3)?
                        } else {
                            parse_pseudo_class_fn(p, &name, loc3)?
                        }
                    }
                    t => {
                        return Err(p.err_at(ErrorKind::SelectorError(SelErr::PseudoElementExpectedIdent(t.clone())), loc3));
                    }
                };
                if matches!(s, Simple::PseudoElement(_) | Simple::CustomPseudoElement(_) | Simple::CustomPseudoElementFn(..) | Simple::Slotted(_) | Simple::Part(_) | Simple::Cue(_) | Simple::CueRegion(_) | Simple::ViewTransition(..)) {
                    *after_pe = true;
                }
                comps.push(Comp::S(s));
            }
            _ => {
                p.reset(st);
                break;
            }
        }
        count += 1;
    }
    Ok(count)
}

fn parse_attr(p: &mut Parser) -> PResult<Simple> {
    p.skip_whitespace();
    // [ns|name op value flags]
    let loc = p.location();
    let t = p.next()?.clone();
    let (ns, name) = match t {
        Token::Ident(n) => {
            let st = p.state();
            match p.next_including_whitespace() {
                Ok(Token::Delim('|')) => {
                    let loc2 = p.location();
                    match p.next_including_whitespace()? {
                        Token::Ident(n2) => (Some(NsPrefix::Named(n)), n2.clone()),
                        t => return Err(p.err_at(ErrorKind::SelectorError(SelErr::InvalidQualNameInAttr(t.clone())), loc2)),
                    }
                }
                _ => {
                    p.reset(st);
                    (None, n)
                }
            }
        }
        Token::Delim('*') => {
            p.expect_delim('|')?;
            let n = p.expect_ident()?.to_string();
            (Some(NsPrefix::Any), n)
        }
        Token::Delim('|') => {
            let n = p.expect_ident()?.to_string();
            (Some(NsPrefix::None), n)
        }
        t => return Err(p.err_at(ErrorKind::SelectorError(SelErr::NoQualifiedNameInAttributeSelector(t.clone())), loc)),
    };
    let ns = match ns {
        Some(NsPrefix::None) => None,
        x => x,
    };
    p.skip_whitespace();
    let loc = p.location();
    let op = match p.next() {
        Err(_) => return Ok(Simple::Attr { ns, name, op: None }),
        Ok(Token::Delim('=')) => AttrOp::Equal,
        Ok(Token::IncludeMatch) => AttrOp::Includes,
        Ok(Token::DashMatch) => AttrOp::DashMatch,
        Ok(Token::PrefixMatch) => AttrOp::Prefix,
        Ok(Token::SuffixMatch) => AttrOp::Suffix,
        Ok(Token::SubstringMatch) => AttrOp::Substring,
        Ok(t) => return Err(p.err_at(ErrorKind::SelectorError(SelErr::UnexpectedTokenInAttributeSelector(t.clone())), loc)),
    };
    let loc = p.location();
    let value = match p.next()? {
        Token::Ident(v) | Token::QuotedString(v) => v.clone(),
        t => return Err(p.err_at(ErrorKind::SelectorError(SelErr::BadValueInAttr(t.clone())), loc)),
    };
    let loc = p.location();
    let flag = match p.next() {
        Err(_) => CaseFlag::None,
        Ok(Token::Ident(f)) if f.eq_ignore_ascii_case("i") => CaseFlag::I,
        Ok(Token::Ident(f)) if f.eq_ignore_ascii_case("s") => CaseFlag::S,
        Ok(t) => return Err(p.err_at(ErrorKind::SelectorError(SelErr::UnexpectedTokenInAttributeSelector(t.clone())), loc)),
    };
    p.expect_exhausted()?;
    Ok(Simple::Attr { ns, name, op: Some((op, value, flag)) })
}

fn unknown_pc_warning(p: &Parser, name: &str, loc: (u32, u32)) {
    let _ = p;
    warn(ParseError {
        kind: ErrorKind::SelectorError(SelErr::UnsupportedPseudoClassOrElement(format!("pc:{}", name))),
        line: loc.0,
        col: loc.1,
    });
}
fn unknown_pe_warning(p: &Parser, name: &str, loc: (u32, u32)) {
    let _ = p;
    warn(ParseError {
        kind: ErrorKind::SelectorError(SelErr::UnsupportedPseudoClassOrElement(format!("pe:{}", name))),
        line: loc.0,
        col: loc.1,
    });
}

fn parse_pseudo_class(p: &mut Parser, name: &str, loc: (u32, u32)) -> PResult<Simple> {
    let l = name.to_ascii_lowercase();
    if PSEUDO_CLASSES.contains(&l.as_str()) || PREFIXED_PSEUDO_CLASSES.contains(&l.as_str()) {
        let norm = match l.as_str() {
            "-moz-placeholder" => "-moz-placeholder-shown".to_string(),
            _ => l,
        };
        return Ok(Simple::PseudoClass(norm));
    }
    match l.as_str() {
        "-moz-placeholder" => return Ok(Simple::PseudoClass("-moz-placeholder-shown".into())),
        "-ms-input-placeholder" => return Ok(Simple::PseudoClass("-ms-placeholder-shown".into())),
        _ => {}
    }
    let cm = CSS_MODULES.with(|c| *c.borrow());
    let _ = cm;
    unknown_pc_warning(p, name, loc);
    Ok(Simple::CustomPseudoClass(name.to_string()))
}

fn parse_nth_ab(p: &mut Parser) -> PResult<(i32, i32)> {
    p.skip_whitespace();
    let loc = p.location();
    let t = p.next()?.clone();
    let parse_b = |p: &mut Parser| -> PResult<i32> {
        // after "an": optional [+-] b, or signed number
        let st = p.state();
        match p.next() {
            Ok(Token::Delim('+')) => {
                let v = p.next()?.clone();
                match v {
                    Token::Number { int_value: Some(b), has_sign: false, .. } => Ok(b),
                    t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                }
            }
            Ok(Token::Delim('-')) => {
                let v = p.next()?.clone();
                match v {
                    Token::Number { int_value: Some(b), has_sign: false, .. } => Ok(-b),
                    t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                }
            }
            Ok(Token::Number { int_value: Some(b), has_sign: true, .. }) => Ok(*b),
            _ => {
                p.reset(st);
                Ok(0)
            }
        }
    };
    match t {
        Token::Number { int_value: Some(b), .. } => Ok((0, b)),
        Token::Dimension { int_value: Some(a), unit, .. } => {
            let u = unit.to_ascii_lowercase();
            if u == "n" {
                let b = parse_b(p)?;
                Ok((a, b))
            } else if u == "n-" {
                let v = p.next()?.clone();
                match v {
                    Token::Number { int_value: Some(b), has_sign: false, .. } => Ok((a, -b)),
                    t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                }
            } else if let Some(rest) = u.strip_prefix("n-") {
                let b: i32 = rest.parse().map_err(|_| p.err(ErrorKind::InvalidValue))?;
                Ok((a, -b))
            } else {
                Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc))
            }
        }
        Token::Ident(s) => {
            let l = s.to_ascii_lowercase();
            match l.as_str() {
                "even" => Ok((2, 0)),
                "odd" => Ok((2, 1)),
                "n" => Ok((1, parse_b(p)?)),
                "-n" => Ok((-1, parse_b(p)?)),
                "n-" => {
                    let v = p.next()?.clone();
                    match v {
                        Token::Number { int_value: Some(b), has_sign: false, .. } => Ok((1, -b)),
                        t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                    }
                }
                "-n-" => {
                    let v = p.next()?.clone();
                    match v {
                        Token::Number { int_value: Some(b), has_sign: false, .. } => Ok((-1, -b)),
                        t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                    }
                }
                _ => {
                    if let Some(rest) = l.strip_prefix("n-") {
                        let b: i32 = rest.parse().map_err(|_| p.err(ErrorKind::InvalidValue))?;
                        Ok((1, -b))
                    } else if let Some(rest) = l.strip_prefix("-n-") {
                        let b: i32 = rest.parse().map_err(|_| p.err(ErrorKind::InvalidValue))?;
                        Ok((-1, -b))
                    } else {
                        Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc))
                    }
                }
            }
        }
        Token::Delim('+') => {
            // +n...
            let t2 = p.next_including_whitespace()?.clone();
            match t2 {
                Token::Ident(s) => {
                    let l = s.to_ascii_lowercase();
                    if l == "n" {
                        Ok((1, parse_b(p)?))
                    } else if l == "n-" {
                        let v = p.next()?.clone();
                        match v {
                            Token::Number { int_value: Some(b), has_sign: false, .. } => Ok((1, -b)),
                            t => Err(p.err(ErrorKind::UnexpectedToken(t))),
                        }
                    } else if let Some(rest) = l.strip_prefix("n-") {
                        let b: i32 = rest.parse().map_err(|_| p.err(ErrorKind::InvalidValue))?;
                        Ok((1, -b))
                    } else {
                        Err(p.err(ErrorKind::UnexpectedToken(Token::Ident(s))))
                    }
                }
                t => Err(p.err(ErrorKind::UnexpectedToken(t))),
            }
        }
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
    }
}

fn parse_pseudo_class_fn(p: &mut Parser, name: &str, loc: (u32, u32)) -> PResult<Simple> {
    let l = name.to_ascii_lowercase();
    match l.as_str() {
        "not" => p.parse_nested_block(|p| Ok(Simple::Not(parse_list_impl(p, false, false, false)?))),
        "is" => p.parse_nested_block(|p| Ok(Simple::Is(parse_list_impl(p, false, false, false)?))),
        "where" => p.parse_nested_block(|p| Ok(Simple::Where(parse_list_impl(p, false, false, false)?))),
        "has" => p.parse_nested_block(|p| Ok(Simple::Has(parse_relative_list(p)?))),
        "-webkit-any" | "-moz-any" => {
            let prefix = if l.starts_with("-webkit") { "-webkit-" } else { "-moz-" };
            p.parse_nested_block(|p| Ok(Simple::Any(prefix.to_string(), parse_list_impl(p, false, false, false)?)))
        }
        "nth-child" | "nth-last-child" => p.parse_nested_block(|p| {
            let (a, b) = parse_nth_ab(p)?;
            let of = if p.try_ident_matching("of") { Some(parse_list_impl(p, false, false, false)?) } else { None };
            Ok(Simple::Nth(if l == "nth-child" { Nth::Child(a, b, of) } else { Nth::LastChild(a, b, of) }))
        }),
        "nth-of-type" | "nth-last-of-type" => p.parse_nested_block(|p| {
            let (a, b) = parse_nth_ab(p)?;
            Ok(Simple::Nth(if l == "nth-of-type" { Nth::OfType(a, b) } else { Nth::LastOfType(a, b) }))
        }),
        "lang" => p.parse_nested_block(|p| {
            let mut v = Vec::new();
            loop {
                v.push(p.expect_ident_or_string()?.to_string());
                if !p.try_comma() {
                    break;
                }
            }
            Ok(Simple::Lang(v))
        }),
        "dir" => p.parse_nested_block(|p| {
            let d = p.expect_ident()?.to_ascii_lowercase();
            if d != "ltr" && d != "rtl" {
                return p.invalid();
            }
            Ok(Simple::Dir(d))
        }),
        "host" => p.parse_nested_block(|p| {
            let s = parse_selector(p, false, false)?;
            // must be a single compound
            if s.0.iter().any(|c| matches!(c, Comp::Comb(_))) {
                return Err(p.err(ErrorKind::SelectorError(SelErr::InvalidState)));
            }
            Ok(Simple::Host(Some(Box::new(s))))
        }),
        "state" => p.parse_nested_block(|p| Ok(Simple::State(p.expect_ident()?.to_string()))),
        "local" | "global" if CSS_MODULES.with(|c| *c.borrow()) => p.parse_nested_block(|p| {
            let s = parse_selector(p, false, false)?;
            Ok(if l == "local" { Simple::Local(Box::new(s)) } else { Simple::Global(Box::new(s)) })
        }),
        _ => {
            unknown_pc_warning(p, name, loc);
            let tl = p.parse_nested_block(|p| crate::tokenlist::TokenList::parse_raw(p))?;
            Ok(Simple::CustomPseudoClassFn(name.to_string(), tl))
        }
    }
}

fn parse_pseudo_element(p: &mut Parser, name: &str, func: Option<()>, loc: (u32, u32)) -> PResult<Simple> {
    let l = name.to_ascii_lowercase();
    if func.is_none() {
        if PSEUDO_ELEMENTS.contains(&l.as_str()) || PREFIXED_PSEUDO_ELEMENTS.contains(&l.as_str()) {
            let norm = match l.as_str() {
                "-webkit-input-placeholder" | "-moz-placeholder" | "-ms-input-placeholder" => l,
                _ => l,
            };
            if norm.starts_with("-webkit-scrollbar") || norm == "-webkit-resizer" {
                return Ok(Simple::WebkitScrollbar(norm));
            }
            return Ok(Simple::PseudoElement(norm));
        }
        unknown_pe_warning(p, name, loc);
        return Ok(Simple::CustomPseudoElement(name.to_string()));
    }
    match l.as_str() {
        "slotted" => p.parse_nested_block(|p| Ok(Simple::Slotted(Box::new(parse_selector(p, false, false)?)))),
        "part" => p.parse_nested_block(|p| {
            let mut v = Vec::new();
            loop {
                match p.try_parse(|p| p.expect_ident_cloned()) {
                    Ok(s) => v.push(s),
                    Err(_) => break,
                }
            }
            if v.is_empty() {
                return p.invalid();
            }
            Ok(Simple::Part(v))
        }),
        "cue" => p.parse_nested_block(|p| Ok(Simple::Cue(Box::new(parse_selector(p, false, false)?)))),
        "cue-region" => p.parse_nested_block(|p| Ok(Simple::CueRegion(Box::new(parse_selector(p, false, false)?)))),
        "view-transition-group" | "view-transition-image-pair" | "view-transition-old" | "view-transition-new" => {
            p.parse_nested_block(|p| {
                let loc = p.location();
                let arg = match p.next()? {
                    Token::Ident(s) => s.clone(),
                    Token::Delim('*') => "*".to_string(),
                    t => return Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
                };
                Ok(Simple::ViewTransition(l.clone(), arg))
            })
        }
        _ => {
            unknown_pe_warning(p, name, loc);
            let tl = p.parse_nested_block(|p| crate::tokenlist::TokenList::parse_raw(p))?;
            Ok(Simple::CustomPseudoElementFn(name.to_string(), tl))
        }
    }
}

// ---------------- Serialization ----------------

fn write_ns(d: &mut Printer, ns: &Option<NsPrefix>) {
    match ns {
        None => {}
        Some(NsPrefix::Any) => d.write_str("*|"),
        Some(NsPrefix::None) => d.write_str("|"),
        Some(NsPrefix::Named(n)) => {
            d.write_ident(n);
            d.write_char('|');
        }
    }
}

pub fn write_nth_ab(d: &mut Printer, a: i32, b: i32) {
    match (a, b) {
        (0, b) => d.write_str(&b.to_string()),
        (2, 1) => d.write_str("odd"),
        (a, b) => {
            match a {
                1 => d.write_str("n"),
                -1 => d.write_str("-n"),
                a => {
                    d.write_str(&a.to_string());
                    d.write_char('n');
                }
            }
            if b > 0 {
                d.write_char('+');
                d.write_str(&b.to_string());
            } else if b < 0 {
                d.write_str(&b.to_string());
            }
        }
    }
}

impl Combinator {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Combinator::Descendant => d.write_char(' '),
            Combinator::Child => d.delim('>', true),
            Combinator::NextSibling => d.delim('+', true),
            Combinator::LaterSibling => d.delim('~', true),
            Combinator::Deep => d.write_str(" >>> "),
        }
    }
}

pub fn attr_value_to_css(d: &mut Printer, v: &str) {
    if d.minify {
        let mut id = String::new();
        serialize_identifier(v, &mut id);
        let mut st = String::new();
        serialize_string(v, &mut st);
        if !v.is_empty() && id.len() <= st.len() {
            d.write_str(&id);
            return;
        }
        d.write_str(&st);
    } else {
        d.write_string(v);
    }
}

impl Simple {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Simple::Nesting => d.write_char('&'),
            Simple::Universal(ns) => {
                write_ns(d, ns);
                d.write_char('*');
            }
            Simple::Type(ns, n) => {
                write_ns(d, ns);
                d.write_ident(n);
            }
            Simple::Id(id) => {
                d.write_char('#');
                crate::css_modules::write_local_ident(d, id);
            }
            Simple::Class(c) => {
                d.write_char('.');
                crate::css_modules::write_local_ident(d, c);
            }
            Simple::Attr { ns, name, op } => {
                d.write_char('[');
                write_ns(d, ns);
                d.write_ident(name);
                if let Some((op, val, flag)) = op {
                    d.write_str(match op {
                        AttrOp::Equal => "=",
                        AttrOp::Includes => "~=",
                        AttrOp::DashMatch => "|=",
                        AttrOp::Prefix => "^=",
                        AttrOp::Suffix => "$=",
                        AttrOp::Substring => "*=",
                    });
                    attr_value_to_css(d, val);
                    match flag {
                        CaseFlag::None => {}
                        CaseFlag::I => d.write_str(" i"),
                        CaseFlag::S => d.write_str(" s"),
                    }
                }
                d.write_char(']');
            }
            Simple::PseudoClass(n) => {
                d.write_char(':');
                let pc = crate::prefixes::pseudo_class_name(n);
                d.write_str(&pc);
            }
            Simple::CustomPseudoClass(n) => {
                d.write_char(':');
                d.write_ident(n);
            }
            Simple::CustomPseudoClassFn(n, tl) => {
                d.write_char(':');
                d.write_ident(n);
                d.write_char('(');
                tl.to_css(d, false);
                d.write_char(')');
            }
            Simple::Not(l) => {
                d.write_str(":not(");
                l.to_css(d);
                d.write_char(')');
            }
            Simple::Is(l) => {
                let name = crate::prefixes::is_name();
                d.write_char(':');
                d.write_str(&name);
                d.write_char('(');
                l.to_css(d);
                d.write_char(')');
            }
            Simple::Where(l) => {
                d.write_str(":where(");
                l.to_css(d);
                d.write_char(')');
            }
            Simple::Has(l) => {
                d.write_str(":has(");
                l.to_css(d);
                d.write_char(')');
            }
            Simple::Any(prefix, l) => {
                d.write_char(':');
                d.write_str(prefix);
                d.write_str("any(");
                l.to_css(d);
                d.write_char(')');
            }
            Simple::Nth(n) => {
                let (name, a, b, of) = match n {
                    Nth::Child(a, b, of) => ("nth-child", *a, *b, of.as_ref()),
                    Nth::LastChild(a, b, of) => ("nth-last-child", *a, *b, of.as_ref()),
                    Nth::OfType(a, b) => ("nth-of-type", *a, *b, None),
                    Nth::LastOfType(a, b) => ("nth-last-of-type", *a, *b, None),
                };
                if a == 0 && b == 1 && of.is_none() {
                    d.write_str(match name {
                        "nth-child" => ":first-child",
                        "nth-last-child" => ":last-child",
                        "nth-of-type" => ":first-of-type",
                        _ => ":last-of-type",
                    });
                    return;
                }
                d.write_char(':');
                d.write_str(name);
                d.write_char('(');
                write_nth_ab(d, a, b);
                if let Some(of) = of {
                    d.write_str(" of ");
                    of.to_css(d);
                }
                d.write_char(')');
            }
            Simple::Lang(v) => {
                d.write_str(":lang(");
                for (i, l) in v.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    d.write_ident(l);
                }
                d.write_char(')');
            }
            Simple::Dir(s) => {
                d.write_str(":dir(");
                d.write_str(s);
                d.write_char(')');
            }
            Simple::Host(s) => {
                d.write_str(":host");
                if let Some(s) = s {
                    d.write_char('(');
                    s.to_css(d);
                    d.write_char(')');
                }
            }
            Simple::State(s) => {
                d.write_str(":state(");
                d.write_ident(s);
                d.write_char(')');
            }
            Simple::Local(s) => s.to_css(d),
            Simple::Global(s) => {
                let prev = crate::css_modules::set_global(true);
                s.to_css(d);
                crate::css_modules::set_global(prev);
            }
            Simple::PseudoElement(n) => {
                match n.as_str() {
                    "before" | "after" | "first-line" | "first-letter" => {
                        d.write_char(':');
                        d.write_str(n);
                    }
                    _ => {
                        d.write_str("::");
                        let pe = crate::prefixes::pseudo_element_name(n);
                        d.write_str(&pe);
                    }
                }
            }
            Simple::WebkitScrollbar(n) => {
                d.write_str("::");
                d.write_str(n);
            }
            Simple::CustomPseudoElement(n) => {
                d.write_str("::");
                d.write_ident(n);
            }
            Simple::CustomPseudoElementFn(n, tl) => {
                d.write_str("::");
                d.write_ident(n);
                d.write_char('(');
                tl.to_css(d, false);
                d.write_char(')');
            }
            Simple::Slotted(s) => {
                d.write_str("::slotted(");
                s.to_css(d);
                d.write_char(')');
            }
            Simple::Part(v) => {
                d.write_str("::part(");
                for (i, n) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_char(' ');
                    }
                    d.write_ident(n);
                }
                d.write_char(')');
            }
            Simple::Cue(s) => {
                d.write_str("::cue(");
                s.to_css(d);
                d.write_char(')');
            }
            Simple::CueRegion(s) => {
                d.write_str("::cue-region(");
                s.to_css(d);
                d.write_char(')');
            }
            Simple::ViewTransition(n, a) => {
                d.write_str("::");
                d.write_str(n);
                d.write_char('(');
                if a == "*" {
                    d.write_char('*');
                } else {
                    d.write_ident(a);
                }
                d.write_char(')');
            }
        }
    }

    pub fn is_type_like(&self) -> bool {
        matches!(self, Simple::Universal(_) | Simple::Type(..))
    }
    pub fn is_pseudo_element(&self) -> bool {
        matches!(
            self,
            Simple::PseudoElement(_)
                | Simple::WebkitScrollbar(_)
                | Simple::CustomPseudoElement(_)
                | Simple::CustomPseudoElementFn(..)
                | Simple::Slotted(_)
                | Simple::Part(_)
                | Simple::Cue(_)
                | Simple::CueRegion(_)
                | Simple::ViewTransition(..)
        )
    }
}

impl Selector {
    pub fn to_css(&self, d: &mut Printer) {
        let comps = &self.0;
        let mut i = 0;
        while i < comps.len() {
            match &comps[i] {
                Comp::Comb(c) => {
                    if i == 0 {
                        // leading combinator (relative selector)
                        match c {
                            Combinator::Descendant => {}
                            _ => {
                                if d.minify {
                                    c.to_css(d);
                                } else {
                                    d.write_char(' ');
                                    let s = match c {
                                        Combinator::Child => '>',
                                        Combinator::NextSibling => '+',
                                        Combinator::LaterSibling => '~',
                                        _ => ' ',
                                    };
                                    d.write_char(s);
                                    d.write_char(' ');
                                }
                            }
                        }
                    } else {
                        c.to_css(d);
                    }
                }
                Comp::S(s) => {
                    // drop universal selector if followed by other simple selectors in same compound
                    if let Simple::Universal(None) = s {
                        let next_is_simple = matches!(comps.get(i + 1), Some(Comp::S(n)) if !matches!(n, Simple::Nesting));
                        if next_is_simple && !self.default_ns_active() {
                            i += 1;
                            continue;
                        }
                    }
                    s.to_css(d);
                }
            }
            i += 1;
        }
    }

    fn default_ns_active(&self) -> bool {
        crate::rules::DEFAULT_NS.with(|n| n.borrow().is_some())
    }

    pub fn has_nesting(&self) -> bool {
        self.0.iter().any(|c| match c {
            Comp::S(s) => simple_has_nesting(s),
            _ => false,
        })
    }

    /// Compounds split by combinators: returns list of (combinator before, compound simple list)
    pub fn compounds(&self) -> Vec<(Option<Combinator>, Vec<Simple>)> {
        let mut out: Vec<(Option<Combinator>, Vec<Simple>)> = Vec::new();
        let mut cur: Vec<Simple> = Vec::new();
        let mut comb: Option<Combinator> = None;
        for c in &self.0 {
            match c {
                Comp::Comb(cb) => {
                    if !cur.is_empty() || !out.is_empty() {
                        out.push((comb, std::mem::take(&mut cur)));
                    }
                    comb = Some(*cb);
                }
                Comp::S(s) => cur.push(s.clone()),
            }
        }
        out.push((comb, cur));
        out
    }
}

pub fn simple_has_nesting(s: &Simple) -> bool {
    match s {
        Simple::Nesting => true,
        Simple::Not(l) | Simple::Is(l) | Simple::Where(l) | Simple::Has(l) | Simple::Any(_, l) => l.0.iter().any(|s| s.has_nesting()),
        Simple::Nth(Nth::Child(_, _, Some(l))) | Simple::Nth(Nth::LastChild(_, _, Some(l))) => l.0.iter().any(|s| s.has_nesting()),
        Simple::Host(Some(s)) | Simple::Slotted(s) | Simple::Local(s) | Simple::Global(s) => s.has_nesting(),
        _ => false,
    }
}

impl SelectorList {
    pub fn to_css(&self, d: &mut Printer) {
        for (i, s) in self.0.iter().enumerate() {
            if i > 0 {
                d.delim(',', false);
            }
            s.to_css(d);
        }
    }
}
EOF
echo ok

