use crate::color::CssColor;
use crate::parser::*;
use crate::printer::Printer;
use crate::tokenizer::Token;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum TV {
    Token(Token),
    Color(CssColor),
    Url(String),
    Var(Box<Variable>),
    Env(Box<EnvVar>),
    Function(String, TokenList),
    Dim(Dim), // length/angle/time/resolution
    DashedIdent(String),
    /// nested raw block: open token, contents, close token
    Block(Token, TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Variable {
    pub name: String,
    pub fallback: Option<TokenList>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct EnvVar {
    pub name: String,
    pub indices: Vec<i32>,
    pub fallback: Option<TokenList>,
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct TokenList(pub Vec<TV>);

pub const MAX_DEPTH: usize = 500;

impl TokenList {
    /// Parse a token list as for custom properties, trimming leading/trailing whitespace when len >= 2.
    pub fn parse(p: &mut Parser) -> PResult<TokenList> {
        let mut v = Vec::new();
        parse_into(p, &mut v, 0)?;
        Ok(TokenList(trim(v)))
    }

    /// Parse raw (no trimming)
    pub fn parse_raw(p: &mut Parser) -> PResult<TokenList> {
        let mut v = Vec::new();
        parse_into(p, &mut v, 0)?;
        Ok(TokenList(v))
    }

    pub fn starts_with_whitespace(&self) -> bool {
        matches!(self.0.first(), Some(TV::Token(Token::WhiteSpace(_))))
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    pub fn has_var(&self) -> bool {
        self.0.iter().any(|t| match t {
            TV::Var(_) | TV::Env(_) => true,
            TV::Function(_, l) | TV::Block(_, l) => l.has_var(),
            _ => false,
        })
    }

    pub fn to_css(&self, d: &mut Printer, _is_custom: bool) {
        for tv in &self.0 {
            tv.to_css(d);
        }
    }
}

fn trim(v: Vec<TV>) -> Vec<TV> {
    if v.len() >= 2 {
        let mut s = &v[..];
        if matches!(s.first(), Some(TV::Token(Token::WhiteSpace(_)))) {
            s = &s[1..];
        }
        if matches!(s.last(), Some(TV::Token(Token::WhiteSpace(_)))) {
            s = &s[..s.len() - 1];
        }
        return s.to_vec();
    }
    v
}

fn parse_into(p: &mut Parser, v: &mut Vec<TV>, depth: usize) -> PResult<()> {
    if depth > MAX_DEPTH {
        return Err(p.err(ErrorKind::MaximumNestingDepth));
    }
    loop {
        let st = p.state();
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t,
            Err(_) => break,
        };
        match t {
            Token::Function(name) => {
                let lname = name.to_ascii_lowercase();
                if lname == "var" {
                    let r = p.parse_nested_block(|p| {
                        p.skip_whitespace();
                        let n = p.expect_ident()?.to_string();
                        if !n.starts_with("--") {
                            return p.invalid();
                        }
                        p.skip_whitespace();
                        let fallback = if p.try_comma() { Some(TokenList::parse(p)?) } else { None };
                        Ok(Variable { name: n, fallback })
                    });
                    match r {
                        Ok(var) => {
                            v.push(TV::Var(Box::new(var)));
                            continue;
                        }
                        Err(_) => {
                            p.reset(st);
                            p.next_including_whitespace_and_comments()?;
                        }
                    }
                } else if lname == "env" {
                    let r = p.parse_nested_block(|p| {
                        p.skip_whitespace();
                        let n = p.expect_ident()?.to_string();
                        let mut indices = Vec::new();
                        loop {
                            match p.try_parse(|p| p.expect_integer()) {
                                Ok(i) => indices.push(i),
                                Err(_) => break,
                            }
                        }
                        p.skip_whitespace();
                        let fallback = if p.try_comma() { Some(TokenList::parse(p)?) } else { None };
                        Ok(EnvVar { name: n, indices, fallback })
                    });
                    match r {
                        Ok(e) => {
                            v.push(TV::Env(Box::new(e)));
                            continue;
                        }
                        Err(_) => {
                            p.reset(st);
                            p.next_including_whitespace_and_comments()?;
                        }
                    }
                } else if lname == "url" {
                    let r = p.parse_nested_block(|p| Ok(p.expect_string()?.to_string()));
                    if let Ok(u) = r {
                        v.push(TV::Url(u));
                        continue;
                    }
                    p.reset(st);
                    p.next_including_whitespace_and_comments()?;
                } else if is_color_fn(&lname) {
                    p.reset(st);
                    if let Ok(c) = p.try_parse(CssColor::parse) {
                        v.push(TV::Color(c));
                        continue;
                    }
                    p.reset(st);
                    p.next_including_whitespace_and_comments()?;
                }
                let name = name.clone();
                let args = p.parse_nested_block(|p| {
                    let mut inner = Vec::new();
                    parse_into(p, &mut inner, depth + 1)?;
                    Ok(TokenList(trim(inner)))
                })?;
                v.push(TV::Function(name, args));
            }
            Token::Hash(_) | Token::IDHash(_) => {
                p.reset(st);
                if let Ok(c) = p.try_parse(|p| {
                    let c = CssColor::parse(p)?;
                    Ok(c)
                }) {
                    v.push(TV::Color(c));
                } else {
                    let t = p.next_including_whitespace_and_comments()?.clone();
                    v.push(TV::Token(t));
                }
            }
            Token::UnquotedUrl(u) => v.push(TV::Url(u.clone())),
            Token::Ident(name) if name.starts_with("--") => v.push(TV::DashedIdent(name.clone())),
            Token::Dimension { value, unit, .. } => {
                let u = unit.to_ascii_lowercase();
                match unit_cat(&u) {
                    Some(Cat::Length) | Some(Cat::Angle) | Some(Cat::Time) | Some(Cat::Resolution) => {
                        v.push(TV::Dim(Dim { v: *value, unit: u }));
                    }
                    _ => v.push(TV::Token(t.clone())),
                }
            }
            Token::ParenthesisBlock | Token::SquareBracketBlock | Token::CurlyBracketBlock => {
                let open = t.clone();
                let inner = p.parse_nested_block(|p| {
                    let mut inner = Vec::new();
                    parse_into(p, &mut inner, depth + 1)?;
                    Ok(TokenList(inner))
                })?;
                v.push(TV::Block(open, inner));
            }
            t => v.push(TV::Token(t.clone())),
        }
    }
    Ok(())
}

pub fn is_color_fn(l: &str) -> bool {
    matches!(
        l,
        "rgb" | "rgba" | "hsl" | "hsla" | "hwb" | "lab" | "lch" | "oklab" | "oklch" | "color" | "color-mix" | "light-dark"
    )
}

impl TV {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            TV::Token(t) => write_token(d, t),
            TV::Color(c) => c.to_css(d),
            TV::Url(u) => crate::url::write_url(d, u),
            TV::Var(var) => {
                d.write_str("var(");
                d.write_dashed_ident_ref(&var.name);
                if let Some(fb) = &var.fallback {
                    d.write_char(',');
                    if !fb.starts_with_whitespace() {
                        d.whitespace();
                    }
                    fb.to_css(d, true);
                }
                d.write_char(')');
            }
            TV::Env(e) => {
                d.write_str("env(");
                d.write_ident(&e.name);
                for i in &e.indices {
                    d.write_char(' ');
                    d.write_str(&i.to_string());
                }
                if let Some(fb) = &e.fallback {
                    d.write_char(',');
                    if !fb.starts_with_whitespace() {
                        d.whitespace();
                    }
                    fb.to_css(d, true);
                }
                d.write_char(')');
            }
            TV::Function(name, args) => {
                d.write_ident(name);
                d.write_char('(');
                args.to_css(d, false);
                d.write_char(')');
            }
            TV::Dim(dim) => match dim.cat() {
                Cat::Length => write_dimension(d, dim.v, &dim.unit),
                _ => dim.to_css(d),
            },
            TV::DashedIdent(n) => d.write_dashed_ident_ref(n),
            TV::Block(open, inner) => {
                let (o, c) = match open {
                    Token::ParenthesisBlock => ('(', ')'),
                    Token::SquareBracketBlock => ('[', ']'),
                    _ => ('{', '}'),
                };
                d.write_char(o);
                inner.to_css(d, false);
                d.write_char(c);
            }
        }
    }
}

/// cssparser-style numeric serialization
pub fn write_numeric_css(out: &mut String, value: f32, int_value: Option<i32>, has_sign: bool) {
    if has_sign && value.is_sign_positive() {
        out.push('+');
    }
    if value == 0.0 && value.is_sign_negative() {
        out.push_str("-0");
        return;
    }
    let s = crate::printer::dtoa_short(value);
    out.push_str(&s);
    if int_value.is_none() && value.fract() == 0.0 && !s.contains('.') && !s.contains('e') {
        out.push_str(".0");
    }
}

pub fn write_token(d: &mut Printer, t: &Token) {
    match t {
        Token::Ident(s) => d.write_ident(s),
        Token::AtKeyword(s) => {
            d.write_char('@');
            d.write_ident(s);
        }
        Token::Hash(s) => {
            d.write_char('#');
            let mut o = String::new();
            crate::printer::serialize_name(s, &mut o);
            d.write_str(&o);
        }
        Token::IDHash(s) => {
            d.write_char('#');
            d.write_ident(s);
        }
        Token::QuotedString(s) => d.write_string(s),
        Token::UnquotedUrl(s) => crate::url::write_url(d, s),
        Token::Delim(c) => d.write_char(*c),
        Token::Number { value, .. } => d.write_num(*value),
        Token::Percentage { unit_value, int_value, has_sign } => {
            let mut o = String::new();
            write_numeric_css(&mut o, unit_value * 100.0, *int_value, *has_sign);
            o.push('%');
            d.write_str(&o);
        }
        Token::Dimension { value, unit, .. } => {
            write_dimension(d, *value, unit);
        }
        Token::WhiteSpace(s) => {
            if d.minify {
                d.write_char(' ');
            } else {
                d.write_str(s);
            }
        }
        Token::Comment(s) => {
            if !d.minify {
                d.write_str("/*");
                d.write_str(s);
                d.write_str("*/");
            }
        }
        Token::Colon => d.write_char(':'),
        Token::Semicolon => d.write_char(';'),
        Token::Comma => d.write_char(','),
        Token::IncludeMatch => d.write_str("~="),
        Token::DashMatch => d.write_str("|="),
        Token::PrefixMatch => d.write_str("^="),
        Token::SuffixMatch => d.write_str("$="),
        Token::SubstringMatch => d.write_str("*="),
        Token::CDO => d.write_str("<!--"),
        Token::CDC => d.write_str("-->"),
        Token::Function(n) => {
            d.write_ident(n);
            d.write_char('(');
        }
        Token::ParenthesisBlock => d.write_char('('),
        Token::SquareBracketBlock => d.write_char('['),
        Token::CurlyBracketBlock => d.write_char('{'),
        Token::BadUrl(s) => {
            d.write_str("url(");
            d.write_str(s);
            d.write_char(')');
        }
        Token::BadString(s) => {
            d.write_char('"');
            d.write_str(s);
        }
        Token::CloseParenthesis => d.write_char(')'),
        Token::CloseSquareBracket => d.write_char(']'),
        Token::CloseCurlyBracket => d.write_char('}'),
    }
}

impl Printer {
    pub fn write_dashed_ident_ref(&mut self, n: &str) {
        crate::css_modules::write_dashed_ident(self, n, false);
    }
}
