use crate::printer::Printer;

pub fn write_url(d: &mut Printer, u: &str) {
    if d.minify {
        // try unquoted url
        let mut ok = true;
        let mut o = String::new();
        for ch in u.chars() {
            match ch {
                ' ' | '\t' | '\n' | '\r' | '\x0C' | '"' | '\'' | '(' | ')' | '\\' => {
                    ok = false;
                    break;
                }
                c if (c as u32) < 0x20 || c as u32 == 0x7F => {
                    ok = false;
                    break;
                }
                c => o.push(c),
            }
        }
        if ok {
            d.write_str("url(");
            d.write_str(&o);
            d.write_char(')');
            return;
        }
    }
    d.write_str("url(");
    d.write_string(u);
    d.write_char(')');
}
