// Declarations and declaration blocks
use crate::parser::*;
use crate::printer::Printer;
use crate::properties::Property;
use crate::tokenizer::Token;

#[derive(Clone, Debug, PartialEq, Default)]
pub struct DeclBlock {
    pub decls: Vec<Property>,
    pub important: Vec<Property>,
}

impl DeclBlock {
    pub fn is_empty(&self) -> bool {
        self.decls.is_empty() && self.important.is_empty()
    }
    pub fn len(&self) -> usize {
        self.decls.len() + self.important.len()
    }

    /// Print declarations each on new line (used inside rules). `last_semicolon`: whether to print ';' after last in minify mode
    pub fn to_css_inner(&self, d: &mut Printer, more_after: bool) {
        let total = self.len();
        let mut i = 0;
        for (list, imp) in [(&self.decls, false), (&self.important, true)] {
            for p in list.iter() {
                d.newline();
                p.to_css(d, imp);
                i += 1;
                if i < total || !d.minify || more_after {
                    d.write_char(';');
                }
            }
        }
    }

    /// Print as a block: ` {` decls `}`
    pub fn to_css_block(&self, d: &mut Printer) {
        d.whitespace();
        d.write_char('{');
        d.indent();
        self.to_css_inner(d, false);
        d.dedent();
        d.newline();
        d.write_char('}');
    }
}

/// Parse a single declaration `name: value [!important]`. Input positioned after name.
pub fn parse_declaration(p: &mut Parser, name: &str) -> PResult<(Property, bool)> {
    p.expect_colon()?;
    let prop = p.parse_until_before(D_BANG, |p| Ok(Property::parse(name, p)))?;
    let important = p
        .try_parse(|p| {
            p.expect_delim('!')?;
            p.expect_ident_matching("important")
        })
        .is_ok();
    p.expect_exhausted()?;
    Ok((prop, important))
}

/// Parse a plain declaration list (no nested rules), e.g. @font-face, @page margin boxes
pub fn parse_declaration_list(p: &mut Parser, warnings: &mut Vec<ParseError>) -> PResult<DeclBlock> {
    let mut block = DeclBlock::default();
    loop {
        p.skip_whitespace();
        let loc = p.location();
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        match t {
            Token::Semicolon => continue,
            Token::Ident(name) => {
                let r = p.parse_until_after(D_SEMI, |p| parse_declaration(p, &name));
                match r {
                    Ok((prop, imp)) => {
                        if imp {
                            block.important.push(prop);
                        } else {
                            block.decls.push(prop);
                        }
                    }
                    Err(e) => {
                        if crate::options::error_recovery() {
                            warnings.push(e);
                        } else {
                            return Err(e);
                        }
                    }
                }
            }
            t => {
                let e = p.err_at(ErrorKind::UnexpectedToken(t), loc);
                let _ = p.parse_until_after(D_SEMI, |_| Ok(()));
                if crate::options::error_recovery() {
                    warnings.push(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok(block)
}
