// Stylesheet rules: parsing and printing.
use crate::decl::*;
use crate::media::*;
use crate::parser::*;
use crate::printer::Printer;
use crate::properties::Property;
use crate::selectors::*;
use crate::tokenizer::Token;
use crate::tokenlist::TokenList;
use std::cell::RefCell;

thread_local! {
    pub static DEFAULT_NS: RefCell<Option<String>> = RefCell::new(None);
    pub static WARNINGS: RefCell<Vec<ParseError>> = RefCell::new(Vec::new());
}

pub fn push_warning(e: ParseError) {
    WARNINGS.with(|w| w.borrow_mut().push(e));
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct Loc {
