}

#[derive(Clone, Debug, PartialEq)]
pub struct PageRule {
    pub selectors: Vec<PageSelector>,
    pub decls: DeclBlock,
    pub margins: Vec<PageMarginRule>,
    pub loc: Loc,
}

#[derive(Clone, Debug, PartialEq)]
pub struct UnknownAtRule {
    pub name: String,
    pub prelude: TokenList,
    pub block: Option<TokenList>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum ScopeSel {
    None,
}

#[derive(Clone, Debug, PartialEq)]
pub struct FontFeatureValuesRule {
    pub families: Vec<String>,
    pub blocks: Vec<(String, Vec<(String, Vec<i32>)>)>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum CssRule {
    Style(StyleRule),
    Media(MediaList, Vec<CssRule>, Loc),
    Import(ImportRule),
    Supports(SupportsCondition, Vec<CssRule>, Loc),
    Keyframes(KeyframesRule),
    FontFace(DeclBlock, Loc),
    FontPaletteValues(String, DeclBlock, Loc),
    FontFeatureValues(FontFeatureValuesRule, Loc),
    Page(PageRule),
    CounterStyle(String, DeclBlock, Loc),
    Namespace(Option<String>, String, Loc),
    MozDocument(Vec<CssRule>, Loc),
    Viewport(u8, DeclBlock, Loc),
    CustomMedia(String, MediaList, Loc),
    LayerStatement(Vec<Vec<String>>, Loc),
    LayerBlock(Option<Vec<String>>, Vec<CssRule>, Loc),
    Property(PropertyRule),
    Container(Option<String>, ContainerCondition, Vec<CssRule>, Loc),
    Scope(Option<SelectorList>, Option<SelectorList>, Vec<CssRule>, Loc),
    StartingStyle(Vec<CssRule>, Loc),
    ViewTransition(DeclBlock, Loc),
    NestedDecls(DeclBlock),
    Unknown(UnknownAtRule, Loc),
    Ignored,
}

#[derive(Clone, Debug, PartialEq)]
pub struct PropertyRule {
    pub name: String,
    pub syntax: crate::syntax::SyntaxString,
    pub inherits: bool,
    pub initial: Option<crate::syntax::ParsedComponent>,
    pub loc: Loc,
}

// ---------------- Parsing ----------------

#[derive(Clone, Copy, PartialEq, PartialOrd)]
enum TopState {
    Start,
    Layers,
    Imports,
    Namespaces,
    Body,
}

fn loc_of(p: &Parser) -> Loc {
    let (l, c) = p.location();
    Loc { line: l, col: c }
}

pub fn parse_stylesheet(p: &mut Parser) -> PResult<Vec<CssRule>> {
    let mut rules = Vec::new();
    let mut state = TopState::Start;
    loop {
        // skip whitespace, comments, CDO, CDC
        loop {
            let st = p.state();
            match p.next_including_whitespace_and_comments() {
                Ok(Token::WhiteSpace(_)) | Ok(Token::Comment(_)) | Ok(Token::CDO) | Ok(Token::CDC) => continue,
                Ok(_) => {
                    p.reset(st);
                    break;
                }
                Err(_) => {
                    p.reset(st);
                    break;
                }
            }
        }
        let loc = loc_of(p);
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        let r = match t {
            Token::AtKeyword(name) => parse_at_rule(p, &name, loc, Ctx::Top(&mut state)),
            _ => {
                p.reset_one_back();
                state = TopState::Body;
                parse_qualified_rule(p, loc, false)
            }
        };
        match r {
            Ok(Some(rule)) => rules.push(rule),
            Ok(None) => {}
            Err(e) => {
                if crate::options::error_recovery() {
                    push_warning(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok(rules)
}

impl<'t> Parser<'t> {
    pub fn reset_one_back(&mut self) {
        // step back one token (only valid right after next_including_whitespace_and_comments of non-block token
        // or block token)
        // find the token whose end leads here: simplest approach is to search backwards
        let mut i = self.pos;
        if i == 0 {
            return;
        }
        i -= 1;
        // if previous position came from skipping a block, find its opener
        let mut j = i;
        loop {
            let t = &self.toks[j];
            if t.token.is_block_open() && (t.close == i || (t.close >= self.toks.len() && i + 1 == self.toks.len())) {
                self.pos = j;
                return;
            }
            if j == 0 {
                break;
            }
            j -= 1;
            if i - j > 0 && !self.toks[j].token.is_block_open() {
                // keep searching openers only
            }
            if j + 100000 < i {
                break;
            }
        }
        self.pos = i;
    }
}

pub enum Ctx<'a> {
    Top(&'a mut TopState),
    /// nested in rule list (e.g. @media at top level)
    Nested,
    /// inside a style rule (nesting)
    Style,
}

fn expect_block_or_semicolon(p: &mut Parser) -> PResult<bool> {
    // returns true if block
    match p.next() {
        Ok(Token::CurlyBracketBlock) => Ok(true),
        Ok(Token::Semicolon) | Err(_) => Ok(false),
        Ok(t) => Err(p.err(ErrorKind::UnexpectedToken(t.clone()))),
    }
}

fn parse_rules_block(p: &mut Parser, in_style: bool) -> PResult<Vec<CssRule>> {
    p.parse_nested_block(|p| {
        if in_style {
            let (decls, rules) = parse_style_body(p)?;
            let mut out = Vec::new();
            if !decls.is_empty() {
                out.push(CssRule::NestedDecls(decls));
            }
            out.extend(rules);
            Ok(out)
        } else {
            parse_rule_list(p)
        }
    })
}

pub fn parse_rule_list(p: &mut Parser) -> PResult<Vec<CssRule>> {
    let mut rules = Vec::new();
    loop {
        p.skip_whitespace();
        let loc = loc_of(p);
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        let r = match t {
            Token::AtKeyword(name) => parse_at_rule(p, &name, loc, Ctx::Nested),
            Token::Semicolon => continue,
            _ => {
                p.reset_one_back();
                parse_qualified_rule(p, loc, false)
            }
        };
        match r {
            Ok(Some(rule)) => rules.push(rule),
            Ok(None) => {}
            Err(e) => {
                if crate::options::error_recovery() {
                    push_warning(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok(rules)
}

fn parse_qualified_rule(p: &mut Parser, loc: Loc, nested: bool) -> PResult<Option<CssRule>> {
    let delims = if nested { D_CURLY | D_SEMI } else { D_CURLY };
    let sel = p.parse_until_before(delims, |p| parse_selector_list(p, nested));
    let sel_warnings: Vec<ParseError> = SEL_WARNINGS.with(|w| std::mem::take(&mut *w.borrow_mut()));
    match p.next() {
        Ok(Token::CurlyBracketBlock) => {}
        Ok(_) | Err(_) => {
            let sel = sel?;
            let _ = sel;
            return Err(p.err(ErrorKind::EndOfInput));
        }
    }
    let sel = sel?;
    for w in sel_warnings {
        push_warning(w);
    }
    let sel = crate::selector_util::normalize_list(sel, nested);
    let (decls, rules) = p.parse_nested_block(parse_style_body)?;
    Ok(Some(CssRule::Style(StyleRule { selectors: sel, decls, rules, loc, prefix: 0 })))
}

/// Parse body of a style rule: declarations and nested rules.
pub fn parse_style_body(p: &mut Parser) -> PResult<(DeclBlock, Vec<CssRule>)> {
    let mut main = DeclBlock::default();
    let mut pending = DeclBlock::default();
    let mut rules: Vec<CssRule> = Vec::new();
    loop {
        p.skip_whitespace();
        let start = p.state();
        let loc = loc_of(p);
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        let flush_pending = |pending: &mut DeclBlock, rules: &mut Vec<CssRule>, main: &mut DeclBlock| {
            if !pending.is_empty() {
                if rules.is_empty() {
                    // shouldn't happen
                    main.decls.extend(pending.decls.drain(..));
                    main.important.extend(pending.important.drain(..));
                } else {
                    rules.push(CssRule::NestedDecls(std::mem::take(pending)));
                }
            }
        };
        match t {
            Token::Semicolon | Token::WhiteSpace(_) | Token::Comment(_) => continue,
            Token::AtKeyword(name) => {
                let r = parse_at_rule(p, &name, loc, Ctx::Style);
                match r {
                    Ok(Some(rule)) => {
                        if rules.is_empty() {
                            main.decls.extend(pending.decls.drain(..));
                            main.important.extend(pending.important.drain(..));
                        }
                        flush_pending(&mut pending, &mut rules, &mut main);
                        rules.push(rule);
                    }
                    Ok(None) => {}
                    Err(e) => {
                        if crate::options::error_recovery() {
                            push_warning(e);
                        } else {
                            return Err(e);
                        }
                    }
                }
            }
            Token::Ident(name) => {
                let r = p.parse_until_after(D_SEMI | D_CURLY, |p| parse_declaration(p, &name));
                match r {
                    Ok((prop, imp)) => {
                        let target = if rules.is_empty() { &mut main } else { &mut pending };
                        if imp {
                            target.important.push(prop);
                        } else {
                            target.decls.push(prop);
                        }
                    }
                    Err(e) => {
                        p.reset(start);
                        match parse_qualified_rule(p, loc.clone(), true) {
                            Ok(Some(rule)) => {
                                if rules.is_empty() {
                                    main.decls.extend(pending.decls.drain(..));
                                    main.important.extend(pending.important.drain(..));
                                }
                                flush_pending(&mut pending, &mut rules, &mut main);
                                rules.push(rule);
                            }
                            Ok(None) => {}
                            Err(_) => {
                                // recover: skip to after ; or block
                                p.reset(start);
                                let _ = p.parse_until_after(D_SEMI, |_| Ok(()));
                                main = DeclBlock::default();
                                if crate::options::error_recovery() {
                                    push_warning(e);
                                } else {
                                    return Err(e);
                                }
                            }
                        }
                    }
                }
            }
            _ => {
                p.reset(start);
                match parse_qualified_rule(p, loc.clone(), true) {
                    Ok(Some(rule)) => {
                        if rules.is_empty() {
                            main.decls.extend(pending.decls.drain(..));
                            main.important.extend(pending.important.drain(..));
                        }
                        flush_pending(&mut pending, &mut rules, &mut main);
                        rules.push(rule);
                    }
                    Ok(None) => {}
                    Err(e) => {
                        p.reset(start);
                        let _ = p.parse_until_after(D_SEMI, |_| Ok(()));
                        main = DeclBlock::default();
                        if crate::options::error_recovery() {
                            push_warning(e);
                        } else {
                            return Err(e);
                        }
                    }
                }
            }
        }
    }
    if !pending.is_empty() {
        if rules.is_empty() {
            main.decls.extend(pending.decls);
            main.important.extend(pending.important);
        } else {
            rules.push(CssRule::NestedDecls(pending));
        }
    }
    Ok((main, rules))
}

fn parse_layer_name(p: &mut Parser) -> PResult<Vec<String>> {
    let mut parts = vec![p.expect_ident()?.to_string()];
    loop {
        let st = p.state();
        match p.next_including_whitespace() {
            Ok(Token::Delim('.')) => match p.next_including_whitespace() {
                Ok(Token::Ident(s)) => parts.push(s.clone()),
                _ => {
                    p.reset(st);
                    return p.invalid();
                }
            },
            _ => {
                p.reset(st);
                break;
            }
        }
    }
    Ok(parts)
}

fn parse_keyframe_selector(p: &mut Parser) -> PResult<KeyframeSel> {
    let loc = p.location();
    match p.next()?.clone() {
        Token::Ident(s) if s.eq_ignore_ascii_case("from") => Ok(KeyframeSel::From),
        Token::Ident(s) if s.eq_ignore_ascii_case("to") => Ok(KeyframeSel::To),
        Token::Percentage { unit_value, .. } => Ok(KeyframeSel::Pct(unit_value)),
        Token::Ident(s) => {
            let l = s.to_ascii_lowercase();
            if matches!(l.as_str(), "cover" | "contain" | "entry" | "exit" | "entry-crossing" | "exit-crossing") {
                let pct = p.expect_percentage()?;
                Ok(KeyframeSel::Timeline(l, pct))
            } else {
                Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), (loc.0, loc.1)))
            }
        }
        t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    }
}

fn parse_keyframes_body(p: &mut Parser) -> PResult<Vec<Keyframe>> {
    let mut out = Vec::new();
    loop {
        p.skip_whitespace();
        if p.is_exhausted() {
            break;
        }
        let r = (|| -> PResult<Keyframe> {
            let sels = p.parse_until_before(D_CURLY, |p| {
                let mut v = Vec::new();
                loop {
                    v.push(parse_keyframe_selector(p)?);
                    if !p.try_comma() {
                        break;
                    }
                }
                Ok(v)
            });
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    sels?;
                    return Err(p.err(ErrorKind::EndOfInput));
                }
            }
            let sels = sels?;
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| parse_declaration_list(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            Ok(Keyframe { selectors: sels, decls })
        })();
        match r {
            Ok(k) => out.push(k),
            Err(e) => {
                if crate::options::error_recovery() {
                    push_warning(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok(out)
}

fn strip_prefix_at(name: &str) -> (u8, String) {
    let l = name.to_ascii_lowercase();
    for (pre, bit) in [("-webkit-", crate::prefixes::WEBKIT), ("-moz-", crate::prefixes::MOZ), ("-ms-", crate::prefixes::MS), ("-o-", crate::prefixes::O)] {
        if let Some(rest) = l.strip_prefix(pre) {
            return (bit, rest.to_string());
        }
    }
    (0, l)
}

fn parse_unknown_at_rule(p: &mut Parser, name: &str, loc: Loc) -> PResult<Option<CssRule>> {
    push_warning(ParseError { kind: ErrorKind::AtRuleInvalid(name.to_string()), line: loc.line, col: loc.col + name.len() as u32 + 1 });
    let prelude = p.parse_until_before(D_SEMI | D_CURLY, TokenList::parse)?;
    let block = match p.next() {
        Ok(Token::CurlyBracketBlock) => Some(p.parse_nested_block(TokenList::parse)?),
        _ => None,
    };
    Ok(Some(CssRule::Unknown(UnknownAtRule { name: name.to_string(), prelude, block }, loc)))
}

pub fn parse_at_rule(p: &mut Parser, name: &str, loc: Loc, ctx: Ctx) -> PResult<Option<CssRule>> {
    let (prefix, base) = strip_prefix_at(name);
    let lname = name.to_ascii_lowercase();
    let in_style = matches!(ctx, Ctx::Style);
    let top = match &ctx {
        Ctx::Top(_) => true,
        _ => false,
    };
    // state handling for top-level
    if let Ctx::Top(state) = ctx {
        match lname.as_str() {
            "import" => {
                if **state > TopState::Imports {
                    let e = p.err_at(ErrorKind::UnexpectedImportRule, (loc.line, loc.col + 7));
                    let _ = p.parse_until_before(D_SEMI | D_CURLY, |p| { while p.next().is_ok() {} Ok(()) });
                    let _ = p.next();
                    return Err(e);
                }
                **state = TopState::Imports;
            }
            "namespace" => {
                if **state > TopState::Namespaces {
                    let e = p.err_at(ErrorKind::UnexpectedNamespaceRule, (loc.line, loc.col));
                    let _ = p.parse_until_before(D_SEMI | D_CURLY, |p| { while p.next().is_ok() {} Ok(()) });
                    let _ = p.next();
                    return Err(e);
                }
                **state = TopState::Namespaces;
            }
            "charset" => {}
            "layer" => {
                if **state <= TopState::Layers {
                    **state = TopState::Layers;
                } else if **state < TopState::Body {
                    **state = TopState::Body;
                }
            }
            "custom-media" if crate::options::custom_media() => {}
            _ => {
                **state = TopState::Body;
            }
        }
    }
    let _ = top;
    match lname.as_str() {
        "charset" => {
            let _ = p.parse_until_before(D_SEMI | D_CURLY, |p| { while p.next().is_ok() {} Ok(()) });
            let _ = p.next();
            return Ok(None);
        }
        "import" if !in_style => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let url = p.expect_url_or_string()?;
                let mut layer = None;
                if p.try_ident_matching("layer") {
                    layer = Some(None);
                } else if let Ok(l) = p.try_parse(|p| {
                    p.expect_function_matching("layer")?;
                    p.parse_nested_block(parse_layer_name)
                }) {
                    layer = Some(Some(l));
                }
                let supports = p
                    .try_parse(|p| {
                        p.expect_function_matching("supports")?;
                        p.parse_nested_block(|p| {
                            p.try_parse(parse_supports_condition).or_else(|_| parse_supports_decl(p))
                        })
                    })
                    .ok();
                let media = parse_media_list(p)?;
                Ok(ImportRule { url, layer, supports, media, loc: loc.clone() })
            });
            let is_block = matches!(p.next(), Ok(Token::CurlyBracketBlock));
            let r = r?;
            if is_block {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::CurlyBracketBlock)));
            }
            return Ok(Some(CssRule::Import(r)));
        }
        "namespace" if !in_style => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let prefix = p.try_parse(|p| p.expect_ident_cloned()).ok();
                let url = p.expect_url_or_string()?;
                Ok((prefix, url))
            });
            let _ = p.next();
            let (prefix, url) = r?;
            if prefix.is_none() {
                DEFAULT_NS.with(|n| *n.borrow_mut() = Some(url.clone()));
            }
            return Ok(Some(CssRule::Namespace(prefix, url, loc)));
        }
        "media" => {
            let media = p.parse_until_before(D_SEMI | D_CURLY, parse_media_list);
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    media?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            let media = media?;
            let rules = parse_rules_block(p, in_style)?;
            return Ok(Some(CssRule::Media(media, rules, loc)));
        }
        "supports" => {
            let cond = p.parse_until_before(D_SEMI | D_CURLY, parse_supports_condition);
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    cond?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            let cond = cond?;
            let rules = parse_rules_block(p, in_style)?;
            return Ok(Some(CssRule::Supports(cond, rules, loc)));
        }
        "container" => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let name = p
                    .try_parse(|p| {
                        let n = p.expect_ident()?.to_string();
                        let l = n.to_ascii_lowercase();
                        if matches!(l.as_str(), "none" | "and" | "not" | "or") {
                            return p.invalid();
                        }
                        Ok(n)
                    })
                    .ok();
                let cond = parse_container_condition(p)?;
                Ok((name, cond))
            });
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    r?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            let (name, cond) = r?;
            let rules = parse_rules_block(p, in_style)?;
            return Ok(Some(CssRule::Container(name, cond, rules, loc)));
        }
        "layer" => {
            let names = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let mut v = Vec::new();
                if p.is_exhausted() {
                    return Ok(v);
                }
                loop {
                    v.push(parse_layer_name(p)?);
                    if !p.try_comma() {
                        break;
                    }
                }
                Ok(v)
            });
            let is_block = matches!(p.next(), Ok(Token::CurlyBracketBlock));
            let names = names?;
            if is_block {
                if names.len() > 1 {
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Comma)));
                }
                let rules = parse_rules_block(p, in_style)?;
                return Ok(Some(CssRule::LayerBlock(names.into_iter().next(), rules, loc)));
            }
            if names.is_empty() {
                return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Semicolon), (loc.line, loc.col + 6)));
            }
            return Ok(Some(CssRule::LayerStatement(names, loc)));
        }
        "starting-style" => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |_p| Ok(()));
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    r?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            r?;
            let rules = parse_rules_block(p, in_style)?;
            return Ok(Some(CssRule::StartingStyle(rules, loc)));
        }
        "scope" => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let start = p
                    .try_parse(|p| {
                        p.expect_parenthesis_block()?;
                        p.parse_nested_block(|p| parse_selector_list(p, false))
                    })
                    .ok();
                let end = if p.try_ident_matching("to") {
                    p.expect_parenthesis_block()?;
                    Some(p.parse_nested_block(|p| parse_selector_list(p, false))?)
                } else {
                    None
                };
                Ok((start, end))
            });
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    r?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            let (start, end) = r?;
            let rules = p.parse_nested_block(|p| {
                let (decls, rules) = parse_style_body(p)?;
                let mut out = Vec::new();
                if !decls.is_empty() {
                    out.push(CssRule::NestedDecls(decls));
                }
                out.extend(rules);
                Ok(out)
            })?;
            return Ok(Some(CssRule::Scope(start, end, rules, loc)));
        }
        _ => {}
    }
    if in_style {
        // other at-rules not allowed inside style rules
        if !matches!(base.as_str(), "nest") {
            return parse_unknown_at_rule(p, name, loc);
        }
    }
    match base.as_str() {
        "keyframes" if prefix == 0 || matches!(prefix, crate::prefixes::WEBKIT | crate::prefixes::MOZ | crate::prefixes::O) => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let loc = p.location();
                match p.next()?.clone() {
                    Token::Ident(s) => {
                        let l = s.to_ascii_lowercase();
                        if matches!(l.as_str(), "none" | "initial" | "inherit" | "unset" | "default" | "revert" | "revert-layer") {
                            return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc));
                        }
                        Ok(KeyframesName::Ident(s))
                    }
                    Token::QuotedString(s) => Ok(KeyframesName::Str(s)),
                    t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
                }
            });
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => {
                    r?;
                    return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
                }
            }
            let name = r?;
            let kfs = p.parse_nested_block(parse_keyframes_body)?;
            return Ok(Some(CssRule::Keyframes(KeyframesRule { name, keyframes: kfs, prefix, loc })));
        }
        "font-face" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |_| Ok(()));
            let blk = expect_block_or_semicolon(p)?;
            r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| crate::fontface::parse_font_face_block(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            return Ok(Some(CssRule::FontFace(decls, loc)));
        }
        "font-palette-values" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let n = p.expect_ident()?.to_string();
                if !n.starts_with("--") {
                    return p.invalid();
                }
                Ok(n)
            });
            let blk = expect_block_or_semicolon(p)?;
            let n = r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| crate::fontface::parse_font_palette_block(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            return Ok(Some(CssRule::FontPaletteValues(n, decls, loc)));
        }
        "font-feature-values" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, crate::fontface::parse_family_list);
            let blk = expect_block_or_semicolon(p)?;
            let fams = r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let blocks = p.parse_nested_block(crate::fontface::parse_ffv_body)?;
            return Ok(Some(CssRule::FontFeatureValues(FontFeatureValuesRule { families: fams, blocks }, loc)));
        }
        "page" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, parse_page_selectors);
            let blk = expect_block_or_semicolon(p)?;
            let sels = r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let (decls, margins) = p.parse_nested_block(parse_page_body)?;
            return Ok(Some(CssRule::Page(PageRule { selectors: sels, decls, margins, loc })));
        }
        "counter-style" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let n = p.expect_ident()?.to_string();
                let l = n.to_ascii_lowercase();
                if matches!(l.as_str(), "none" | "initial" | "inherit" | "unset" | "default" | "revert" | "revert-layer" | "decimal" | "disc") {
                    return p.invalid();
                }
                Ok(n)
            });
            let blk = expect_block_or_semicolon(p)?;
            let n = r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| parse_declaration_list(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            return Ok(Some(CssRule::CounterStyle(n, decls, loc)));
        }
        "document" if prefix == crate::prefixes::MOZ => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                p.expect_function_matching("url-prefix")?;
                p.parse_nested_block(|p| {
                    let _ = p.try_parse(|p| p.expect_string().map(|_| ()));
                    p.expect_exhausted()
                })
            });
            let blk = expect_block_or_semicolon(p)?;
            r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let rules = parse_rules_block(p, false)?;
            return Ok(Some(CssRule::MozDocument(rules, loc)));
        }
        "viewport" if prefix == 0 || prefix == crate::prefixes::MS || prefix == crate::prefixes::O || prefix == crate::prefixes::WEBKIT || prefix == crate::prefixes::MOZ => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |_| Ok(()));
            let blk = expect_block_or_semicolon(p)?;
            r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| parse_declaration_list(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            return Ok(Some(CssRule::Viewport(prefix, decls, loc)));
        }
        "custom-media" if prefix == 0 && crate::options::custom_media() => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let n = p.expect_ident()?.to_string();
                if !n.starts_with("--") {
                    return p.invalid();
                }
                let m = parse_media_list(p)?;
                Ok((n, m))
            });
            let blk = expect_block_or_semicolon(p)?;
            let (n, m) = r?;
            if blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::CurlyBracketBlock)));
            }
            return Ok(Some(CssRule::CustomMedia(n, m, loc)));
        }
        "property" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |p| {
                let n = p.expect_ident()?.to_string();
                if !n.starts_with("--") {
                    return p.invalid();
                }
                Ok(n)
            });
            let blk = expect_block_or_semicolon(p)?;
            let n = r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let pr = p.parse_nested_block(|p| crate::syntax::parse_property_rule(p, n.clone(), loc.clone()))?;
            return Ok(Some(CssRule::Property(pr)));
        }
        "view-transition" if prefix == 0 => {
            let r = p.parse_until_before(D_SEMI | D_CURLY, |_| Ok(()));
            let blk = expect_block_or_semicolon(p)?;
            r?;
            if !blk {
                return Err(p.err(ErrorKind::UnexpectedToken(Token::Semicolon)));
            }
            let mut warnings = Vec::new();
            let decls = p.parse_nested_block(|p| parse_declaration_list(p, &mut warnings))?;
            for w in warnings {
                push_warning(w);
            }
            return Ok(Some(CssRule::ViewTransition(decls, loc)));
        }
        _ => {}
    }
    parse_unknown_at_rule(p, name, loc)
}

fn parse_page_selectors(p: &mut Parser) -> PResult<Vec<PageSelector>> {
    let mut v = Vec::new();
    if p.is_exhausted() {
        return Ok(v);
    }
    loop {
        p.skip_whitespace();
        let name = p.try_parse(|p| p.expect_ident_cloned()).ok();
        let mut pseudos = Vec::new();
        loop {
            let st = p.state();
            match p.next_including_whitespace() {
                Ok(Token::Colon) => {
                    let n = match p.next_including_whitespace() {
                        Ok(Token::Ident(s)) => s.to_ascii_lowercase(),
                        _ => return Err(p.err(ErrorKind::InvalidPageSelector)),
                    };
                    if !matches!(n.as_str(), "left" | "right" | "first" | "last" | "blank") {
                        return Err(p.err(ErrorKind::InvalidPageSelector));
                    }
                    pseudos.push(n);
                }
                _ => {
                    p.reset(st);
                    break;
                }
            }
        }
        if name.is_none() && pseudos.is_empty() {
            return Err(p.err(ErrorKind::InvalidPageSelector));
        }
        v.push(PageSelector { name, pseudos });
        p.skip_whitespace();
        if !p.try_comma() {
            break;
        }
    }
    Ok(v)
}

const PAGE_MARGINS: &[&str] = &[
    "top-left-corner", "top-left", "top-center", "top-right", "top-right-corner", "bottom-left-corner", "bottom-left",
    "bottom-center", "bottom-right", "bottom-right-corner", "left-top", "left-middle", "left-bottom", "right-top",
    "right-middle", "right-bottom",
];

fn parse_page_body(p: &mut Parser) -> PResult<(DeclBlock, Vec<PageMarginRule>)> {
    let mut block = DeclBlock::default();
    let mut margins = Vec::new();
    loop {
        p.skip_whitespace();
        let loc = p.location();
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        match t {
            Token::Semicolon => continue,
            Token::AtKeyword(name) => {
                let l = name.to_ascii_lowercase();
                if PAGE_MARGINS.contains(&l.as_str()) {
                    let r = p.parse_until_before(D_SEMI | D_CURLY, |_| Ok(()));
                    let blk = expect_block_or_semicolon(p)?;
                    r?;
                    if blk {
                        let mut warnings = Vec::new();
                        let decls = p.parse_nested_block(|p| parse_declaration_list(p, &mut warnings))?;
                        margins.push(PageMarginRule { name: l, decls });
                    }
                } else {
                    let e = p.err_at(ErrorKind::AtRuleInvalid(name.clone()), loc);
                    let _ = p.parse_until_before(D_SEMI | D_CURLY, |p| { while p.next().is_ok() {} Ok(()) });
                    let _ = p.next();
                    if crate::options::error_recovery() {
                        push_warning(e);
                    } else {
                        return Err(e);
                    }
                }
            }
            Token::Ident(name) => {
                let r = p.parse_until_after(D_SEMI, |p| parse_declaration(p, &name));
                match r {
                    Ok((prop, imp)) => {
                        if imp {
                            block.important.push(prop);
                        } else {
                            block.decls.push(prop);
                        }
                    }
                    Err(e) => {
                        if crate::options::error_recovery() {
                            push_warning(e);
                        } else {
                            return Err(e);
                        }
                    }
                }
            }
            t => {
                let e = p.err_at(ErrorKind::UnexpectedToken(t), loc);
                let _ = p.parse_until_after(D_SEMI, |_| Ok(()));
                if crate::options::error_recovery() {
                    push_warning(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok((block, margins))
}

// ---------------- Printing ----------------

pub fn rules_to_css(rules: &[CssRule], d: &mut Printer) {
    let mut first = true;
    let mut last_without_block = false;
    for rule in rules {
        if let CssRule::Ignored = rule {
            continue;
        }
        if first {
            first = false;
        } else {
            let nb = matches!(rule, CssRule::Import(..) | CssRule::Namespace(..) | CssRule::LayerStatement(..));
            if !d.minify && !(last_without_block && nb) {
                d.write_char('\n');
            }
            d.newline();
        }
        rule_to_css(rule, d);
        last_without_block = matches!(rule, CssRule::Import(..) | CssRule::Namespace(..) | CssRule::LayerStatement(..));
    }
}

fn block_rules(d: &mut Printer, rules: &[CssRule]) {
    d.whitespace();
    d.write_char('{');
    d.indent();
    d.newline();
    rules_to_css(rules, d);
    d.dedent();
    d.newline();
    d.write_char('}');
}

pub fn write_layer_name(d: &mut Printer, n: &[String]) {
    for (i, part) in n.iter().enumerate() {
        if i > 0 {
            d.write_char('.');
        }
        d.write_ident(part);
    }
}

pub fn style_rule_to_css(r: &StyleRule, d: &mut Printer) {
    d.add_mapping(r.loc.line, r.loc.col - 1);
    crate::nesting::write_selectors(&r.selectors, d);
    d.whitespace();
    d.write_char('{');
    d.indent();
    let has_rules = r.rules.iter().any(|x| !matches!(x, CssRule::Ignored));
    r.decls.to_css_inner(d, has_rules);
    if has_rules {
        if !d.minify && !r.decls.is_empty() {
            d.write_char('\n');
        }
        d.newline();
        crate::nesting::with_parent(&r.selectors, || rules_to_css(&r.rules, d));
    }
    d.dedent();
    d.newline();
    d.write_char('}');
}

pub fn rule_to_css(rule: &CssRule, d: &mut Printer) {
    match rule {
        CssRule::Style(r) => style_rule_to_css(r, d),
        CssRule::NestedDecls(decls) => {
            let total = decls.len();
            let mut i = 0;
            for (list, imp) in [(&decls.decls, false), (&decls.important, true)] {
                for p in list.iter() {
                    if i > 0 {
                        d.newline();
                    }
                    p.to_css(d, imp);
                    i += 1;
                    if i < total || !d.minify {
                        d.write_char(';');
                    }
                }
            }
        }
        CssRule::Media(m, rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@media");
            if !m.0.is_empty() {
                d.write_char(' ');
                m.to_css(d);
            }
            block_rules(d, rules);
        }
        CssRule::Supports(c, rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@supports ");
            c.to_css(d);
            block_rules(d, rules);
        }
        CssRule::Container(name, c, rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@container ");
            if let Some(n) = name {
                d.write_ident(n);
                d.write_char(' ');
            }
            c.to_css(d);
            block_rules(d, rules);
        }
        CssRule::Import(r) => {
            d.add_mapping(r.loc.line, r.loc.col - 1);
            d.write_str("@import ");
            d.write_string(&r.url);
            if let Some(l) = &r.layer {
                d.write_str(" layer");
                if let Some(n) = l {
                    d.write_char('(');
                    write_layer_name(d, n);
                    d.write_char(')');
                }
            }
            if let Some(s) = &r.supports {
                d.write_str(" supports(");
                s.to_css_in_parens_ctx(d, true);
                d.write_char(')');
            }
            if !r.media.0.is_empty() {
                d.write_char(' ');
                r.media.to_css(d);
            }
            d.write_char(';');
        }
        CssRule::Namespace(prefix, url, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@namespace ");
            if let Some(p) = prefix {
                d.write_ident(p);
                d.write_char(' ');
            }
            d.write_string(url);
            d.write_char(';');
        }
        CssRule::LayerStatement(names, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@layer ");
            for (i, n) in names.iter().enumerate() {
                if i > 0 {
                    d.delim(',', false);
                }
                write_layer_name(d, n);
            }
            d.write_char(';');
        }
        CssRule::LayerBlock(name, rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@layer");
            if let Some(n) = name {
                d.write_char(' ');
                write_layer_name(d, n);
            }
            block_rules(d, rules);
        }
        CssRule::StartingStyle(rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@starting-style");
            block_rules(d, rules);
        }
        CssRule::Scope(start, end, rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@scope");
            d.whitespace();
            if let Some(s) = start {
                d.write_char('(');
                s.to_css(d);
                d.write_char(')');
                d.whitespace();
            }
            if let Some(e) = end {
                if d.minify && start.is_some() {
                    d.write_char(' ');
                }
                d.write_str("to");
                d.whitespace();
                d.write_char('(');
                e.to_css(d);
                d.write_char(')');
                d.whitespace();
            }
            d.write_char('{');
            d.indent();
            d.newline();
            crate::nesting::with_scope(|| rules_to_css(rules, d));
            d.dedent();
            d.newline();
            d.write_char('}');
        }
        CssRule::MozDocument(rules, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@-moz-document url-prefix()");
            block_rules(d, rules);
        }
        CssRule::Keyframes(k) => crate::keyframes::keyframes_to_css(k, d),
        CssRule::FontFace(decls, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@font-face");
            decls.to_css_block(d);
        }
        CssRule::FontPaletteValues(name, decls, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@font-palette-values ");
            d.write_dashed_ident_ref(name);
            decls.to_css_block(d);
        }
        CssRule::FontFeatureValues(r, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            crate::fontface::ffv_to_css(r, d);
        }
        CssRule::CounterStyle(name, decls, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@counter-style ");
            crate::css_modules::write_local_ident_kind(d, name, crate::css_modules::Kind::CounterStyle);
            decls.to_css_block(d);
        }
        CssRule::Viewport(prefix, decls, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_char('@');
            d.write_str(crate::prefixes::prefix_str(*prefix));
            d.write_str("viewport");
            decls.to_css_block(d);
        }
        CssRule::CustomMedia(name, m, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@custom-media ");
            d.write_str(name);
            d.write_char(' ');
            m.to_css(d);
            d.write_char(';');
        }
        CssRule::Property(pr) => crate::syntax::property_rule_to_css(pr, d),
        CssRule::ViewTransition(decls, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_str("@view-transition");
            decls.to_css_block(d);
        }
        CssRule::Page(pr) => {
            d.add_mapping(pr.loc.line, pr.loc.col - 1);
            d.write_str("@page");
            if !pr.selectors.is_empty() {
                let first_has_name = pr.selectors[0].name.is_some();
                if first_has_name || !d.minify {
                    d.write_char(' ');
                }
                for (i, s) in pr.selectors.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    if let Some(n) = &s.name {
                        d.write_ident(n);
                    }
                    for ps in &s.pseudos {
                        d.write_char(':');
                        d.write_str(ps);
                    }
                }
            }
            d.whitespace();
            d.write_char('{');
            d.indent();
            let total = pr.decls.len();
            let has_margins = !pr.margins.is_empty();
            let mut i = 0;
            for (list, imp) in [(&pr.decls.decls, false), (&pr.decls.important, true)] {
                for p in list.iter() {
                    d.newline();
                    p.to_css(d, imp);
                    i += 1;
                    if i < total || !d.minify || has_margins {
                        d.write_char(';');
                    }
                }
            }
            if has_margins {
                if !d.minify && total > 0 {
                    d.write_char('\n');
                }
                for (i, m) in pr.margins.iter().enumerate() {
                    if i > 0 && !d.minify {
                        d.write_char('\n');
                    }
                    d.newline();
                    d.write_char('@');
                    d.write_str(&m.name);
                    m.decls.to_css_block(d);
                }
            }
            d.dedent();
            d.newline();
            d.write_char('}');
        }
        CssRule::Unknown(u, loc) => {
            d.add_mapping(loc.line, loc.col - 1);
            d.write_char('@');
            d.write_ident(&u.name);
            if !u.prelude.is_empty() {
                d.write_char(' ');
                u.prelude.to_css(d, false);
            }
            if let Some(b) = &u.block {
                d.whitespace();
                d.write_char('{');
                d.indent();
                d.newline();
                b.to_css(d, false);
                d.dedent();
                d.newline();
                d.write_char('}');
            } else {
                d.write_char(';');
            }
        }
        CssRule::Ignored => {}
    }
}

impl Property {
    pub fn is_custom_like(&self) -> bool {
        matches!(self, Property::Custom(..) | Property::Unknown(..))
    }
}
