// Media queries, @supports and @container conditions.
use crate::parser::*;
use crate::printer::Printer;
use crate::tokenizer::Token;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum MediaType {
    All,
    Print,
    Screen,
    Custom(String),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Qualifier {
    Only,
    Not,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Op {
    And,
    Or,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum RangeOp {
    Eq,
    Gt,
    Ge,
    Lt,
    Le,
}

impl RangeOp {
    fn s(&self) -> &'static str {
        match self {
            RangeOp::Eq => "=",
            RangeOp::Gt => ">",
            RangeOp::Ge => ">=",
            RangeOp::Lt => "<",
            RangeOp::Le => "<=",
        }
    }
    fn flip(&self) -> RangeOp {
        match self {
            RangeOp::Eq => RangeOp::Eq,
            RangeOp::Gt => RangeOp::Lt,
            RangeOp::Ge => RangeOp::Le,
            RangeOp::Lt => RangeOp::Gt,
            RangeOp::Le => RangeOp::Ge,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum FValue {
    Len(NumVal),
    Num(f32),
    Int(i32),
    Ratio(f32, f32),
    Res(Dim),
    Ident(String),
    Env(crate::tokenlist::TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Feature {
    Plain(String, FValue),
    Boolean(String),
    Range(String, RangeOp, FValue),
    Interval(String, FValue, RangeOp, FValue, RangeOp),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Cond {
    Feature(Feature),
    Not(Box<Cond>),
    Op(Op, Vec<Cond>),
    // container-specific
    Style(Box<StyleQuery>),
    ScrollState(crate::tokenlist::TokenList),
    Unknown(crate::tokenlist::TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub enum StyleQuery {
    Decl(String, crate::tokenlist::TokenList),
    Prop(String),
    Not(Box<StyleQuery>),
    Op(Op, Vec<StyleQuery>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct MediaQuery {
    pub qualifier: Option<Qualifier>,
    pub media_type: MediaType,
    pub condition: Option<Cond>,
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct MediaList(pub Vec<MediaQuery>);

pub type ContainerCondition = Option<Cond>;

// feature kinds
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum FKind {
    Length,
    Ratio,
    Resolution,
    Integer,
    Number,
    Ident,
    Unknown,
}

fn feature_kind(name: &str, container: bool) -> FKind {
    match name {
        "width" | "height" | "inline-size" | "block-size" => FKind::Length,
        "device-width" | "device-height" if !container => FKind::Length,
        "aspect-ratio" => FKind::Ratio,
        "device-aspect-ratio" if !container => FKind::Ratio,
        "orientation" => FKind::Ident,
        _ if container => FKind::Unknown,
        "resolution" => FKind::Resolution,
        "color" | "color-index" | "monochrome" | "grid" => FKind::Integer,
        "-webkit-device-pixel-ratio" | "-moz-device-pixel-ratio" => FKind::Number,
        "scan" | "update" | "overflow-block" | "overflow-inline" | "color-gamut" | "pointer" | "hover" | "any-pointer"
        | "any-hover" | "display-mode" | "dynamic-range" | "video-dynamic-range" | "scripting" | "inverted-colors"
        | "forced-colors" | "prefers-color-scheme" | "prefers-contrast" | "prefers-reduced-motion"
        | "prefers-reduced-transparency" | "prefers-reduced-data" | "environment-blending" | "nav-controls" => FKind::Ident,
        _ => FKind::Unknown,
    }
}

fn is_range_kind(k: FKind) -> bool {
    matches!(k, FKind::Length | FKind::Ratio | FKind::Resolution | FKind::Integer | FKind::Number | FKind::Unknown)
}

fn parse_fvalue(p: &mut Parser, kind: FKind) -> PResult<FValue> {
    match kind {
        FKind::Length => {
            let v = parse_numval(p, C_LEN, true)?;
            Ok(FValue::Len(v))
        }
        FKind::Ratio => parse_ratio(p),
        FKind::Resolution => parse_resolution(p),
        FKind::Integer => Ok(FValue::Int(parse_integer(p)?)),
        FKind::Number => Ok(FValue::Num(parse_number(p)?)),
        FKind::Ident => Ok(FValue::Ident(p.expect_ident()?.to_string())),
        FKind::Unknown => {
            if let Ok(v) = p.try_parse(|p| parse_numval(p, C_LEN, false)) {
                return Ok(FValue::Len(v));
            }
            if let Ok(v) = p.try_parse(parse_resolution) {
                return Ok(FValue::Res(match v {
                    FValue::Res(d) => d,
                    _ => unreachable!(),
                }));
            }
            if let Ok(v) = p.try_parse(parse_ratio_strict) {
                return Ok(v);
            }
            if let Ok(n) = p.try_parse(parse_number) {
                return Ok(FValue::Num(n));
            }
            if let Ok(e) = p.try_parse(|p| {
                p.expect_function_matching("env")?;
                p.parse_nested_block(crate::tokenlist::TokenList::parse)
            }) {
                return Ok(FValue::Env(e));
            }
            Ok(FValue::Ident(p.expect_ident()?.to_string()))
        }
    }
}

fn parse_ratio_strict(p: &mut Parser) -> PResult<FValue> {
    let a = parse_number(p)?;
    p.expect_delim('/')?;
    let b = parse_number(p)?;
    Ok(FValue::Ratio(a, b))
}

fn parse_ratio(p: &mut Parser) -> PResult<FValue> {
    let a = parse_number(p)?;
    let b = if p.try_delim('/') { parse_number(p)? } else { 1.0 };
    Ok(FValue::Ratio(a, b))
}

fn parse_resolution(p: &mut Parser) -> PResult<FValue> {
    let v = parse_numval(p, C_RES, false)?;
    match v {
        NumVal::D(d) => Ok(FValue::Res(d)),
        _ => p.invalid(),
    }
}

impl FValue {
    pub fn to_css(&self, d: &mut Printer, legacy: bool) {
        match self {
            FValue::Len(v) => v.to_css(d),
            FValue::Num(n) => d.write_num(*n),
            FValue::Int(i) => d.write_str(&i.to_string()),
            FValue::Ratio(a, b) => {
                d.write_num(*a);
                d.delim('/', true);
                d.write_num(*b);
            }
            FValue::Res(r) => {
                if legacy && (r.unit == "x" || r.unit == "dppx") {
                    write_dimension(d, r.v, "dppx");
                } else {
                    r.to_css(d);
                }
            }
            FValue::Ident(s) => d.write_ident(s),
            FValue::Env(e) => {
                d.write_str("env(");
                e.to_css(d, false);
                d.write_char(')');
            }
        }
    }
}

fn parse_feature_name(p: &mut Parser) -> PResult<String> {
    let n = p.expect_ident()?.to_string();
    Ok(n)
}

/// Normalize a feature name: returns (base name, Some(op)) for min-/max- forms.
fn split_min_max(name: &str) -> (String, Option<RangeOp>) {
    let l = name.to_ascii_lowercase();
    if l.starts_with("--") {
        return (name.to_string(), None);
    }
    let (prefix, rest) = if let Some(r) = l.strip_prefix("-webkit-") {
        ("-webkit-", r.to_string())
    } else if let Some(r) = l.strip_prefix("-moz-") {
        ("-moz-", r.to_string())
    } else {
        ("", l.clone())
    };
    if let Some(r) = rest.strip_prefix("min-") {
        if l == "min--moz-device-pixel-ratio" {
            return ("-moz-device-pixel-ratio".into(), Some(RangeOp::Ge));
        }
        return (format!("{}{}", prefix, r), Some(RangeOp::Ge));
    }
    if let Some(r) = rest.strip_prefix("max-") {
        if l == "max--moz-device-pixel-ratio" {
            return ("-moz-device-pixel-ratio".into(), Some(RangeOp::Le));
        }
        return (format!("{}{}", prefix, r), Some(RangeOp::Le));
    }
    if l == "min--moz-device-pixel-ratio" {
        return ("-moz-device-pixel-ratio".into(), Some(RangeOp::Ge));
    }
    if l == "max--moz-device-pixel-ratio" {
        return ("-moz-device-pixel-ratio".into(), Some(RangeOp::Le));
    }
    (l, None)
}

fn parse_range_op(p: &mut Parser) -> PResult<RangeOp> {
    let loc = p.location();
    let t = p.next()?.clone();
    let op = match t {
        Token::Delim('=') => return Ok(RangeOp::Eq),
        Token::Delim('>') => RangeOp::Gt,
        Token::Delim('<') => RangeOp::Lt,
        t => return Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    };
    let st = p.state();
    match p.next_including_whitespace() {
        Ok(Token::Delim('=')) => Ok(match op {
            RangeOp::Gt => RangeOp::Ge,
            _ => RangeOp::Le,
        }),
        _ => {
            p.reset(st);
            Ok(op)
        }
    }
}

fn known_feature(name: &str, container: bool) -> bool {
    feature_kind(name, container) != FKind::Unknown
}

/// Parse the inside of a ( ) feature
fn parse_feature(p: &mut Parser, container: bool) -> PResult<Feature> {
    // try name-first
    if let Ok(f) = p.try_parse(|p| {
        let name = parse_feature_name(p)?;
        p.skip_whitespace();
        if p.is_exhausted() {
            let (base, _) = split_min_max(&name);
            let lname = name.to_ascii_lowercase();
            let n = if known_feature(&lname, container) || lname.starts_with("--") { if lname.starts_with("--") { name.clone() } else { lname } } else { name.clone() };
            let _ = base;
            return Ok(Feature::Boolean(n));
        }
        let st = p.state();
        if p.try_parse(|p| p.expect_colon()).is_ok() {
            let (base, mm) = split_min_max(&name);
            if let Some(op) = mm {
                let kind = feature_kind(&base, container);
                if kind != FKind::Unknown && is_range_kind(kind) {
                    let v = parse_fvalue(p, kind)?;
                    return Ok(Feature::Range(base, op, v));
                }
            }
            let lname = name.to_ascii_lowercase();
            let kind = feature_kind(&lname, container);
            let v = parse_fvalue(p, kind)?;
            let n = if kind != FKind::Unknown { lname } else { name.clone() };
            return Ok(Feature::Plain(n, v));
        }
        p.reset(st);
        let op = parse_range_op(p)?;
        let lname = name.to_ascii_lowercase();
        let kind = feature_kind(&lname, container);
        if !is_range_kind(kind) {
            return p.invalid();
        }
        let v = parse_fvalue(p, kind)?;
        let n = if kind != FKind::Unknown { lname } else { name.clone() };
        Ok(Feature::Range(n, op, v))
    }) {
        return Ok(f);
    }
    // value-first: v op name [op v]
    let v1 = parse_fvalue(p, FKind::Unknown)?;
    let op1 = parse_range_op(p)?;
    let name = parse_feature_name(p)?;
    let lname = name.to_ascii_lowercase();
    let kind = feature_kind(&lname, container);
    // re-type the value
    let v1 = retype(v1, kind);
    let n = if kind != FKind::Unknown { lname } else { name.clone() };
    if p.is_exhausted() {
        return Ok(Feature::Range(n, op1.flip(), v1));
    }
    let op2 = parse_range_op(p)?;
    let v2 = parse_fvalue(p, if kind == FKind::Unknown { FKind::Unknown } else { kind })?;
    // ops must be in same direction
    let lt = |o: RangeOp| matches!(o, RangeOp::Lt | RangeOp::Le);
    let gt = |o: RangeOp| matches!(o, RangeOp::Gt | RangeOp::Ge);
    if !((lt(op1) && lt(op2)) || (gt(op1) && gt(op2))) {
        return p.invalid();
    }
    Ok(Feature::Interval(n, v1, op1, v2, op2))
}

fn retype(v: FValue, kind: FKind) -> FValue {
    match (v, kind) {
        (FValue::Num(n), FKind::Integer) => FValue::Int(n as i32),
        (FValue::Num(n), FKind::Ratio) => FValue::Ratio(n, 1.0),
        (FValue::Num(n), FKind::Length) if n == 0.0 => FValue::Len(NumVal::zero_px()),
        (v, _) => v,
    }
}

fn parse_in_parens(p: &mut Parser, container: bool) -> PResult<Cond> {
    let loc = p.location();
    let t = p.next()?.clone();
    match t {
        Token::ParenthesisBlock => p.parse_nested_block(|p| {
            if let Ok(c) = p.try_parse(|p| parse_condition(p, container, true)) {
                return Ok(c);
            }
            if p.is_exhausted() {
                return Err(p.err(ErrorKind::EmptyBracketInCondition));
            }
            Ok(Cond::Feature(parse_feature(p, container)?))
        }),
        Token::Function(name) if container && name.eq_ignore_ascii_case("style") => {
            p.parse_nested_block(|p| Ok(Cond::Style(Box::new(parse_style_query(p)?))))
        }
        Token::Function(name) if container && name.eq_ignore_ascii_case("scroll-state") => {
            p.parse_nested_block(|p| Ok(Cond::ScrollState(crate::tokenlist::TokenList::parse(p)?)))
        }
        t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    }
}

fn parse_style_query(p: &mut Parser) -> PResult<StyleQuery> {
    if let Ok(q) = p.try_parse(|p| {
        let name = p.expect_ident()?.to_string();
        if p.is_exhausted() {
            return Ok(StyleQuery::Prop(name));
        }
        p.expect_colon()?;
        let v = crate::tokenlist::TokenList::parse(p)?;
        Ok(StyleQuery::Decl(name, v))
    }) {
        return Ok(q);
    }
    if p.try_ident_matching("not") {
        p.expect_parenthesis_block()?;
        let q = p.parse_nested_block(parse_style_query)?;
        return Ok(StyleQuery::Not(Box::new(q)));
    }
    let mut v = Vec::new();
    let mut op = None;
    loop {
        p.expect_parenthesis_block()?;
        v.push(p.parse_nested_block(parse_style_query)?);
        let st = p.state();
        match p.next() {
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("and") && op != Some(Op::Or) => op = Some(Op::And),
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("or") && op != Some(Op::And) => op = Some(Op::Or),
            _ => {
                p.reset(st);
                break;
            }
        }
    }
    if v.len() == 1 {
        return Ok(v.pop().unwrap());
    }
    Ok(StyleQuery::Op(op.unwrap_or(Op::And), v))
}

/// media-condition (allow_or = true) or media-condition-without-or
pub fn parse_condition(p: &mut Parser, container: bool, allow_or: bool) -> PResult<Cond> {
    if p.try_ident_matching("not") {
        let c = parse_in_parens(p, container)?;
        return Ok(Cond::Not(Box::new(c)));
    }
    let first = parse_in_parens(p, container)?;
    let mut conds = vec![first];
    let mut op: Option<Op> = None;
    loop {
        let st = p.state();
        let o = match p.next() {
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("and") => Op::And,
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("or") && allow_or => Op::Or,
            _ => {
                p.reset(st);
                break;
            }
        };
        if let Some(prev) = op {
            if prev != o {
                p.reset(st);
                return p.invalid();
            }
        }
        op = Some(o);
        conds.push(parse_in_parens(p, container)?);
    }
    if conds.len() == 1 {
        return Ok(conds.pop().unwrap());
    }
    Ok(Cond::Op(op.unwrap(), conds))
}

pub fn parse_media_query(p: &mut Parser) -> PResult<MediaQuery> {
    // try condition only
    if let Ok(c) = p.try_parse(|p| parse_condition(p, false, true)) {
        return Ok(MediaQuery { qualifier: None, media_type: MediaType::All, condition: Some(c) });
    }
    let qualifier = if p.try_ident_matching("only") {
        Some(Qualifier::Only)
    } else if p.try_ident_matching("not") {
        Some(Qualifier::Not)
    } else {
        None
    };
    let loc = p.location();
    let t = p.expect_ident()?.to_ascii_lowercase();
    let media_type = match t.as_str() {
        "all" => MediaType::All,
        "print" => MediaType::Print,
        "screen" => MediaType::Screen,
        "only" | "not" | "and" | "or" | "layer" => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(t.clone())), loc)),
        _ => MediaType::Custom(t),
    };
    let condition = if p.try_ident_matching("and") { Some(parse_condition(p, false, false)?) } else { None };
    Ok(MediaQuery { qualifier, media_type, condition })
}

pub fn parse_media_list(p: &mut Parser) -> PResult<MediaList> {
    let mut v = Vec::new();
    p.skip_whitespace();
    if p.is_exhausted() {
        return Ok(MediaList(v));
    }
    loop {
        let r = p.parse_until_before(D_COMMA, parse_media_query);
        match r {
            Ok(q) => v.push(q),
            Err(e) => {
                if crate::options::error_recovery() || true {
                    // invalid media queries become "not all"
                    let _ = e;
                    return Err(e);
                }
            }
        }
        if !p.try_comma() {
            break;
        }
    }
    Ok(MediaList(v))
}

// ---------------- printing ----------------

fn range_legacy() -> bool {
    !crate::targets::supports(crate::targets::Feature::MediaRangeSyntax)
}

impl Feature {
    pub fn to_css(&self, d: &mut Printer, container: bool) {
        match self {
            Feature::Plain(n, v) => {
                d.write_char('(');
                d.write_ident(n);
                d.delim(':', false);
                v.to_css(d, false);
                d.write_char(')');
            }
            Feature::Boolean(n) => {
                d.write_char('(');
                d.write_ident(n);
                d.write_char(')');
            }
            Feature::Range(n, op, v) => {
                if !container && range_legacy() {
                    return legacy_range(d, n, *op, v);
                }
                d.write_char('(');
                d.write_ident(n);
                d.delim_str(op.s());
                v.to_css(d, false);
                d.write_char(')');
            }
            Feature::Interval(n, a, op1, b, op2) => {
                if !container && range_legacy() {
                    // (a op1 n) and (n op2 b)
                    let c1 = legacy_cond(n, op1.flip(), a);
                    let c2 = legacy_cond(n, *op2, b);
                    let c = Cond::Op(Op::And, vec![c1, c2]);
                    c.to_css(d, container);
                    return;
                }
                d.write_char('(');
                a.to_css(d, false);
                d.delim_str(op1.s());
                d.write_ident(n);
                d.delim_str(op2.s());
                b.to_css(d, false);
                d.write_char(')');
            }
        }
    }
}

fn legacy_name(n: &str, prefix: &str) -> String {
    if let Some(rest) = n.strip_prefix("-webkit-") {
        format!("-webkit-{}{}", prefix, rest)
    } else if n == "-moz-device-pixel-ratio" {
        format!("{}-moz-device-pixel-ratio", if prefix == "min-" { "min-" } else { "max-" })
    } else {
        format!("{}{}", prefix, n)
    }
}

pub struct LegacyFeature(pub String, pub FValue);

fn legacy_cond(n: &str, op: RangeOp, v: &FValue) -> Cond {
    let mk = |name: String| Cond::Feature(Feature::Plain(name, v.clone()));
    match op {
        RangeOp::Ge => mk(legacy_name(n, "min-")),
        RangeOp::Le => mk(legacy_name(n, "max-")),
        RangeOp::Gt => Cond::Not(Box::new(mk(legacy_name(n, "max-")))),
        RangeOp::Lt => Cond::Not(Box::new(mk(legacy_name(n, "min-")))),
        RangeOp::Eq => mk(n.to_string()),
    }
}

fn legacy_range(d: &mut Printer, n: &str, op: RangeOp, v: &FValue) {
    let c = legacy_cond(n, op, v);
    print_legacy(&c, d);
}

fn print_legacy(c: &Cond, d: &mut Printer) {
    match c {
        Cond::Feature(Feature::Plain(n, v)) => {
            d.write_char('(');
            d.write_ident(n);
            d.delim(':', false);
            v.to_css(d, true);
            d.write_char(')');
        }
        Cond::Not(inner) => {
            d.write_str("not ");
            print_legacy(inner, d);
        }
        _ => c.to_css(d, false),
    }
}

impl Printer {
    pub fn delim_str(&mut self, s: &str) {
        if self.minify {
            self.write_str(s);
        } else {
            self.write_char(' ');
            self.write_str(s);
            self.write_char(' ');
        }
    }
}

impl Cond {
    fn needs_parens(&self, parent: Option<Op>, container: bool) -> bool {
        match self {
            Cond::Not(_) => true,
            Cond::Op(op, _) => Some(*op) != parent,
            Cond::Feature(Feature::Range(..)) | Cond::Feature(Feature::Interval(..)) if !container && range_legacy() => {
                // legacy expansions might produce not/and
                match self {
                    Cond::Feature(Feature::Range(_, RangeOp::Gt, _)) | Cond::Feature(Feature::Range(_, RangeOp::Lt, _)) => true,
                    Cond::Feature(Feature::Interval(..)) => parent != Some(Op::And),
                    _ => false,
                }
            }
            _ => false,
        }
    }

    pub fn to_css_with_parens(&self, d: &mut Printer, parens: bool, container: bool) {
        if parens {
            d.write_char('(');
            self.to_css(d, container);
            d.write_char(')');
        } else {
            self.to_css(d, container);
        }
    }

    pub fn to_css(&self, d: &mut Printer, container: bool) {
        match self {
            Cond::Feature(f) => f.to_css(d, container),
            Cond::Not(c) => {
                d.write_str("not ");
                let np = c.needs_parens(None, container);
                c.to_css_with_parens(d, np, container);
            }
            Cond::Op(op, conds) => {
                for (i, c) in conds.iter().enumerate() {
                    if i > 0 {
                        d.write_str(match op {
                            Op::And => " and ",
                            Op::Or => " or ",
                        });
                    }
                    let np = c.needs_parens(Some(*op), container);
                    c.to_css_with_parens(d, np, container);
                }
            }
            Cond::Style(q) => {
                d.write_str("style(");
                q.to_css(d);
                d.write_char(')');
            }
            Cond::ScrollState(t) => {
                d.write_str("scroll-state(");
                write_tl_query(d, t);
                d.write_char(')');
            }
            Cond::Unknown(t) => t.to_css(d, false),
        }
    }
}

fn write_tl_query(d: &mut Printer, t: &crate::tokenlist::TokenList) {
    // print "name: value" with minified colon spacing
    let mut after_colon = false;
    for tv in &t.0 {
        match tv {
            crate::tokenlist::TV::Token(Token::Colon) => {
                d.delim(':', false);
                after_colon = true;
            }
            crate::tokenlist::TV::Token(Token::WhiteSpace(_)) if after_colon => {}
            other => {
                after_colon = false;
                other.to_css(d);
            }
        }
    }
}

impl StyleQuery {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            StyleQuery::Decl(n, v) => {
                d.write_dashed_ident_ref(n);
                d.delim(':', false);
                v.to_css(d, true);
            }
            StyleQuery::Prop(n) => d.write_dashed_ident_ref(n),
            StyleQuery::Not(q) => {
                d.write_str("not (");
                q.to_css(d);
                d.write_char(')');
            }
            StyleQuery::Op(op, v) => {
                for (i, q) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_str(match op {
                            Op::And => " and ",
                            Op::Or => " or ",
                        });
                    }
                    d.write_char('(');
                    q.to_css(d);
                    d.write_char(')');
                }
            }
        }
    }
}

impl MediaQuery {
    pub fn to_css(&self, d: &mut Printer) {
        if let Some(q) = self.qualifier {
            d.write_str(match q {
                Qualifier::Only => "only ",
                Qualifier::Not => "not ",
            });
        }
        match &self.media_type {
            MediaType::All => {
                if self.qualifier.is_some() || self.condition.is_none() {
                    d.write_str("all");
                }
            }
            MediaType::Print => d.write_str("print"),
            MediaType::Screen => d.write_str("screen"),
            MediaType::Custom(s) => d.write_ident(s),
        }
        let c = match &self.condition {
            Some(c) => c,
            None => return,
        };
        let needs_parens = if self.media_type != MediaType::All || self.qualifier.is_some() {
            d.write_str(" and ");
            matches!(c, Cond::Op(op, _) if *op != Op::And)
        } else {
            false
        };
        c.to_css_with_parens(d, needs_parens, false);
    }

    pub fn always_matches(&self) -> bool {
        self.qualifier.is_none() && self.media_type == MediaType::All && self.condition.is_none()
    }
    pub fn never_matches(&self) -> bool {
        self.qualifier == Some(Qualifier::Not) && self.media_type == MediaType::All && self.condition.is_none()
    }
}

impl MediaList {
    pub fn to_css(&self, d: &mut Printer) {
        if self.0.is_empty() {
            d.write_str("not all");
            return;
        }
        let mut first = true;
        for q in self.0.iter() {
            for q2 in crate::prefixes::expand_media_query(q) {
                if !first {
                    d.delim(',', false);
                }
                first = false;
                q2.to_css(d);
            }
        }
    }
    pub fn always_matches(&self) -> bool {
        self.0.is_empty() || self.0.iter().all(|q| q.always_matches())
    }
    pub fn never_matches(&self) -> bool {
        !self.0.is_empty() && self.0.iter().all(|q| q.never_matches())
    }
}

// ---------------- @supports ----------------

#[derive(Clone, Debug, PartialEq)]
pub enum SupportsCondition {
    Not(Box<SupportsCondition>),
    And(Vec<SupportsCondition>),
    Or(Vec<SupportsCondition>),
    /// property name (base, lowercase if known), prefix bits (crate::prefixes), known, value
    Decl { name: String, prefixes: u8, known: bool, value: String },
    Selector(String),
    Unknown(String),
}

pub fn parse_supports_condition(p: &mut Parser) -> PResult<SupportsCondition> {
    if p.try_ident_matching("not") {
        let c = parse_supports_in_parens(p)?;
        return Ok(SupportsCondition::Not(Box::new(c)));
    }
    let first = parse_supports_in_parens(p)?;
    let mut conds = vec![first];
    let mut op: Option<Op> = None;
    loop {
        let st = p.state();
        let o = match p.next() {
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("and") => Op::And,
            Ok(Token::Ident(s)) if s.eq_ignore_ascii_case("or") => Op::Or,
            _ => {
                p.reset(st);
                break;
            }
        };
        if let Some(prev) = op {
            if prev != o {
                return p.invalid();
            }
        }
        op = Some(o);
        let c = parse_supports_in_parens(p)?;
        // dedupe / merge
        if let SupportsCondition::Decl { name, known, value, .. } = &c {
            if *known {
                let mut merged = false;
                for ex in conds.iter_mut() {
                    if let SupportsCondition::Decl { name: n2, prefixes, value: v2, known: k2 } = ex {
                        if *k2 && n2 == name && v2 == value {
                            *prefixes |= crate::prefixes::NONE;
                            merged = true;
                            break;
                        }
                    }
                }
                if merged {
                    continue;
                }
                conds.push(SupportsCondition::Decl { name: name.clone(), prefixes: crate::prefixes::NONE, known: true, value: value.clone() });
                continue;
            }
        }
        if conds.contains(&c) {
            continue;
        }
        conds.push(c);
    }
    if conds.len() == 1 {
        return Ok(conds.pop().unwrap());
    }
    Ok(match op.unwrap() {
        Op::And => SupportsCondition::And(conds),
        Op::Or => SupportsCondition::Or(conds),
    })
}

pub fn parse_supports_decl(p: &mut Parser) -> PResult<SupportsCondition> {
    let name = p.expect_ident()?.to_string();
    p.expect_colon()?;
    p.skip_whitespace();
    let start = p.byte_pos();
    // consume the rest
    while p.next_including_whitespace_and_comments().is_ok() {}
    let end = p.byte_pos_end();
    let value = p.src[start..end].trim_end().to_string();
    let (prefix, base) = crate::prefixes::split_prefix(&name);
    let known = crate::properties::is_known_with_prefix(&base, prefix);
    if known {
        Ok(SupportsCondition::Decl { name: base, prefixes: if prefix == 0 { crate::prefixes::NONE } else { prefix }, known: true, value })
    } else {
        Ok(SupportsCondition::Decl { name, prefixes: crate::prefixes::NONE, known: false, value })
    }
}

fn parse_supports_in_parens(p: &mut Parser) -> PResult<SupportsCondition> {
    p.skip_whitespace();
    let loc = p.location();
    let st = p.state();
    let t = p.next()?.clone();
    match t {
        Token::ParenthesisBlock => {
            let start = p.toks[st.pos_index()].end;
            let r = p.parse_nested_block(|p| {
                if let Ok(c) = p.try_parse(parse_supports_condition) {
                    return Ok(c);
                }
                if let Ok(c) = p.try_parse(parse_supports_decl) {
                    return Ok(c);
                }
                while p.next_including_whitespace_and_comments().is_ok() {}
                Err(p.err(ErrorKind::InvalidValue))
            });
            match r {
                Ok(c) => Ok(c),
                Err(_) => {
                    let end = p.byte_pos_prev_end();
                    let s = &p.src[start..end.saturating_sub(1).max(start)];
                    Ok(SupportsCondition::Unknown(format!("({})", s)))
                }
            }
        }
        Token::Function(name) if name.eq_ignore_ascii_case("selector") => {
            let start = p.toks[st.pos_index()].end;
            p.parse_nested_block(|p| {
                crate::selectors::parse_selector_list(p, false)?;
                Ok(())
            })?;
            let end = p.byte_pos_prev_end();
            let s = p.src[start..end.saturating_sub(1).max(start)].trim().to_string();
            Ok(SupportsCondition::Selector(s))
        }
        Token::Function(_) => {
            let start = p.toks[st.pos_index()].start;
            let _ = p.parse_nested_block(|p| {
                while p.next_including_whitespace_and_comments().is_ok() {}
                Ok(())
            });
            let end = p.byte_pos_prev_end();
            Ok(SupportsCondition::Unknown(p.src[start..end].to_string()))
        }
        t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    }
}

impl<'t> Parser<'t> {
    pub fn byte_pos_end(&self) -> usize {
        // end of the last consumed token
        if self.pos == 0 {
            return 0;
        }
        let i = self.pos.min(self.toks.len()) - 1;
        self.toks[i].end
    }
    pub fn byte_pos_prev_end(&self) -> usize {
        self.byte_pos_end()
    }
}

impl crate::parser::State {
    pub fn pos_index(&self) -> usize {
        self.pos_value()
    }
}

impl SupportsCondition {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            SupportsCondition::Not(c) => {
                d.write_str("not ");
                c.to_css_in_parens(d);
            }
            SupportsCondition::And(v) | SupportsCondition::Or(v) => {
                let op = if matches!(self, SupportsCondition::And(_)) { " and " } else { " or " };
                for (i, c) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_str(op);
                    }
                    c.to_css_in_parens(d);
                }
            }
            SupportsCondition::Decl { name, prefixes, known, value } => {
                if *known {
                    let multi = *prefixes != crate::prefixes::NONE;
                    if multi {
                        d.write_char('(');
                    }
                    let mut first = true;
                    for (bit, pre) in [
                        (crate::prefixes::WEBKIT, "-webkit-"),
                        (crate::prefixes::MOZ, "-moz-"),
                        (crate::prefixes::MS, "-ms-"),
                        (crate::prefixes::O, "-o-"),
                        (crate::prefixes::NONE, ""),
                    ] {
                        if prefixes & bit != 0 {
                            if !first {
                                d.write_str(" or ");
                            }
                            first = false;
                            d.write_char('(');
                            d.write_str(pre);
                            d.write_str(name);
                            d.delim(':', false);
                            d.write_str(value);
                            d.write_char(')');
                        }
                    }
                    if multi {
                        d.write_char(')');
                    }
                } else {
                    d.write_char('(');
                    d.write_str(name);
                    d.delim(':', false);
                    d.write_str(value);
                    d.write_char(')');
                }
            }
            SupportsCondition::Selector(s) => {
                d.write_str("selector(");
                d.write_str(s);
                d.write_char(')');
            }
            SupportsCondition::Unknown(s) => d.write_str(s),
        }
    }

    fn to_css_in_parens(&self, d: &mut Printer) {
        match self {
            SupportsCondition::Not(_) | SupportsCondition::And(_) | SupportsCondition::Or(_) => {
                d.write_char('(');
                self.to_css(d);
                d.write_char(')');
            }
            _ => self.to_css(d),
        }
    }

    pub fn to_css_in_parens_ctx(&self, d: &mut Printer, import: bool) {
        // inside @import supports(): declarations printed without parens
        if import {
            if let SupportsCondition::Decl { name, prefixes, known, value } = self {
                if !*known || *prefixes == crate::prefixes::NONE {
                    d.write_str(name);
                    d.delim(':', false);
                    d.write_str(value);
                    return;
                }
            }
        }
        self.to_css(d);
    }
}

pub fn parse_container_condition(p: &mut Parser) -> PResult<ContainerCondition> {
    p.skip_whitespace();
    if p.is_exhausted() {
        return Ok(None);
    }
    Ok(Some(parse_condition(p, true, true)?))
}

pub fn container_to_css(c: &ContainerCondition, d: &mut Printer) {
    if let Some(c) = c {
        c.to_css(d, true);
    }
}
