pub fn find_def(base: &str) -> Option<&'static PropDef> {
    PROPS.iter().find(|d| d.name == base)
}

pub fn is_known_with_prefix(base: &str, prefix: u8) -> bool {
    match find_def(base) {
        Some(d) => prefix == 0 || prefix == NONE || d.prefixes & prefix != 0,
        None => false,
    }
}

/// Resolve a property name into PropId if known
pub fn lookup(name: &str) -> Option<PropId> {
    let (prefix, base) = split_prefix(name);
    // special: -webkit-mask-composite is its own property
    if name.eq_ignore_ascii_case("-webkit-mask-composite") {
        return Some(PropId::new("-webkit-mask-composite", NONE));
    }
    let d = find_def(&base)?;
    if prefix == 0 {
        Some(PropId::new(d.name, NONE))
    } else if d.prefixes & prefix != 0 {
        Some(PropId::new(d.name, prefix))
    } else {
        None
    }
}

pub const CSS_WIDE: &[&str] = &["inherit", "initial", "unset", "revert", "revert-layer"];

impl Property {
    pub fn parse(name: &str, p: &mut Parser) -> Property {
        if name.starts_with("--") {
            let st = p.state();
            match TokenList::parse(p) {
                Ok(tl) => return Property::Custom(name.to_string(), tl),
                Err(_) => {
                    p.reset(st);
                    return Property::Custom(name.to_string(), TokenList::default());
                }
            }
        }
        let id = match lookup(name) {
            Some(id) => id,
            None => {
                let tl = TokenList::parse(p).unwrap_or_default();
                return Property::Unknown(name.to_string(), tl);
            }
        };
        let st = p.state();
        // css-wide keywords
        if let Ok(kw) = p.try_parse(|p| {
            let k = p.expect_ident()?.to_ascii_lowercase();
            if CSS_WIDE.contains(&k.as_str()) {
                p.expect_exhausted()?;
                Ok(k)
            } else {
                p.invalid()
            }
        }) {
            return Property::Wide(id, kw);
        }
        p.reset(st);
        match p.try_parse(|p| {
            let v = parse_value(&id, p)?;
            p.expect_exhausted()?;
            Ok(v)
        }) {
            Ok(v) => Property::Val(id, v),
            Err(_) => {
                p.reset(st);
                let tl = TokenList::parse(p).unwrap_or_default();
                Property::Unparsed(id, tl)
            }
        }
    }

    pub fn id(&self) -> Option<&PropId> {
        match self {
            Property::Unparsed(id, _) | Property::Wide(id, _) | Property::Val(id, _) => Some(id),
            _ => None,
        }
    }

    pub fn name_is(&self, n: &str) -> bool {
        self.id().map(|i| i.name == n).unwrap_or(false)
    }

    pub fn to_css(&self, d: &mut Printer, important: bool) {
        match self {
            Property::Custom(name, tl) => {
                crate::css_modules::write_dashed_ident(d, name, true);
                d.write_char(':');
                if !tl.starts_with_whitespace() {
                    d.whitespace();
                }
                tl.to_css(d, true);
            }
            Property::Unknown(name, tl) => {
                d.write_ident(name);
                d.write_char(':');
                if !tl.starts_with_whitespace() {
                    d.whitespace();
                }
                tl.to_css(d, false);
            }
            Property::Unparsed(id, tl) => {
                let prefixes = each(id.prefix);
                for (i, pre) in prefixes.iter().enumerate() {
                    if i > 0 {
                        d.write_char(';');
                        d.newline();
                    }
                    d.write_str(prefix_str(*pre));
                    d.write_str(&id.name);
                    d.delim(':', false);
                    tl.to_css(d, false);
                    write_important(d, important);
                }
            }
            Property::Wide(id, kw) => {
                let prefixes = each(id.prefix);
                for (i, pre) in prefixes.iter().enumerate() {
                    if i > 0 {
                        d.write_char(';');
                        d.newline();
                    }
                    d.write_str(prefix_str(*pre));
                    d.write_str(&id.name);
                    d.delim(':', false);
                    d.write_str(kw);
                    write_important(d, important);
                }
            }
            Property::Val(id, v) => {
                let prefixes = each(id.prefix);
                for (i, pre) in prefixes.iter().enumerate() {
                    if i > 0 {
                        d.write_char(';');
                        d.newline();
                    }
                    d.write_str(prefix_str(*pre));
                    d.write_str(&id.name);
                    d.delim(':', false);
                    print_value(id, *pre, v, d);
                    write_important(d, important);
                }
            }
        }
        if let Property::Custom(..) | Property::Unknown(..) = self {
            write_important(d, important);
        }
    }
}

pub fn write_important(d: &mut Printer, important: bool) {
    if important {
        d.whitespace();
        d.write_str("!important");
    }
}

pub fn print_value(id: &PropId, prefix: u8, v: &Value, d: &mut Printer) {
    match v {
        Value::Color(c) => c.to_css(d),
        Value::Ident(s) => d.write_str(s),
        Value::Num(n) => n.to_css(d),
        Value::Auto => d.write_str("auto"),
        Value::Integer(i) => d.write_str(&i.to_string()),
        Value::Opacity(f) => d.write_num(*f),
        Value::Size(s) => s.to_css(d, prefix),
        Value::Rect(v) => crate::pvals::write_rect(d, v),
        Value::Pair(v) => crate::pvals::write_pair(d, v),
        Value::LPA(v) => v.to_css(d),
        Value::Generic(g) => g.to_css(d),
        Value::Background(b) => crate::background::write_backgrounds(d, b),
        Value::BgLayers(b) => b.to_css(d),
        Value::Border(b) => b.to_css(d, id, prefix),
        Value::Font(f) => f.to_css(d),
        Value::Transition(t) => t.to_css(d, prefix),
        Value::Animation(a) => a.to_css(d, prefix),
        Value::Transform(t) => t.to_css(d, prefix),
        Value::Flex(f) => f.to_css(d, prefix),
        Value::Align(a) => a.to_css(d),
        Value::Grid(g) => g.to_css(d),
        Value::Text(t) => t.to_css(d, prefix),
        Value::Effect(e) => e.to_css(d, prefix),
        Value::List(l) => l.to_css(d),
        Value::Display(x) => x.to_css(d, prefix),
        Value::Misc(m) => m.to_css(d, prefix),
    }
}

pub fn expect_keyword(p: &mut Parser, list: &[&str]) -> PResult<String> {
    let loc = p.location();
    let s = p.expect_ident()?.to_ascii_lowercase();
    if list.contains(&s.as_str()) {
        Ok(s)
    } else {
        Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc))
    }
}

pub fn parse_value(id: &PropId, p: &mut Parser) -> PResult<Value> {
    use crate::pvals::*;
    let n = id.name.as_str();
    match n {
        "color" | "background-color" | "border-top-color" | "border-bottom-color" | "border-left-color"
        | "border-right-color" | "border-block-start-color" | "border-block-end-color" | "border-inline-start-color"
        | "border-inline-end-color" | "outline-color" | "text-decoration-color" | "text-emphasis-color" => {
            Ok(Value::Color(CssColor::parse(p)?))
        }
        "accent-color" | "caret-color" => {
            if p.try_ident_matching("auto") {
                return Ok(Value::Auto);
            }
            Ok(Value::Color(CssColor::parse(p)?))
        }
        "opacity" | "fill-opacity" | "stroke-opacity" => Ok(Value::Opacity(parse_number_or_percentage(p)?)),
        "z-index" => {
            if p.try_ident_matching("auto") {
                return Ok(Value::Auto);
            }
            Ok(Value::Integer(parse_integer(p)?))
        }
        "visibility" => Ok(Value::Ident(expect_keyword(p, &["visible", "hidden", "collapse"])?)),
        "box-sizing" => Ok(Value::Ident(expect_keyword(p, &["content-box", "border-box"])?)),
        "position" => crate::display::parse_position(p),
        "width" | "height" | "min-width" | "min-height" | "block-size" | "inline-size" | "min-block-size"
        | "min-inline-size" => Ok(Value::Size(Size::parse(p, false)?)),
        "max-width" | "max-height" | "max-block-size" | "max-inline-size" => Ok(Value::Size(Size::parse(p, true)?)),
        "margin-top" | "margin-bottom" | "margin-left" | "margin-right" | "margin-block-start" | "margin-block-end"
        | "margin-inline-start" | "margin-inline-end" | "top" | "bottom" | "left" | "right" | "inset-block-start"
        | "inset-block-end" | "inset-inline-start" | "inset-inline-end" | "scroll-padding-top"
        | "scroll-padding-bottom" | "scroll-padding-left" | "scroll-padding-right" | "scroll-padding-block-start"
        | "scroll-padding-block-end" | "scroll-padding-inline-start" | "scroll-padding-inline-end" => {
            Ok(Value::LPA(LPA::parse(p, true, true)?))
        }
        "padding-top" | "padding-bottom" | "padding-left" | "padding-right" | "padding-block-start"
        | "padding-block-end" | "padding-inline-start" | "padding-inline-end" => Ok(Value::LPA(LPA::parse(p, false, true)?)),
        "scroll-margin-top" | "scroll-margin-bottom" | "scroll-margin-left" | "scroll-margin-right"
        | "scroll-margin-block-start" | "scroll-margin-block-end" | "scroll-margin-inline-start"
        | "scroll-margin-inline-end" => Ok(Value::LPA(LPA::parse(p, false, false)?)),
        "margin" | "inset" | "scroll-padding" => Ok(Value::Rect(parse_rect(p, |p| LPA::parse(p, true, true))?)),
        "padding" => Ok(Value::Rect(parse_rect(p, |p| LPA::parse(p, false, true))?)),
        "scroll-margin" => Ok(Value::Rect(parse_rect(p, |p| LPA::parse(p, false, false))?)),
        "margin-block" | "margin-inline" | "inset-block" | "inset-inline" | "scroll-padding-block"
        | "scroll-padding-inline" => Ok(Value::Pair(parse_pair(p, |p| LPA::parse(p, true, true))?)),
        "padding-block" | "padding-inline" => Ok(Value::Pair(parse_pair(p, |p| LPA::parse(p, false, true))?)),
        "scroll-margin-block" | "scroll-margin-inline" => Ok(Value::Pair(parse_pair(p, |p| LPA::parse(p, false, false))?)),
        _ => {
            if let Some(r) = crate::background::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::border::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::font::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::transition::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::animation::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::transform::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::flex::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::grid::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::text::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::effects::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::list::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::display::parse(n, p) {
                return r;
            }
            if let Some(r) = crate::misc::parse(n, p) {
                return r;
            }
            p.invalid()
        }
    }
