#[derive(Clone, Debug, PartialEq)]
pub enum LPA {
    Auto,
    V(NumVal),
}

impl LPA {
    pub fn parse(p: &mut Parser, allow_auto: bool, allow_pct: bool) -> PResult<LPA> {
        if allow_auto && p.try_ident_matching("auto") {
            return Ok(LPA::Auto);
        }
        let v = parse_numval(p, if allow_pct { C_LEN | C_PCT } else { C_LEN }, true)?;
        Ok(LPA::V(v))
    }
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            LPA::Auto => d.write_str("auto"),
            LPA::V(v) => v.to_css(d),
        }
    }
    pub fn zero() -> LPA {
        LPA::V(NumVal::zero_px())
    }
    pub fn is_zero(&self) -> bool {
        matches!(self, LPA::V(v) if v.is_zero())
    }
}

pub fn parse_rect<F: Fn(&mut Parser) -> PResult<LPA>>(p: &mut Parser, f: F) -> PResult<Vec<LPA>> {
    let a = f(p)?;
    let b = p.try_parse(|p| f(p)).ok();
    let c = if b.is_some() { p.try_parse(|p| f(p)).ok() } else { None };
    let dd = if c.is_some() { p.try_parse(|p| f(p)).ok() } else { None };
    let b2 = b.clone().unwrap_or_else(|| a.clone());
    let c2 = c.clone().unwrap_or_else(|| a.clone());
    let d2 = dd.unwrap_or_else(|| b2.clone());
    Ok(vec![a, b2, c2, d2])
}

pub fn parse_pair<F: Fn(&mut Parser) -> PResult<LPA>>(p: &mut Parser, f: F) -> PResult<Vec<LPA>> {
    let a = f(p)?;
    let b = p.try_parse(|p| f(p)).ok().unwrap_or_else(|| a.clone());
    Ok(vec![a, b])
}

pub fn write_rect_generic<T: PartialEq, F: Fn(&T, &mut Printer)>(d: &mut Printer, v: &[T], f: F) {
    let (t, r, b, l) = (&v[0], &v[1], &v[2], &v[3]);
    f(t, d);
    let same_vert = t == b;
    let same_horiz = r == l;
    if same_vert && same_horiz && t == r {
        return;
    }
    d.write_char(' ');
    f(r, d);
    if same_vert && same_horiz {
        return;
    }
    d.write_char(' ');
    f(b, d);
    if same_horiz {
        return;
    }
    d.write_char(' ');
    f(l, d);
}

pub fn write_rect(d: &mut Printer, v: &[LPA]) {
    write_rect_generic(d, v, |x, d| x.to_css(d));
}

pub fn write_pair(d: &mut Printer, v: &[LPA]) {
    v[0].to_css(d);
    if v[1] != v[0] {
        d.write_char(' ');
        v[1].to_css(d);
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Size {
    Auto,
    None,
    V(NumVal),
    Kw(String, u8), // keyword with vendor prefix bits (for min-content etc.)
    FitContentFn(NumVal),
}

impl Size {
    pub fn parse(p: &mut Parser, max: bool) -> PResult<Size> {
        if let Ok(s) = p.try_parse(|p| {
            let loc = p.location();
            let s = p.expect_ident()?.to_ascii_lowercase();
            Ok(match s.as_str() {
                "auto" if !max => Size::Auto,
                "none" if max => Size::None,
                "min-content" | "max-content" | "fit-content" | "stretch" | "contain" => Size::Kw(s, crate::prefixes::NONE),
                "-webkit-min-content" => Size::Kw("min-content".into(), crate::prefixes::WEBKIT),
                "-moz-min-content" => Size::Kw("min-content".into(), crate::prefixes::MOZ),
                "-webkit-max-content" => Size::Kw("max-content".into(), crate::prefixes::WEBKIT),
                "-moz-max-content" => Size::Kw("max-content".into(), crate::prefixes::MOZ),
                "-webkit-fit-content" => Size::Kw("fit-content".into(), crate::prefixes::WEBKIT),
                "-moz-fit-content" => Size::Kw("fit-content".into(), crate::prefixes::MOZ),
                "-webkit-fill-available" => Size::Kw("stretch".into(), crate::prefixes::WEBKIT),
                "-moz-available" => Size::Kw("stretch".into(), crate::prefixes::MOZ),
                _ => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc)),
            })
        }) {
            return Ok(s);
        }
        if let Ok(v) = p.try_parse(|p| {
            p.expect_function_matching("fit-content")?;
            p.parse_nested_block(parse_length_percentage)
        }) {
            return Ok(Size::FitContentFn(v));
        }
        Ok(Size::V(parse_length_percentage(p)?))
    }
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            Size::Auto => d.write_str("auto"),
            Size::None => d.write_str("none"),
            Size::V(v) => v.to_css(d),
            Size::Kw(k, pre) => {
                if *pre == crate::prefixes::WEBKIT && k == "stretch" {
                    d.write_str("-webkit-fill-available");
                } else if *pre == crate::prefixes::MOZ && k == "stretch" {
                    d.write_str("-moz-available");
                } else {
                    d.write_str(crate::prefixes::prefix_str(*pre));
                    d.write_str(k);
                }
            }
            Size::FitContentFn(v) => {
                d.write_str("fit-content(");
                v.to_css(d);
                d.write_char(')');
            }
        }
    }
}

/// A generic parsed value: sequence of simple items.
#[derive(Clone, Debug, PartialEq)]
pub enum GItem {
    Ident(String),
    Num(NumVal),
    Color(CssColor),
    Str(String),
    Url(String),
    Comma,
    Slash,
    Func(String, Vec<GItem>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Generic(pub Vec<GItem>);

impl GItem {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            GItem::Ident(s) => d.write_ident(s),
            GItem::Num(n) => n.to_css(d),
            GItem::Color(c) => c.to_css(d),
            GItem::Str(s) => d.write_string(s),
            GItem::Url(u) => crate::url::write_url(d, u),
            GItem::Comma => d.write_char(','),
            GItem::Slash => d.write_char('/'),
            GItem::Func(n, args) => {
                d.write_str(n);
                d.write_char('(');
                write_items(d, args);
                d.write_char(')');
