        }
    }
}

pub fn write_items(d: &mut Printer, items: &[GItem]) {
    for (i, it) in items.iter().enumerate() {
        match it {
            GItem::Comma => d.delim(',', false),
            GItem::Slash => d.delim('/', true),
            _ => {
                if i > 0 && !matches!(items[i - 1], GItem::Comma | GItem::Slash) {
