pub fn parse_family_list(p: &mut Parser) -> PResult<Vec<String>> {
    let mut v = Vec::new();
    loop {
        let mut name = String::new();
        if let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
            name = s;
        } else {
            loop {
                match p.try_parse(|p| p.expect_ident_cloned()) {
