use crate::selectors::*;

pub fn normalize_list(l: SelectorList, _nested: bool) -> SelectorList {
    SelectorList(l.0.into_iter().map(normalize_selector).collect())
}

fn is_simple_compound(s: &Selector) -> bool {
    s.0.iter().all(|c| match c {
        Comp::S(s) => !s.is_type_like() && !s.is_pseudo_element() && !matches!(s, Simple::Nesting),
        Comp::Comb(_) => false,
    })
}

pub fn normalize_selector(s: Selector) -> Selector {
    let mut out: Vec<Comp> = Vec::new();
    for c in s.0.into_iter() {
