                        for c2 in l.0[0].0.iter() {
                            out.push(c2.clone());
                        }
                    }
                    other => out.push(Comp::S(other)),
                }
            }
            other => out.push(other),
        }
    }
    Selector(out)
}

fn normalize_simple(s: Simple) -> Simple {
    match s {
        Simple::Not(l) => {
            // :not(:is(.a)) -> :not(.a)
            let l = SelectorList(
                l.0.into_iter()
                    .map(|sel| {
                        let sel = normalize_selector(sel);
                        sel
                    })
                    .collect(),
            );
            Simple::Not(l)
        }
        Simple::Is(l) => Simple::Is(normalize_list(l, false)),
        Simple::Where(l) => Simple::Where(normalize_list(l, false)),
        Simple::Has(l) => Simple::Has(normalize_list(l, false)),
        other => other,
    }
}
