// CSS modules support
use crate::printer::Printer;
use std::cell::RefCell;
use std::collections::BTreeMap;

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    Class,
    Keyframes,
    CounterStyle,
    Other,
}

#[derive(Clone, Debug, Default)]
pub struct Export {
    pub name: String,
    pub composes: Vec<(String, String, Option<String>)>, // type, name, specifier
    pub is_referenced: bool,
}

#[derive(Default)]
pub struct State {
    pub enabled: bool,
    pub dashed: bool,
    pub hash: String,
    pub pattern: String,
    pub file_stem: String,
    pub exports: BTreeMap<String, Export>,
    pub global: bool,
    pub order: Vec<String>,
}

thread_local! {
    pub static CM: RefCell<State> = RefCell::new(State::default());
}

pub fn enabled() -> bool {
    CM.with(|c| c.borrow().enabled)
}

pub fn set_global(g: bool) -> bool {
    CM.with(|c| {
        let mut c = c.borrow_mut();
        let prev = c.global;
        c.global = g;
        prev
    })
}

const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890_-";

fn encode(bytes: &[u8]) -> String {
    let mut out = String::new();
    let mut i = 0;
    while i + 3 <= bytes.len() {
        let n = (bytes[i] as u32) << 16 | (bytes[i + 1] as u32) << 8 | bytes[i + 2] as u32;
        for k in (0..4).rev() {
            out.push(ALPHABET[((n >> (6 * k)) & 63) as usize] as char);
        }
        i += 3;
    }
    let rem = bytes.len() - i;
    if rem == 1 {
        let n = (bytes[i] as u32) << 16;
        out.push(ALPHABET[((n >> 18) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 12) & 63) as usize] as char);
    } else if rem == 2 {
        let n = (bytes[i] as u32) << 16 | (bytes[i + 1] as u32) << 8;
        out.push(ALPHABET[((n >> 18) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 12) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 6) & 63) as usize] as char);
    }
    out
}

pub fn hash(s: &str, at_start: bool) -> String {
    use std::hash::{Hash, Hasher};
    #[allow(deprecated)]
    let mut h = std::collections::hash_map::DefaultHasher::new();
    s.hash(&mut h);
    let v = h.finish() as u32;
    let e = encode(&v.to_le_bytes());
    if at_start && e.as_bytes()[0].is_ascii_digit() {
        format!("_{}", e)
    } else {
        e
    }
}

pub fn init(enabled: bool, dashed: bool, path: &str, pattern: Option<String>) {
    let pattern = pattern.unwrap_or_else(|| "[hash]_[local]".to_string());
    let stem = std::path::Path::new(path).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
    let at_start = pattern.starts_with("[hash]");
    let h = hash(path, at_start);
    CM.with(|c| {
        let mut c = c.borrow_mut();
        c.enabled = enabled;
        c.dashed = dashed;
        c.hash = h;
        c.pattern = pattern;
        c.file_stem = stem;
    });
}

pub fn local_name(name: &str) -> String {
    CM.with(|c| {
        let c = c.borrow();
        let mut out = String::new();
        let pat = &c.pattern;
        let mut rest = pat.as_str();
        while !rest.is_empty() {
            if let Some(r) = rest.strip_prefix("[hash]") {
                out.push_str(&c.hash);
                rest = r;
            } else if let Some(r) = rest.strip_prefix("[local]") {
                out.push_str(name);
                rest = r;
            } else if let Some(r) = rest.strip_prefix("[name]") {
                out.push_str(&c.file_stem);
                rest = r;
            } else {
