// Browser targets and feature compatibility
use crate::media::MediaQuery;
use std::cell::RefCell;

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Browsers {
    pub android: Option<u32>,
    pub chrome: Option<u32>,
    pub edge: Option<u32>,
    pub firefox: Option<u32>,
    pub ie: Option<u32>,
    pub ios_saf: Option<u32>,
    pub opera: Option<u32>,
    pub safari: Option<u32>,
    pub samsung: Option<u32>,
}

thread_local! {
    pub static TARGETS: RefCell<Option<Browsers>> = RefCell::new(None);
    pub static IS_PREFIX: RefCell<Option<String>> = RefCell::new(None);
}

pub fn targets() -> Option<Browsers> {
    TARGETS.with(|t| *t.borrow())
}

pub fn v(major: u32, minor: u32, patch: u32) -> u32 {
    (major << 16) | (minor << 8) | patch
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Feature {
    MediaRangeSyntax,
    HexAlphaColors,
    LabColors,
    OklabColors,
    P3Colors,
    ColorFunction,
    LightDark,
    Nesting,
    IsSelector,
    LogicalProps,
    Other,
}

/// Minimum versions (chrome, firefox, safari, ios, edge, ie, opera, samsung, android)
type Min = [Option<u32>; 9];

fn table(f: Feature) -> Min {
    let n = None;
    let s = |a: u32, b: u32| Some(v(a, b, 0));
    match f {
        Feature::MediaRangeSyntax => [s(104, 0), s(63, 0), s(16, 4), s(16, 4), s(104, 0), n, s(91, 0), s(20, 0), s(104, 0)],
        Feature::HexAlphaColors => [s(62, 0), s(49, 0), s(10, 0), s(9, 3), s(79, 0), n, s(52, 0), s(8, 0), s(62, 0)],
        Feature::LabColors => [s(111, 0), s(113, 0), s(15, 0), s(15, 0), s(111, 0), n, s(97, 0), n, s(111, 0)],
        Feature::OklabColors => [s(111, 0), s(113, 0), s(15, 4), s(15, 4), s(111, 0), n, s(97, 0), n, s(111, 0)],
        Feature::P3Colors => [s(111, 0), s(113, 0), s(15, 0), s(15, 0), s(111, 0), n, s(97, 0), n, s(111, 0)],
        Feature::ColorFunction => [s(111, 0), s(113, 0), s(15, 0), s(15, 0), s(111, 0), n, s(97, 0), n, s(111, 0)],
        Feature::LightDark => [s(123, 0), s(120, 0), s(17, 5), s(17, 5), s(123, 0), n, s(109, 0), n, s(123, 0)],
        Feature::Nesting => [s(120, 0), s(117, 0), s(17, 2), s(17, 2), s(120, 0), n, s(106, 0), n, s(120, 0)],
        Feature::IsSelector => [s(88, 0), s(78, 0), s(14, 0), s(14, 0), s(88, 0), n, s(74, 0), s(15, 0), s(88, 0)],
        Feature::LogicalProps => [s(89, 0), s(66, 0), s(15, 0), s(15, 0), s(89, 0), n, s(75, 0), s(15, 0), s(89, 0)],
        Feature::Other => [s(0, 0), s(0, 0), s(0, 0), s(0, 0), s(0, 0), s(0, 0), s(0, 0), s(0, 0), s(0, 0)],
    }
}

pub fn is_compatible(b: &Browsers, m: &Min) -> bool {
    let list = [b.chrome, b.firefox, b.safari, b.ios_saf, b.edge, b.ie, b.opera, b.samsung, b.android];
    for (i, ver) in list.iter().enumerate() {
        if let Some(ver) = ver {
            match m[i] {
                Some(min) => {
                    if *ver < min {
                        return false;
                    }
                }
                None => return false,
            }
        }
    }
    true
}

/// Whether the feature is supported by all targets (true if no targets)
pub fn supports(f: Feature) -> bool {
    match targets() {
        None => true,
        Some(b) => is_compatible(&b, &table(f)),
    }
}

pub fn should_compile_light_dark() -> bool {
    !supports(Feature::LightDark)
}

pub fn expand_media_query(q: &MediaQuery) -> Vec<MediaQuery> {
    vec![q.clone()]
}

// ---------- query parsing ----------

#[derive(Debug)]
pub enum QueryError {
    BrowserNotFound(String),
    Nom(String),
}

fn parse_version(s: &str) -> Option<u32> {
    let mut parts = s.split('.');
    let major: u32 = parts.next()?.parse().ok()?;
    let minor: u32 = parts.next().map(|x| x.parse().unwrap_or(0)).unwrap_or(0);
    let patch: u32 = parts.next().map(|x| x.parse().unwrap_or(0)).unwrap_or(0);
    Some(v(major, minor, patch))
}

fn set_min(slot: &mut Option<u32>, ver: u32) {
    match slot {
        Some(x) if *x <= ver => {}
        _ => *slot = Some(ver),
    }
}

pub fn browser_slot<'a>(b: &'a mut Browsers, name: &str) -> Result<Option<&'a mut Option<u32>>, QueryError> {
    Ok(Some(match name {
        "chrome" | "and_chr" | "chromeandroid" => &mut b.chrome,
        "firefox" | "ff" | "and_ff" | "firefoxandroid" | "fx" => &mut b.firefox,
        "safari" => &mut b.safari,
        "ios_saf" | "ios" | "ios_safari" => &mut b.ios_saf,
        "edge" => &mut b.edge,
        "ie" | "explorer" => &mut b.ie,
        "opera" | "op_mob" | "operamobile" => &mut b.opera,
        "samsung" => &mut b.samsung,
        "android" => &mut b.android,
        "ie_mob" | "iemobile" | "op_mini" | "operamini" | "and_uc" | "ucandroid" | "baidu" | "kaios" | "and_qq" | "bb" | "blackberry" | "qqandroid" => return Ok(None),
        _ => return Err(QueryError::BrowserNotFound(name.to_string())),
    }))
}

pub fn parse_query(q: &str) -> Result<Browsers, QueryError> {
    let mut b = Browsers::default();
    for part in q.split(|c| c == ',') {
        for part in part.split(" or ") {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            let lower = part.to_ascii_lowercase();
            let toks: Vec<&str> = lower.split_whitespace().collect();
            if toks.len() >= 2 {
                let name = toks[0];
                let (op, ver) = if toks.len() == 3 { (toks[1], toks[2]) } else { ("", toks[1]) };
                let slot = browser_slot(&mut b, name)?;
                if let Some(slot) = slot {
                    let ver_s = ver.split('-').next().unwrap();
