// Declaration handlers: merging longhands into shorthands, dedupe, prefixes.
use crate::decl::DeclBlock;
use crate::properties::*;
use std::collections::HashMap;

pub trait Handler {
    /// returns true if handled
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, important: bool) -> bool;
    fn finalize(&mut self, out: &mut Vec<Property>, important: bool);
}

const FALLBACK_PROPS: &[&str] = &["color", "text-shadow", "filter", "backdrop-filter", "fill", "stroke", "caret-color", "caret"];
const PREFIX_PROPS: &[&str] = &[
    "transform-origin", "transform-style", "backface-visibility", "perspective", "perspective-origin", "box-sizing",
    "tab-size", "hyphens", "text-align-last", "text-decoration-skip-ink", "text-overflow", "user-select",
    "appearance", "clip-path", "box-decoration-break", "text-size-adjust", "print-color-adjust",
];

#[derive(Default)]
pub struct DedupeHandler {
    fallback: HashMap<String, usize>,
    prefix: HashMap<String, usize>,
    custom: HashMap<String, usize>,
}

impl Handler for DedupeHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _important: bool) -> bool {
        match p {
            Property::Custom(name, _) => {
                if let Some(&i) = self.custom.get(name) {
                    out[i] = p.clone();
                } else {
                    self.custom.insert(name.clone(), out.len());
                    out.push(p.clone());
                }
                true
            }
            Property::Val(id, v) | Property::Unparsed(id, _) | Property::Wide(id, _)
                if FALLBACK_PROPS.contains(&id.name.as_str()) && id.prefix == crate::prefixes::NONE =>
            {
                let _ = v_of(p);
                let _ = v;
                let p2 = crate::fallbacks::with_fallbacks(p, out);
                if let Some(&i) = self.fallback.get(&id.name) {
                    if i < out.len() {
                        out[i] = p2;
                        return true;
                    }
                }
                self.fallback.insert(id.name.clone(), out.len());
                out.push(p2);
                true
            }
            Property::Val(id, val) if PREFIX_PROPS.contains(&id.name.as_str()) => {
                if let Some(&i) = self.prefix.get(&id.name) {
                    if let Some(Property::Val(cur_id, cur)) = out.get_mut(i) {
                        if cur_id.name == id.name && (cur == val || cur_id.prefix & id.prefix != 0) {
                            *cur = val.clone();
                            cur_id.prefix |= id.prefix;
                            cur_id.prefix = crate::prefixer::prefixes_for(&id.name, cur_id.prefix);
                            return true;
                        }
                    }
                }
                let mut id2 = id.clone();
                id2.prefix = crate::prefixer::prefixes_for(&id.name, id.prefix);
                self.prefix.insert(id.name.clone(), out.len());
                out.push(Property::Val(id2, val.clone()));
                true
            }
            _ => false,
        }
    }
    fn finalize(&mut self, _out: &mut Vec<Property>, _important: bool) {}
}

fn v_of(p: &Property) -> Option<&Value> {
    match p {
        Property::Val(_, v) => Some(v),
        _ => None,
    }
}

pub struct DeclHandler {
    pub handlers: Vec<Box<dyn Handler>>,
    pub dedupe: DedupeHandler,
    pub out: Vec<Property>,
    pub important: bool,
}

impl DeclHandler {
    pub fn new(important: bool) -> DeclHandler {
        DeclHandler { handlers: crate::handler_list::make_handlers(), dedupe: DedupeHandler::default(), out: Vec::new(), important }
    }
    pub fn handle(&mut self, p: &Property) {
        for h in self.handlers.iter_mut() {
            if h.handle(p, &mut self.out, self.important) {
                return;
            }
        }
        if self.dedupe.handle(p, &mut self.out, self.important) {
            return;
        }
        let p2 = crate::prefixer::prefix_property(p);
        self.out.push(p2);
    }
    pub fn finalize(mut self) -> Vec<Property> {
        for h in self.handlers.iter_mut() {
            h.finalize(&mut self.out, self.important);
        }
        self.out
    }
}

pub fn process_block(block: &mut DeclBlock) {
    let mut hn = DeclHandler::new(false);
    let mut hi = DeclHandler::new(true);
    for p in block.important.iter() {
        hi.handle(p);
    }
    for p in block.decls.iter() {
        hn.handle(p);
    }
    block.decls = hn.finalize();
    block.important = hi.finalize();
}
