// Stylesheet-level transformations (always run, like lightningcss minify step)
use crate::rules::*;
use crate::selectors::*;

pub fn minify_rules(rules: &mut Vec<CssRule>, in_style: bool) {
    let input = std::mem::take(rules);
    let mut out: Vec<CssRule> = Vec::new();
    for rule in input.into_iter() {
        match rule {
            CssRule::Style(mut s) => {
                crate::handlers::process_block(&mut s.decls);
                minify_rules(&mut s.rules, true);
                if s.decls.is_empty() && s.rules.iter().all(|r| matches!(r, CssRule::Ignored)) {
                    continue;
                }
                if let Some(CssRule::Style(last)) = out.last_mut() {
                    if merge_style_rules(&mut s, last) {
                        continue;
                    }
                }
                out.push(CssRule::Style(s));
            }
            CssRule::NestedDecls(mut d) => {
                crate::handlers::process_block(&mut d);
                if d.is_empty() {
                    continue;
                }
                out.push(CssRule::NestedDecls(d));
            }
            CssRule::Media(m, mut rs, loc) => {
                if m.never_matches() {
                    continue;
                }
                minify_rules(&mut rs, in_style);
                if rs.is_empty() {
                    continue;
                }
                if crate::options::minify() && m.always_matches() && !m.0.is_empty() && !in_style {
                    out.extend(rs);
                    continue;
                }
                if let Some(CssRule::Media(lm, lrs, _)) = out.last_mut() {
                    if *lm == m {
                        lrs.extend(rs);
                        let mut tmp = std::mem::take(lrs);
                        minify_rules(&mut tmp, in_style);
                        *lrs = tmp;
                        continue;
                    }
                }
                out.push(CssRule::Media(m, rs, loc));
            }
            CssRule::Supports(c, mut rs, loc) => {
                minify_rules(&mut rs, in_style);
                if rs.is_empty() {
                    continue;
                }
                if let Some(CssRule::Supports(lc, lrs, _)) = out.last_mut() {
                    if *lc == c {
                        lrs.extend(rs);
                        let mut tmp = std::mem::take(lrs);
                        minify_rules(&mut tmp, in_style);
                        *lrs = tmp;
                        continue;
                    }
                }
                out.push(CssRule::Supports(c, rs, loc));
            }
            CssRule::Container(n, c, mut rs, loc) => {
                minify_rules(&mut rs, in_style);
                if rs.is_empty() {
                    continue;
                }
                out.push(CssRule::Container(n, c, rs, loc));
            }
            CssRule::LayerBlock(n, mut rs, loc) => {
                minify_rules(&mut rs, in_style);
                out.push(CssRule::LayerBlock(n, rs, loc));
            }
            CssRule::StartingStyle(mut rs, loc) => {
                minify_rules(&mut rs, in_style);
                if rs.is_empty() {
                    continue;
                }
                out.push(CssRule::StartingStyle(rs, loc));
            }
            CssRule::Scope(a, b, mut rs, loc) => {
                minify_rules(&mut rs, true);
                out.push(CssRule::Scope(a, b, rs, loc));
            }
            CssRule::MozDocument(mut rs, loc) => {
                minify_rules(&mut rs, in_style);
                out.push(CssRule::MozDocument(rs, loc));
            }
            CssRule::Keyframes(mut k) => {
                for kf in k.keyframes.iter_mut() {
                    crate::handlers::process_block(&mut kf.decls);
                }
                out.push(CssRule::Keyframes(k));
            }
            CssRule::Page(mut pr) => {
                crate::handlers::process_block(&mut pr.decls);
                for m in pr.margins.iter_mut() {
                    crate::handlers::process_block(&mut m.decls);
                }
                out.push(CssRule::Page(pr));
            }
            CssRule::FontFace(d, loc) => out.push(CssRule::FontFace(d, loc)),
            CssRule::Viewport(pre, mut d, loc) => {
                crate::handlers::process_block(&mut d);
                out.push(CssRule::Viewport(pre, d, loc));
            }
            other => out.push(other),
        }
    }
    *rules = out;
}

pub fn selector_compatible(s: &Selector) -> bool {
    s.0.iter().all(|c| match c {
        Comp::S(s) => simple_compatible(s),
        _ => true,
    })
}

fn list_compatible(l: &SelectorList) -> bool {
    l.0.iter().all(selector_compatible)
}

fn simple_compatible(s: &Simple) -> bool {
    match s {
        Simple::CustomPseudoClass(_) | Simple::CustomPseudoClassFn(..) | Simple::CustomPseudoElement(_) | Simple::CustomPseudoElementFn(..) => false,
        Simple::Any(..) | Simple::WebkitScrollbar(_) => false,
        Simple::PseudoClass(n) => !n.starts_with('-'),
        Simple::PseudoElement(n) => !n.starts_with('-') && n != "file-selector-button",
        Simple::Not(l) | Simple::Is(l) | Simple::Where(l) | Simple::Has(l) => list_compatible(l),
        Simple::Nth(Nth::Child(_, _, Some(l))) | Simple::Nth(Nth::LastChild(_, _, Some(l))) => list_compatible(l),
        Simple::Host(Some(s)) | Simple::Slotted(s) => selector_compatible(s),
        _ => true,
    }
}

pub fn rule_compatible(r: &StyleRule) -> bool {
    list_compatible(&r.selectors) && crate::targets_sel::selectors_supported(&r.selectors)
}

fn merge_style_rules(rule: &mut StyleRule, last: &mut StyleRule) -> bool {
    if rule.selectors == last.selectors
        && rule_compatible(rule)
        && rule_compatible(last)
        && rule.rules.is_empty()
        && last.rules.is_empty()
        && rule.prefix == last.prefix
    {
        last.decls.decls.extend(rule.decls.decls.drain(..));
        last.decls.important.extend(rule.decls.important.drain(..));
        crate::handlers::process_block(&mut last.decls);
        return true;
    }
    if rule.decls == last.decls
        && rule.rules.is_empty()
        && last.rules.is_empty()
        && rule_compatible(rule)
        && rule_compatible(last)
        && rule.prefix == last.prefix
    {
        last.selectors.0.extend(rule.selectors.0.drain(..));
        return true;
    }
    false
}
