// Source map generation (VLQ)
const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn vlq(mut v: i64, out: &mut String) {
    let mut x: u64 = if v < 0 { ((-v as u64) << 1) | 1 } else { (v as u64) << 1 };
    loop {
        let mut digit = (x & 31) as u8;
        x >>= 5;
        if x > 0 {
            digit |= 32;
        }
        out.push(B64[digit as usize] as char);
        if x == 0 {
            break;
        }
    }
    v = 0;
    let _ = v;
}

pub fn mappings(maps: &[(u32, u32, u32, u32, u32)]) -> String {
    let mut out = String::new();
    let mut prev_gen_line = 0u32;
    let mut prev_gen_col: i64 = 0;
    let mut prev_src: i64 = 0;
    let mut prev_line: i64 = 0;
    let mut prev_col: i64 = 0;
    let mut first_in_line = true;
    for &(gl, gc, src, ol, oc) in maps {
        while prev_gen_line < gl {
            out.push(';');
            prev_gen_line += 1;
            prev_gen_col = 0;
            first_in_line = true;
        }
        if !first_in_line {
            out.push(',');
        }
        first_in_line = false;
        vlq(gc as i64 - prev_gen_col, &mut out);
        prev_gen_col = gc as i64;
        vlq(src as i64 - prev_src, &mut out);
        prev_src = src as i64;
        vlq(ol as i64 - prev_line, &mut out);
        prev_line = ol as i64;
        vlq(oc as i64 - prev_col, &mut out);
        prev_col = oc as i64;
    }
    out
}
