{"command":"cd /workspace/src; cat > cli.rs <<'EOF'
use crate::help::HELP;
use std::io::{Read, Write};

#[derive(Default)]
pub struct Args {
    pub inputs: Vec<String>,
    pub output_file: Option<String>,
    pub output_dir: Option<String>,
    pub minify: bool,
    pub css_modules: Option<Option<String>>,
    pub css_modules_pattern: Option<String>,
    pub css_modules_dashed: bool,
    pub sourcemap: bool,
    pub custom_media: bool,
    pub bundle: bool,
    pub error_recovery: bool,
    pub targets: Option<String>,
    pub browserslist: bool,
}

fn bin_name() -> String {
    let a = std::env::args().next().unwrap_or_else(|| "lightningcss".into());
    std::path::Path::new(&a).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or(a)
}

fn clap_error(msg: &str, usage: Option<&str>) -> ! {
    let mut s = format!("error: {}\n\n", msg);
    if let Some(u) = usage {
        s.push_str(u);
        s.push_str("\n\n");
    }
    s.push_str("For more information try --help\n");
    eprint!("{}", s);
    std::process::exit(2);
}

fn default_usage() -> String {
    format!("USAGE:\n    {} [OPTIONS] [INPUT_FILE]...", bin_name())
}

fn value_name(long: &str) -> &'static str {
    match long {
        "output-file" => "OUTPUT_FILE",
        "output-dir" => "OUTPUT_DIR",
        "targets" => "TARGETS",
        "css-modules-pattern" => "CSS_MODULES_PATTERN",
        _ => "VALUE",
    }
}

pub fn parse_args() -> Args {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut a = Args::default();
    let mut i = 0;
    let mut only_pos = false;
    let takes_value = |l: &str| matches!(l, "output-file" | "output-dir" | "targets" | "css-modules-pattern");
    let flags = ["browserslist", "bundle", "css-modules-dashed-idents", "custom-media", "error-recovery", "help", "minify", "sourcemap", "version"];
    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if only_pos || arg == "-" || !arg.starts_with('-') {
            a.inputs.push(arg);
            continue;
        }
        if arg == "--" {
            only_pos = true;
            continue;
        }
        let mut handle_long = |name: &str, inline: Option<String>, i: &mut usize, a: &mut Args| {
            if takes_value(name) {
                let val = match inline {
                    Some(v) => v,
                    None => {
                        if *i < argv.len() {
                            let v = argv[*i].clone();
                            *i += 1;
                            v
                        } else {
                            clap_error(&format!("The argument '--{} <{}>' requires a value but none was supplied", name, value_name(name)), None);
                        }
                    }
                };
                match name {
                    "output-file" => a.output_file = Some(val),
                    "output-dir" => a.output_dir = Some(val),
                    "targets" => a.targets = Some(val),
                    "css-modules-pattern" => a.css_modules_pattern = Some(val),
                    _ => {}
                }
                return;
            }
            if name == "css-modules" {
                let val = match inline {
                    Some(v) => Some(v),
                    None => {
                        if *i < argv.len() && !argv[*i].starts_with('-') {
                            let v = argv[*i].clone();
                            *i += 1;
                            Some(v)
                        } else {
                            None
                        }
                    }
                };
                a.css_modules = Some(val);
                return;
            }
            if flags.contains(&name) {
                if let Some(v) = inline {
                    clap_error(
                        &format!("The value '{}' was provided to '--{}' but it wasn't expecting any more values", v, name),
                        Some(&format!("{} [OPTIONS] [INPUT_FILE]...", bin_name())),
                    );
                }
                match name {
                    "browserslist" => a.browserslist = true,
                    "bundle" => a.bundle = true,
                    "css-modules-dashed-idents" => a.css_modules_dashed = true,
                    "custom-media" => a.custom_media = true,
                    "error-recovery" => a.error_recovery = true,
                    "minify" => a.minify = true,
                    "sourcemap" => a.sourcemap = true,
                    "help" => {
                        print!("{}", HELP.replace("{BIN}", &bin_name()));
                        std::process::exit(0);
                    }
                    "version" => {
                        println!("lightningcss 1.0.0-alpha.70");
                        std::process::exit(0);
                    }
                    _ => {}
                }
                return;
            }
            clap_error(
                &format!("Found argument '--{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `--{}` as a value rather than a flag, use `-- --{}`", name, name, name),
                Some(&default_usage()),
            );
        };
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, inline) = match rest.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (rest.to_string(), None),
            };
            handle_long(&name, inline, &mut i, &mut a);
        } else {
            // short flags
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                let long = match c {
                    'd' => "output-dir",
                    'h' => "help",
                    'm' => "minify",
                    'o' => "output-file",
                    't' => "targets",
                    'V' => "version",
                    _ => {
                        clap_error(
