pub fn relative_path(f: &str) -> String {
    if f.starts_with("stdin-") && !std::path::Path::new(f).exists() {
        return f.to_string();
    }
    let p = std::path::Path::new(f);
    let abs = std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
    let cwd = std::env::current_dir().ok().and_then(|c| std::fs::canonicalize(c).ok());
    if let Some(cwd) = cwd {
        if let Ok(r) = abs.strip_prefix(&cwd) {
            return r.to_string_lossy().to_string();
        }
        // compute ../ path
        let a: Vec<_> = abs.components().collect();
        let b: Vec<_> = cwd.components().collect();
        let mut i = 0;
        while i < a.len() && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        let mut parts: Vec<String> = Vec::new();
        for _ in i..b.len() {
            parts.push("..".into());
        }
        for c in &a[i..] {
            parts.push(c.as_os_str().to_string_lossy().to_string());
        }
        return parts.join("/");
    }
    f.to_string()
}

fn write_output(args: &Args, fname: &str, out: Output) {
    let css_modules = args.css_modules.is_some();
    let out_path: Option<String> = if let Some(dir) = &args.output_dir {
        let base = std::path::Path::new(fname).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
