                let map_path = format!("{}.map", path);
                let map_name = std::path::Path::new(&map_path).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
                code.push_str(&format!("\n/*# sourceMappingURL={} */\n", map_name));
