            }
            if css_modules {
                let json_path = match &args.css_modules {
                    Some(Some(f)) => f.clone(),
                    _ => {
                        let p = std::path::Path::new(&path);
                        p.with_extension("json").to_string_lossy().to_string()
                    }
                };
