                if let Some(Some(f)) = &args.css_modules {
                    let _ = std::fs::write(f, crate::css_modules::exports_json_file());
                }
                let stdout = std::io::stdout();
                let mut l = stdout.lock();
                let _ = writeln!(l, "{}", json);
            } else {
                let stdout = std::io::stdout();
                let mut l = stdout.lock();
                let _ = writeln!(l, "{}", out.code);
            }
        }
    }
}
