        e.col
    )
}

pub fn process(fname: &str, rel: &str, src: &str, args: &Args) -> Output {
    crate::options::OPTS.with(|o| {
        let mut o = o.borrow_mut();
        o.minify = args.minify;
        o.error_recovery = args.error_recovery;
        o.custom_media = args.custom_media;
        o.css_modules = args.css_modules.is_some();
        o.filename = fname.to_string();
    });
    crate::css_modules::init(args.css_modules.is_some(), args.css_modules_dashed, rel, args.css_modules_pattern.clone());
    crate::selectors::CSS_MODULES.with(|c| *c.borrow_mut() = args.css_modules.is_some());
    let src_owned: String;
    let src = if args.bundle {
        src_owned = src.to_string();
        &src_owned
    } else {
        src
    };
    let toks = crate::tokenizer::tokenize(src);
    let mut p = Parser::new(&toks, src);
    let mut rules = match crate::rules::parse_stylesheet(&mut p) {
        Ok(r) => r,
        Err(e) => crate::errors_panic::panic_debug(&error_debug(&e, fname), 187, 45),
    };
    if args.bundle {
        rules = crate::bundle::bundle(fname, rules);
    }
    // warnings
    if args.error_recovery {
        let ws: Vec<ParseError> = crate::rules::WARNINGS.with(|w| std::mem::take(&mut *w.borrow_mut()));
        for w in ws {
            eprintln!("{} at {}:{}:{}", crate::errors::message(&w.kind), fname, w.line, w.col);
        }
    }
    crate::transform::transform_stylesheet(&mut rules);
    crate::minify::minify_rules(&mut rules, false);
    let mut d = Printer::new(args.minify);
    crate::color::HEX_ALPHA_SUPPORTED.with(|h| *h.borrow_mut() = crate::targets::supports(crate::targets::Feature::HexAlphaColors));
    crate::rules::rules_to_css(&rules, &mut d);
    d.newline();
    let map = if args.sourcemap {
        Some(format!(
            "{{\"version\":3,\"mappings\":{},\"sources\":[{}],\"sourcesContent\":[{}],\"names\":[]}}",
            crate::css_modules::json_string(&crate::sourcemap::mappings(&d.mappings)),
            crate::css_modules::json_string(&rel.replace('\\', "/")),
            crate::css_modules::json_string(src)
        ))
    } else {
        None
    };
    Output { code: d.out, map }
}
