// Logical property lowering
use crate::properties::*;
use crate::pvals::LPA;

pub fn push_logical(out: &mut Vec<Property>, family: &str, axis: &str, start: Option<&LPA>, end: Option<&LPA>) {
    // Without lowering support yet, emit logical longhands
    let mk = |name: String, v: &LPA| Property::Val(PropId::new(crate::handler_list::lookup_static(&name), crate::prefixes::NONE), Value::LPA(v.clone()));
    let prefix = if family == "inset" { "inset".to_string() } else { family.to_string() };
    if axis == "block" {
        // block axis maps to top/bottom in horizontal writing mode
        let (t, b) = if family == "inset" { ("top".to_string(), "bottom".to_string()) } else { (format!("{}-top", family), format!("{}-bottom", family)) };
        if let Some(s) = start {
            out.push(mk(t, s));
        }
        if let Some(e) = end {
            out.push(mk(b, e));
        }
    } else {
        if let Some(s) = start {
            out.push(mk(format!("{}-inline-start", prefix), s));
        }
        if let Some(e) = end {
            out.push(mk(format!("{}-inline-end", prefix), e));
        }
    }
}
