            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}

/// margin / padding / inset / scroll-margin / scroll-padding
pub struct SideHandler {
    family: &'static str,
    // top, bottom, left, right, block-start, block-end, inline-start, inline-end
    vals: [Option<LPA>; 8],
    has_any: bool,
    cat: Cat,
    shorthand_ok: bool,
}

impl SideHandler {
    pub fn new(family: &'static str, _shorthand: bool) -> Self {
        SideHandler { family, vals: Default::default(), has_any: false, cat: Cat::Physical, shorthand_ok: true }
    }

    fn names(&self) -> [String; 8] {
        let f = self.family;
        if f == "inset" {
            [
                "top".into(),
                "bottom".into(),
                "left".into(),
                "right".into(),
                "inset-block-start".into(),
                "inset-block-end".into(),
                "inset-inline-start".into(),
                "inset-inline-end".into(),
            ]
        } else {
            [
                format!("{}-top", f),
                format!("{}-bottom", f),
                format!("{}-left", f),
                format!("{}-right", f),
                format!("{}-block-start", f),
                format!("{}-block-end", f),
                format!("{}-inline-start", f),
                format!("{}-inline-end", f),
            ]
        }
    }

    fn mk(name: &str, v: Value) -> Property {
        Property::Val(PropId::new(lookup_static(name), crate::prefixes::NONE), v)
    }

    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let names = self.names();
        let f = self.family;
        let v = std::mem::take(&mut self.vals);
        // physical
        if let (Some(t), Some(b), Some(l), Some(r)) = (&v[0], &v[1], &v[2], &v[3]) {
            if self.shorthand_ok {
                out.push(Self::mk(f, Value::Rect(vec![t.clone(), r.clone(), b.clone(), l.clone()])));
            }
        } else {
            for i in 0..4 {
                if let Some(x) = &v[i] {
                    out.push(Self::mk(&names[i], Value::LPA(x.clone())));
                }
            }
        }
        // logical
        let logical_supported = crate::targets::supports(crate::targets::Feature::LogicalProps);
        for (si, ei, short) in [(4usize, 5usize, "block"), (6, 7, "inline")] {
            match (&v[si], &v[ei]) {
                (Some(s), Some(e)) => {
                    if logical_supported || short == "block" && false {
                        out.push(Self::mk(&format!("{}-{}", f, short), Value::Pair(vec![s.clone(), e.clone()])));
                    } else {
                        crate::logical::push_logical(out, f, short, Some(s), Some(e));
                    }
                }
                (s, e) => {
                    if logical_supported {
                        if let Some(s) = s {
                            out.push(Self::mk(&names[si], Value::LPA(s.clone())));
                        }
                        if let Some(e) = e {
                            out.push(Self::mk(&names[ei], Value::LPA(e.clone())));
                        }
                    } else {
                        crate::logical::push_logical(out, f, short, s.as_ref(), e.as_ref());
                    }
                }
            }
        }
    }
}

pub fn lookup_static(name: &str) -> &'static str {
    match find_def(name) {
        Some(d) => d.name,
        None => Box::leak(name.to_string().into_boxed_str()),
    }
}

impl Handler for SideHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(id) => id,
            None => return false,
        };
        let names = self.names();
        let f = self.family;
        let n = id.name.as_str();
        let is_short = n == f;
        let is_block = n == format!("{}-block", f);
        let is_inline = n == format!("{}-inline", f);
        let idx = names.iter().position(|x| x == n);
        if !is_short && !is_block && !is_inline && idx.is_none() {
            return false;
        }
        match p {
            Property::Val(_, v) => {
                let cat = if is_short || idx.map(|i| i < 4).unwrap_or(false) { Cat::Physical } else { Cat::Logical };
                if cat != self.cat && self.has_any {
                    self.flush(out);
                }
                self.cat = cat;
                self.has_any = true;
                match v {
                    Value::Rect(r) if is_short => {
                        self.vals[0] = Some(r[0].clone());
                        self.vals[3] = Some(r[1].clone());
                        self.vals[1] = Some(r[2].clone());
                        self.vals[2] = Some(r[3].clone());
                    }
                    Value::Pair(pr) if is_block => {
                        self.vals[4] = Some(pr[0].clone());
                        self.vals[5] = Some(pr[1].clone());
                    }
                    Value::Pair(pr) if is_inline => {
                        self.vals[6] = Some(pr[0].clone());
                        self.vals[7] = Some(pr[1].clone());
                    }
                    Value::LPA(x) => {
                        self.vals[idx.unwrap()] = Some(x.clone());
                    }
                    _ => {
                        self.flush(out);
                        out.push(p.clone());
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
