pub const GENERIC: &[&str] = &[
    "serif", "sans-serif", "cursive", "fantasy", "monospace", "system-ui", "emoji", "math", "fangsong", "ui-serif",
    "ui-sans-serif", "ui-monospace", "ui-rounded",
];

const VARIANT_CAPS: &[&str] = &["normal", "small-caps", "all-small-caps", "petite-caps", "all-petite-caps", "unicase", "titling-caps"];
const SIZE_KW: &[&str] = &["xx-small", "x-small", "small", "medium", "large", "x-large", "xx-large", "xxx-large", "larger", "smaller", "math"];
const STRETCH_KW: &[(&str, f32)] = &[
    ("ultra-condensed", 0.5),
    ("extra-condensed", 0.625),
    ("condensed", 0.75),
    ("semi-condensed", 0.875),
    ("normal", 1.0),
    ("semi-expanded", 1.125),
    ("expanded", 1.25),
    ("extra-expanded", 1.5),
    ("ultra-expanded", 2.0),
];

pub fn parse_weight(p: &mut Parser) -> PResult<Weight> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["normal", "bold", "bolder", "lighter"])) {
        return Ok(match k.as_str() {
            "normal" => Weight::Normal,
            "bold" => Weight::Bold,
            "bolder" => Weight::Bolder,
            _ => Weight::Lighter,
        });
    }
    Ok(Weight::Num(parse_number(p)?))
}

fn parse_weight_abs(p: &mut Parser) -> PResult<Weight> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["normal", "bold"])) {
        return Ok(if k == "normal" { Weight::Normal } else { Weight::Bold });
    }
    Ok(Weight::Num(parse_number(p)?))
}

pub fn parse_size(p: &mut Parser) -> PResult<FSize> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, SIZE_KW)) {
        return Ok(FSize::Kw(k));
    }
    Ok(FSize::V(parse_length_percentage(p)?))
}

fn parse_stretch_kw(p: &mut Parser) -> PResult<Stretch> {
    let names: Vec<&str> = STRETCH_KW.iter().map(|x| x.0).collect();
    Ok(Stretch::Kw(expect_keyword(p, &names)?))
}

pub fn parse_stretch(p: &mut Parser) -> PResult<Stretch> {
    if let Ok(s) = p.try_parse(parse_stretch_kw) {
        return Ok(s);
    }
    match parse_percentage(p)? {
        NumVal::D(d) => Ok(Stretch::Pct(d.v)),
        _ => p.invalid(),
    }
}

pub fn parse_style(p: &mut Parser) -> PResult<FStyle> {
    let k = expect_keyword(p, &["normal", "italic", "oblique"])?;
    Ok(match k.as_str() {
        "normal" => FStyle::Normal,
        "italic" => FStyle::Italic,
        _ => {
            let a = p.try_parse(|p| parse_angle(p, false)).ok();
            FStyle::Oblique(a)
        }
    })
}

pub fn parse_line_height(p: &mut Parser) -> PResult<LineHeight> {
    if p.try_ident_matching("normal") {
        return Ok(LineHeight::Normal);
    }
    if let Ok(n) = p.try_parse(parse_number) {
        return Ok(LineHeight::Num(n));
    }
    Ok(LineHeight::V(parse_length_percentage(p)?))
}

pub fn parse_family_list(p: &mut Parser) -> PResult<Vec<Family>> {
    let mut v = Vec::new();
    loop {
        p.skip_whitespace();
        let loc = p.location();
        if let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
            v.push(Family::Name(s));
        } else {
            let first = p.expect_ident()?.to_string();
            let lf = first.to_ascii_lowercase();
            let mut more = Vec::new();
            while let Ok(s) = p.try_parse(|p| p.expect_ident_cloned()) {
                more.push(s);
            }
            if more.is_empty() && GENERIC.contains(&lf.as_str()) {
                v.push(Family::Generic(lf));
            } else {
                if more.is_empty() && (CSS_WIDE.contains(&lf.as_str()) || lf == "default") {
                    return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(first)), loc));
                }
                let mut name = first;
                for m in more {
                    name.push(' ');
                    name.push_str(&m);
                }
                v.push(Family::Name(name));
            }
        }
        if !p.try_comma() {
            break;
        }
    }
    Ok(v)
}

pub fn write_family_name(d: &mut Printer, f: &str) {
    let l = f.to_ascii_lowercase();
    if !f.is_empty() && !GENERIC.contains(&l.as_str()) && !CSS_WIDE.contains(&l.as_str()) && l != "default" {
        let mut id = String::new();
        let mut first = true;
        for slice in f.split(' ') {
            if first {
                first = false;
            } else {
                id.push(' ');
            }
            crate::printer::serialize_identifier(slice, &mut id);
        }
        if id.len() < f.len() + 2 {
            d.write_str(&id);
            return;
        }
    }
    d.write_string(f);
}

pub fn write_families(d: &mut Printer, v: &[Family]) {
    for (i, f) in v.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        match f {
            Family::Generic(g) => d.write_str(g),
            Family::Name(n) => write_family_name(d, n),
        }
    }
}

impl Weight {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Weight::Normal => d.write_str("400"),
            Weight::Bold => d.write_str("700"),
            Weight::Bolder => d.write_str("bolder"),
            Weight::Lighter => d.write_str("lighter"),
            Weight::Num(n) => d.write_num(*n),
        }
    }
}

impl FSize {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            FSize::V(v) => v.to_css(d),
            FSize::Kw(k) => d.write_str(k),
        }
    }
}

impl Stretch {
    pub fn to_css(&self, d: &mut Printer) {
        let pct = match self {
            Stretch::Kw(k) => STRETCH_KW.iter().find(|x| x.0 == k).map(|x| x.1).unwrap_or(1.0),
            Stretch::Pct(p) => *p,
        };
        d.write_num(pct * 100.0);
        d.write_char('%');
    }
    fn is_default(&self) -> bool {
        matches!(self, Stretch::Kw(k) if k == "normal")
    }
}

impl FStyle {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            FStyle::Normal => d.write_str("normal"),
            FStyle::Italic => d.write_str("italic"),
            FStyle::Oblique(a) => {
                d.write_str("oblique");
                if let Some(a) = a {
                    let is_default = matches!(a, NumVal::D(dd) if dd.unit == "deg" && dd.v == 14.0);
                    if !is_default {
                        d.write_char(' ');
                        a.to_css(d);
                    }
                }
            }
        }
    }
}

impl LineHeight {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            LineHeight::Normal => d.write_str("normal"),
            LineHeight::Num(n) => d.write_num(*n),
            LineHeight::V(v) => v.to_css(d),
        }
    }
}

impl Font {
    pub fn to_css(&self, d: &mut Printer) {
        if self.style != FStyle::Normal {
            self.style.to_css(d);
            d.write_char(' ');
        }
        if self.variant_caps != "normal" {
            d.write_str(&self.variant_caps);
            d.write_char(' ');
        }
        if self.weight != Weight::Normal {
            self.weight.to_css(d);
            d.write_char(' ');
        }
        if !self.stretch.is_default() {
            self.stretch.to_css(d);
            d.write_char(' ');
        }
        self.size.to_css(d);
        if self.line_height != LineHeight::Normal {
            d.delim('/', true);
            self.line_height.to_css(d);
        }
        d.write_char(' ');
        write_families(d, &self.family);
    }
}

pub fn parse_font(p: &mut Parser) -> PResult<Font> {
    let mut style = None;
    let mut weight = None;
    let mut stretch = None;
    let mut variant = None;
    let mut count = 0;
    let size;
    loop {
        if p.try_ident_matching("normal") {
            count += 1;
            continue;
        }
        if style.is_none() {
            if let Ok(s) = p.try_parse(parse_style) {
                style = Some(s);
                count += 1;
                continue;
            }
        }
        if weight.is_none() {
            if let Ok(w) = p.try_parse(parse_weight) {
                weight = Some(w);
                count += 1;
                continue;
            }
        }
        if variant.is_none() {
            if let Ok(v) = p.try_parse(|p| expect_keyword(p, &["small-caps"])) {
                variant = Some(v);
                count += 1;
                continue;
            }
        }
        if stretch.is_none() {
            if let Ok(s) = p.try_parse(parse_stretch_kw) {
                stretch = Some(s);
                count += 1;
                continue;
            }
        }
        size = parse_size(p)?;
        break;
    }
    if count > 4 {
        return p.invalid();
    }
    let line_height = if p.try_delim('/') { parse_line_height(p)? } else { LineHeight::Normal };
    let family = parse_family_list(p)?;
    Ok(Font {
        family,
        size,
        style: style.unwrap_or(FStyle::Normal),
        weight: weight.unwrap_or(Weight::Normal),
        stretch: stretch.unwrap_or(Stretch::Kw("normal".into())),
        line_height,
        variant_caps: variant.unwrap_or_else(|| "normal".into()),
    })
}

impl FontValue {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            FontValue::Weight(w) => w.to_css(d),
            FontValue::Size(s) => s.to_css(d),
            FontValue::Stretch(s) => s.to_css(d),
            FontValue::Style(s) => s.to_css(d),
            FontValue::VariantCaps(s) => d.write_str(s),
            FontValue::LineHeight(l) => l.to_css(d),
            FontValue::Family(f) => write_families(d, f),
            FontValue::Font(f) => f.to_css(d),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "font-weight" => parse_weight(p).map(FontValue::Weight),
        "font-size" => parse_size(p).map(FontValue::Size),
        "font-stretch" => parse_stretch(p).map(FontValue::Stretch),
        "font-style" => parse_style(p).map(FontValue::Style),
        "font-variant-caps" => expect_keyword(p, VARIANT_CAPS).map(FontValue::VariantCaps),
        "line-height" => parse_line_height(p).map(FontValue::LineHeight),
        "font-family" => parse_family_list(p).map(FontValue::Family),
        "font" => parse_font(p).map(FontValue::Font),
        _ => return None,
    };
    let _ = parse_weight_abs;
    Some(r.map(Value::Font))
}

#[derive(Default)]
pub struct FontHandler {
    family: Option<Vec<Family>>,
    size: Option<FSize>,
    style: Option<FStyle>,
    weight: Option<Weight>,
    stretch: Option<Stretch>,
    line_height: Option<LineHeight>,
    variant_caps: Option<String>,
    has_any: bool,
}

fn fp(name: &str, v: FontValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Font(v))
}

impl FontHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let family = self.family.take();
        let size = self.size.take();
        let style = self.style.take();
        let weight = self.weight.take();
        let stretch = self.stretch.take();
        let lh = self.line_height.take();
        let vc = self.variant_caps.take();
        if let (Some(family), Some(size), Some(style), Some(weight), Some(stretch), Some(lh), Some(vc)) =
            (family.clone(), size.clone(), style.clone(), weight.clone(), stretch.clone(), lh.clone(), vc.clone())
        {
            // variant caps must be css2 compatible for shorthand
            if vc == "normal" || vc == "small-caps" {
                let family = crate::prefixer::font_family_fallbacks(family);
                out.push(fp("font", FontValue::Font(Font { family, size, style, weight, stretch, line_height: lh, variant_caps: vc })));
                return;
            }
        }
        if let Some(f) = family {
            out.push(fp("font-family", FontValue::Family(crate::prefixer::font_family_fallbacks(f))));
        }
        if let Some(x) = size {
            out.push(fp("font-size", FontValue::Size(x)));
        }
        if let Some(x) = style {
            out.push(fp("font-style", FontValue::Style(x)));
        }
        if let Some(x) = weight {
            out.push(fp("font-weight", FontValue::Weight(x)));
        }
        if let Some(x) = stretch {
            out.push(fp("font-stretch", FontValue::Stretch(x)));
        }
        if let Some(x) = lh {
            out.push(fp("line-height", FontValue::LineHeight(x)));
        }
        if let Some(x) = vc {
            out.push(fp("font-variant-caps", FontValue::VariantCaps(x)));
        }
    }
}

impl crate::handlers::Handler for FontHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(
            id.name.as_str(),
            "font" | "font-family" | "font-size" | "font-style" | "font-weight" | "font-stretch" | "line-height" | "font-variant-caps"
        ) {
            return false;
        }
        match p {
            Property::Val(_, Value::Font(v)) => {
                self.has_any = true;
                match v {
                    FontValue::Family(f) => self.family = Some(f.clone()),
                    FontValue::Size(f) => self.size = Some(f.clone()),
                    FontValue::Style(f) => self.style = Some(f.clone()),
                    FontValue::Weight(f) => self.weight = Some(f.clone()),
                    FontValue::Stretch(f) => self.stretch = Some(f.clone()),
                    FontValue::LineHeight(f) => self.line_height = Some(f.clone()),
                    FontValue::VariantCaps(f) => self.variant_caps = Some(f.clone()),
                    FontValue::Font(f) => {
                        self.family = Some(f.family.clone());
                        self.size = Some(f.size.clone());
                        self.style = Some(f.style.clone());
                        self.weight = Some(f.weight.clone());
                        self.stretch = Some(f.stretch.clone());
                        self.line_height = Some(f.line_height.clone());
                        self.variant_caps = Some(f.variant_caps.clone());
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
