use crate::parser::*;
use crate::printer::Printer;
use crate::tokenizer::Token;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum Easing {
    Linear,
    Ease,
    EaseIn,
    EaseOut,
    EaseInOut,
    Cubic(f32, f32, f32, f32),
    Steps(i32, String),
    LinearFn(crate::tokenlist::TokenList),
}

impl Easing {
    pub fn is_ease(&self) -> bool {
        matches!(self, Easing::Ease)
    }
    pub fn parse(p: &mut Parser) -> PResult<Easing> {
        let loc = p.location();
        let t = p.next()?.clone();
        match t {
            Token::Ident(s) => {
                let l = s.to_ascii_lowercase();
                Ok(match l.as_str() {
                    "linear" => Easing::Linear,
                    "ease" => Easing::Ease,
                    "ease-in" => Easing::EaseIn,
                    "ease-out" => Easing::EaseOut,
                    "ease-in-out" => Easing::EaseInOut,
                    "step-start" => Easing::Steps(1, "start".into()),
                    "step-end" => Easing::Steps(1, "end".into()),
                    _ => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc)),
                })
            }
            Token::Function(f) => {
                let l = f.to_ascii_lowercase();
                match l.as_str() {
                    "cubic-bezier" => p.parse_nested_block(|p| {
                        let x1 = parse_number(p)?;
                        p.expect_comma()?;
                        let y1 = parse_number(p)?;
                        p.expect_comma()?;
                        let x2 = parse_number(p)?;
                        p.expect_comma()?;
                        let y2 = parse_number(p)?;
                        if !(0.0..=1.0).contains(&x1) || !(0.0..=1.0).contains(&x2) {
                            return p.invalid();
                        }
                        Ok(Easing::Cubic(x1, y1, x2, y2))
                    }),
                    "steps" => p.parse_nested_block(|p| {
                        let n = parse_integer(p)?;
                        let pos = if p.try_comma() {
                            let k = crate::properties::expect_keyword(p, &["start", "end", "jump-start", "jump-end", "jump-none", "jump-both"])?;
                            match k.as_str() {
                                "jump-start" => "start".to_string(),
                                "jump-end" => "end".to_string(),
                                _ => k,
                            }
                        } else {
                            "end".to_string()
                        };
                        Ok(Easing::Steps(n, pos))
                    }),
                    "linear" => {
                        let tl = p.parse_nested_block(crate::tokenlist::TokenList::parse)?;
                        Ok(Easing::LinearFn(tl))
                    }
                    _ => Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f)), loc)),
                }
            }
            t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
        }
    }

    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Easing::Linear => d.write_str("linear"),
            Easing::Ease => d.write_str("ease"),
            Easing::EaseIn => d.write_str("ease-in"),
            Easing::EaseOut => d.write_str("ease-out"),
            Easing::EaseInOut => d.write_str("ease-in-out"),
            Easing::Cubic(a, b, c, e) => {
                let k = (*a, *b, *c, *e);
                if k == (0.25, 0.1, 0.25, 1.0) {
                    d.write_str("ease");
                } else if k == (0.42, 0.0, 1.0, 1.0) {
                    d.write_str("ease-in");
                } else if k == (0.0, 0.0, 0.58, 1.0) {
                    d.write_str("ease-out");
                } else if k == (0.42, 0.0, 0.58, 1.0) {
                    d.write_str("ease-in-out");
                } else if k == (0.0, 0.0, 1.0, 1.0) {
                    d.write_str("linear");
                } else {
                    d.write_str("cubic-bezier(");
                    d.write_num(*a);
                    d.delim(',', false);
                    d.write_num(*b);
                    d.delim(',', false);
                    d.write_num(*c);
                    d.delim(',', false);
                    d.write_num(*e);
                    d.write_char(')');
                }
            }
            Easing::Steps(n, pos) => {
                if *n == 1 && pos == "start" {
                    d.write_str("step-start");
                } else if *n == 1 && pos == "end" {
                    d.write_str("step-end");
                } else {
                    d.write_str("steps(");
                    d.write_str(&n.to_string());
                    d.delim(',', false);
                    d.write_str(pos);
                    d.write_char(')');
                }
            }
            Easing::LinearFn(tl) => {
                d.write_str("linear(");
                tl.to_css(d, false);
                d.write_char(')');
            }
        }
    }

    pub fn normalized(&self) -> Easing {
        match self {
            Easing::Cubic(a, b, c, e) => {
                let k = (*a, *b, *c, *e);
                if k == (0.25, 0.1, 0.25, 1.0) {
                    Easing::Ease
                } else if k == (0.42, 0.0, 1.0, 1.0) {
                    Easing::EaseIn
                } else if k == (0.0, 0.0, 0.58, 1.0) {
                    Easing::EaseOut
                } else if k == (0.42, 0.0, 0.58, 1.0) {
                    Easing::EaseInOut
                } else {
                    self.clone()
                }
            }
            _ => self.clone(),
        }
    }
}

pub fn parse_time_val(p: &mut Parser) -> PResult<NumVal> {
    parse_numval(p, C_TIME, false)
}

pub fn time_is_zero(t: &NumVal) -> bool {
    t.is_zero()
}

pub fn parse_comma_list<T, F: Fn(&mut Parser) -> PResult<T>>(p: &mut Parser, f: F) -> PResult<Vec<T>> {
    let mut v = Vec::new();
    loop {
        v.push(p.parse_until_before(D_COMMA, |p| f(p))?);
        if !p.try_comma() {
            break;
        }
    }
    Ok(v)
}

pub fn write_comma_list<T, F: Fn(&T, &mut Printer)>(d: &mut Printer, v: &[T], f: F) {
    for (i, x) in v.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        f(x, d);
    }
}
