use crate::easing::*;
use crate::parser::*;
use crate::printer::Printer;
use crate::properties::*;
use crate::tokenizer::Token;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum TProp {
    All,
    None,
    Prop(String),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Transition {
    pub property: TProp,
    pub duration: NumVal,
    pub delay: NumVal,
    pub timing: Easing,
    pub behavior: Option<String>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum TransValue {
    Property(Vec<TProp>),
    Duration(Vec<NumVal>),
    Delay(Vec<NumVal>),
    Timing(Vec<Easing>),
    Behavior(Vec<String>),
    Shorthand(Vec<Transition>),
}

pub fn parse_tprop(p: &mut Parser) -> PResult<TProp> {
    let loc = p.location();
    let s = p.expect_ident()?.to_string();
    let l = s.to_ascii_lowercase();
    Ok(match l.as_str() {
        "all" => TProp::All,
        "none" => TProp::None,
        "initial" | "inherit" | "unset" | "default" | "revert" | "revert-layer" => {
            return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc));
        }
        _ => {
            if crate::properties::lookup(&l).is_some() {
                TProp::Prop(l)
            } else {
                TProp::Prop(s)
            }
        }
    })
}

impl TProp {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            TProp::All => d.write_str("all"),
            TProp::None => d.write_str("none"),
            TProp::Prop(s) => d.write_ident(s),
        }
    }
}

fn parse_transition(p: &mut Parser) -> PResult<Transition> {
    let mut property = None;
    let mut duration = None;
    let mut delay = None;
    let mut timing = None;
    let mut behavior = None;
    loop {
        if duration.is_none() {
            if let Ok(t) = p.try_parse(parse_time_val) {
                duration = Some(t);
                continue;
            }
        }
        if timing.is_none() {
            if let Ok(t) = p.try_parse(Easing::parse) {
                timing = Some(t);
                continue;
            }
        }
        if delay.is_none() {
            if let Ok(t) = p.try_parse(parse_time_val) {
                delay = Some(t);
                continue;
            }
        }
        if property.is_none() {
            if let Ok(t) = p.try_parse(parse_tprop) {
                property = Some(t);
                continue;
            }
        }
        if behavior.is_none() {
            if let Ok(b) = p.try_parse(|p| expect_keyword(p, &["normal", "allow-discrete"])) {
                behavior = Some(b);
                continue;
            }
        }
        break;
    }
    if property.is_none() && duration.is_none() && delay.is_none() && timing.is_none() && behavior.is_none() {
        return p.invalid();
    }
    Ok(Transition {
        property: property.unwrap_or(TProp::All),
        duration: duration.unwrap_or(NumVal::D(Dim::new(0.0, "s"))),
        delay: delay.unwrap_or(NumVal::D(Dim::new(0.0, "s"))),
        timing: timing.unwrap_or(Easing::Ease),
        behavior,
    })
}

impl Transition {
    pub fn to_css(&self, d: &mut Printer, prefix: u8) {
        write_tprop_prefixed(d, &self.property, prefix);
        if !self.duration.is_zero() || !self.delay.is_zero() {
            d.write_char(' ');
            self.duration.to_css(d);
        }
        if !self.timing.normalized().is_ease() {
            d.write_char(' ');
            self.timing.to_css(d);
        }
        if !self.delay.is_zero() {
            d.write_char(' ');
            self.delay.to_css(d);
        }
        if let Some(b) = &self.behavior {
            if b != "normal" {
                d.write_char(' ');
                d.write_str(b);
            }
        }
    }
}

fn write_tprop_prefixed(d: &mut Printer, t: &TProp, _prefix: u8) {
    t.to_css(d);
}

impl TransValue {
    pub fn to_css(&self, d: &mut Printer, prefix: u8) {
        match self {
            TransValue::Property(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            TransValue::Duration(v) | TransValue::Delay(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            TransValue::Timing(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            TransValue::Behavior(v) => write_comma_list(d, v, |x, d| d.write_str(x)),
            TransValue::Shorthand(v) => write_comma_list(d, v, |x, d| x.to_css(d, prefix)),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "transition-property" => parse_comma_list(p, parse_tprop).map(TransValue::Property),
        "transition-duration" => parse_comma_list(p, parse_time_val).map(TransValue::Duration),
        "transition-delay" => parse_comma_list(p, parse_time_val).map(TransValue::Delay),
        "transition-timing-function" => parse_comma_list(p, Easing::parse).map(TransValue::Timing),
        "transition-behavior" => parse_comma_list(p, |p| expect_keyword(p, &["normal", "allow-discrete"])).map(TransValue::Behavior),
        "transition" => parse_comma_list(p, parse_transition).map(TransValue::Shorthand),
        _ => return None,
    };
    Some(r.map(Value::Transition))
}

#[derive(Default)]
pub struct TransitionHandler {
    props: Option<(Vec<TProp>, u8)>,
    durations: Option<(Vec<NumVal>, u8)>,
    delays: Option<(Vec<NumVal>, u8)>,
    timings: Option<(Vec<Easing>, u8)>,
    has_any: bool,
}

fn tp(name: &str, prefix: u8, v: TransValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Transition(v))
}

impl TransitionHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let props = self.props.take();
        let durations = self.durations.take();
        let delays = self.delays.take();
        let timings = self.timings.take();
        if let (Some((pv, pp)), Some((dv, dp)), Some((lv, lp)), Some((tv, tpre))) = (&props, &durations, &delays, &timings) {
            if pp == dp && dp == lp && lp == tpre && !pv.is_empty() && !dv.is_empty() && !lv.is_empty() && !tv.is_empty() {
                let n = pv.len();
                let mut list = Vec::new();
                for i in 0..n {
                    list.push(Transition {
                        property: pv[i].clone(),
                        duration: dv[i % dv.len()].clone(),
                        delay: lv[i % lv.len()].clone(),
                        timing: tv[i % tv.len()].clone(),
                        behavior: None,
                    });
                }
                let prefix = crate::prefixer::transition_prefixes(*pp, &list);
                out.push(tp("transition", prefix, TransValue::Shorthand(list)));
                return;
            }
        }
        if let Some((v, pre)) = props {
            out.push(tp("transition-property", pre, TransValue::Property(v)));
        }
        if let Some((v, pre)) = durations {
            out.push(tp("transition-duration", pre, TransValue::Duration(v)));
        }
        if let Some((v, pre)) = timings {
            out.push(tp("transition-timing-function", pre, TransValue::Timing(v)));
        }
        if let Some((v, pre)) = delays {
            out.push(tp("transition-delay", pre, TransValue::Delay(v)));
        }
    }
}

impl crate::handlers::Handler for TransitionHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(
            id.name.as_str(),
            "transition" | "transition-property" | "transition-duration" | "transition-delay" | "transition-timing-function"
        ) {
            return false;
        }
        let pre = id.prefix;
        macro_rules! set {
            ($field:ident, $v:expr) => {{
                if let Some((_, p0)) = &self.$field {
                    if *p0 != pre {
                        self.flush(out);
                    }
                }
                self.$field = Some(($v, pre));
                self.has_any = true;
            }};
        }
        match p {
            Property::Val(_, Value::Transition(v)) => match v {
                TransValue::Property(x) => set!(props, x.clone()),
                TransValue::Duration(x) => set!(durations, x.clone()),
                TransValue::Delay(x) => set!(delays, x.clone()),
                TransValue::Timing(x) => set!(timings, x.clone()),
                TransValue::Shorthand(list) => {
                    if list.iter().any(|t| t.behavior.is_some()) {
                        self.flush(out);
                        out.push(p.clone());
                        return true;
                    }
                    set!(props, list.iter().map(|t| t.property.clone()).collect());
                    set!(durations, list.iter().map(|t| t.duration.clone()).collect());
                    set!(delays, list.iter().map(|t| t.delay.clone()).collect());
                    set!(timings, list.iter().map(|t| t.timing.clone()).collect());
                }
                TransValue::Behavior(_) => {
                    self.flush(out);
                    out.push(p.clone());
                }
            },
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
