                TransValue::Property(x) => set!(props, x.clone()),
                TransValue::Duration(x) => set!(durations, x.clone()),
                TransValue::Delay(x) => set!(delays, x.clone()),
                TransValue::Timing(x) => set!(timings, x.clone()),
                TransValue::Shorthand(list) => {
                    if list.iter().any(|t| t.behavior.is_some()) {
                        self.flush(out);
                        out.push(p.clone());
                        return true;
                    }
                    set!(props, list.iter().map(|t| t.property.clone()).collect());
                    set!(durations, list.iter().map(|t| t.duration.clone()).collect());
                    set!(delays, list.iter().map(|t| t.delay.clone()).collect());
                    set!(timings, list.iter().map(|t| t.timing.clone()).collect());
                }
                TransValue::Behavior(_) => {
                    self.flush(out);
                    out.push(p.clone());
                }
            },
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
