        }
        if timeline.is_none() {
            if let Ok(t) = p.try_parse(parse_timeline) {
                timeline = Some(t);
                continue;
            }
        }
        break;
    }
    Ok(Animation {
        name: name.unwrap_or(AName::None),
        duration: duration.unwrap_or(NumVal::D(Dim::new(0.0, "s"))),
        timing: timing.unwrap_or(Easing::Ease),
        delay: delay.unwrap_or(NumVal::D(Dim::new(0.0, "s"))),
        iter: iter.unwrap_or(Iter::N(1.0)),
        direction: direction.unwrap_or_else(|| "normal".into()),
        fill: fill.unwrap_or_else(|| "none".into()),
        play: play.unwrap_or_else(|| "running".into()),
        timeline: timeline.unwrap_or(Timeline::Auto),
    })
}

fn is_easing_ident(s: &str) -> bool {
    matches!(s.to_ascii_lowercase().as_str(), "linear" | "ease" | "ease-in" | "ease-out" | "ease-in-out" | "step-start" | "step-end")
}

impl Animation {
    pub fn to_css(&self, d: &mut Printer) {
        if let Some(name) = self.name.text() {
            let lname = name.to_ascii_lowercase();
            if !self.duration.is_zero() || !self.delay.is_zero() {
                self.duration.to_css(d);
                d.write_char(' ');
            }
            if !self.timing.normalized().is_ease() || is_easing_ident(name) {
                self.timing.to_css(d);
                d.write_char(' ');
            }
            if !self.delay.is_zero() {
                self.delay.to_css(d);
                d.write_char(' ');
            }
            if self.iter != Iter::N(1.0) || lname == "infinite" {
                self.iter.to_css(d);
                d.write_char(' ');
            }
            if self.direction != "normal" || DIRECTIONS.contains(&lname.as_str()) {
                d.write_str(&self.direction);
                d.write_char(' ');
            }
            if self.fill != "none" || (lname != "none" && FILLS.contains(&lname.as_str())) {
                d.write_str(&self.fill);
                d.write_char(' ');
            }
            if self.play != "running" || PLAYS.contains(&lname.as_str()) {
                d.write_str(&self.play);
                d.write_char(' ');
            }
        }
        self.name.to_css(d);
        if self.timeline != Timeline::Auto {
            d.write_char(' ');
            self.timeline.to_css(d);
        }
    }
}

impl AnimValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            AnimValue::Name(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            AnimValue::Duration(v) | AnimValue::Delay(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            AnimValue::Timing(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            AnimValue::Iter(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            AnimValue::Direction(v) | AnimValue::Fill(v) | AnimValue::Play(v) | AnimValue::Composition(v) => {
                write_comma_list(d, v, |x, d| d.write_str(x))
            }
            AnimValue::Timeline(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            AnimValue::Shorthand(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "animation-name" => parse_comma_list(p, parse_name).map(AnimValue::Name),
        "animation-duration" => parse_comma_list(p, parse_time_val).map(AnimValue::Duration),
        "animation-timing-function" => parse_comma_list(p, Easing::parse).map(AnimValue::Timing),
        "animation-delay" => parse_comma_list(p, parse_time_val).map(AnimValue::Delay),
        "animation-iteration-count" => parse_comma_list(p, parse_iter).map(AnimValue::Iter),
        "animation-direction" => parse_comma_list(p, |p| expect_keyword(p, DIRECTIONS)).map(AnimValue::Direction),
        "animation-fill-mode" => parse_comma_list(p, |p| expect_keyword(p, FILLS)).map(AnimValue::Fill),
        "animation-play-state" => parse_comma_list(p, |p| expect_keyword(p, PLAYS)).map(AnimValue::Play),
        "animation-timeline" => parse_comma_list(p, parse_timeline).map(AnimValue::Timeline),
        "animation-composition" => parse_comma_list(p, |p| expect_keyword(p, &["replace", "add", "accumulate"])).map(AnimValue::Composition),
        "animation" => parse_comma_list(p, parse_animation).map(AnimValue::Shorthand),
        _ => return None,
    };
    Some(r.map(Value::Animation))
}

#[derive(Default)]
pub struct AnimationHandler {
    names: Option<(Vec<AName>, u8)>,
    durations: Option<(Vec<NumVal>, u8)>,
    timings: Option<(Vec<Easing>, u8)>,
    iters: Option<(Vec<Iter>, u8)>,
    directions: Option<(Vec<String>, u8)>,
    plays: Option<(Vec<String>, u8)>,
    delays: Option<(Vec<NumVal>, u8)>,
    fills: Option<(Vec<String>, u8)>,
    timelines: Option<(Vec<Timeline>, u8)>,
    has_any: bool,
}

fn ap(name: &str, prefix: u8, v: AnimValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Animation(v))
}

impl AnimationHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let names = self.names.take();
        let durations = self.durations.take();
        let timings = self.timings.take();
        let iters = self.iters.take();
        let directions = self.directions.take();
        let plays = self.plays.take();
        let delays = self.delays.take();
        let fills = self.fills.take();
        let timelines = self.timelines.take();
        if let (Some(n), Some(du), Some(t), Some(i), Some(di), Some(pl), Some(de), Some(f), Some(tl)) =
            (&names, &durations, &timings, &iters, &directions, &plays, &delays, &fills, &timelines)
        {
            let len = n.0.len();
            let pre = n.1;
            if du.0.len() == len
                && t.0.len() == len
                && i.0.len() == len
                && di.0.len() == len
                && pl.0.len() == len
                && de.0.len() == len
                && f.0.len() == len
                && tl.0.len() == len
                && [du.1, t.1, i.1, di.1, pl.1, de.1, f.1, tl.1].iter().all(|x| *x == pre)
            {
                let mut list = Vec::new();
                for k in 0..len {
                    list.push(Animation {
                        name: n.0[k].clone(),
                        duration: du.0[k].clone(),
                        timing: t.0[k].clone(),
                        delay: de.0[k].clone(),
                        iter: i.0[k].clone(),
                        direction: di.0[k].clone(),
                        fill: f.0[k].clone(),
                        play: pl.0[k].clone(),
                        timeline: tl.0[k].clone(),
                    });
                }
                let pre2 = crate::prefixer::animation_prefixes(pre);
                out.push(ap("animation", pre2, AnimValue::Shorthand(list)));
                return;
            }
        }
        if let Some((v, p)) = names {
            out.push(ap("animation-name", p, AnimValue::Name(v)));
        }
        if let Some((v, p)) = durations {
            out.push(ap("animation-duration", p, AnimValue::Duration(v)));
        }
        if let Some((v, p)) = timings {
            out.push(ap("animation-timing-function", p, AnimValue::Timing(v)));
        }
        if let Some((v, p)) = iters {
            out.push(ap("animation-iteration-count", p, AnimValue::Iter(v)));
        }
        if let Some((v, p)) = directions {
            out.push(ap("animation-direction", p, AnimValue::Direction(v)));
        }
        if let Some((v, p)) = plays {
            out.push(ap("animation-play-state", p, AnimValue::Play(v)));
        }
        if let Some((v, p)) = delays {
            out.push(ap("animation-delay", p, AnimValue::Delay(v)));
        }
        if let Some((v, p)) = fills {
            out.push(ap("animation-fill-mode", p, AnimValue::Fill(v)));
        }
        if let Some((v, p)) = timelines {
            out.push(ap("animation-timeline", p, AnimValue::Timeline(v)));
        }
    }
}

impl crate::handlers::Handler for AnimationHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(
            id.name.as_str(),
            "animation" | "animation-name" | "animation-duration" | "animation-timing-function" | "animation-iteration-count"
                | "animation-direction" | "animation-play-state" | "animation-delay" | "animation-fill-mode" | "animation-timeline"
        ) {
            return false;
        }
        let pre = id.prefix;
        macro_rules! set {
            ($field:ident, $v:expr) => {{
                if let Some((_, p0)) = &self.$field {
                    if *p0 != pre {
                        self.flush(out);
                    }
                }
                self.$field = Some(($v, pre));
                self.has_any = true;
            }};
        }
        match p {
            Property::Val(_, Value::Animation(v)) => match v {
                AnimValue::Name(x) => set!(names, x.clone()),
                AnimValue::Duration(x) => set!(durations, x.clone()),
                AnimValue::Timing(x) => set!(timings, x.clone()),
                AnimValue::Iter(x) => set!(iters, x.clone()),
                AnimValue::Direction(x) => set!(directions, x.clone()),
                AnimValue::Play(x) => set!(plays, x.clone()),
                AnimValue::Delay(x) => set!(delays, x.clone()),
                AnimValue::Fill(x) => set!(fills, x.clone()),
                AnimValue::Timeline(x) => set!(timelines, x.clone()),
                AnimValue::Shorthand(list) => {
                    set!(names, list.iter().map(|a| a.name.clone()).collect());
                    set!(durations, list.iter().map(|a| a.duration.clone()).collect());
                    set!(timings, list.iter().map(|a| a.timing.clone()).collect());
                    set!(iters, list.iter().map(|a| a.iter.clone()).collect());
                    set!(directions, list.iter().map(|a| a.direction.clone()).collect());
                    set!(plays, list.iter().map(|a| a.play.clone()).collect());
                    set!(delays, list.iter().map(|a| a.delay.clone()).collect());
                    set!(fills, list.iter().map(|a| a.fill.clone()).collect());
                    set!(timelines, list.iter().map(|a| a.timeline.clone()).collect());
                }
                AnimValue::Composition(_) => {
                    self.flush(out);
                    out.push(p.clone());
                }
            },
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
