            },
            PComp::Len(l) => Some(l.clone()),
            PComp::Center => Some(NumVal::pct(0.5)),
            _ => None,
        }
    }
}

impl Position {
    pub fn center() -> Position {
        Position { x: PComp::Center, y: PComp::Center }
    }
    pub fn zero() -> Position {
        Position { x: PComp::Len(NumVal::pct(0.0)), y: PComp::Len(NumVal::pct(0.0)) }
    }
    pub fn is_zero(&self) -> bool {
        self.x.is_zero() && self.y.is_zero()
    }

    pub fn parse(p: &mut Parser) -> PResult<Position> {
        match p.try_parse(|p| parse_comp(p, true)) {
            Ok(PComp::Center) => {
                if let Ok(x) = p.try_parse(|p| kw(p, is_hkw)) {
                    let off = p.try_parse(parse_length_percentage).ok();
                    return Ok(Position { x: PComp::Side(x, off), y: PComp::Center });
                }
                let y = p.try_parse(|p| parse_comp(p, false)).unwrap_or(PComp::Center);
                return Ok(Position { x: PComp::Center, y });
            }
            Ok(x @ PComp::Len(_)) => {
                if let Ok(yk) = p.try_parse(|p| kw(p, is_vkw)) {
                    return Ok(Position { x, y: PComp::Side(yk, None) });
                }
                if let Ok(yl) = p.try_parse(parse_length_percentage) {
                    return Ok(Position { x, y: PComp::Len(yl) });
                }
                let _ = p.try_ident_matching("center");
                return Ok(Position { x, y: PComp::Center });
            }
            Ok(PComp::Side(xk, lp)) => {
                if lp.is_some() {
                    // must be followed by y keyword (4-value or 3-value)
                    if let Ok(yk) = p.try_parse(|p| kw(p, is_vkw)) {
                        let yl = p.try_parse(parse_length_percentage).ok();
                        return Ok(Position { x: PComp::Side(xk, lp), y: PComp::Side(yk, yl) });
                    }
                    if p.try_ident_matching("center") {
                        return Ok(Position { x: PComp::Side(xk, lp), y: PComp::Center });
                    }
                    // two-value: keyword followed by length => x side, y length
                    return Ok(Position { x: PComp::Side(xk, None), y: PComp::Len(lp.unwrap()) });
                }
                if p.try_ident_matching("center") {
                    return Ok(Position { x: PComp::Side(xk, None), y: PComp::Center });
                }
                if let Ok(yk) = p.try_parse(|p| kw(p, is_vkw)) {
                    let yl = p.try_parse(parse_length_percentage).ok();
                    return Ok(Position { x: PComp::Side(xk, None), y: PComp::Side(yk, yl) });
                }
                return Ok(Position { x: PComp::Side(xk, None), y: PComp::Center });
            }
            Err(_) => {}
        }
        let yk = kw(p, is_vkw)?;
        let r = p.try_parse(|p| {
            let yl = p.try_parse(parse_length_percentage).ok();
            if let Ok(xk) = p.try_parse(|p| kw(p, is_hkw)) {
                let xl = p.try_parse(parse_length_percentage).ok();
                return Ok((yl, PComp::Side(xk, xl)));
            }
            p.expect_ident_matching("center")?;
            Ok((yl, PComp::Center))
        });
        if let Ok((yl, x)) = r {
            return Ok(Position { x, y: PComp::Side(yk, yl) });
        }
        Ok(Position { x: PComp::Center, y: PComp::Side(yk, None) })
    }

    pub fn to_css(&self, d: &mut Printer) {
        let (x, y) = (&self.x, &self.y);
        match (x, y) {
            (PComp::Side(s, Some(_)), PComp::Len(yl)) if s != "left" => {
                x.to_css(d);
                d.write_str(" top ");
                yl.to_css(d);
            }
            (PComp::Side(s, Some(_)), y) if s != "left" && y.is_center() => {
                x.to_css(d);
                d.write_str(" center");
            }
            (x, y) if x.is_center() && y.is_center() => x.to_css(d),
            (PComp::Len(xl), y) if y.is_center() => xl.to_css(d),
            (PComp::Side(s, None), y) if y.is_center() => {
                let lp = if s == "left" { NumVal::zero_px() } else { NumVal::pct(1.0) };
                lp.to_css(d);
            }
            (x, PComp::Side(_, None)) if x.is_center() => y.to_css(d),
            (PComp::Side(_, None), PComp::Side(_, None)) => {
                x.side_lp().unwrap().to_css(d);
                d.write_char(' ');
                y.side_lp().unwrap().to_css(d);
            }
            _ => {
                if let (Some(a), Some(b)) = (x.final_lp("left"), y.final_lp("top")) {
                    a.to_css(d);
                    d.write_char(' ');
                    b.to_css(d);
                } else {
                    x.to_css(d);
                    d.write_char(' ');
                    y.to_css(d);
                }
            }
        }
    }
}
