use crate::color::CssColor;
use crate::parser::*;
use crate::position::*;
use crate::printer::Printer;
use crate::tokenizer::Token;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum LineDir {
    Angle(NumVal),
    H(String),
    V(String),
    Corner(String, String),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Item {
    Stop(CssColor, Option<NumVal>, Option<NumVal>),
    Hint(NumVal),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Shape {
    Circle(Option<String>, Option<NumVal>),       // extent or radius
    Ellipse(Option<String>, Option<(NumVal, NumVal)>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Gradient {
    Linear { prefix: u8, repeating: bool, dir: LineDir, items: Vec<Item> },
    Radial { prefix: u8, repeating: bool, shape: Shape, pos: Position, items: Vec<Item> },
    Conic { repeating: bool, angle: Option<NumVal>, pos: Position, items: Vec<Item> },
    WebkitLegacy(crate::tokenlist::TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub struct ImageSetItem {
    pub url: Option<String>,
    pub string: Option<String>,
    pub gradient: Option<Box<Gradient>>,
    pub res: Dim,
    pub ty: Option<String>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Image {
    None,
    Url(String),
    Gradient(Box<Gradient>),
    ImageSet(u8, Vec<ImageSetItem>),
}

fn prefix_of(name: &str) -> (u8, String) {
    crate::prefixes::split_prefix(name)
}

impl Image {
    pub fn parse(p: &mut Parser) -> PResult<Image> {
        if p.try_ident_matching("none") {
            return Ok(Image::None);
        }
        let loc = p.location();
        let st = p.state();
        match p.next()?.clone() {
            Token::UnquotedUrl(u) => Ok(Image::Url(u)),
            Token::Function(f) => {
                let (prefix, base) = prefix_of(&f);
                match base.as_str() {
                    "url" if prefix == 0 => {
                        let u = p.parse_nested_block(|p| Ok(p.expect_string()?.to_string()))?;
                        Ok(Image::Url(u))
                    }
                    "linear-gradient" | "repeating-linear-gradient" | "radial-gradient" | "repeating-radial-gradient"
                    | "conic-gradient" | "repeating-conic-gradient" | "gradient" => {
                        p.reset(st);
                        Ok(Image::Gradient(Box::new(parse_gradient(p)?)))
                    }
                    "image-set" if prefix == 0 || prefix == crate::prefixes::WEBKIT => {
                        let items = p.parse_nested_block(|p| {
                            crate::easing::parse_comma_list(p, |p| {
                                let mut item = ImageSetItem { url: None, string: None, gradient: None, res: Dim::new(1.0, "x"), ty: None };
                                if let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
                                    item.string = Some(s);
                                } else {
                                    match Image::parse(p)? {
                                        Image::Url(u) => item.url = Some(u),
                                        Image::Gradient(g) => item.gradient = Some(g),
                                        _ => return p.invalid(),
                                    }
                                }
                                loop {
                                    if let Ok(NumVal::D(r)) = p.try_parse(|p| parse_numval(p, C_RES, false)) {
                                        item.res = r;
                                        continue;
                                    }
                                    if let Ok(t) = p.try_parse(|p| {
                                        p.expect_function_matching("type")?;
                                        p.parse_nested_block(|p| Ok(p.expect_string()?.to_string()))
                                    }) {
                                        item.ty = Some(t);
                                        continue;
                                    }
                                    break;
                                }
                                Ok(item)
                            })
                        })?;
                        Ok(Image::ImageSet(if prefix == 0 { crate::prefixes::NONE } else { prefix }, items))
                    }
                    _ => Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f)), loc)),
                }
            }
            t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
        }
    }

    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Image::None => d.write_str("none"),
            Image::Url(u) => crate::url::write_url(d, u),
            Image::Gradient(g) => g.to_css(d),
            Image::ImageSet(prefix, items) => {
                d.write_str(crate::prefixes::prefix_str(*prefix));
                d.write_str("image-set(");
                for (i, it) in items.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    if let Some(u) = &it.url {
                        crate::url::write_url(d, u);
                    } else if let Some(s) = &it.string {
                        d.write_string(s);
                    } else if let Some(g) = &it.gradient {
                        g.to_css(d);
                    }
                    d.write_char(' ');
                    it.res.to_css(d);
                    if let Some(t) = &it.ty {
                        d.write_str(" type(");
                        d.write_string(t);
                        d.write_char(')');
                    }
                }
                d.write_char(')');
            }
        }
    }

    pub fn colors(&self) -> Vec<&CssColor> {
        match self {
            Image::Gradient(g) => g.colors(),
            _ => vec![],
        }
    }
}

fn parse_items(p: &mut Parser, angle: bool) -> PResult<Vec<Item>> {
    let mut items = Vec::new();
    let mut seen_stop = false;
    loop {
        let it = p.parse_until_before(D_COMMA, |p| {
            let parse_pos = |p: &mut Parser| -> PResult<NumVal> {
                if angle {
                    parse_numval(p, C_ANG | C_PCT, true)
                } else {
                    parse_length_percentage(p)
                }
            };
            if let Ok(c) = p.try_parse(CssColor::parse) {
                let p1 = p.try_parse(parse_pos).ok();
                let p2 = if p1.is_some() { p.try_parse(parse_pos).ok() } else { None };
                return Ok(Item::Stop(c, p1, p2));
            }
            let pos = parse_pos(p)?;
            if let Ok(c) = p.try_parse(CssColor::parse) {
                return Ok(Item::Stop(c, Some(pos), None));
            }
            Ok(Item::Hint(pos))
        })?;
        match &it {
            Item::Hint(_) => {
                if !seen_stop {
                    return p.invalid();
                }
                seen_stop = false;
            }
            Item::Stop(..) => seen_stop = true,
        }
        items.push(it);
        if !p.try_comma() {
            break;
        }
    }
    if !seen_stop || items.len() < 2 {
        return p.invalid();
    }
    Ok(items)
}

fn parse_side(p: &mut Parser) -> PResult<String> {
    let loc = p.location();
    let s = p.expect_ident()?.to_ascii_lowercase();
    if matches!(s.as_str(), "left" | "right" | "top" | "bottom") {
        Ok(s)
    } else {
        Err(p.err_at(ErrorKind::InvalidValue, loc))
    }
}

fn parse_line_dir(p: &mut Parser, prefixed: bool) -> PResult<LineDir> {
    if let Ok(a) = p.try_parse(|p| parse_angle(p, true)) {
        return Ok(LineDir::Angle(a));
    }
    if !prefixed {
        p.expect_ident_matching("to")?;
    }
    let a = parse_side(p)?;
    let b = p.try_parse(parse_side).ok();
    let is_h = |s: &str| s == "left" || s == "right";
    Ok(match b {
        None => {
            if is_h(&a) {
                LineDir::H(a)
            } else {
                LineDir::V(a)
            }
        }
        Some(b) => {
            if is_h(&a) && !is_h(&b) {
                LineDir::Corner(a, b)
            } else if !is_h(&a) && is_h(&b) {
                LineDir::Corner(b, a)
            } else {
                return p.invalid();
            }
        }
    })
}

const EXTENTS: &[&str] = &["closest-side", "closest-corner", "farthest-side", "farthest-corner"];

fn parse_shape(p: &mut Parser) -> PResult<Shape> {
    let mut kind: Option<String> = None;
    let mut extent: Option<String> = None;
    let mut l1: Option<NumVal> = None;
    let mut l2: Option<NumVal> = None;
    let mut any = false;
    loop {
        if kind.is_none() {
            if let Ok(k) = p.try_parse(|p| crate::properties::expect_keyword(p, &["circle", "ellipse"])) {
                kind = Some(k);
                any = true;
                continue;
            }
        }
        if extent.is_none() && l1.is_none() {
            if let Ok(e) = p.try_parse(|p| crate::properties::expect_keyword(p, EXTENTS)) {
                extent = Some(e);
                any = true;
                continue;
            }
            if let Ok(a) = p.try_parse(parse_length_percentage) {
                l1 = Some(a);
                l2 = p.try_parse(parse_length_percentage).ok();
                any = true;
                continue;
            }
        }
        break;
    }
    if !any {
        return p.invalid();
    }
    let k = kind.unwrap_or_else(|| if l1.is_some() && l2.is_none() { "circle".into() } else { "ellipse".into() });
    if k == "circle" {
        if l2.is_some() {
            return p.invalid();
        }
        if let Some(NumVal::D(dd)) = &l1 {
            if dd.unit == "%" {
                return p.invalid();
            }
        }
        Ok(Shape::Circle(extent, l1))
    } else {
        if l1.is_some() && l2.is_none() {
            return p.invalid();
        }
        Ok(Shape::Ellipse(extent, l1.map(|a| (a, l2.unwrap()))))
    }
}

pub fn parse_gradient(p: &mut Parser) -> PResult<Gradient> {
    let loc = p.location();
    let f = p.expect_function()?.to_string();
    let (prefix, base) = prefix_of(&f);
    let prefix_bits = if prefix == 0 { crate::prefixes::NONE } else { prefix };
    let prefixed = prefix != 0;
    match base.as_str() {
        "linear-gradient" | "repeating-linear-gradient" => {
            let repeating = base.starts_with("repeating");
            p.parse_nested_block(|p| {
                let dir = match p.try_parse(|p| parse_line_dir(p, prefixed)) {
                    Ok(d) => {
                        p.expect_comma()?;
                        d
                    }
                    Err(_) => LineDir::V("bottom".into()),
                };
                let items = parse_items(p, false)?;
                Ok(Gradient::Linear { prefix: prefix_bits, repeating, dir, items })
            })
        }
        "radial-gradient" | "repeating-radial-gradient" => {
            let repeating = base.starts_with("repeating");
            p.parse_nested_block(|p| {
                let shape = p.try_parse(parse_shape).ok();
                let pos = if p.try_ident_matching("at") { Some(Position::parse(p)?) } else { None };
                if shape.is_some() || pos.is_some() {
                    p.expect_comma()?;
                }
                let items = parse_items(p, false)?;
                Ok(Gradient::Radial {
                    prefix: prefix_bits,
                    repeating,
                    shape: shape.unwrap_or(Shape::Ellipse(Some("farthest-corner".into()), None)),
                    pos: pos.unwrap_or_else(Position::center),
                    items,
                })
            })
        }
        "conic-gradient" | "repeating-conic-gradient" if prefix == 0 => {
            let repeating = base.starts_with("repeating");
            p.parse_nested_block(|p| {
                let angle = if p.try_ident_matching("from") { Some(parse_angle(p, true)?) } else { None };
                let pos = if p.try_ident_matching("at") { Some(Position::parse(p)?) } else { None };
                if angle.is_some() || pos.is_some() {
                    p.expect_comma()?;
                }
                let items = parse_items(p, true)?;
                Ok(Gradient::Conic { repeating, angle, pos: pos.unwrap_or_else(Position::center), items })
            })
        }
        "gradient" if prefix == crate::prefixes::WEBKIT => {
            let tl = p.parse_nested_block(crate::tokenlist::TokenList::parse)?;
            Ok(Gradient::WebkitLegacy(tl))
        }
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f)), loc)),
    }
}

fn write_items(d: &mut Printer, items: &[Item]) {
    for (i, it) in items.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        match it {
            Item::Stop(c, p1, p2) => {
                c.to_css(d);
                if let Some(p1) = p1 {
                    d.write_char(' ');
                    p1.to_css(d);
                }
                if let Some(p2) = p2 {
                    d.write_char(' ');
                    p2.to_css(d);
                }
            }
            Item::Hint(h) => h.to_css(d),
        }
    }
}

fn pct_of(v: &NumVal) -> Option<f32> {
    match v {
        NumVal::D(d) if d.unit == "%" => Some(d.v),
        _ => None,
    }
}

impl Gradient {
    pub fn colors(&self) -> Vec<&CssColor> {
        let items = match self {
            Gradient::Linear { items, .. } | Gradient::Radial { items, .. } | Gradient::Conic { items, .. } => items,
            _ => return vec![],
        };
        items
            .iter()
            .filter_map(|i| match i {
                Item::Stop(c, ..) => Some(c),
                _ => None,
            })
            .collect()
    }

    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Gradient::Linear { prefix, repeating, dir, items } => {
                d.write_str(crate::prefixes::prefix_str(*prefix));
                d.write_str(if *repeating { "repeating-linear-gradient(" } else { "linear-gradient(" });
                let prefixed = *prefix != crate::prefixes::NONE;
                let angle: Option<f32> = match dir {
                    LineDir::V(s) if s == "bottom" => Some(180.0),
                    LineDir::V(_) => Some(0.0),
                    LineDir::Angle(NumVal::D(a)) => a.to_canonical(),
                    _ => None,
                };
                if angle == Some(180.0) {
                    write_items(d, items);
                } else if angle == Some(0.0)
                    && d.minify
                    && items.iter().all(|i| match i {
                        Item::Hint(h) => pct_of(h).is_some(),
                        Item::Stop(_, p1, p2) => p1.as_ref().map(|x| pct_of(x).is_some()).unwrap_or(true) && p2.as_ref().map(|x| pct_of(x).is_some()).unwrap_or(true),
                    })
                {
                    let flipped: Vec<Item> = items
                        .iter()
                        .rev()
                        .map(|i| match i {
                            Item::Hint(h) => Item::Hint(NumVal::pct(1.0 - pct_of(h).unwrap())),
                            Item::Stop(c, p1, p2) => {
                                let f = |x: &Option<NumVal>| x.as_ref().map(|v| NumVal::pct(1.0 - pct_of(v).unwrap()));
                                match (p1, p2) {
                                    (Some(_), Some(_)) => Item::Stop(c.clone(), f(p2), f(p1)),
                                    _ => Item::Stop(c.clone(), f(p1), None),
                                }
                            }
                        })
                        .collect();
                    write_items(d, &flipped);
                } else {
                    write_line_dir(d, dir, prefixed);
                    d.delim(',', false);
                    write_items(d, items);
                }
                d.write_char(')');
            }
            Gradient::Radial { prefix, repeating, shape, pos, items } => {
                d.write_str(crate::prefixes::prefix_str(*prefix));
                d.write_str(if *repeating { "repeating-radial-gradient(" } else { "radial-gradient(" });
                let mut wrote = false;
                match shape {
                    Shape::Ellipse(Some(e), None) if e == "farthest-corner" => {}
                    Shape::Ellipse(None, None) => {}
                    Shape::Ellipse(Some(e), None) => {
                        d.write_str(e);
                        wrote = true;
                    }
                    Shape::Ellipse(_, Some((a, b))) => {
                        a.to_css(d);
                        d.write_char(' ');
                        b.to_css(d);
                        wrote = true;
                    }
                    Shape::Circle(e, l) => {
                        match (e, l) {
                            (_, Some(l)) => l.to_css(d),
                            (Some(e), None) if e == "farthest-corner" => d.write_str("circle"),
                            (None, None) => d.write_str("circle"),
                            (Some(e), None) => {
                                d.write_str("circle ");
                                d.write_str(e);
                            }
                        }
                        wrote = true;
                    }
                }
                if !pos.x.is_center() || !pos.y.is_center() {
                    if wrote {
                        d.write_char(' ');
                    }
                    d.write_str("at ");
                    pos.to_css(d);
                    wrote = true;
                }
                if wrote {
                    d.delim(',', false);
                }
                write_items(d, items);
                d.write_char(')');
            }
            Gradient::Conic { repeating, angle, pos, items } => {
                d.write_str(if *repeating { "repeating-conic-gradient(" } else { "conic-gradient(" });
                let mut wrote = false;
                if let Some(a) = angle {
                    if !a.is_zero() {
                        d.write_str("from ");
                        a.to_css(d);
                        wrote = true;
                    }
                }
                if !pos.x.is_center() || !pos.y.is_center() {
                    if wrote {
                        d.write_char(' ');
                    }
                    d.write_str("at ");
                    pos.to_css(d);
                    wrote = true;
                }
                if wrote {
                    d.delim(',', false);
                }
                write_conic_items(d, items);
                d.write_char(')');
            }
            Gradient::WebkitLegacy(tl) => {
                d.write_str("-webkit-gradient(");
                tl.to_css(d, false);
                d.write_char(')');
            }
        }
    }
}

fn write_conic_items(d: &mut Printer, items: &[Item]) {
    for (i, it) in items.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        let wp = |d: &mut Printer, v: &NumVal| match v {
            NumVal::D(dd) if dd.cat() == Cat::Angle => write_angle(d, dd.v, &dd.unit, false),
            v => v.to_css(d),
        };
        match it {
            Item::Stop(c, p1, p2) => {
                c.to_css(d);
                if let Some(p1) = p1 {
                    d.write_char(' ');
                    wp(d, p1);
                }
                if let Some(p2) = p2 {
                    d.write_char(' ');
                    wp(d, p2);
                }
            }
            Item::Hint(h) => wp(d, h),
        }
    }
}

fn write_line_dir(d: &mut Printer, dir: &LineDir, prefixed: bool) {
    match dir {
        LineDir::Angle(a) => match a {
            NumVal::D(dd) => write_angle(d, dd.v, &dd.unit, false),
            _ => a.to_css(d),
        },
        LineDir::H(s) => {
            if d.minify {
                d.write_str(if s == "left" { "270deg" } else { "90deg" });
            } else {
                if !prefixed {
                    d.write_str("to ");
                }
                d.write_str(s);
            }
        }
        LineDir::V(s) => {
            if d.minify {
                d.write_str(if s == "top" { "0deg" } else { "180deg" });
            } else {
                if !prefixed {
                    d.write_str("to ");
                }
                d.write_str(s);
            }
        }
        LineDir::Corner(h, v) => {
            if !prefixed {
                d.write_str("to ");
            }
            d.write_str(v);
            d.write_char(' ');
            d.write_str(h);
        }
    }
}
