use crate::position::*;
use crate::printer::Printer;
use crate::properties::*;
use crate::pvals::LPA;

#[derive(Clone, Debug, PartialEq)]
pub enum BgSize {
    Explicit(LPA, LPA),
    Cover,
    Contain,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Repeat(pub String, pub String);

#[derive(Clone, Debug, PartialEq)]
pub struct Background {
    pub image: Image,
    pub color: CssColor,
    pub pos: Position,
    pub size: BgSize,
    pub repeat: Repeat,
    pub attachment: String,
    pub origin: String,
    pub clip: String,
}

#[derive(Clone, Debug, PartialEq)]
pub enum BgLonghand {
    Image(Vec<Image>),
    Position(Vec<Position>),
    PosX(Vec<PComp>),
    PosY(Vec<PComp>),
    Size(Vec<BgSize>),
    Repeat(Vec<Repeat>),
    Attachment(Vec<String>),
    Origin(Vec<String>),
    Clip(Vec<String>),
}

const REPEAT_KW: &[&str] = &["repeat", "no-repeat", "space", "round"];
const BOXES: &[&str] = &["border-box", "padding-box", "content-box"];
const CLIPS: &[&str] = &["border-box", "padding-box", "content-box", "text"];

pub fn parse_size(p: &mut Parser) -> PResult<BgSize> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["cover", "contain"])) {
        return Ok(if k == "cover" { BgSize::Cover } else { BgSize::Contain });
    }
    let w = LPA::parse(p, true, true)?;
    let h = p.try_parse(|p| LPA::parse(p, true, true)).unwrap_or(LPA::Auto);
    Ok(BgSize::Explicit(w, h))
}

impl BgSize {
    pub fn is_default(&self) -> bool {
        matches!(self, BgSize::Explicit(LPA::Auto, LPA::Auto))
    }
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            BgSize::Cover => d.write_str("cover"),
            BgSize::Contain => d.write_str("contain"),
            BgSize::Explicit(w, h) => {
                w.to_css(d);
                if *h != LPA::Auto {
                    d.write_char(' ');
                    h.to_css(d);
                }
            }
        }
    }
}

pub fn parse_repeat(p: &mut Parser) -> PResult<Repeat> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["repeat-x", "repeat-y"])) {
        return Ok(if k == "repeat-x" { Repeat("repeat".into(), "no-repeat".into()) } else { Repeat("no-repeat".into(), "repeat".into()) });
    }
    let x = expect_keyword(p, REPEAT_KW)?;
    let y = p.try_parse(|p| expect_keyword(p, REPEAT_KW)).unwrap_or_else(|_| x.clone());
    Ok(Repeat(x, y))
}

impl Repeat {
    pub fn is_default(&self) -> bool {
        self.0 == "repeat" && self.1 == "repeat"
    }
    pub fn to_css(&self, d: &mut Printer) {
        match (self.0.as_str(), self.1.as_str()) {
            ("repeat", "no-repeat") => d.write_str("repeat-x"),
            ("no-repeat", "repeat") => d.write_str("repeat-y"),
            (a, b) if a == b => d.write_str(a),
            (a, b) => {
                d.write_str(a);
                d.write_char(' ');
                d.write_str(b);
            }
        }
    }
}

fn parse_layer(p: &mut Parser) -> PResult<Background> {
    let mut color = None;
    let mut pos = None;
    let mut size = None;
    let mut image = None;
    let mut repeat = None;
    let mut attachment = None;
    let mut origin = None;
    let mut clip = None;
    loop {
        if color.is_none() {
            if let Ok(c) = p.try_parse(CssColor::parse) {
                color = Some(c);
                continue;
            }
        }
        if pos.is_none() {
            if let Ok(ps) = p.try_parse(Position::parse) {
                pos = Some(ps);
                size = p
                    .try_parse(|p| {
                        p.expect_delim('/')?;
                        parse_size(p)
                    })
                    .ok();
                continue;
            }
        }
        if image.is_none() {
            if let Ok(i) = p.try_parse(Image::parse) {
                image = Some(i);
                continue;
            }
        }
        if repeat.is_none() {
            if let Ok(r) = p.try_parse(parse_repeat) {
                repeat = Some(r);
                continue;
            }
        }
        if attachment.is_none() {
            if let Ok(a) = p.try_parse(|p| expect_keyword(p, &["scroll", "fixed", "local"])) {
                attachment = Some(a);
                continue;
            }
        }
        if origin.is_none() {
            if let Ok(o) = p.try_parse(|p| expect_keyword(p, BOXES)) {
                origin = Some(o);
                continue;
            }
        }
        if clip.is_none() {
            if let Ok(c) = p.try_parse(|p| expect_keyword(p, CLIPS)) {
                clip = Some(c);
                continue;
            }
        }
        break;
    }
    if clip.is_none() {
        if let Some(o) = &origin {
            clip = Some(o.clone());
        }
    }
    Ok(Background {
        image: image.unwrap_or(Image::None),
        color: color.unwrap_or_else(CssColor::transparent),
        pos: pos.unwrap_or_else(Position::zero),
        size: size.unwrap_or(BgSize::Explicit(LPA::Auto, LPA::Auto)),
        repeat: repeat.unwrap_or(Repeat("repeat".into(), "repeat".into())),
        attachment: attachment.unwrap_or_else(|| "scroll".into()),
        origin: origin.unwrap_or_else(|| "padding-box".into()),
        clip: clip.unwrap_or_else(|| "border-box".into()),
    })
}

pub fn parse_backgrounds(p: &mut Parser) -> PResult<Vec<Background>> {
    let layers = parse_comma_list(p, parse_layer)?;
    // color only in last layer
    for (i, l) in layers.iter().enumerate() {
        if i + 1 < layers.len() && l.color != CssColor::transparent() {
            return p.invalid();
        }
    }
    Ok(layers)
}

impl Background {
    pub fn to_css(&self, d: &mut Printer) {
        let mut has = false;
        if self.color != CssColor::transparent() {
            self.color.to_css(d);
            has = true;
        }
        if self.image != Image::None {
            if has {
                d.write_char(' ');
            }
            self.image.to_css(d);
            has = true;
        }
        if !self.pos.is_zero() || !self.size.is_default() {
            if has {
                d.write_char(' ');
            }
            self.pos.to_css(d);
            if !self.size.is_default() {
                d.delim('/', true);
                self.size.to_css(d);
            }
            has = true;
        }
        if !self.repeat.is_default() {
            if has {
                d.write_char(' ');
            }
            self.repeat.to_css(d);
            has = true;
        }
        if self.attachment != "scroll" {
            if has {
                d.write_char(' ');
            }
            d.write_str(&self.attachment);
            has = true;
        }
        let output_padding = self.origin != "padding-box" || (self.clip != "border-box" && self.clip != "text");
        if output_padding {
            if has {
                d.write_char(' ');
            }
            d.write_str(&self.origin);
            has = true;
        }
        if (output_padding && self.clip != self.origin) || self.clip != "border-box" {
            if has {
                d.write_char(' ');
            }
            d.write_str(&self.clip);
            has = true;
        }
        if !has {
            if d.minify {
                d.write_str("0 0");
            } else {
                d.write_str("none");
            }
        }
    }
}

pub fn write_backgrounds(d: &mut Printer, b: &[Background]) {
    write_comma_list(d, b, |x, d| x.to_css(d));
}

fn write_pcomp_long(d: &mut Printer, c: &PComp, horiz: bool) {
    match c {
        PComp::Side(s, None) if (horiz && s == "left") || (!horiz && s == "top") => {
            // keep keyword
            d.write_str(s);
        }
        _ => c.to_css(d),
    }
}

impl BgLonghand {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            BgLonghand::Image(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            BgLonghand::Position(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            BgLonghand::PosX(v) => write_comma_list(d, v, |x, d| write_pcomp_long(d, x, true)),
            BgLonghand::PosY(v) => write_comma_list(d, v, |x, d| write_pcomp_long(d, x, false)),
            BgLonghand::Size(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            BgLonghand::Repeat(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            BgLonghand::Attachment(v) | BgLonghand::Origin(v) | BgLonghand::Clip(v) => write_comma_list(d, v, |x, d| d.write_str(x)),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "background" => return Some(parse_backgrounds(p).map(Value::Background)),
        "background-image" => parse_comma_list(p, Image::parse).map(BgLonghand::Image),
        "background-position" => parse_comma_list(p, Position::parse).map(BgLonghand::Position),
        "background-position-x" => parse_comma_list(p, |p| parse_comp(p, true)).map(BgLonghand::PosX),
        "background-position-y" => parse_comma_list(p, |p| parse_comp(p, false)).map(BgLonghand::PosY),
        "background-size" => parse_comma_list(p, parse_size).map(BgLonghand::Size),
        "background-repeat" => parse_comma_list(p, parse_repeat).map(BgLonghand::Repeat),
        "background-attachment" => parse_comma_list(p, |p| expect_keyword(p, &["scroll", "fixed", "local"])).map(BgLonghand::Attachment),
        "background-origin" => parse_comma_list(p, |p| expect_keyword(p, BOXES)).map(BgLonghand::Origin),
        "background-clip" => parse_comma_list(p, |p| expect_keyword(p, CLIPS)).map(BgLonghand::Clip),
        _ => return None,
    };
    Some(r.map(Value::BgLayers))
}

#[derive(Default)]
pub struct BgHandler {
    color: Option<CssColor>,
    images: Option<Vec<Image>>,
    xs: Option<Vec<PComp>>,
    ys: Option<Vec<PComp>>,
    sizes: Option<Vec<BgSize>>,
    repeats: Option<Vec<Repeat>>,
    attachments: Option<Vec<String>>,
    origins: Option<Vec<String>>,
    clips: Option<(Vec<String>, u8)>,
    has_any: bool,
}

fn bp(name: &str, prefix: u8, v: Value) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), v)
}

impl BgHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let color = self.color.take();
        let images = self.images.take();
        let xs = self.xs.take();
        let ys = self.ys.take();
        let sizes = self.sizes.take();
        let repeats = self.repeats.take();
        let attachments = self.attachments.take();
        let origins = self.origins.take();
        let clips = self.clips.take();
        if let (Some(color), Some(images), Some(xs), Some(ys), Some(sizes), Some(repeats), Some(att), Some(ori), Some((clips, cpre))) =
            (&color, &images, &xs, &ys, &sizes, &repeats, &attachments, &origins, &clips)
        {
            let n = images.len();
            if xs.len() == n && ys.len() == n && sizes.len() == n && repeats.len() == n && att.len() == n && ori.len() == n && clips.len() == n && *cpre == crate::prefixes::NONE {
                let mut layers = Vec::new();
                for i in 0..n {
                    layers.push(Background {
                        image: images[i].clone(),
                        color: if i + 1 == n { color.clone() } else { CssColor::transparent() },
                        pos: Position { x: xs[i].clone(), y: ys[i].clone() },
                        size: sizes[i].clone(),
                        repeat: repeats[i].clone(),
                        attachment: att[i].clone(),
                        origin: ori[i].clone(),
                        clip: clips[i].clone(),
                    });
                }
                crate::fallbacks::push_background_with_fallbacks(out, layers);
                return;
            }
        }
        if let Some(c) = color {
            crate::fallbacks::push_color_prop(out, "background-color", c);
        }
        if let Some(i) = images {
            crate::fallbacks::push_bg_images(out, i);
        }
        match (xs, ys) {
            (Some(x), Some(y)) if x.len() == y.len() => {
                let v: Vec<Position> = x.into_iter().zip(y).map(|(x, y)| Position { x, y }).collect();
                out.push(bp("background-position", crate::prefixes::NONE, Value::BgLayers(BgLonghand::Position(v))));
            }
            (x, y) => {
                if let Some(x) = x {
                    out.push(bp("background-position-x", crate::prefixes::NONE, Value::BgLayers(BgLonghand::PosX(x))));
                }
                if let Some(y) = y {
                    out.push(bp("background-position-y", crate::prefixes::NONE, Value::BgLayers(BgLonghand::PosY(y))));
                }
            }
        }
        if let Some(v) = sizes {
            out.push(bp("background-size", crate::prefixes::NONE, Value::BgLayers(BgLonghand::Size(v))));
        }
        if let Some(v) = repeats {
            out.push(bp("background-repeat", crate::prefixes::NONE, Value::BgLayers(BgLonghand::Repeat(v))));
        }
        if let Some(v) = attachments {
            out.push(bp("background-attachment", crate::prefixes::NONE, Value::BgLayers(BgLonghand::Attachment(v))));
        }
        if let Some(v) = origins {
            out.push(bp("background-origin", crate::prefixes::NONE, Value::BgLayers(BgLonghand::Origin(v))));
        }
        if let Some((v, pre)) = clips {
            let pre = crate::prefixer::bg_clip_prefixes(pre, &v);
            out.push(bp("background-clip", pre, Value::BgLayers(BgLonghand::Clip(v))));
        }
    }
}

impl crate::handlers::Handler for BgHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !id.name.starts_with("background") {
            return false;
        }
        match p {
            Property::Val(_, Value::Color(c)) if id.name == "background-color" => {
                self.color = Some(c.clone());
                self.has_any = true;
            }
            Property::Val(_, Value::Background(layers)) => {
                self.color = Some(layers.last().map(|l| l.color.clone()).unwrap_or_else(CssColor::transparent));
                self.images = Some(layers.iter().map(|l| l.image.clone()).collect());
                self.xs = Some(layers.iter().map(|l| l.pos.x.clone()).collect());
                self.ys = Some(layers.iter().map(|l| l.pos.y.clone()).collect());
                self.sizes = Some(layers.iter().map(|l| l.size.clone()).collect());
                self.repeats = Some(layers.iter().map(|l| l.repeat.clone()).collect());
                self.attachments = Some(layers.iter().map(|l| l.attachment.clone()).collect());
                self.origins = Some(layers.iter().map(|l| l.origin.clone()).collect());
                self.clips = Some((layers.iter().map(|l| l.clip.clone()).collect(), crate::prefixes::NONE));
                self.has_any = true;
            }
            Property::Val(id, Value::BgLayers(l)) => {
                self.has_any = true;
                match l {
                    BgLonghand::Image(v) => self.images = Some(v.clone()),
                    BgLonghand::Position(v) => {
                        self.xs = Some(v.iter().map(|p| p.x.clone()).collect());
                        self.ys = Some(v.iter().map(|p| p.y.clone()).collect());
                    }
                    BgLonghand::PosX(v) => self.xs = Some(v.clone()),
                    BgLonghand::PosY(v) => self.ys = Some(v.clone()),
                    BgLonghand::Size(v) => self.sizes = Some(v.clone()),
                    BgLonghand::Repeat(v) => self.repeats = Some(v.clone()),
                    BgLonghand::Attachment(v) => self.attachments = Some(v.clone()),
                    BgLonghand::Origin(v) => self.origins = Some(v.clone()),
                    BgLonghand::Clip(v) => {
                        if let Some((cur, pre)) = &mut self.clips {
                            if cur == v {
                                *pre |= id.prefix;
                                return true;
                            }
                            self.flush(out);
                        }
                        self.clips = Some((v.clone(), id.prefix));
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
