const CLIPS: &[&str] = &["border-box", "padding-box", "content-box", "text"];

pub fn parse_size(p: &mut Parser) -> PResult<BgSize> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["cover", "contain"])) {
        return Ok(if k == "cover" { BgSize::Cover } else { BgSize::Contain });
    }
