}

pub const STYLES: &[&str] = &["none", "hidden", "inset", "groove", "outset", "ridge", "dotted", "dashed", "solid", "double"];

pub fn parse_bwidth(p: &mut Parser) -> PResult<BWidth> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["thin", "medium", "thick"])) {
        return Ok(match k.as_str() {
            "thin" => BWidth::Thin,
            "medium" => BWidth::Medium,
            _ => BWidth::Thick,
        });
    }
    Ok(BWidth::L(parse_length(p)?))
}

impl BWidth {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            BWidth::Thin => d.write_str("thin"),
            BWidth::Medium => d.write_str("medium"),
            BWidth::Thick => d.write_str("thick"),
            BWidth::L(l) => l.to_css(d),
        }
    }
}

pub fn parse_side(p: &mut Parser, outline: bool) -> PResult<BSide> {
    let mut width = None;
    let mut style = None;
    let mut color = None;
    let styles: Vec<&str> = if outline { let mut v = STYLES.to_vec(); v.push("auto"); v } else { STYLES.to_vec() };
    loop {
        if width.is_none() {
            if let Ok(w) = p.try_parse(parse_bwidth) {
                width = Some(w);
                continue;
            }
        }
        if style.is_none() {
            if let Ok(s) = p.try_parse(|p| expect_keyword(p, &styles)) {
                style = Some(s);
                continue;
            }
        }
        if color.is_none() {
            if let Ok(c) = p.try_parse(CssColor::parse) {
                color = Some(c);
                continue;
            }
        }
        break;
    }
    if width.is_none() && style.is_none() && color.is_none() {
        return p.invalid();
    }
    Ok(BSide {
        width: width.unwrap_or(BWidth::Medium),
        style: style.unwrap_or_else(|| "none".into()),
        color: color.unwrap_or(CssColor::CurrentColor),
    })
}

impl BSide {
    pub fn to_css(&self, d: &mut Printer) {
        if self.width == BWidth::Medium && self.style == "none" && self.color == CssColor::CurrentColor {
            d.write_str("none");
            return;
        }
        let mut sp = false;
        if self.width != BWidth::Medium {
            self.width.to_css(d);
            sp = true;
        }
        if self.style != "none" {
            if sp {
                d.write_char(' ');
            }
            d.write_str(&self.style);
            sp = true;
        }
        if self.color != CssColor::CurrentColor {
            if sp {
                d.write_char(' ');
            }
            self.color.to_css(d);
        }
    }
}

fn parse_rect_of<T: Clone, F: Fn(&mut Parser) -> PResult<T>>(p: &mut Parser, f: F) -> PResult<Vec<T>> {
    let a = f(p)?;
    let b = p.try_parse(|p| f(p)).ok();
    let c = if b.is_some() { p.try_parse(|p| f(p)).ok() } else { None };
    let dd = if c.is_some() { p.try_parse(|p| f(p)).ok() } else { None };
    let b2 = b.clone().unwrap_or_else(|| a.clone());
    let c2 = c.unwrap_or_else(|| a.clone());
    let d2 = dd.unwrap_or_else(|| b2.clone());
    Ok(vec![a, b2, c2, d2])
}

fn parse_bival(p: &mut Parser, allow_auto: bool, allow_pct: bool) -> PResult<BIVal> {
    if allow_auto && p.try_ident_matching("auto") {
        return Ok(BIVal::Auto);
    }
    if let Ok(n) = p.try_parse(parse_number) {
        return Ok(BIVal::Num(n));
    }
    Ok(BIVal::L(parse_numval(p, if allow_pct { C_LEN | C_PCT } else { C_LEN }, true)?))
}

impl BIVal {
    fn to_css(&self, d: &mut Printer) {
        match self {
            BIVal::Num(n) => d.write_num(*n),
            BIVal::L(l) => l.to_css(d),
            BIVal::Auto => d.write_str("auto"),
        }
    }
}

fn parse_slice(p: &mut Parser) -> PResult<(Vec<f32>, Vec<bool>, bool)> {
    let mut fill = p.try_ident_matching("fill");
    let one = |p: &mut Parser| -> PResult<(f32, bool)> {
        match parse_numval(p, C_NUM | C_PCT, false)? {
            NumVal::D(d) => Ok((d.v, d.unit == "%")),
            _ => p.invalid(),
        }
    };
    let r = parse_rect_of(p, one)?;
    if !fill {
        fill = p.try_ident_matching("fill");
    }
    Ok((r.iter().map(|x| x.0).collect(), r.iter().map(|x| x.1).collect(), fill))
}

fn write_slice(d: &mut Printer, s: &(Vec<f32>, Vec<bool>, bool)) {
    let items: Vec<(f32, bool)> = s.0.iter().cloned().zip(s.1.iter().cloned()).collect();
    write_rect_generic(d, &items, |x, d| {
        if x.1 {
            d.write_num(x.0 * 100.0);
            d.write_char('%');
        } else {
            d.write_num(x.0);
        }
    });
    if s.2 {
        d.write_str(" fill");
    }
}

fn parse_bi_repeat(p: &mut Parser) -> PResult<(String, String)> {
    let kws = &["stretch", "repeat", "round", "space"];
    let a = expect_keyword(p, kws)?;
    let b = p.try_parse(|p| expect_keyword(p, kws)).unwrap_or_else(|_| a.clone());
    Ok((a, b))
}

fn write_bi_repeat(d: &mut Printer, r: &(String, String)) {
    d.write_str(&r.0);
    if r.1 != r.0 {
        d.write_char(' ');
        d.write_str(&r.1);
    }
}

fn default_slice() -> (Vec<f32>, Vec<bool>, bool) {
    (vec![1.0; 4], vec![true; 4], false)
}

pub fn parse_border_image(p: &mut Parser) -> PResult<BorderImage> {
    let mut source = None;
    let mut slice = None;
    let mut width = None;
    let mut outset = None;
    let mut repeat = None;
    loop {
        if slice.is_none() {
            if let Ok(s) = p.try_parse(parse_slice) {
                slice = Some(s);
                // width / outset
                if p.try_delim('/') {
                    if let Ok(w) = p.try_parse(|p| parse_rect_of(p, |p| parse_bival(p, true, true))) {
                        width = Some(w);
                    }
                    if p.try_delim('/') {
                        outset = Some(parse_rect_of(p, |p| parse_bival(p, false, false))?);
                    } else if width.is_none() {
                        return p.invalid();
                    }
                }
                continue;
            }
        }
        if source.is_none() {
            if let Ok(i) = p.try_parse(Image::parse) {
                source = Some(i);
                continue;
            }
        }
        if repeat.is_none() {
            if let Ok(r) = p.try_parse(parse_bi_repeat) {
                repeat = Some(r);
                continue;
            }
        }
        break;
    }
    if source.is_none() && slice.is_none() && repeat.is_none() {
        return p.invalid();
    }
    Ok(BorderImage {
        source: source.unwrap_or(Image::None),
        slice: slice.unwrap_or_else(default_slice),
        width: width.unwrap_or_else(|| vec![BIVal::Num(1.0); 4]),
        outset: outset.unwrap_or_else(|| vec![BIVal::Num(0.0); 4]),
        repeat: repeat.unwrap_or(("stretch".into(), "stretch".into())),
    })
}

fn is_default_outset(v: &[BIVal]) -> bool {
    v.iter().all(|x| matches!(x, BIVal::Num(n) if *n == 0.0) || matches!(x, BIVal::L(l) if l.is_zero()))
}

impl BorderImage {
    pub fn to_css(&self, d: &mut Printer) {
        let mut sp = false;
        if self.source != Image::None {
            self.source.to_css(d);
            sp = true;
        }
        let has_slice = self.slice != default_slice();
        let has_width = self.width != vec![BIVal::Num(1.0); 4];
        let has_outset = !is_default_outset(&self.outset);
        if has_slice || has_width || has_outset {
            if sp {
                d.write_char(' ');
            }
            write_slice(d, &self.slice);
            if has_width || has_outset {
                d.delim('/', true);
            }
            if has_width {
                write_rect_generic(d, &self.width, |x, d| x.to_css(d));
            }
            if has_outset {
                d.delim('/', true);
                write_rect_generic(d, &self.outset, |x, d| x.to_css(d));
            }
            sp = true;
        }
        if self.repeat != ("stretch".to_string(), "stretch".to_string()) {
            if sp {
                d.write_char(' ');
            }
            write_bi_repeat(d, &self.repeat);
        }
    }
}

fn parse_radius_pair(p: &mut Parser) -> PResult<(NumVal, NumVal)> {
    let a = parse_length_percentage(p)?;
    let b = p.try_parse(parse_length_percentage).unwrap_or_else(|_| a.clone());
    Ok((a, b))
}

fn parse_radii(p: &mut Parser) -> PResult<Vec<(NumVal, NumVal)>> {
    let h = parse_rect_of(p, parse_length_percentage)?;
    let v = if p.try_delim('/') { parse_rect_of(p, parse_length_percentage)? } else { h.clone() };
    Ok(h.into_iter().zip(v).collect())
}

fn write_radii(d: &mut Printer, r: &[(NumVal, NumVal)]) {
    let h: Vec<NumVal> = r.iter().map(|x| x.0.clone()).collect();
    let v: Vec<NumVal> = r.iter().map(|x| x.1.clone()).collect();
    write_rect_generic(d, &h, |x, d| x.to_css(d));
    if h != v {
        d.delim('/', true);
        write_rect_generic(d, &v, |x, d| x.to_css(d));
    }
}

impl BorderValue {
    pub fn to_css(&self, d: &mut Printer, _id: &PropId, _prefix: u8) {
        match self {
            BorderValue::Width(w) => w.to_css(d),
            BorderValue::Style(s) => d.write_str(s),
            BorderValue::Side(s) => s.to_css(d),
            BorderValue::Widths(v) => write_rect_generic(d, v, |x, d| x.to_css(d)),
            BorderValue::Styles(v) => write_rect_generic(d, v, |x, d| d.write_str(x)),
            BorderValue::Colors(v) => write_rect_generic(d, v, |x, d| x.to_css(d)),
            BorderValue::Radius(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
            BorderValue::Radii(r) => write_radii(d, r),
            BorderValue::Image(i) => i.to_css(d),
            BorderValue::ImageSource(i) => i.to_css(d),
            BorderValue::ImageSlice(s) => write_slice(d, s),
            BorderValue::ImageWidth(v) | BorderValue::ImageOutset(v) => write_rect_generic(d, v, |x, d| x.to_css(d)),
            BorderValue::ImageRepeat(r) => write_bi_repeat(d, r),
            BorderValue::Spacing(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
            BorderValue::PairWidths(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
            BorderValue::PairStyles(a, b) => {
                d.write_str(a);
                if a != b {
                    d.write_char(' ');
                    d.write_str(b);
                }
            }
            BorderValue::PairColors(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
        }
    }
}

const SIDES: &[&str] = &["top", "bottom", "left", "right", "block-start", "block-end", "inline-start", "inline-end"];

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "border" | "border-top" | "border-bottom" | "border-left" | "border-right" | "border-block" | "border-inline"
        | "border-block-start" | "border-block-end" | "border-inline-start" | "border-inline-end" => parse_side(p, false).map(BorderValue::Side),
        "outline" => parse_side(p, true).map(BorderValue::Side),
        "outline-width" => parse_bwidth(p).map(BorderValue::Width),
        "outline-style" => {
            let mut v = STYLES.to_vec();
            v.push("auto");
            expect_keyword(p, &v).map(BorderValue::Style)
        }
        "outline-color" => return None,
        "border-width" => parse_rect_of(p, parse_bwidth).map(BorderValue::Widths),
        "border-style" => parse_rect_of(p, |p| expect_keyword(p, STYLES)).map(BorderValue::Styles),
        "border-color" => parse_rect_of(p, CssColor::parse).map(BorderValue::Colors),
        "border-block-width" | "border-inline-width" => parse_bwidth(p).and_then(|a| {
            let b = p.try_parse(parse_bwidth).unwrap_or_else(|_| a.clone());
            Ok(BorderValue::PairWidths(a, b))
        }),
        "border-block-style" | "border-inline-style" => expect_keyword(p, STYLES).and_then(|a| {
            let b = p.try_parse(|p| expect_keyword(p, STYLES)).unwrap_or_else(|_| a.clone());
            Ok(BorderValue::PairStyles(a, b))
        }),
        "border-block-color" | "border-inline-color" => CssColor::parse(p).and_then(|a| {
            let b = p.try_parse(CssColor::parse).unwrap_or_else(|_| a.clone());
            Ok(BorderValue::PairColors(a, b))
        }),
        "border-radius" => parse_radii(p).map(BorderValue::Radii),
        "border-top-left-radius" | "border-top-right-radius" | "border-bottom-left-radius" | "border-bottom-right-radius"
        | "border-start-start-radius" | "border-start-end-radius" | "border-end-start-radius" | "border-end-end-radius" => {
            parse_radius_pair(p).map(|(a, b)| BorderValue::Radius(a, b))
        }
        "border-image" => parse_border_image(p).map(BorderValue::Image),
        "border-image-source" => Image::parse(p).map(BorderValue::ImageSource),
        "border-image-slice" => parse_slice(p).map(BorderValue::ImageSlice),
        "border-image-width" => parse_rect_of(p, |p| parse_bival(p, true, true)).map(BorderValue::ImageWidth),
        "border-image-outset" => parse_rect_of(p, |p| parse_bival(p, false, false)).map(BorderValue::ImageOutset),
        "border-image-repeat" => parse_bi_repeat(p).map(BorderValue::ImageRepeat),
        "border-spacing" => parse_length(p).and_then(|a| {
            let b = p.try_parse(parse_length).unwrap_or_else(|_| a.clone());
            Ok(BorderValue::Spacing(a, b))
        }),
        _ => {
            if let Some(rest) = n.strip_prefix("border-") {
                for s in SIDES {
                    if let Some(k) = rest.strip_prefix(s) {
                        match k {
                            "-width" => return Some(parse_bwidth(p).map(|w| Value::Border(BorderValue::Width(w)))),
                            "-style" => return Some(expect_keyword(p, STYLES).map(|w| Value::Border(BorderValue::Style(w)))),
                            _ => {}
                        }
                    }
                }
            }
            return None;
        }
    };
    let _ = parse_comma_list::<i32, fn(&mut Parser) -> PResult<i32>>;
    Some(r.map(Value::Border))
}

// ---------------- handler ----------------

#[derive(Clone, Default, PartialEq)]
struct SideState {
    width: Option<BWidth>,
    style: Option<String>,
    color: Option<CssColor>,
}

impl SideState {
    fn complete(&self) -> Option<BSide> {
        Some(BSide { width: self.width.clone()?, style: self.style.clone()?, color: self.color.clone()? })
    }
    fn is_empty(&self) -> bool {
        self.width.is_none() && self.style.is_none() && self.color.is_none()
    }
}

#[derive(Default)]
pub struct BorderHandler {
    sides: [SideState; 8],
    has_any: bool,
    logical: bool,
    radius: [Option<((NumVal, NumVal), u8)>; 4],
    lradius: [Option<(NumVal, NumVal)>; 4],
    has_radius: bool,
    image: Option<(BorderImage, u8)>,
    image_parts: (Option<Image>, Option<(Vec<f32>, Vec<bool>, bool)>, Option<Vec<BIVal>>, Option<Vec<BIVal>>, Option<(String, String)>),
    has_image: bool,
}

fn bp(name: &str, prefix: u8, v: BorderValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Border(v))
}
fn cp(name: &str, c: CssColor) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Color(c))
}

fn most_common<T: PartialEq + Clone>(v: [&T; 4]) -> T {
    let mut best = v[0];
    let mut best_n = 0;
    for x in v.iter() {
        let n = v.iter().filter(|y| **y == *x).count();
        if n > best_n {
            best_n = n;
            best = x;
        }
    }
    best.clone()
}

impl BorderHandler {
    fn side_names(i: usize) -> &'static str {
        SIDES[i]
    }

    fn side_diff(out: &mut Vec<Property>, base: &BSide, other: &BSide, side: &str) {
        let ew = base.width == other.width;
        let es = base.style == other.style;
        let ec = base.color == other.color;
        if ew && es {
            out.push(cp(&format!("border-{}-color", side), other.color.clone()));
        } else if ew && ec {
            out.push(bp(&format!("border-{}-style", side), crate::prefixes::NONE, BorderValue::Style(other.style.clone())));
        } else if es && ec {
            out.push(bp(&format!("border-{}-width", side), crate::prefixes::NONE, BorderValue::Width(other.width.clone())));
        } else {
            out.push(bp(&format!("border-{}", side), crate::prefixes::NONE, BorderValue::Side(other.clone())));
        }
    }

    fn flush_sides(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let sides = std::mem::take(&mut self.sides);
        // physical
        let (t, b, l, r) = (&sides[0], &sides[1], &sides[2], &sides[3]);
        if let (Some(t), Some(b), Some(l), Some(r)) = (t.complete(), b.complete(), l.complete(), r.complete()) {
            let none = crate::prefixes::NONE;
            if t == b && b == l && l == r {
                out.push(bp("border", none, BorderValue::Side(t)));
            } else if t == b && t == l {
                out.push(bp("border", none, BorderValue::Side(t.clone())));
                Self::side_diff(out, &t, &r, "right");
            } else if t == b && t == r {
                out.push(bp("border", none, BorderValue::Side(t.clone())));
                Self::side_diff(out, &t, &l, "left");
            } else if l == r && b == l {
                out.push(bp("border", none, BorderValue::Side(l.clone())));
                Self::side_diff(out, &l, &t, "top");
            } else if l == r && t == l {
                out.push(bp("border", none, BorderValue::Side(l.clone())));
                Self::side_diff(out, &l, &b, "bottom");
            } else {
                let ws = t.width == b.width && b.width == l.width && l.width == r.width;
                let ss = t.style == b.style && b.style == l.style && l.style == r.style;
                let cs = t.color == b.color && b.color == l.color && l.color == r.color;
                if ws && ss {
                    let c = most_common([&t.color, &r.color, &b.color, &l.color]);
                    out.push(bp("border", none, BorderValue::Side(BSide { width: t.width.clone(), style: t.style.clone(), color: c })));
                    out.push(bp("border-color", none, BorderValue::Colors(vec![t.color, r.color, b.color, l.color])));
                } else if ws && cs {
                    let s = most_common([&t.style, &r.style, &b.style, &l.style]);
                    out.push(bp("border", none, BorderValue::Side(BSide { width: t.width.clone(), style: s, color: t.color.clone() })));
                    out.push(bp("border-style", none, BorderValue::Styles(vec![t.style, r.style, b.style, l.style])));
                } else if ss && cs {
                    let w = most_common([&t.width, &r.width, &b.width, &l.width]);
                    out.push(bp("border", none, BorderValue::Side(BSide { width: w, style: t.style.clone(), color: t.color.clone() })));
                    out.push(bp("border-width", none, BorderValue::Widths(vec![t.width, r.width, b.width, l.width])));
                } else if t == b && l == r {
                    out.push(bp("border", none, BorderValue::Side(t.clone())));
                    Self::side_diff(out, &t, &l, "left");
                    Self::side_diff(out, &t, &r, "right");
                } else {
                    out.push(bp("border-top", none, BorderValue::Side(t)));
                    out.push(bp("border-bottom", none, BorderValue::Side(b)));
                    out.push(bp("border-left", none, BorderValue::Side(l)));
                    out.push(bp("border-right", none, BorderValue::Side(r)));
                }
            }
        } else {
            let none = crate::prefixes::NONE;
            let mut used_w = false;
            let mut used_s = false;
            let mut used_c = false;
            if let (Some(a), Some(bb), Some(c), Some(dd)) = (&t.style, &b.style, &l.style, &r.style) {
                out.push(bp("border-style", none, BorderValue::Styles(vec![a.clone(), dd.clone(), bb.clone(), c.clone()])));
                used_s = true;
            }
            if let (Some(a), Some(bb), Some(c), Some(dd)) = (&t.width, &b.width, &l.width, &r.width) {
                out.push(bp("border-width", none, BorderValue::Widths(vec![a.clone(), dd.clone(), bb.clone(), c.clone()])));
                used_w = true;
            }
            if let (Some(a), Some(bb), Some(c), Some(dd)) = (&t.color, &b.color, &l.color, &r.color) {
                out.push(bp("border-color", none, BorderValue::Colors(vec![a.clone(), dd.clone(), bb.clone(), c.clone()])));
                used_c = true;
            }
            for i in 0..4 {
                let s = &sides[i];
                let name = Self::side_names(i);
                if !used_w && !used_s && !used_c {
                    if let Some(full) = s.complete() {
                        out.push(bp(&format!("border-{}", name), none, BorderValue::Side(full)));
                        continue;
                    }
                }
                if !used_s {
                    if let Some(x) = &s.style {
                        out.push(bp(&format!("border-{}-style", name), none, BorderValue::Style(x.clone())));
                    }
                }
                if !used_w {
                    if let Some(x) = &s.width {
                        out.push(bp(&format!("border-{}-width", name), none, BorderValue::Width(x.clone())));
                    }
                }
                if !used_c {
                    if let Some(x) = &s.color {
                        out.push(cp(&format!("border-{}-color", name), x.clone()));
                    }
                }
            }
        }
        // logical
        for (si, ei, axis) in [(4usize, 5usize, "block"), (6, 7, "inline")] {
            let (s, e) = (&sides[si], &sides[ei]);
            if s.is_empty() && e.is_empty() {
                continue;
            }
            let none = crate::prefixes::NONE;
            if let (Some(a), Some(bb)) = (s.complete(), e.complete()) {
                if a == bb {
                    out.push(bp(&format!("border-{}", axis), none, BorderValue::Side(a)));
                    continue;
                }
                out.push(bp(&format!("border-{}-start", axis), none, BorderValue::Side(a)));
                out.push(bp(&format!("border-{}-end", axis), none, BorderValue::Side(bb)));
                continue;
            }
            let mut used_w = false;
            let mut used_s = false;
            let mut used_c = false;
            if let (Some(a), Some(bb)) = (&s.style, &e.style) {
                out.push(bp(&format!("border-{}-style", axis), none, BorderValue::PairStyles(a.clone(), bb.clone())));
                used_s = true;
            }
            if let (Some(a), Some(bb)) = (&s.width, &e.width) {
                out.push(bp(&format!("border-{}-width", axis), none, BorderValue::PairWidths(a.clone(), bb.clone())));
                used_w = true;
            }
            if let (Some(a), Some(bb)) = (&s.color, &e.color) {
                out.push(bp(&format!("border-{}-color", axis), none, BorderValue::PairColors(a.clone(), bb.clone())));
                used_c = true;
            }
            for i in [si, ei] {
                let st = &sides[i];
                let name = Self::side_names(i);
                if !used_w && !used_s && !used_c {
                    if let Some(full) = st.complete() {
                        out.push(bp(&format!("border-{}", name), none, BorderValue::Side(full)));
                        continue;
                    }
                }
                if !used_s {
                    if let Some(x) = &st.style {
                        out.push(bp(&format!("border-{}-style", name), none, BorderValue::Style(x.clone())));
                    }
                }
                if !used_w {
                    if let Some(x) = &st.width {
                        out.push(bp(&format!("border-{}-width", name), none, BorderValue::Width(x.clone())));
                    }
                }
                if !used_c {
                    if let Some(x) = &st.color {
                        out.push(cp(&format!("border-{}-color", name), x.clone()));
                    }
                }
            }
        }
    }

    fn flush_image(&mut self, out: &mut Vec<Property>) {
        if !self.has_image {
            return;
        }
        self.has_image = false;
        let parts = std::mem::take(&mut self.image_parts);
        if let Some((img, pre)) = self.image.take() {
            out.push(bp("border-image", crate::prefixer::border_image_prefixes(pre), BorderValue::Image(img)));
            return;
        }
        let none = crate::prefixes::NONE;
        if let (Some(src), Some(slice), Some(width), Some(outset), Some(rep)) = (&parts.0, &parts.1, &parts.2, &parts.3, &parts.4) {
            out.push(bp(
                "border-image",
                crate::prefixer::border_image_prefixes(none),
                BorderValue::Image(BorderImage { source: src.clone(), slice: slice.clone(), width: width.clone(), outset: outset.clone(), repeat: rep.clone() }),
            ));
            return;
        }
        if let Some(x) = parts.0 {
            out.push(bp("border-image-source", none, BorderValue::ImageSource(x)));
        }
        if let Some(x) = parts.1 {
            out.push(bp("border-image-slice", none, BorderValue::ImageSlice(x)));
        }
        if let Some(x) = parts.2 {
            out.push(bp("border-image-width", none, BorderValue::ImageWidth(x)));
        }
        if let Some(x) = parts.3 {
            out.push(bp("border-image-outset", none, BorderValue::ImageOutset(x)));
        }
        if let Some(x) = parts.4 {
            out.push(bp("border-image-repeat", none, BorderValue::ImageRepeat(x)));
        }
    }

    fn flush_radius(&mut self, out: &mut Vec<Property>) {
        if !self.has_radius {
            return;
        }
        self.has_radius = false;
        let r = std::mem::take(&mut self.radius);
        let lr = std::mem::take(&mut self.lradius);
        // order: top-left, top-right, bottom-right, bottom-left
        if let (Some(a), Some(b), Some(c), Some(dd)) = (&r[0], &r[1], &r[2], &r[3]) {
            if a.1 == b.1 && b.1 == c.1 && c.1 == dd.1 {
                out.push(bp(
                    "border-radius",
                    crate::prefixer::radius_prefixes(a.1),
                    BorderValue::Radii(vec![a.0.clone(), b.0.clone(), c.0.clone(), dd.0.clone()]),
                ));
            } else {
                for (i, n) in ["top-left", "top-right", "bottom-right", "bottom-left"].iter().enumerate() {
                    let x = r[i].clone().unwrap();
                    out.push(bp(&format!("border-{}-radius", n), x.1, BorderValue::Radius(x.0 .0, x.0 .1)));
                }
            }
        } else {
            for (i, n) in ["top-left", "top-right", "bottom-right", "bottom-left"].iter().enumerate() {
                if let Some(x) = r[i].clone() {
                    out.push(bp(&format!("border-{}-radius", n), crate::prefixer::radius_prefixes(x.1), BorderValue::Radius(x.0 .0, x.0 .1)));
                }
            }
        }
        for (i, n) in ["start-start", "start-end", "end-end", "end-start"].iter().enumerate() {
            if let Some(x) = lr[i].clone() {
                out.push(bp(&format!("border-{}-radius", n), crate::prefixes::NONE, BorderValue::Radius(x.0, x.1)));
            }
        }
    }

    fn flush(&mut self, out: &mut Vec<Property>) {
        self.flush_sides(out);
        self.flush_image(out);
        self.flush_radius(out);
    }

    fn set_side(&mut self, i: usize, w: Option<BWidth>, s: Option<String>, c: Option<CssColor>, out: &mut Vec<Property>) {
        let logical = i >= 4;
        if self.has_any && logical != self.logical {
            self.flush_sides(out);
        }
        self.logical = logical;
        self.has_any = true;
        if let Some(w) = w {
            self.sides[i].width = Some(w);
        }
        if let Some(s) = s {
            self.sides[i].style = Some(s);
        }
        if let Some(c) = c {
            self.sides[i].color = Some(c);
        }
    }
}

fn side_index(s: &str) -> Option<usize> {
    SIDES.iter().position(|x| *x == s)
}

impl crate::handlers::Handler for BorderHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        let n = id.name.as_str();
        if !n.starts_with("border") || n == "border-spacing" || n == "border-collapse" {
            return false;
        }
        let val = match p {
            Property::Val(_, v) => v,
            _ => {
                self.flush(out);
                out.push(p.clone());
                return true;
            }
        };
        let rest = &n[6..]; // after "border"
        match (rest, val) {
            ("", Value::Border(BorderValue::Side(s))) => {
                for i in 0..4 {
                    self.set_side(i, Some(s.width.clone()), Some(s.style.clone()), Some(s.color.clone()), out);
                }
                // border shorthand resets border-image
                self.image = None;
                self.image_parts = Default::default();
                self.has_image = false;
            }
            ("-width", Value::Border(BorderValue::Widths(v))) => {
                for (i, k) in [0usize, 3, 1, 2].iter().enumerate() {
                    self.set_side(*k, Some(v[i].clone()), None, None, out);
                }
            }
            ("-style", Value::Border(BorderValue::Styles(v))) => {
                for (i, k) in [0usize, 3, 1, 2].iter().enumerate() {
                    self.set_side(*k, None, Some(v[i].clone()), None, out);
                }
            }
            ("-color", Value::Border(BorderValue::Colors(v))) => {
                for (i, k) in [0usize, 3, 1, 2].iter().enumerate() {
                    self.set_side(*k, None, None, Some(v[i].clone()), out);
                }
            }
            ("-block", Value::Border(BorderValue::Side(s))) | ("-inline", Value::Border(BorderValue::Side(s))) => {
                let base = if rest == "-block" { 4 } else { 6 };
                for i in [base, base + 1] {
                    self.set_side(i, Some(s.width.clone()), Some(s.style.clone()), Some(s.color.clone()), out);
                }
            }
            ("-block-width", Value::Border(BorderValue::PairWidths(a, b))) | ("-inline-width", Value::Border(BorderValue::PairWidths(a, b))) => {
                let base = if rest.starts_with("-block") { 4 } else { 6 };
                self.set_side(base, Some(a.clone()), None, None, out);
                self.set_side(base + 1, Some(b.clone()), None, None, out);
            }
            ("-block-style", Value::Border(BorderValue::PairStyles(a, b))) | ("-inline-style", Value::Border(BorderValue::PairStyles(a, b))) => {
                let base = if rest.starts_with("-block") { 4 } else { 6 };
                self.set_side(base, None, Some(a.clone()), None, out);
                self.set_side(base + 1, None, Some(b.clone()), None, out);
            }
            ("-block-color", Value::Border(BorderValue::PairColors(a, b))) | ("-inline-color", Value::Border(BorderValue::PairColors(a, b))) => {
                let base = if rest.starts_with("-block") { 4 } else { 6 };
                self.set_side(base, None, None, Some(a.clone()), out);
                self.set_side(base + 1, None, None, Some(b.clone()), out);
            }
            ("-radius", Value::Border(BorderValue::Radii(r))) => {
                let pre = id.prefix;
                // merge prefix if same value
                let same = self.radius.iter().enumerate().all(|(i, x)| matches!(x, Some((v, _)) if *v == r[i]));
                if same {
                    for x in self.radius.iter_mut() {
                        if let Some((_, p0)) = x {
                            *p0 |= pre;
                        }
                    }
                } else {
                    if self.radius.iter().any(|x| matches!(x, Some((_, p0)) if *p0 != pre)) {
                        self.flush_radius(out);
                    }
                    for i in 0..4 {
                        self.radius[i] = Some((r[i].clone(), pre));
                    }
                }
                self.has_radius = true;
            }
            ("-image", Value::Border(BorderValue::Image(img))) => {
                if let Some((cur, pre)) = &mut self.image {
                    if cur == img {
                        *pre |= id.prefix;
                        return true;
                    }
                }
                self.flush_image(out);
                self.image = Some((img.clone(), id.prefix));
                self.has_image = true;
            }
            ("-image-source", Value::Border(BorderValue::ImageSource(x))) => {
                self.image_from_parts();
                self.image_parts.0 = Some(x.clone());
                self.has_image = true;
            }
            ("-image-slice", Value::Border(BorderValue::ImageSlice(x))) => {
                self.image_from_parts();
                self.image_parts.1 = Some(x.clone());
                self.has_image = true;
            }
            ("-image-width", Value::Border(BorderValue::ImageWidth(x))) => {
                self.image_from_parts();
                self.image_parts.2 = Some(x.clone());
                self.has_image = true;
            }
            ("-image-outset", Value::Border(BorderValue::ImageOutset(x))) => {
                self.image_from_parts();
                self.image_parts.3 = Some(x.clone());
                self.has_image = true;
            }
            ("-image-repeat", Value::Border(BorderValue::ImageRepeat(x))) => {
                self.image_from_parts();
                self.image_parts.4 = Some(x.clone());
                self.has_image = true;
            }
            (r, v) => {
                // side-specific
                let r = &r[1..];
                for (i, s) in SIDES.iter().enumerate() {
                    if r == *s {
                        if let Value::Border(BorderValue::Side(x)) = v {
                            self.set_side(i, Some(x.width.clone()), Some(x.style.clone()), Some(x.color.clone()), out);
                            return true;
                        }
                    } else if let Some(k) = r.strip_prefix(s) {
                        match (k, v) {
                            ("-width", Value::Border(BorderValue::Width(w))) => {
                                self.set_side(i, Some(w.clone()), None, None, out);
                                return true;
                            }
                            ("-style", Value::Border(BorderValue::Style(w))) => {
                                self.set_side(i, None, Some(w.clone()), None, out);
                                return true;
                            }
                            ("-color", Value::Color(c)) => {
                                self.set_side(i, None, None, Some(c.clone()), out);
                                return true;
                            }
                            _ => {}
                        }
                    }
                }
                // radius corners
                for (i, c) in ["top-left", "top-right", "bottom-right", "bottom-left"].iter().enumerate() {
                    if r == format!("{}-radius", c) {
                        if let Value::Border(BorderValue::Radius(a, b)) = v {
                            let pre = id.prefix;
                            if let Some((cur, p0)) = &self.radius[i] {
                                if *p0 != pre && *cur != (a.clone(), b.clone()) {
                                    self.flush_radius(out);
                                }
                            }
                            let pre2 = match &self.radius[i] {
                                Some((cur, p0)) if *cur == (a.clone(), b.clone()) => *p0 | pre,
                                _ => pre,
                            };
                            self.radius[i] = Some(((a.clone(), b.clone()), pre2));
                            self.has_radius = true;
                            return true;
                        }
                    }
                }
                for (i, c) in ["start-start", "start-end", "end-end", "end-start"].iter().enumerate() {
                    if r == format!("{}-radius", c) {
                        if let Value::Border(BorderValue::Radius(a, b)) = v {
                            self.lradius[i] = Some((a.clone(), b.clone()));
                            self.has_radius = true;
                            return true;
                        }
                    }
                }
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}

impl BorderHandler {
    fn image_from_parts(&mut self) {
        if let Some((img, _)) = self.image.take() {
            self.image_parts = (Some(img.source), Some(img.slice), Some(img.width), Some(img.outset), Some(img.repeat));
        }
    }
}

#[derive(Default)]
pub struct OutlineHandler {
    width: Option<BWidth>,
    style: Option<String>,
    color: Option<CssColor>,
    has_any: bool,
}

impl OutlineHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (w, s, c) = (self.width.take(), self.style.take(), self.color.take());
        if let (Some(w), Some(s), Some(c)) = (&w, &s, &c) {
            out.push(bp("outline", crate::prefixes::NONE, BorderValue::Side(BSide { width: w.clone(), style: s.clone(), color: c.clone() })));
            return;
        }
        if let Some(w) = w {
            out.push(bp("outline-width", crate::prefixes::NONE, BorderValue::Width(w)));
        }
        if let Some(s) = s {
            out.push(bp("outline-style", crate::prefixes::NONE, BorderValue::Style(s)));
        }
        if let Some(c) = c {
            out.push(cp("outline-color", c));
        }
    }
}

impl crate::handlers::Handler for OutlineHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !id.name.starts_with("outline") || id.name == "outline-offset" {
            return false;
        }
        match p {
            Property::Val(_, Value::Border(BorderValue::Side(s))) => {
                self.width = Some(s.width.clone());
                self.style = Some(s.style.clone());
                self.color = Some(s.color.clone());
                self.has_any = true;
            }
            Property::Val(_, Value::Border(BorderValue::Width(w))) => {
                self.width = Some(w.clone());
                self.has_any = true;
            }
            Property::Val(_, Value::Border(BorderValue::Style(s))) => {
                self.style = Some(s.clone());
                self.has_any = true;
            }
            Property::Val(_, Value::Color(c)) => {
                self.color = Some(c.clone());
                self.has_any = true;
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
