#[derive(Clone, Debug, PartialEq)]
pub enum TF {
    Translate(NumVal, NumVal),
    TranslateX(NumVal),
    TranslateY(NumVal),
    TranslateZ(NumVal),
    Translate3d(NumVal, NumVal, NumVal),
