    Translate(Option<(NumVal, NumVal, NumVal)>),
    Rotate(Option<(f32, f32, f32, NumVal)>),
    Scale(Option<(f32, f32, f32)>),
}

fn lp(p: &mut Parser) -> PResult<NumVal> {
    parse_length_percentage(p)
}
fn len(p: &mut Parser) -> PResult<NumVal> {
    parse_length(p)
}
fn ang(p: &mut Parser) -> PResult<NumVal> {
    parse_angle(p, true)
}
fn num_or_pct(p: &mut Parser) -> PResult<f32> {
    parse_number_or_percentage(p)
}

fn parse_tf(p: &mut Parser) -> PResult<TF> {
    let loc = p.location();
    let f = p.expect_function()?.to_ascii_lowercase();
    p.parse_nested_block(|p| {
        Ok(match f.as_str() {
            "translate" => {
                let x = lp(p)?;
                if p.try_comma() {
                    TF::Translate(x, lp(p)?)
                } else {
                    TF::Translate(x, NumVal::zero_px())
                }
            }
            "translatex" => TF::TranslateX(lp(p)?),
            "translatey" => TF::TranslateY(lp(p)?),
            "translatez" => TF::TranslateZ(len(p)?),
            "translate3d" => {
                let x = lp(p)?;
                p.expect_comma()?;
                let y = lp(p)?;
                p.expect_comma()?;
                let z = len(p)?;
                TF::Translate3d(x, y, z)
            }
            "scale" => {
                let x = num_or_pct(p)?;
                if p.try_comma() {
                    TF::Scale(x, num_or_pct(p)?)
                } else {
                    TF::Scale(x, x)
                }
            }
            "scalex" => TF::ScaleX(num_or_pct(p)?),
            "scaley" => TF::ScaleY(num_or_pct(p)?),
            "scalez" => TF::ScaleZ(num_or_pct(p)?),
            "scale3d" => {
                let x = num_or_pct(p)?;
                p.expect_comma()?;
                let y = num_or_pct(p)?;
                p.expect_comma()?;
                let z = num_or_pct(p)?;
                TF::Scale3d(x, y, z)
            }
            "rotate" => TF::Rotate(ang(p)?),
            "rotatex" => TF::RotateX(ang(p)?),
            "rotatey" => TF::RotateY(ang(p)?),
            "rotatez" => TF::RotateZ(ang(p)?),
            "rotate3d" => {
                let x = parse_number(p)?;
                p.expect_comma()?;
                let y = parse_number(p)?;
                p.expect_comma()?;
                let z = parse_number(p)?;
                p.expect_comma()?;
                let a = ang(p)?;
                TF::Rotate3d(x, y, z, a)
            }
            "skew" => {
                let x = ang(p)?;
                if p.try_comma() {
                    TF::Skew(x, ang(p)?)
                } else {
                    TF::Skew(x, NumVal::D(Dim::new(0.0, "deg")))
                }
            }
            "skewx" => TF::SkewX(ang(p)?),
            "skewy" => TF::SkewY(ang(p)?),
            "perspective" => TF::Perspective(len(p)?),
            "matrix" => {
                let mut v = vec![parse_number(p)?];
                for _ in 0..5 {
                    p.expect_comma()?;
                    v.push(parse_number(p)?);
                }
                TF::Matrix(v)
            }
            "matrix3d" => {
                let mut v = vec![parse_number(p)?];
                for _ in 0..15 {
                    p.expect_comma()?;
                    v.push(parse_number(p)?);
                }
                TF::Matrix3d(v)
            }
            _ => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f.clone())), loc)),
        })
    })
}

fn wa(d: &mut Printer, a: &NumVal, unitless_zero: bool) {
    match a {
        NumVal::D(dd) => write_angle(d, dd.v, &dd.unit, unitless_zero),
        _ => a.to_css(d),
    }
}

fn args(d: &mut Printer, name: &str, f: impl FnOnce(&mut Printer)) {
    d.write_str(name);
    d.write_char('(');
    f(d);
    d.write_char(')');
}

impl TF {
    pub fn to_css(&self, d: &mut Printer) {
        let m = d.minify;
        match self {
            TF::Translate(x, y) => {
                if m && x.is_zero() && !y.is_zero() {
                    args(d, "translateY", |d| y.to_css(d));
                } else if y.is_zero() {
                    args(d, "translate", |d| x.to_css(d));
                } else {
                    args(d, "translate", |d| {
                        x.to_css(d);
                        d.delim(',', false);
                        y.to_css(d);
                    });
                }
            }
            TF::TranslateX(x) => args(d, if m { "translate" } else { "translateX" }, |d| x.to_css(d)),
            TF::TranslateY(y) => args(d, "translateY", |d| y.to_css(d)),
            TF::TranslateZ(z) => args(d, "translateZ", |d| z.to_css(d)),
            TF::Translate3d(x, y, z) => {
                if m && z.is_zero() {
                    TF::Translate(x.clone(), y.clone()).to_css(d);
                } else if m && x.is_zero() && y.is_zero() {
                    args(d, "translateZ", |d| z.to_css(d));
                } else {
                    args(d, "translate3d", |d| {
                        x.to_css(d);
                        d.delim(',', false);
                        y.to_css(d);
                        d.delim(',', false);
                        z.to_css(d);
                    });
                }
            }
            TF::Scale(x, y) => {
                if x == y {
                    args(d, "scale", |d| d.write_num(*x));
                } else if m && *y == 1.0 {
                    args(d, "scaleX", |d| d.write_num(*x));
                } else if m && *x == 1.0 {
                    args(d, "scaleY", |d| d.write_num(*y));
                } else {
                    args(d, "scale", |d| {
                        d.write_num(*x);
                        d.delim(',', false);
                        d.write_num(*y);
                    });
                }
            }
            TF::ScaleX(x) => args(d, "scaleX", |d| d.write_num(*x)),
            TF::ScaleY(y) => args(d, "scaleY", |d| d.write_num(*y)),
            TF::ScaleZ(z) => args(d, "scaleZ", |d| d.write_num(*z)),
            TF::Scale3d(x, y, z) => {
                if m && *z == 1.0 {
                    TF::Scale(*x, *y).to_css(d);
                } else if m && *x == 1.0 && *y == 1.0 {
                    args(d, "scaleZ", |d| d.write_num(*z));
                } else {
                    args(d, "scale3d", |d| {
                        d.write_num(*x);
                        d.delim(',', false);
                        d.write_num(*y);
                        d.delim(',', false);
                        d.write_num(*z);
                    });
                }
            }
            TF::Rotate(a) => args(d, "rotate", |d| wa(d, a, true)),
            TF::RotateX(a) => args(d, "rotateX", |d| wa(d, a, true)),
            TF::RotateY(a) => args(d, "rotateY", |d| wa(d, a, true)),
            TF::RotateZ(a) => args(d, if m { "rotate" } else { "rotateZ" }, |d| wa(d, a, true)),
            TF::Rotate3d(x, y, z, a) => {
                if m && (*x, *y, *z) == (1.0, 0.0, 0.0) {
                    args(d, "rotateX", |d| wa(d, a, true));
                } else if m && (*x, *y, *z) == (0.0, 1.0, 0.0) {
                    args(d, "rotateY", |d| wa(d, a, true));
                } else if m && (*x, *y, *z) == (0.0, 0.0, 1.0) {
                    args(d, "rotate", |d| wa(d, a, true));
                } else {
                    args(d, "rotate3d", |d| {
                        d.write_num(*x);
                        d.delim(',', false);
                        d.write_num(*y);
                        d.delim(',', false);
                        d.write_num(*z);
                        d.delim(',', false);
                        wa(d, a, true);
                    });
                }
            }
            TF::Skew(x, y) => {
                if y.is_zero() {
                    args(d, "skew", |d| wa(d, x, false));
                } else if m && x.is_zero() {
                    args(d, "skewY", |d| wa(d, y, false));
                } else {
                    args(d, "skew", |d| {
                        wa(d, x, false);
                        d.delim(',', false);
                        wa(d, y, false);
                    });
                }
            }
            TF::SkewX(x) => args(d, if m { "skew" } else { "skewX" }, |d| wa(d, x, false)),
            TF::SkewY(y) => args(d, "skewY", |d| wa(d, y, false)),
            TF::Perspective(l) => args(d, "perspective", |d| l.to_css(d)),
            TF::Matrix(v) => args(d, "matrix", |d| {
                for (i, x) in v.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    d.write_num(*x);
                }
            }),
            TF::Matrix3d(v) => args(d, "matrix3d", |d| {
                for (i, x) in v.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    d.write_num(*x);
                }
            }),
        }
    }
}

fn parse_origin(p: &mut Parser) -> PResult<TransformValue> {
    let pos = Position::parse(p)?;
    let z = p.try_parse(len).ok();
    Ok(TransformValue::Origin(pos, z))
}

impl TransformValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            TransformValue::None => d.write_str("none"),
            TransformValue::List(v) => {
                for f in v {
                    f.to_css(d);
                }
            }
            TransformValue::Origin(pos, z) => {
                match z {
                    Some(z) if !z.is_zero() => {
                        write_comp_3(d, &pos.x);
                        d.write_char(' ');
                        write_comp_3(d, &pos.y);
                        d.write_char(' ');
                        z.to_css(d);
                    }
                    Some(z) => {
                        // explicit zero z keeps three values
                        write_comp_3(d, &pos.x);
                        d.write_char(' ');
                        write_comp_3(d, &pos.y);
                        d.write_char(' ');
                        z.to_css(d);
                    }
                    None => pos.to_css(d),
                }
            }
            TransformValue::Translate(t) => match t {
                None => d.write_str("none"),
                Some((x, y, z)) => {
                    x.to_css(d);
                    if !y.is_zero() || !z.is_zero() {
                        d.write_char(' ');
                        y.to_css(d);
                    }
                    if !z.is_zero() {
                        d.write_char(' ');
                        z.to_css(d);
                    }
                }
            },
            TransformValue::Rotate(r) => match r {
                None => d.write_str("none"),
                Some((x, y, z, a)) => {
                    if (*x, *y, *z) == (1.0, 0.0, 0.0) {
                        d.write_str("x ");
                    } else if (*x, *y, *z) == (0.0, 1.0, 0.0) {
                        d.write_str("y ");
                    } else if (*x, *y, *z) != (0.0, 0.0, 1.0) {
                        d.write_num(*x);
                        d.write_char(' ');
                        d.write_num(*y);
                        d.write_char(' ');
                        d.write_num(*z);
                        d.write_char(' ');
                    }
                    wa(d, a, false);
                }
            },
            TransformValue::Scale(s) => match s {
                None => d.write_str("none"),
                Some((x, y, z)) => {
                    d.write_num(*x);
                    if x != y || *z != 1.0 {
                        d.write_char(' ');
                        d.write_num(*y);
                    }
                    if *z != 1.0 {
                        d.write_char(' ');
                        d.write_num(*z);
                    }
                }
            },
        }
    }
}

fn write_comp_3(d: &mut Printer, c: &PComp) {
    match c {
        PComp::Center => d.write_str("50%"),
        PComp::Side(s, None) => {
            let v = if s == "left" || s == "top" { NumVal::zero_px() } else { NumVal::pct(1.0) };
            v.to_css(d);
        }
        _ => c.to_css(d),
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "transform" => {
            if p.try_ident_matching("none") {
                Ok(TransformValue::None)
            } else {
                let mut v = Vec::new();
                loop {
                    match p.try_parse(parse_tf) {
                        Ok(f) => v.push(f),
                        Err(e) => {
                            if v.is_empty() {
                                return Some(Err(e));
                            }
                            break;
                        }
                    }
                }
                Ok(TransformValue::List(v))
            }
        }
        "transform-origin" | "perspective-origin" => parse_origin(p),
        "translate" => {
            if p.try_ident_matching("none") {
                Ok(TransformValue::Translate(None))
            } else {
                (|| {
                    let x = lp(p)?;
                    let y = p.try_parse(lp).unwrap_or_else(|_| NumVal::zero_px());
                    let z = p.try_parse(len).unwrap_or_else(|_| NumVal::zero_px());
                    Ok(TransformValue::Translate(Some((x, y, z))))
                })()
            }
        }
        "rotate" => {
            if p.try_ident_matching("none") {
                Ok(TransformValue::Rotate(None))
            } else {
                (|| {
                    let a = p.try_parse(ang).ok();
                    let axis = if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["x", "y", "z"])) {
                        match k.as_str() {
                            "x" => (1.0, 0.0, 0.0),
                            "y" => (0.0, 1.0, 0.0),
                            _ => (0.0, 0.0, 1.0),
                        }
                    } else if let Ok(x) = p.try_parse(parse_number) {
                        let y = parse_number(p)?;
                        let z = parse_number(p)?;
                        (x, y, z)
                    } else {
                        (0.0, 0.0, 1.0)
                    };
                    let a = match a {
                        Some(a) => a,
                        None => ang(p)?,
                    };
                    Ok(TransformValue::Rotate(Some((axis.0, axis.1, axis.2, a))))
                })()
            }
        }
        "scale" => {
            if p.try_ident_matching("none") {
                Ok(TransformValue::Scale(None))
            } else {
                (|| {
                    let x = num_or_pct(p)?;
                    let y = p.try_parse(num_or_pct).unwrap_or(x);
                    let z = p.try_parse(num_or_pct).unwrap_or(1.0);
                    Ok(TransformValue::Scale(Some((x, y, z))))
                })()
            }
        }
        "perspective" => {
            if p.try_ident_matching("none") {
                return Some(Ok(Value::Ident("none".into())));
            }
            return Some(len(p).map(Value::Num));
        }
        "transform-style" => return Some(expect_keyword(p, &["flat", "preserve-3d"]).map(Value::Ident)),
        "transform-box" => return Some(expect_keyword(p, &["content-box", "border-box", "fill-box", "stroke-box", "view-box"]).map(Value::Ident)),
        "backface-visibility" => return Some(expect_keyword(p, &["visible", "hidden"]).map(Value::Ident)),
        _ => return None,
    };
    Some(r.map(Value::Transform))
}

#[derive(Default)]
pub struct TransformHandler {
    transform: Option<(TransformValue, u8)>,
    translate: Option<TransformValue>,
    rotate: Option<TransformValue>,
    scale: Option<TransformValue>,
    has_any: bool,
}

fn tp(name: &str, prefix: u8, v: TransformValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Transform(v))
}

impl TransformHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        if let Some((t, pre)) = self.transform.take() {
            out.push(tp("transform", crate::prefixer::transform_prefixes(pre), t));
        }
        if let Some(t) = self.translate.take() {
            out.push(tp("translate", crate::prefixes::NONE, t));
        }
        if let Some(t) = self.rotate.take() {
            out.push(tp("rotate", crate::prefixes::NONE, t));
        }
        if let Some(t) = self.scale.take() {
            out.push(tp("scale", crate::prefixes::NONE, t));
        }
    }
}

impl crate::handlers::Handler for TransformHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(id.name.as_str(), "transform" | "translate" | "rotate" | "scale") {
            return false;
        }
        match p {
            Property::Val(id, Value::Transform(v)) => {
                match id.name.as_str() {
                    "transform" => {
                        if let Some((cur, pre)) = &mut self.transform {
                            if cur == v {
                                *pre |= id.prefix;
                                return true;
                            }
                            if *pre != id.prefix {
                                self.flush(out);
                            }
                        }
                        self.transform = Some((v.clone(), id.prefix));
                    }
                    "translate" => self.translate = Some(v.clone()),
                    "rotate" => self.rotate = Some(v.clone()),
                    _ => self.scale = Some(v.clone()),
                }
                self.has_any = true;
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}

pub fn transform_stylesheet(_rules: &mut Vec<crate::rules::CssRule>) {}
