#[derive(Clone, Debug, PartialEq)]
pub enum FlexValue {
    Direction(String),
    Wrap(String),
    Flow(String, String),
    Grow(f32),
    Shrink(f32),
    Basis(LPA),
    BasisContent,
    Flex(f32, f32, LPA),
    Order(i32),
}

#[derive(Clone, Debug, PartialEq)]
pub struct AlignValue(pub Vec<String>);

#[derive(Clone, Debug, PartialEq)]
pub struct Place(pub AlignValue, pub AlignValue);

const DIRS: &[&str] = &["row", "row-reverse", "column", "column-reverse"];
const WRAPS: &[&str] = &["nowrap", "wrap", "wrap-reverse"];

fn parse_basis(p: &mut Parser) -> PResult<LPA> {
    LPA::parse(p, true, true)
}

fn parse_flex(p: &mut Parser) -> PResult<FlexValue> {
    if p.try_ident_matching("none") {
        return Ok(FlexValue::Flex(0.0, 0.0, LPA::Auto));
    }
    let mut grow = None;
    let mut shrink = None;
    let mut basis = None;
    loop {
        if grow.is_none() {
            if let Ok(g) = p.try_parse(parse_number) {
                grow = Some(g);
                shrink = p.try_parse(parse_number).ok();
                continue;
            }
        }
        if basis.is_none() {
            if let Ok(b) = p.try_parse(parse_basis) {
                basis = Some(b);
                continue;
            }
        }
        break;
    }
    if grow.is_none() && basis.is_none() {
        return p.invalid();
    }
    Ok(FlexValue::Flex(grow.unwrap_or(1.0), shrink.unwrap_or(1.0), basis.unwrap_or(LPA::V(NumVal::pct(0.0)))))
}

fn parse_flow(p: &mut Parser) -> PResult<FlexValue> {
    let mut dir = None;
    let mut wrap = None;
    loop {
        if dir.is_none() {
            if let Ok(d) = p.try_parse(|p| expect_keyword(p, DIRS)) {
                dir = Some(d);
                continue;
            }
        }
        if wrap.is_none() {
            if let Ok(w) = p.try_parse(|p| expect_keyword(p, WRAPS)) {
                wrap = Some(w);
                continue;
            }
        }
        break;
    }
    if dir.is_none() && wrap.is_none() {
        return p.invalid();
    }
    Ok(FlexValue::Flow(dir.unwrap_or_else(|| "row".into()), wrap.unwrap_or_else(|| "nowrap".into())))
}

fn is_zero_pct(b: &LPA) -> bool {
    matches!(b, LPA::V(NumVal::D(d)) if d.unit == "%" && d.v == 0.0)
}
fn is_zero_len(b: &LPA) -> bool {
    matches!(b, LPA::V(NumVal::D(d)) if d.unit != "%" && d.v == 0.0)
}

impl FlexValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            FlexValue::Direction(s) | FlexValue::Wrap(s) => d.write_str(s),
            FlexValue::Flow(dir, wrap) => {
                let mut sp = false;
                if dir != "row" || wrap == "nowrap" {
                    d.write_str(dir);
                    sp = true;
                }
                if wrap != "nowrap" {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str(wrap);
                }
            }
            FlexValue::Grow(g) | FlexValue::Shrink(g) => d.write_num(*g),
            FlexValue::Basis(b) => b.to_css(d),
            FlexValue::BasisContent => d.write_str("content"),
            FlexValue::Order(o) => d.write_str(&o.to_string()),
            FlexValue::Flex(g, s, b) => {
                if *g == 1.0 && *s == 1.0 && *b == LPA::Auto {
                    d.write_str("auto");
                    return;
                }
                if *g == 0.0 && *s == 0.0 && *b == LPA::Auto {
                    d.write_str("none");
                    return;
                }
                let mut sp = false;
                if *g != 1.0 || *s != 1.0 || is_zero_pct(b) || is_zero_len(b) {
                    d.write_num(*g);
                    sp = true;
                }
                if *s != 1.0 || is_zero_len(b) {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_num(*s);
                    sp = true;
                }
                if !is_zero_pct(b) {
                    if sp {
                        d.write_char(' ');
                    }
                    b.to_css(d);
                }
            }
        }
    }
}

const OVERFLOW: &[&str] = &["safe", "unsafe"];

fn parse_align(p: &mut Parser, kind: &str) -> PResult<AlignValue> {
    let mut v: Vec<String> = Vec::new();
    // baseline
    if let Ok(k) = p.try_parse(|p| {
        let first = p.try_parse(|p| expect_keyword(p, &["first", "last"])).ok();
        p.expect_ident_matching("baseline")?;
        Ok(first)
    }) {
        match k {
            Some(f) if f == "last" => return Ok(AlignValue(vec!["last".into(), "baseline".into()])),
            _ => return Ok(AlignValue(vec!["baseline".into()])),
        }
    }
    let (singles, positions): (&[&str], &[&str]) = match kind {
        "align-content" => (&["normal", "space-between", "space-around", "space-evenly", "stretch"], &["center", "start", "end", "flex-start", "flex-end"]),
        "justify-content" => (&["normal", "space-between", "space-around", "space-evenly", "stretch"], &["center", "start", "end", "flex-start", "flex-end", "left", "right"]),
        "align-self" => (&["auto", "normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end"]),
        "justify-self" => (&["auto", "normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end", "left", "right"]),
        "align-items" => (&["normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end"]),
        _ => (&["normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end", "left", "right"]),
    };
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, singles)) {
        return Ok(AlignValue(vec![k]));
    }
    if kind == "justify-items" {
        if let Ok(r) = p.try_parse(|p| {
            let a = expect_keyword(p, &["legacy", "left", "right", "center"])?;
            if a == "legacy" {
                let b = p.try_parse(|p| expect_keyword(p, &["left", "right", "center"])).ok();
                let mut v = vec!["legacy".to_string()];
                if let Some(b) = b {
                    v.push(b);
                }
                Ok(v)
            } else {
                p.expect_ident_matching("legacy")?;
                Ok(vec!["legacy".to_string(), a])
            }
        }) {
            return Ok(AlignValue(r));
        }
    }
    if let Ok(o) = p.try_parse(|p| expect_keyword(p, OVERFLOW)) {
        v.push(o);
    }
    v.push(expect_keyword(p, positions)?);
    Ok(AlignValue(v))
}

impl AlignValue {
    pub fn to_css(&self, d: &mut Printer) {
        for (i, s) in self.0.iter().enumerate() {
            if i > 0 {
                d.write_char(' ');
            }
            d.write_str(s);
        }
    }
}

fn parse_place(p: &mut Parser, a: &str, j: &str) -> PResult<Place> {
    let x = parse_align(p, a)?;
    let y = match p.try_parse(|p| parse_align(p, j)) {
        Ok(y) => y,
        Err(_) => {
            // single value applies to both, if valid
            x.clone()
        }
    };
    Ok(Place(x, y))
}

