#[derive(Clone, Debug, PartialEq)]
pub enum AlignOrGap {
    Align(AlignValue),
    Place(Place),
    Gap(GapValue),
    Gap2(GapValue, GapValue),
}

impl AlignOrGap {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            AlignOrGap::Align(a) => a.to_css(d),
            AlignOrGap::Place(Place(a, b)) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
            AlignOrGap::Gap(g) => g.to_css(d),
            AlignOrGap::Gap2(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "flex-direction" => expect_keyword(p, DIRS).map(FlexValue::Direction),
        "flex-wrap" => expect_keyword(p, WRAPS).map(FlexValue::Wrap),
        "flex-flow" => parse_flow(p),
        "flex-grow" => parse_number(p).map(FlexValue::Grow),
        "flex-shrink" => parse_number(p).map(FlexValue::Shrink),
        "flex-basis" => {
            if p.try_ident_matching("content") {
                Ok(FlexValue::BasisContent)
            } else {
                parse_basis(p).map(FlexValue::Basis)
            }
        }
        "flex" => parse_flex(p),
        "order" => parse_integer(p).map(FlexValue::Order),
        "align-content" | "justify-content" | "align-self" | "justify-self" | "align-items" | "justify-items" => {
            return Some(parse_align(p, n).map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Align(a)))));
        }
        "place-content" => return Some(parse_place(p, "align-content", "justify-content").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "place-self" => return Some(parse_place(p, "align-self", "justify-self").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "place-items" => return Some(parse_place(p, "align-items", "justify-items").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "row-gap" | "column-gap" => return Some(parse_gap(p).map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Gap(a))))),
        "gap" => {
            return Some((|| {
                let a = parse_gap(p)?;
                let b = p.try_parse(parse_gap).unwrap_or_else(|_| a.clone());
                Ok(Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Gap2(a, b))))
            })())
        }
        _ => return None,
    };
    Some(r.map(Value::Flex))
}

#[derive(Default)]
pub struct FlexHandler {
    dir: Option<(String, u8)>,
    wrap: Option<(String, u8)>,
    grow: Option<(f32, u8)>,
    shrink: Option<(f32, u8)>,
    basis: Option<(FlexValue, u8)>,
    order: Option<(i32, u8)>,
    has_any: bool,
}

fn fp(name: &str, prefix: u8, v: FlexValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Flex(v))
}

impl FlexHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (dir, wrap, grow, shrink, basis, order) =
            (self.dir.take(), self.wrap.take(), self.grow.take(), self.shrink.take(), self.basis.take(), self.order.take());
        match (dir, wrap) {
            (Some((dv, dp)), Some((wv, wp))) if dp == wp => out.push(fp("flex-flow", dp, FlexValue::Flow(dv, wv))),
            (d, w) => {
                if let Some((v, p)) = d {
                    out.push(fp("flex-direction", p, FlexValue::Direction(v)));
                }
                if let Some((v, p)) = w {
                    out.push(fp("flex-wrap", p, FlexValue::Wrap(v)));
                }
            }
        }
        match (grow, shrink, basis) {
            (Some((g, gp)), Some((s, sp)), Some((FlexValue::Basis(b), bp))) if gp == sp && sp == bp => {
                out.push(fp("flex", gp, FlexValue::Flex(g, s, b)));
            }
            (g, s, b) => {
                if let Some((v, p)) = g {
                    out.push(fp("flex-grow", p, FlexValue::Grow(v)));
                }
                if let Some((v, p)) = s {
                    out.push(fp("flex-shrink", p, FlexValue::Shrink(v)));
                }
                if let Some((v, p)) = b {
                    out.push(fp("flex-basis", p, v));
                }
            }
        }
        if let Some((v, p)) = order {
            out.push(fp("order", p, FlexValue::Order(v)));
        }
    }
}

impl crate::handlers::Handler for FlexHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(id.name.as_str(), "flex-direction" | "flex-wrap" | "flex-flow" | "flex-grow" | "flex-shrink" | "flex-basis" | "flex" | "order") {
            return false;
        }
        let pre = id.prefix;
        macro_rules! set {
            ($f:ident, $v:expr) => {{
                if let Some((_, p0)) = &self.$f {
                    if *p0 != pre {
                        self.flush(out);
                    }
                }
                self.$f = Some(($v, pre));
                self.has_any = true;
            }};
        }
        match p {
            Property::Val(_, Value::Flex(v)) => match v {
                FlexValue::Direction(x) => set!(dir, x.clone()),
                FlexValue::Wrap(x) => set!(wrap, x.clone()),
                FlexValue::Flow(a, b) => {
                    set!(dir, a.clone());
                    set!(wrap, b.clone());
                }
                FlexValue::Grow(x) => set!(grow, *x),
                FlexValue::Shrink(x) => set!(shrink, *x),
                FlexValue::Basis(_) | FlexValue::BasisContent => set!(basis, v.clone()),
                FlexValue::Flex(g, s, b) => {
                    set!(grow, *g);
                    set!(shrink, *s);
                    set!(basis, FlexValue::Basis(b.clone()));
                }
                FlexValue::Order(o) => set!(order, *o),
            },
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}

#[derive(Default)]
pub struct AlignHandler {
    ac: Option<AlignValue>,
    jc: Option<AlignValue>,
    as_: Option<AlignValue>,
    js: Option<AlignValue>,
    ai: Option<AlignValue>,
    ji: Option<AlignValue>,
    rg: Option<GapValue>,
    cg: Option<GapValue>,
