}

fn ap(name: &str, v: AlignOrGap) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Misc(crate::misc::MiscValue::Align(v)))
}

impl AlignHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        for (a, j, pn, an, jn) in [
            (self.ac.take(), self.jc.take(), "place-content", "align-content", "justify-content"),
            (self.as_.take(), self.js.take(), "place-self", "align-self", "justify-self"),
            (self.ai.take(), self.ji.take(), "place-items", "align-items", "justify-items"),
        ] {
            match (a, j) {
                (Some(a), Some(j)) => {
                    // place-content can't have left/right in justify part when single
                    let ok = !(pn == "place-items" && j.0.first().map(|s| s == "legacy").unwrap_or(false));
                    if ok {
                        out.push(ap(pn, AlignOrGap::Place(Place(a, j))));
                    } else {
                        out.push(ap(an, AlignOrGap::Align(a)));
                        out.push(ap(jn, AlignOrGap::Align(j)));
                    }
                }
                (a, j) => {
                    if let Some(a) = a {
                        out.push(ap(an, AlignOrGap::Align(a)));
                    }
                    if let Some(j) = j {
                        out.push(ap(jn, AlignOrGap::Align(j)));
                    }
                }
            }
        }
        match (self.rg.take(), self.cg.take()) {
            (Some(r), Some(c)) => out.push(ap("gap", AlignOrGap::Gap2(r, c))),
            (r, c) => {
                if let Some(r) = r {
                    out.push(ap("row-gap", AlignOrGap::Gap(r)));
                }
                if let Some(c) = c {
                    out.push(ap("column-gap", AlignOrGap::Gap(c)));
                }
            }
