use crate::parser::*;
use crate::printer::Printer;
use crate::properties::*;
use crate::pvals::LPA;
use crate::values::*;

#[derive(Clone, Debug, PartialEq)]
pub enum FlexValue {
    Direction(String),
    Wrap(String),
    Flow(String, String),
    Grow(f32),
    Shrink(f32),
    Basis(LPA),
    BasisContent,
    Flex(f32, f32, LPA),
    Order(i32),
}

#[derive(Clone, Debug, PartialEq)]
pub struct AlignValue(pub Vec<String>);

#[derive(Clone, Debug, PartialEq)]
pub struct Place(pub AlignValue, pub AlignValue);

const DIRS: &[&str] = &["row", "row-reverse", "column", "column-reverse"];
const WRAPS: &[&str] = &["nowrap", "wrap", "wrap-reverse"];

fn parse_basis(p: &mut Parser) -> PResult<LPA> {
    LPA::parse(p, true, true)
}

fn parse_flex(p: &mut Parser) -> PResult<FlexValue> {
    if p.try_ident_matching("none") {
        return Ok(FlexValue::Flex(0.0, 0.0, LPA::Auto));
    }
    let mut grow = None;
    let mut shrink = None;
    let mut basis = None;
    loop {
        if grow.is_none() {
            if let Ok(g) = p.try_parse(parse_number) {
                grow = Some(g);
                shrink = p.try_parse(parse_number).ok();
                continue;
            }
        }
        if basis.is_none() {
            if let Ok(b) = p.try_parse(parse_basis) {
                basis = Some(b);
                continue;
            }
        }
        break;
    }
    if grow.is_none() && basis.is_none() {
        return p.invalid();
    }
    Ok(FlexValue::Flex(grow.unwrap_or(1.0), shrink.unwrap_or(1.0), basis.unwrap_or(LPA::V(NumVal::pct(0.0)))))
}

fn parse_flow(p: &mut Parser) -> PResult<FlexValue> {
    let mut dir = None;
    let mut wrap = None;
    loop {
        if dir.is_none() {
            if let Ok(d) = p.try_parse(|p| expect_keyword(p, DIRS)) {
                dir = Some(d);
                continue;
            }
        }
        if wrap.is_none() {
            if let Ok(w) = p.try_parse(|p| expect_keyword(p, WRAPS)) {
                wrap = Some(w);
                continue;
            }
        }
        break;
    }
    if dir.is_none() && wrap.is_none() {
        return p.invalid();
    }
    Ok(FlexValue::Flow(dir.unwrap_or_else(|| "row".into()), wrap.unwrap_or_else(|| "nowrap".into())))
}

fn is_zero_pct(b: &LPA) -> bool {
    matches!(b, LPA::V(NumVal::D(d)) if d.unit == "%" && d.v == 0.0)
}
fn is_zero_len(b: &LPA) -> bool {
    matches!(b, LPA::V(NumVal::D(d)) if d.unit != "%" && d.v == 0.0)
}

impl FlexValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            FlexValue::Direction(s) | FlexValue::Wrap(s) => d.write_str(s),
            FlexValue::Flow(dir, wrap) => {
                let mut sp = false;
                if dir != "row" || wrap == "nowrap" {
                    d.write_str(dir);
                    sp = true;
                }
                if wrap != "nowrap" {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str(wrap);
                }
            }
            FlexValue::Grow(g) | FlexValue::Shrink(g) => d.write_num(*g),
            FlexValue::Basis(b) => b.to_css(d),
            FlexValue::BasisContent => d.write_str("content"),
            FlexValue::Order(o) => d.write_str(&o.to_string()),
            FlexValue::Flex(g, s, b) => {
                if *g == 1.0 && *s == 1.0 && *b == LPA::Auto {
                    d.write_str("auto");
                    return;
                }
                if *g == 0.0 && *s == 0.0 && *b == LPA::Auto {
                    d.write_str("none");
                    return;
                }
                let mut sp = false;
                if *g != 1.0 || *s != 1.0 || is_zero_pct(b) || is_zero_len(b) {
                    d.write_num(*g);
                    sp = true;
                }
                if *s != 1.0 || is_zero_len(b) {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_num(*s);
                    sp = true;
                }
                if !is_zero_pct(b) {
                    if sp {
                        d.write_char(' ');
                    }
                    b.to_css(d);
                }
            }
        }
    }
}

const OVERFLOW: &[&str] = &["safe", "unsafe"];

fn parse_align(p: &mut Parser, kind: &str) -> PResult<AlignValue> {
    let mut v: Vec<String> = Vec::new();
    // baseline
    if let Ok(k) = p.try_parse(|p| {
        let first = p.try_parse(|p| expect_keyword(p, &["first", "last"])).ok();
        p.expect_ident_matching("baseline")?;
        Ok(first)
    }) {
        match k {
            Some(f) if f == "last" => return Ok(AlignValue(vec!["last".into(), "baseline".into()])),
            _ => return Ok(AlignValue(vec!["baseline".into()])),
        }
    }
    let (singles, positions): (&[&str], &[&str]) = match kind {
        "align-content" => (&["normal", "space-between", "space-around", "space-evenly", "stretch"], &["center", "start", "end", "flex-start", "flex-end"]),
        "justify-content" => (&["normal", "space-between", "space-around", "space-evenly", "stretch"], &["center", "start", "end", "flex-start", "flex-end", "left", "right"]),
        "align-self" => (&["auto", "normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end"]),
        "justify-self" => (&["auto", "normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end", "left", "right"]),
        "align-items" => (&["normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end"]),
        _ => (&["normal", "stretch"], &["center", "start", "end", "self-start", "self-end", "flex-start", "flex-end", "left", "right"]),
    };
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, singles)) {
        return Ok(AlignValue(vec![k]));
    }
    if kind == "justify-items" {
        if let Ok(r) = p.try_parse(|p| {
            let a = expect_keyword(p, &["legacy", "left", "right", "center"])?;
            if a == "legacy" {
                let b = p.try_parse(|p| expect_keyword(p, &["left", "right", "center"])).ok();
                let mut v = vec!["legacy".to_string()];
                if let Some(b) = b {
                    v.push(b);
                }
                Ok(v)
            } else {
                p.expect_ident_matching("legacy")?;
                Ok(vec!["legacy".to_string(), a])
            }
        }) {
            return Ok(AlignValue(r));
        }
    }
    if let Ok(o) = p.try_parse(|p| expect_keyword(p, OVERFLOW)) {
        v.push(o);
    }
    v.push(expect_keyword(p, positions)?);
    Ok(AlignValue(v))
}

impl AlignValue {
    pub fn to_css(&self, d: &mut Printer) {
        for (i, s) in self.0.iter().enumerate() {
            if i > 0 {
                d.write_char(' ');
            }
            d.write_str(s);
        }
    }
}

fn parse_place(p: &mut Parser, a: &str, j: &str) -> PResult<Place> {
    let x = parse_align(p, a)?;
    let y = match p.try_parse(|p| parse_align(p, j)) {
        Ok(y) => y,
        Err(_) => {
            // single value applies to both, if valid
            x.clone()
        }
    };
    Ok(Place(x, y))
}

#[derive(Clone, Debug, PartialEq)]
pub enum GapValue {
    Normal,
    V(NumVal),
}

fn parse_gap(p: &mut Parser) -> PResult<GapValue> {
    if p.try_ident_matching("normal") {
        return Ok(GapValue::Normal);
    }
    Ok(GapValue::V(parse_length_percentage(p)?))
}

impl GapValue {
    fn to_css(&self, d: &mut Printer) {
        match self {
            GapValue::Normal => d.write_str("normal"),
            GapValue::V(v) => v.to_css(d),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum AlignOrGap {
    Align(AlignValue),
    Place(Place),
    Gap(GapValue),
    Gap2(GapValue, GapValue),
}

impl AlignOrGap {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            AlignOrGap::Align(a) => a.to_css(d),
            AlignOrGap::Place(Place(a, b)) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
            AlignOrGap::Gap(g) => g.to_css(d),
            AlignOrGap::Gap2(a, b) => {
                a.to_css(d);
                if a != b {
                    d.write_char(' ');
                    b.to_css(d);
                }
            }
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "flex-direction" => expect_keyword(p, DIRS).map(FlexValue::Direction),
        "flex-wrap" => expect_keyword(p, WRAPS).map(FlexValue::Wrap),
        "flex-flow" => parse_flow(p),
        "flex-grow" => parse_number(p).map(FlexValue::Grow),
        "flex-shrink" => parse_number(p).map(FlexValue::Shrink),
        "flex-basis" => {
            if p.try_ident_matching("content") {
                Ok(FlexValue::BasisContent)
            } else {
                parse_basis(p).map(FlexValue::Basis)
            }
        }
        "flex" => parse_flex(p),
        "order" => parse_integer(p).map(FlexValue::Order),
        "align-content" | "justify-content" | "align-self" | "justify-self" | "align-items" | "justify-items" => {
            return Some(parse_align(p, n).map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Align(a)))));
        }
        "place-content" => return Some(parse_place(p, "align-content", "justify-content").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "place-self" => return Some(parse_place(p, "align-self", "justify-self").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "place-items" => return Some(parse_place(p, "align-items", "justify-items").map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Place(a))))),
        "row-gap" | "column-gap" => return Some(parse_gap(p).map(|a| Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Gap(a))))),
        "gap" => {
            return Some((|| {
                let a = parse_gap(p)?;
                let b = p.try_parse(parse_gap).unwrap_or_else(|_| a.clone());
                Ok(Value::Misc(crate::misc::MiscValue::Align(AlignOrGap::Gap2(a, b))))
            })())
        }
        _ => return None,
    };
    Some(r.map(Value::Flex))
}

#[derive(Default)]
pub struct FlexHandler {
    dir: Option<(String, u8)>,
    wrap: Option<(String, u8)>,
    grow: Option<(f32, u8)>,
    shrink: Option<(f32, u8)>,
    basis: Option<(FlexValue, u8)>,
    order: Option<(i32, u8)>,
    has_any: bool,
}

fn fp(name: &str, prefix: u8, v: FlexValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), prefix), Value::Flex(v))
}

impl FlexHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (dir, wrap, grow, shrink, basis, order) =
            (self.dir.take(), self.wrap.take(), self.grow.take(), self.shrink.take(), self.basis.take(), self.order.take());
        match (dir, wrap) {
            (Some((dv, dp)), Some((wv, wp))) if dp == wp => out.push(fp("flex-flow", dp, FlexValue::Flow(dv, wv))),
            (d, w) => {
                if let Some((v, p)) = d {
                    out.push(fp("flex-direction", p, FlexValue::Direction(v)));
                }
                if let Some((v, p)) = w {
                    out.push(fp("flex-wrap", p, FlexValue::Wrap(v)));
                }
            }
        }
        match (grow, shrink, basis) {
            (Some((g, gp)), Some((s, sp)), Some((FlexValue::Basis(b), bp))) if gp == sp && sp == bp => {
                out.push(fp("flex", gp, FlexValue::Flex(g, s, b)));
            }
            (g, s, b) => {
                if let Some((v, p)) = g {
                    out.push(fp("flex-grow", p, FlexValue::Grow(v)));
                }
                if let Some((v, p)) = s {
                    out.push(fp("flex-shrink", p, FlexValue::Shrink(v)));
                }
                if let Some((v, p)) = b {
                    out.push(fp("flex-basis", p, v));
                }
            }
        }
        if let Some((v, p)) = order {
            out.push(fp("order", p, FlexValue::Order(v)));
        }
    }
}

impl crate::handlers::Handler for FlexHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !matches!(id.name.as_str(), "flex-direction" | "flex-wrap" | "flex-flow" | "flex-grow" | "flex-shrink" | "flex-basis" | "flex" | "order") {
            return false;
        }
        let pre = id.prefix;
        macro_rules! set {
            ($f:ident, $v:expr) => {{
                if let Some((_, p0)) = &self.$f {
                    if *p0 != pre {
                        self.flush(out);
                    }
                }
                self.$f = Some(($v, pre));
                self.has_any = true;
            }};
        }
        match p {
            Property::Val(_, Value::Flex(v)) => match v {
                FlexValue::Direction(x) => set!(dir, x.clone()),
                FlexValue::Wrap(x) => set!(wrap, x.clone()),
                FlexValue::Flow(a, b) => {
                    set!(dir, a.clone());
                    set!(wrap, b.clone());
                }
                FlexValue::Grow(x) => set!(grow, *x),
                FlexValue::Shrink(x) => set!(shrink, *x),
                FlexValue::Basis(_) | FlexValue::BasisContent => set!(basis, v.clone()),
                FlexValue::Flex(g, s, b) => {
                    set!(grow, *g);
                    set!(shrink, *s);
                    set!(basis, FlexValue::Basis(b.clone()));
                }
                FlexValue::Order(o) => set!(order, *o),
            },
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}

#[derive(Default)]
pub struct AlignHandler {
    ac: Option<AlignValue>,
    jc: Option<AlignValue>,
    as_: Option<AlignValue>,
    js: Option<AlignValue>,
    ai: Option<AlignValue>,
    ji: Option<AlignValue>,
    rg: Option<GapValue>,
    cg: Option<GapValue>,
    has_any: bool,
}

fn ap(name: &str, v: AlignOrGap) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Misc(crate::misc::MiscValue::Align(v)))
}

impl AlignHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        for (a, j, pn, an, jn) in [
            (self.ac.take(), self.jc.take(), "place-content", "align-content", "justify-content"),
            (self.as_.take(), self.js.take(), "place-self", "align-self", "justify-self"),
            (self.ai.take(), self.ji.take(), "place-items", "align-items", "justify-items"),
        ] {
            match (a, j) {
                (Some(a), Some(j)) => {
                    // place-content can't have left/right in justify part when single
                    let ok = !(pn == "place-items" && j.0.first().map(|s| s == "legacy").unwrap_or(false));
                    if ok {
                        out.push(ap(pn, AlignOrGap::Place(Place(a, j))));
                    } else {
                        out.push(ap(an, AlignOrGap::Align(a)));
                        out.push(ap(jn, AlignOrGap::Align(j)));
                    }
                }
                (a, j) => {
                    if let Some(a) = a {
                        out.push(ap(an, AlignOrGap::Align(a)));
                    }
                    if let Some(j) = j {
                        out.push(ap(jn, AlignOrGap::Align(j)));
                    }
                }
            }
        }
        match (self.rg.take(), self.cg.take()) {
            (Some(r), Some(c)) => out.push(ap("gap", AlignOrGap::Gap2(r, c))),
            (r, c) => {
                if let Some(r) = r {
                    out.push(ap("row-gap", AlignOrGap::Gap(r)));
                }
                if let Some(c) = c {
                    out.push(ap("column-gap", AlignOrGap::Gap(c)));
                }
            }
        }
    }
}

impl crate::handlers::Handler for AlignHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        let n = id.name.as_str();
        if !matches!(
            n,
            "align-content" | "justify-content" | "place-content" | "align-self" | "justify-self" | "place-self" | "align-items"
                | "justify-items" | "place-items" | "row-gap" | "column-gap" | "gap"
        ) {
            return false;
        }
        match p {
            Property::Val(id2, Value::Misc(crate::misc::MiscValue::Align(v))) if id2.prefix == crate::prefixes::NONE => {
                self.has_any = true;
                match (n, v) {
                    ("align-content", AlignOrGap::Align(a)) => self.ac = Some(a.clone()),
                    ("justify-content", AlignOrGap::Align(a)) => self.jc = Some(a.clone()),
                    ("align-self", AlignOrGap::Align(a)) => self.as_ = Some(a.clone()),
                    ("justify-self", AlignOrGap::Align(a)) => self.js = Some(a.clone()),
                    ("align-items", AlignOrGap::Align(a)) => self.ai = Some(a.clone()),
                    ("justify-items", AlignOrGap::Align(a)) => self.ji = Some(a.clone()),
                    ("place-content", AlignOrGap::Place(Place(a, b))) => {
                        self.ac = Some(a.clone());
                        self.jc = Some(b.clone());
                    }
                    ("place-self", AlignOrGap::Place(Place(a, b))) => {
                        self.as_ = Some(a.clone());
                        self.js = Some(b.clone());
                    }
                    ("place-items", AlignOrGap::Place(Place(a, b))) => {
                        self.ai = Some(a.clone());
                        self.ji = Some(b.clone());
                    }
                    ("row-gap", AlignOrGap::Gap(g)) => self.rg = Some(g.clone()),
                    ("column-gap", AlignOrGap::Gap(g)) => self.cg = Some(g.clone()),
                    ("gap", AlignOrGap::Gap2(a, b)) => {
                        self.rg = Some(a.clone());
                        self.cg = Some(b.clone());
                    }
                    _ => {}
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
