fn parse_breadth(p: &mut Parser) -> PResult<Breadth> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["min-content", "max-content", "auto"])) {
        return Ok(match k.as_str() {
            "min-content" => Breadth::MinContent,
            "max-content" => Breadth::MaxContent,
            _ => Breadth::Auto,
        });
    }
    if let Ok(f) = p.try_parse(|p| {
        let loc = p.location();
        match p.next()? {
            Token::Dimension { value, unit, .. } if unit.eq_ignore_ascii_case("fr") && *value >= 0.0 => Ok(*value),
            t => Err(p.err_at(ErrorKind::UnexpectedToken(t.clone()), loc)),
        }
    }) {
        return Ok(Breadth::Flex(f));
    }
    Ok(Breadth::LP(parse_length_percentage(p)?))
}

fn parse_track_size(p: &mut Parser) -> PResult<TrackSize> {
    if let Ok(b) = p.try_parse(parse_breadth) {
        return Ok(TrackSize::B(b));
    }
    let loc = p.location();
    let f = p.expect_function()?.to_ascii_lowercase();
    match f.as_str() {
        "minmax" => p.parse_nested_block(|p| {
            let a = parse_breadth(p)?;
            p.expect_comma()?;
            let b = parse_breadth(p)?;
            Ok(TrackSize::MinMax(a, b))
        }),
        "fit-content" => p.parse_nested_block(|p| Ok(TrackSize::FitContent(parse_length_percentage(p)?))),
        _ => Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f)), loc)),
    }
}

fn parse_line_names(p: &mut Parser) -> PResult<Vec<String>> {
    p.expect_square_block()?;
    p.parse_nested_block(|p| {
        let mut v = Vec::new();
        while let Ok(s) = p.try_parse(|p| p.expect_ident_cloned()) {
            v.push(s);
        }
        Ok(v)
    })
}

fn parse_track_list(p: &mut Parser) -> PResult<TrackList> {
    let mut names = Vec::new();
    let mut items = Vec::new();
    loop {
        let n = p.try_parse(parse_line_names).unwrap_or_default();
        names.push(n);
        if let Ok(t) = p.try_parse(parse_track_size) {
            items.push(TrackItem::Track(t));
            continue;
        }
        if let Ok(r) = p.try_parse(|p| {
            p.expect_function_matching("repeat")?;
            p.parse_nested_block(|p| {
                let count = if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["auto-fill", "auto-fit"])) {
                    if k == "auto-fill" { RepeatCount::AutoFill } else { RepeatCount::AutoFit }
                } else {
                    RepeatCount::N(parse_integer(p)?)
                };
                p.expect_comma()?;
                let mut rn = Vec::new();
                let mut rt = Vec::new();
                loop {
                    rn.push(p.try_parse(parse_line_names).unwrap_or_default());
                    match p.try_parse(parse_track_size) {
                        Ok(t) => rt.push(t),
                        Err(_) => break,
                    }
                }
                if rt.is_empty() {
                    return p.invalid();
                }
                Ok(TrackItem::Repeat(count, rn, rt))
            })
        }) {
            items.push(r);
            continue;
        }
        break;
    }
    if items.is_empty() {
        return p.invalid();
    }
    Ok(TrackList { names, items })
}

fn parse_sizing(p: &mut Parser) -> PResult<TrackSizing> {
    if p.try_ident_matching("none") {
        return Ok(TrackSizing::None);
    }
    if p.try_ident_matching("subgrid") {
        let mut v = Vec::new();
        while let Ok(n) = p.try_parse(parse_line_names) {
            v.push(n);
        }
        return Ok(TrackSizing::Subgrid(v));
    }
    Ok(TrackSizing::List(parse_track_list(p)?))
}

fn write_names(d: &mut Printer, n: &[String]) {
    d.write_char('[');
    for (i, s) in n.iter().enumerate() {
        if i > 0 {
            d.write_char(' ');
        }
        d.write_ident(s);
    }
    d.write_char(']');
}

impl Breadth {
    fn to_css(&self, d: &mut Printer) {
        match self {
            Breadth::LP(v) => v.to_css(d),
            Breadth::Flex(f) => {
                d.write_num(*f);
                d.write_str("fr");
            }
            Breadth::MinContent => d.write_str("min-content"),
            Breadth::MaxContent => d.write_str("max-content"),
            Breadth::Auto => d.write_str("auto"),
        }
    }
}

impl TrackSize {
    fn to_css(&self, d: &mut Printer) {
        match self {
            TrackSize::B(b) => b.to_css(d),
            TrackSize::MinMax(a, b) => {
                d.write_str("minmax(");
                a.to_css(d);
                d.delim(',', false);
                b.to_css(d);
                d.write_char(')');
            }
            TrackSize::FitContent(v) => {
                d.write_str("fit-content(");
                v.to_css(d);
                d.write_char(')');
            }
        }
    }
}

fn write_names_and_tracks<T, F: Fn(&T, &mut Printer)>(d: &mut Printer, names: &[Vec<String>], items: &[T], f: F) {
    for (i, n) in names.iter().enumerate() {
        if !n.is_empty() {
            write_names(d, n);
        }
        if let Some(it) = items.get(i) {
            if !n.is_empty() {
                d.whitespace();
            } else if i > 0 {
                d.write_char(' ');
            }
            f(it, d);
        }
    }
}

impl TrackItem {
    fn to_css(&self, d: &mut Printer) {
        match self {
            TrackItem::Track(t) => t.to_css(d),
            TrackItem::Repeat(c, names, tracks) => {
                d.write_str("repeat(");
                match c {
                    RepeatCount::N(n) => d.write_str(&n.to_string()),
                    RepeatCount::AutoFill => d.write_str("auto-fill"),
                    RepeatCount::AutoFit => d.write_str("auto-fit"),
                }
                d.delim(',', false);
                write_names_and_tracks(d, names, tracks, |t, d| t.to_css(d));
                d.write_char(')');
            }
        }
    }
}

impl TrackList {
    fn to_css(&self, d: &mut Printer) {
        write_names_and_tracks(d, &self.names, &self.items, |t, d| t.to_css(d));
    }
}

impl TrackSizing {
    fn to_css(&self, d: &mut Printer) {
        match self {
            TrackSizing::None => d.write_str("none"),
            TrackSizing::List(l) => l.to_css(d),
            TrackSizing::Subgrid(v) => {
                d.write_str("subgrid");
                for n in v {
                    d.write_char(' ');
                    write_names(d, n);
                }
            }
        }
    }
}

fn parse_area_string(s: &str) -> Option<Vec<Option<String>>> {
    let mut v = Vec::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0C' {
            i += 1;
            continue;
        }
        if c == '.' {
            while i < chars.len() && chars[i] == '.' {
                i += 1;
            }
            v.push(None);
            continue;
        }
        let is_name = |c: char| c.is_alphanumeric() || c == '-' || c == '_' || (c as u32) >= 0x80;
        if is_name(c) {
            let start = i;
            while i < chars.len() && is_name(chars[i]) {
                i += 1;
            }
            v.push(Some(chars[start..i].iter().collect()));
            continue;
        }
        return None;
    }
    Some(v)
}

fn parse_areas(p: &mut Parser) -> PResult<Areas> {
    if p.try_ident_matching("none") {
        return Ok(Areas::None);
    }
    let mut cols = 0;
    let mut all = Vec::new();
    let mut rows = 0;
    while let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
        let row = parse_area_string(&s).ok_or_else(|| p.err(ErrorKind::InvalidValue))?;
        if rows == 0 {
            cols = row.len();
        } else if row.len() != cols {
            return p.invalid();
        }
        rows += 1;
        all.extend(row);
    }
    if rows == 0 {
        return p.invalid();
    }
    Ok(Areas::Areas(cols, all))
}

impl Areas {
    fn write_row(&self, d: &mut Printer, i: usize) {
        if let Areas::Areas(cols, v) = self {
            d.write_char('"');
            let mut last_null = false;
            for j in 0..*cols {
                match &v[i * cols + j] {
                    Some(n) => {
                        if j > 0 && !last_null {
                            d.write_char(' ');
                        }
                        d.write_str(n);
                        last_null = false;
                    }
                    None => {
                        if j > 0 && last_null {
                            d.write_char(' ');
                        }
                        d.write_char('.');
                        last_null = true;
                    }
                }
            }
            d.write_char('"');
        }
    }
    fn rows(&self) -> usize {
        match self {
            Areas::None => 0,
            Areas::Areas(c, v) => {
                if *c == 0 {
                    0
                } else {
                    v.len() / c
                }
            }
        }
    }
    fn to_css(&self, d: &mut Printer) {
        match self {
            Areas::None => d.write_str("none"),
            Areas::Areas(..) => {
                let n = self.rows();
                for i in 0..n {
                    if i > 0 {
                        d.newline();
                    }
                    self.write_row(d, i);
                }
            }
        }
    }
}

fn parse_grid_line(p: &mut Parser) -> PResult<GridLine> {
    if p.try_ident_matching("auto") {
        return Ok(GridLine::Auto);
    }
    if p.try_ident_matching("span") {
        let mut n = None;
        let mut name = None;
        loop {
            if n.is_none() {
                if let Ok(i) = p.try_parse(parse_integer) {
                    if i <= 0 {
                        return p.invalid();
                    }
                    n = Some(i);
                    continue;
                }
            }
            if name.is_none() {
                if let Ok(s) = p.try_parse(custom_ident) {
                    name = Some(s);
                    continue;
                }
            }
            break;
        }
        if n.is_none() && name.is_none() {
            return p.invalid();
        }
        return Ok(GridLine::Span(n.unwrap_or(1), name));
    }
    let mut n = None;
    let mut name = None;
    loop {
        if n.is_none() {
            if let Ok(i) = p.try_parse(parse_integer) {
                if i == 0 {
                    return p.invalid();
                }
                n = Some(i);
                continue;
            }
        }
        if name.is_none() {
            if let Ok(s) = p.try_parse(custom_ident) {
                name = Some(s);
                continue;
            }
        }
        break;
    }
    match (n, name) {
        (Some(n), name) => Ok(GridLine::Line(n, name)),
        (None, Some(name)) => Ok(GridLine::Ident(name)),
        _ => p.invalid(),
    }
}

fn custom_ident(p: &mut Parser) -> PResult<String> {
    let loc = p.location();
    let s = p.expect_ident()?.to_string();
    let l = s.to_ascii_lowercase();
    if matches!(l.as_str(), "auto" | "span" | "initial" | "inherit" | "unset" | "default") {
        return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Ident(s)), loc));
    }
    Ok(s)
}

impl GridLine {
    fn to_css(&self, d: &mut Printer) {
        match self {
            GridLine::Auto => d.write_str("auto"),
            GridLine::Ident(n) => d.write_ident(n),
            GridLine::Line(n, name) => {
                d.write_str(&n.to_string());
                if let Some(name) = name {
                    d.write_char(' ');
                    d.write_ident(name);
                }
            }
            GridLine::Span(n, name) => {
                d.write_str("span ");
                if *n != 1 || name.is_none() {
                    d.write_str(&n.to_string());
                    if name.is_some() {
                        d.write_char(' ');
                    }
                }
                if let Some(name) = name {
                    d.write_ident(name);
                }
            }
        }
    }
    fn can_omit_end(&self, start: &GridLine) -> bool {
        match start {
            GridLine::Ident(n) => matches!(self, GridLine::Ident(m) if m == n),
            _ => *self == GridLine::Auto,
        }
    }
    fn default_end(start: &GridLine) -> GridLine {
        match start {
            GridLine::Ident(n) => GridLine::Ident(n.clone()),
            _ => GridLine::Auto,
        }
    }
}

fn parse_placement(p: &mut Parser) -> PResult<GridValue> {
    let a = parse_grid_line(p)?;
    let b = if p.try_delim('/') { parse_grid_line(p)? } else { GridLine::default_end(&a) };
    Ok(GridValue::Placement(a, b))
}

fn parse_area(p: &mut Parser) -> PResult<GridValue> {
    let rs = parse_grid_line(p)?;
    let cs = if p.try_delim('/') { parse_grid_line(p)? } else { GridLine::default_end(&rs) };
    let re = if p.try_delim('/') { parse_grid_line(p)? } else { GridLine::default_end(&rs) };
    let ce = if p.try_delim('/') { parse_grid_line(p)? } else { GridLine::default_end(&cs) };
    Ok(GridValue::Area(rs, cs, re, ce))
}

fn parse_flow(p: &mut Parser) -> PResult<(String, bool)> {
    let mut dir = None;
    let mut dense = false;
    loop {
        if dir.is_none() {
            if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["row", "column"])) {
                dir = Some(k);
                continue;
            }
        }
        if !dense && p.try_ident_matching("dense") {
            dense = true;
            continue;
        }
        break;
    }
    if dir.is_none() && !dense {
        return p.invalid();
    }
    Ok((dir.unwrap_or_else(|| "row".into()), dense))
}

fn write_flow(d: &mut Printer, f: &(String, bool)) {
    if f.0 == "row" && f.1 {
        d.write_str("dense");
    } else {
        d.write_str(&f.0);
        if f.1 {
            d.write_str(" dense");
        }
    }
}

fn parse_template(p: &mut Parser) -> PResult<GridTemplate> {
    if p.try_ident_matching("none") {
        return Ok(GridTemplate { rows: TrackSizing::None, columns: TrackSizing::None, areas: Areas::None });
    }
    if let Ok(t) = p.try_parse(|p| {
        let rows = parse_sizing(p)?;
        p.expect_delim('/')?;
        let cols = parse_sizing(p)?;
        Ok(GridTemplate { rows, columns: cols, areas: Areas::None })
    }) {
        return Ok(t);
    }
    // areas form
    let mut names: Vec<Vec<String>> = Vec::new();
    let mut items: Vec<TrackItem> = Vec::new();
    let mut cols_n = 0usize;
    let mut areas: Vec<Option<String>> = Vec::new();
    let mut rows = 0;
    loop {
        let mut n = p.try_parse(parse_line_names).unwrap_or_default();
        let s = match p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
            Ok(s) => s,
            Err(_) => {
                if rows == 0 {
                    return p.invalid();
                }
                // trailing names belong to previous
                if !n.is_empty() {
                    return p.invalid();
                }
                break;
            }
        };
        if let Some(last) = names.last_mut() {
            if !last.is_empty() || !n.is_empty() {
                last.extend(n.drain(..));
            }
            if names.len() > items.len() {
                // merged
            }
        } else {
            names.push(n);
        }
        let row = parse_area_string(&s).ok_or_else(|| p.err(ErrorKind::InvalidValue))?;
        if rows == 0 {
            cols_n = row.len();
        } else if row.len() != cols_n {
            return p.invalid();
        }
        rows += 1;
        areas.extend(row);
        let t = p.try_parse(parse_track_size).unwrap_or(TrackSize::B(Breadth::Auto));
        items.push(TrackItem::Track(t));
        let after = p.try_parse(parse_line_names).unwrap_or_default();
        names.push(after);
    }
    let columns = if p.try_delim('/') {
        let l = parse_track_list(p)?;
        if l.items.iter().any(|i| matches!(i, TrackItem::Repeat(..))) {
            return p.invalid();
        }
        TrackSizing::List(l)
    } else {
        TrackSizing::None
    };
    Ok(GridTemplate { rows: TrackSizing::List(TrackList { names, items }), columns, areas: Areas::Areas(cols_n, areas) })
}

impl GridTemplate {
    fn to_css(&self, d: &mut Printer, indent: usize) {
        match &self.areas {
            Areas::None => {
                if self.rows == TrackSizing::None && self.columns == TrackSizing::None {
                    d.write_str("none");
                } else {
                    self.rows.to_css(d);
                    d.delim('/', true);
                    self.columns.to_css(d);
                }
            }
            Areas::Areas(..) => {
                let n = self.areas.rows();
                d.indent += indent;
                let (names, items) = match &self.rows {
                    TrackSizing::List(l) => (l.names.clone(), l.items.clone()),
                    _ => (vec![], vec![]),
                };
                for i in 0..n {
                    if i > 0 {
                        d.newline();
                    }
                    if let Some(nm) = names.get(i) {
                        if !nm.is_empty() {
                            write_names(d, nm);
                            d.whitespace();
                        }
                    }
                    self.areas.write_row(d, i);
                    if let Some(TrackItem::Track(t)) = items.get(i) {
                        if *t != TrackSize::B(Breadth::Auto) {
                            d.whitespace();
                            t.to_css(d);
                        }
                    }
                    if i + 1 == n {
                        if let Some(nm) = names.get(i + 1) {
                            if !nm.is_empty() {
                                d.whitespace();
                                write_names(d, nm);
                            }
                        }
                    }
                }
                if self.columns != TrackSizing::None {
                    d.newline();
                    d.delim('/', false);
                    self.columns.to_css(d);
                }
                d.indent -= indent;
            }
        }
    }
}

fn parse_grid(p: &mut Parser) -> PResult<Grid> {
    if let Ok(t) = p.try_parse(parse_template) {
        return Ok(Grid { template: t, auto_rows: vec![TrackSize::B(Breadth::Auto)], auto_columns: vec![TrackSize::B(Breadth::Auto)], flow: ("row".into(), false) });
    }
    // rows / auto-flow
    if let Ok(g) = p.try_parse(|p| {
        let rows = parse_sizing(p)?;
        p.expect_delim('/')?;
        let dense1 = p.try_ident_matching("dense");
        p.expect_ident_matching("auto-flow")?;
        let dense = dense1 || p.try_ident_matching("dense");
        let cols = p.try_parse(|p| {
            let mut v = vec![parse_track_size(p)?];
            while let Ok(t) = p.try_parse(parse_track_size) {
                v.push(t);
            }
            Ok(v)
        }).unwrap_or_else(|_| vec![TrackSize::B(Breadth::Auto)]);
        Ok(Grid {
            template: GridTemplate { rows, columns: TrackSizing::None, areas: Areas::None },
            auto_rows: vec![TrackSize::B(Breadth::Auto)],
            auto_columns: cols,
            flow: ("column".into(), dense),
        })
    }) {
        return Ok(g);
    }
    let dense1 = p.try_ident_matching("dense");
    p.expect_ident_matching("auto-flow")?;
    let dense = dense1 || p.try_ident_matching("dense");
    let rows = p
        .try_parse(|p| {
            let mut v = vec![parse_track_size(p)?];
            while let Ok(t) = p.try_parse(parse_track_size) {
                v.push(t);
            }
            Ok(v)
        })
        .unwrap_or_else(|_| vec![TrackSize::B(Breadth::Auto)]);
    p.expect_delim('/')?;
    let cols = parse_sizing(p)?;
    Ok(Grid {
        template: GridTemplate { rows: TrackSizing::None, columns: cols, areas: Areas::None },
        auto_rows: rows,
        auto_columns: vec![TrackSize::B(Breadth::Auto)],
        flow: ("row".into(), dense),
    })
}

fn write_tracks(d: &mut Printer, v: &[TrackSize]) {
    for (i, t) in v.iter().enumerate() {
        if i > 0 {
            d.write_char(' ');
        }
        t.to_css(d);
    }
}

fn is_auto_tracks(v: &[TrackSize]) -> bool {
    v.len() == 1 && v[0] == TrackSize::B(Breadth::Auto)
}

impl Grid {
    fn to_css(&self, d: &mut Printer) {
        let t = &self.template;
        let default_auto = is_auto_tracks(&self.auto_rows) && is_auto_tracks(&self.auto_columns) && self.flow == ("row".to_string(), false);
        if default_auto {
            t.to_css(d, 0);
            return;
        }
        if self.flow.0 == "column" && t.columns == TrackSizing::None && t.areas == Areas::None {
            t.rows.to_css(d);
            d.delim('/', true);
            d.write_str("auto-flow");
            if self.flow.1 {
                d.write_str(" dense");
            }
            if !is_auto_tracks(&self.auto_columns) {
                d.write_char(' ');
                write_tracks(d, &self.auto_columns);
            }
            return;
        }
        d.write_str("auto-flow");
        if self.flow.1 {
            d.write_str(" dense");
        }
        if !is_auto_tracks(&self.auto_rows) {
            d.write_char(' ');
            write_tracks(d, &self.auto_rows);
        }
        d.delim('/', true);
        t.columns.to_css(d);
    }
}

impl GridValue {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            GridValue::Sizing(s) => s.to_css(d),
            GridValue::AutoTracks(v) => write_tracks(d, v),
            GridValue::Areas(a) => {
                let ind = "grid-template-areas: ".len();
                d.indent += ind;
                a.to_css(d);
                d.indent -= ind;
            }
            GridValue::Flow(a, b) => write_flow(d, &(a.clone(), *b)),
            GridValue::Line(l) => l.to_css(d),
            GridValue::Placement(a, b) => {
                a.to_css(d);
                if !b.can_omit_end(a) {
                    d.delim('/', true);
                    b.to_css(d);
                }
            }
            GridValue::Area(rs, cs, re, ce) => {
                rs.to_css(d);
                let omit_ce = ce.can_omit_end(cs);
                let omit_re = omit_ce && re.can_omit_end(rs);
                let omit_cs = omit_re && cs.can_omit_end(rs);
                if !omit_cs {
                    d.delim('/', true);
                    cs.to_css(d);
                }
                if !omit_re {
                    d.delim('/', true);
                    re.to_css(d);
                }
                if !omit_ce {
                    d.delim('/', true);
                    ce.to_css(d);
                }
            }
            GridValue::Template(t) => t.to_css(d, "grid-template: ".len()),
            GridValue::Grid(g) => g.to_css(d),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "grid-template-columns" | "grid-template-rows" => parse_sizing(p).map(GridValue::Sizing),
        "grid-auto-columns" | "grid-auto-rows" => (|| {
            let mut v = vec![parse_track_size(p)?];
            while let Ok(t) = p.try_parse(parse_track_size) {
                v.push(t);
            }
            Ok(GridValue::AutoTracks(v))
        })(),
        "grid-template-areas" => parse_areas(p).map(GridValue::Areas),
        "grid-auto-flow" => parse_flow(p).map(|(a, b)| GridValue::Flow(a, b)),
        "grid-row-start" | "grid-row-end" | "grid-column-start" | "grid-column-end" => parse_grid_line(p).map(GridValue::Line),
        "grid-row" | "grid-column" => parse_placement(p),
        "grid-area" => parse_area(p),
        "grid-template" => parse_template(p).map(GridValue::Template),
        "grid" => parse_grid(p).map(GridValue::Grid),
        _ => return None,
    };
    Some(r.map(Value::Grid))
}

#[derive(Default)]
pub struct GridHandler {
    rows: Option<TrackSizing>,
    cols: Option<TrackSizing>,
    areas: Option<Areas>,
    auto_rows: Option<Vec<TrackSize>>,
    auto_cols: Option<Vec<TrackSize>>,
    flow: Option<(String, bool)>,
    rs: Option<GridLine>,
    re: Option<GridLine>,
    cs: Option<GridLine>,
    ce: Option<GridLine>,
    has_any: bool,
}

fn gp(name: &str, v: GridValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Grid(v))
}

impl GridHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (rows, cols, areas, ar, ac, flow) =
            (self.rows.take(), self.cols.take(), self.areas.take(), self.auto_rows.take(), self.auto_cols.take(), self.flow.take());
        let mut done_template = false;
        if let (Some(r), Some(c), Some(a)) = (&rows, &cols, &areas) {
            let valid_areas = match (a, r) {
                (Areas::Areas(..), TrackSizing::List(l)) => {
                    l.items.len() == a.rows() && l.items.iter().all(|i| matches!(i, TrackItem::Track(_))) && !matches!(c, TrackSizing::List(cl) if cl.items.iter().any(|i| matches!(i, TrackItem::Repeat(..))))
                }
                (Areas::Areas(..), _) => false,
                _ => true,
            };
            if valid_areas {
                let t = GridTemplate { rows: r.clone(), columns: c.clone(), areas: a.clone() };
                if let (Some(ar), Some(ac), Some(fl)) = (&ar, &ac, &flow) {
                    out.push(gp("grid", GridValue::Grid(Grid { template: t, auto_rows: ar.clone(), auto_columns: ac.clone(), flow: fl.clone() })));
                    done_template = true;
                    self.flush_placement(out);
                    return;
                }
                out.push(gp("grid-template", GridValue::Template(t)));
                done_template = true;
            }
        }
        if !done_template {
            if let Some(r) = rows {
                out.push(gp("grid-template-rows", GridValue::Sizing(r)));
            }
            if let Some(c) = cols {
                out.push(gp("grid-template-columns", GridValue::Sizing(c)));
            }
            if let Some(a) = areas {
                out.push(gp("grid-template-areas", GridValue::Areas(a)));
            }
        }
        if let Some(v) = ar {
            out.push(gp("grid-auto-rows", GridValue::AutoTracks(v)));
        }
        if let Some(v) = ac {
            out.push(gp("grid-auto-columns", GridValue::AutoTracks(v)));
        }
        if let Some((a, b)) = flow {
            out.push(gp("grid-auto-flow", GridValue::Flow(a, b)));
        }
        self.flush_placement(out);
    }

    fn flush_placement(&mut self, out: &mut Vec<Property>) {
        let (rs, re, cs, ce) = (self.rs.take(), self.re.take(), self.cs.take(), self.ce.take());
        if let (Some(rs), Some(re), Some(cs), Some(ce)) = (&rs, &re, &cs, &ce) {
            out.push(gp("grid-area", GridValue::Area(rs.clone(), cs.clone(), re.clone(), ce.clone())));
            return;
        }
        match (rs, re) {
            (Some(a), Some(b)) => out.push(gp("grid-row", GridValue::Placement(a, b))),
            (a, b) => {
                if let Some(a) = a {
                    out.push(gp("grid-row-start", GridValue::Line(a)));
                }
                if let Some(b) = b {
                    out.push(gp("grid-row-end", GridValue::Line(b)));
                }
            }
        }
        match (cs, ce) {
            (Some(a), Some(b)) => out.push(gp("grid-column", GridValue::Placement(a, b))),
            (a, b) => {
                if let Some(a) = a {
                    out.push(gp("grid-column-start", GridValue::Line(a)));
                }
                if let Some(b) = b {
                    out.push(gp("grid-column-end", GridValue::Line(b)));
                }
            }
        }
    }
}

impl crate::handlers::Handler for GridHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        let n = id.name.as_str();
        if !n.starts_with("grid") {
            return false;
        }
        match p {
            Property::Val(_, Value::Grid(v)) => {
                self.has_any = true;
                match (n, v) {
                    ("grid-template-rows", GridValue::Sizing(s)) => self.rows = Some(s.clone()),
                    ("grid-template-columns", GridValue::Sizing(s)) => self.cols = Some(s.clone()),
                    ("grid-template-areas", GridValue::Areas(a)) => self.areas = Some(a.clone()),
                    ("grid-auto-rows", GridValue::AutoTracks(a)) => self.auto_rows = Some(a.clone()),
                    ("grid-auto-columns", GridValue::AutoTracks(a)) => self.auto_cols = Some(a.clone()),
                    ("grid-auto-flow", GridValue::Flow(a, b)) => self.flow = Some((a.clone(), *b)),
                    ("grid-row-start", GridValue::Line(l)) => self.rs = Some(l.clone()),
                    ("grid-row-end", GridValue::Line(l)) => self.re = Some(l.clone()),
                    ("grid-column-start", GridValue::Line(l)) => self.cs = Some(l.clone()),
                    ("grid-column-end", GridValue::Line(l)) => self.ce = Some(l.clone()),
                    ("grid-row", GridValue::Placement(a, b)) => {
                        self.rs = Some(a.clone());
                        self.re = Some(b.clone());
                    }
                    ("grid-column", GridValue::Placement(a, b)) => {
                        self.cs = Some(a.clone());
                        self.ce = Some(b.clone());
                    }
                    ("grid-area", GridValue::Area(a, b, c, e)) => {
                        self.rs = Some(a.clone());
                        self.cs = Some(b.clone());
                        self.re = Some(c.clone());
                        self.ce = Some(e.clone());
                    }
                    ("grid-template", GridValue::Template(t)) => {
                        self.rows = Some(t.rows.clone());
                        self.cols = Some(t.columns.clone());
                        self.areas = Some(t.areas.clone());
                    }
                    ("grid", GridValue::Grid(g)) => {
                        self.rows = Some(g.template.rows.clone());
                        self.cols = Some(g.template.columns.clone());
                        self.areas = Some(g.template.areas.clone());
                        self.auto_rows = Some(g.auto_rows.clone());
                        self.auto_cols = Some(g.auto_columns.clone());
                        self.flow = Some(g.flow.clone());
                    }
                    _ => {
                        self.flush(out);
                        out.push(p.clone());
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
