pub enum Shape {
    Inset(Vec<NumVal>, Option<Vec<(NumVal, NumVal)>>),
    Circle(Option<NumVal>, Option<String>, Position),
    Ellipse(Option<(NumVal, NumVal)>, Option<String>, Position),
    Polygon(Option<String>, Vec<(NumVal, NumVal)>),
    Other(String, crate::tokenlist::TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub enum ClipPath {
    None,
    Url(String),
    Shape(Shape, Option<String>),
    Box(String),
