pub fn parse_shadow(p: &mut Parser, allow_inset_spread: bool) -> PResult<Shadow> {
    let mut color = None;
    let mut lens: Option<(NumVal, NumVal, NumVal, NumVal)> = None;
    let mut inset = false;
    loop {
        if allow_inset_spread && !inset && p.try_ident_matching("inset") {
            inset = true;
            continue;
        }
        if lens.is_none() {
            if let Ok(l) = p.try_parse(|p| {
                let x = parse_length(p)?;
                let y = parse_length(p)?;
                let blur = p.try_parse(parse_length).unwrap_or_else(|_| NumVal::zero_px());
                let spread = if allow_inset_spread { p.try_parse(parse_length).unwrap_or_else(|_| NumVal::zero_px()) } else { NumVal::zero_px() };
                Ok((x, y, blur, spread))
            }) {
                lens = Some(l);
                continue;
            }
        }
        if color.is_none() {
            if let Ok(c) = p.try_parse(CssColor::parse) {
                color = Some(c);
                continue;
            }
        }
        break;
    }
    let (x, y, blur, spread) = match lens {
        Some(l) => l,
        None => return p.invalid(),
    };
    Ok(Shadow { color: color.unwrap_or(CssColor::CurrentColor), x, y, blur, spread, inset })
}

impl Shadow {
    pub fn to_css(&self, d: &mut Printer) {
        if self.inset {
            d.write_str("inset ");
        }
        self.x.to_css(d);
        d.write_char(' ');
        self.y.to_css(d);
        if !self.blur.is_zero() || !self.spread.is_zero() {
            d.write_char(' ');
            self.blur.to_css(d);
            if !self.spread.is_zero() {
                d.write_char(' ');
                self.spread.to_css(d);
            }
        }
        if self.color != CssColor::CurrentColor {
            d.write_char(' ');
            self.color.to_css(d);
        }
    }
}

fn parse_filter(p: &mut Parser) -> PResult<Filter> {
    let loc = p.location();
    match p.next()?.clone() {
        Token::UnquotedUrl(u) => Ok(Filter::Url(u)),
        Token::Function(f) => {
            let l = f.to_ascii_lowercase();
            p.parse_nested_block(|p| {
                Ok(match l.as_str() {
                    "url" => Filter::Url(p.expect_string()?.to_string()),
                    "blur" => Filter::Fn(l.clone(), p.try_parse(parse_length).ok()),
                    "brightness" | "contrast" | "grayscale" | "invert" | "opacity" | "saturate" | "sepia" => {
                        Filter::Fn(l.clone(), p.try_parse(|p| parse_numval(p, C_NUM | C_PCT, false)).ok())
                    }
                    "hue-rotate" => Filter::Fn(l.clone(), p.try_parse(|p| parse_angle(p, true)).ok()),
                    "drop-shadow" => Filter::DropShadow(parse_shadow(p, false)?),
                    _ => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f.clone())), loc)),
                })
            })
        }
        t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    }
}

impl Filter {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            Filter::Url(u) => crate::url::write_url(d, u),
            Filter::DropShadow(s) => {
                d.write_str("drop-shadow(");
                s.to_css(d);
                d.write_char(')');
            }
            Filter::Fn(n, v) => {
                d.write_str(n);
                d.write_char('(');
                if let Some(v) = v {
                    let is_default = match (n.as_str(), v) {
                        ("blur", v) => v.is_zero(),
                        ("hue-rotate", v) => v.is_zero(),
                        (_, NumVal::D(dd)) => dd.v == 1.0 && (dd.unit.is_empty() || dd.unit == "%"),
                        _ => false,
                    };
                    if !is_default {
                        match v {
                            NumVal::D(dd) if dd.cat() == Cat::Angle => write_angle(d, dd.v, &dd.unit, false),
                            _ => v.to_css(d),
                        }
                    }
                }
                d.write_char(')');
            }
        }
    }
}

const GEOM_BOXES: &[&str] = &["border-box", "padding-box", "content-box", "margin-box", "fill-box", "stroke-box", "view-box"];

fn parse_shape(p: &mut Parser) -> PResult<Shape> {
    let loc = p.location();
    let f = p.expect_function()?.to_ascii_lowercase();
    p.parse_nested_block(|p| {
        Ok(match f.as_str() {
            "inset" => {
                let mut v = vec![parse_length_percentage(p)?];
                while v.len() < 4 {
                    match p.try_parse(parse_length_percentage) {
                        Ok(x) => v.push(x),
                        Err(_) => break,
                    }
                }
                let rect = expand4(v);
                let round = if p.try_ident_matching("round") {
                    let mut h = vec![parse_length_percentage(p)?];
                    while h.len() < 4 {
                        match p.try_parse(parse_length_percentage) {
                            Ok(x) => h.push(x),
                            Err(_) => break,
                        }
                    }
                    let h = expand4(h);
                    let vv = if p.try_delim('/') {
                        let mut v = vec![parse_length_percentage(p)?];
                        while v.len() < 4 {
                            match p.try_parse(parse_length_percentage) {
                                Ok(x) => v.push(x),
                                Err(_) => break,
                            }
                        }
                        expand4(v)
                    } else {
                        h.clone()
                    };
                    Some(h.into_iter().zip(vv).collect())
                } else {
                    None
                };
                Shape::Inset(rect, round)
            }
            "circle" => {
                let r = p.try_parse(parse_length_percentage).ok();
                let ext = if r.is_none() { p.try_parse(|p| expect_keyword(p, &["closest-side", "farthest-side"])).ok() } else { None };
                let pos = if p.try_ident_matching("at") { Position::parse(p)? } else { Position::center() };
                Shape::Circle(r, ext, pos)
            }
            "ellipse" => {
                let r = p.try_parse(|p| Ok((parse_length_percentage(p)?, parse_length_percentage(p)?))).ok();
                let pos = if p.try_ident_matching("at") { Position::parse(p)? } else { Position::center() };
                Shape::Ellipse(r, None, pos)
            }
            "polygon" => {
                let rule = p
                    .try_parse(|p| {
                        let r = expect_keyword(p, &["nonzero", "evenodd"])?;
                        p.expect_comma()?;
                        Ok(r)
                    })
                    .ok();
                let pts = parse_comma_list(p, |p| Ok((parse_length_percentage(p)?, parse_length_percentage(p)?)))?;
                Shape::Polygon(rule, pts)
            }
            _ => return Err(p.err_at(ErrorKind::UnexpectedToken(Token::Function(f.clone())), loc)),
        })
    })
}

fn expand4<T: Clone>(v: Vec<T>) -> Vec<T> {
    let a = v[0].clone();
    let b = v.get(1).cloned().unwrap_or_else(|| a.clone());
    let c = v.get(2).cloned().unwrap_or_else(|| a.clone());
    let dd = v.get(3).cloned().unwrap_or_else(|| b.clone());
    vec![a, b, c, dd]
}

impl Shape {
    fn to_css(&self, d: &mut Printer) {
        match self {
            Shape::Inset(r, round) => {
                d.write_str("inset(");
                crate::pvals::write_rect_generic(d, r, |x, d| x.to_css(d));
                if let Some(rr) = round {
                    d.write_str(" round ");
                    let h: Vec<NumVal> = rr.iter().map(|x| x.0.clone()).collect();
                    let v: Vec<NumVal> = rr.iter().map(|x| x.1.clone()).collect();
                    crate::pvals::write_rect_generic(d, &h, |x, d| x.to_css(d));
                    if h != v {
                        d.delim('/', true);
                        crate::pvals::write_rect_generic(d, &v, |x, d| x.to_css(d));
                    }
                }
                d.write_char(')');
            }
            Shape::Circle(r, e, pos) => {
                d.write_str("circle(");
                let mut sp = false;
                if let Some(r) = r {
                    r.to_css(d);
                    sp = true;
                } else if let Some(e) = e {
                    if e != "closest-side" {
                        d.write_str(e);
                        sp = true;
                    }
                }
                if !pos.x.is_center() || !pos.y.is_center() {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str("at ");
                    pos.to_css(d);
                }
                d.write_char(')');
            }
            Shape::Ellipse(r, _, pos) => {
                d.write_str("ellipse(");
                let mut sp = false;
                if let Some((a, b)) = r {
                    a.to_css(d);
                    d.write_char(' ');
                    b.to_css(d);
                    sp = true;
                }
                if !pos.x.is_center() || !pos.y.is_center() {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str("at ");
                    pos.to_css(d);
                }
                d.write_char(')');
            }
            Shape::Polygon(rule, pts) => {
                d.write_str("polygon(");
                if let Some(r) = rule {
                    if r != "nonzero" {
                        d.write_str(r);
                        d.delim(',', false);
                    }
                }
                write_comma_list(d, pts, |(x, y), d| {
                    x.to_css(d);
                    d.write_char(' ');
                    y.to_css(d);
                });
                d.write_char(')');
            }
            Shape::Other(n, tl) => {
                d.write_str(n);
                d.write_char('(');
                tl.to_css(d, false);
                d.write_char(')');
            }
        }
    }
}

fn parse_clip_path(p: &mut Parser) -> PResult<ClipPath> {
    if p.try_ident_matching("none") {
        return Ok(ClipPath::None);
    }
    if let Ok(u) = p.try_parse(|p| p.expect_url()) {
        return Ok(ClipPath::Url(u));
    }
    if let Ok(s) = p.try_parse(parse_shape) {
        let b = p.try_parse(|p| expect_keyword(p, GEOM_BOXES)).ok();
        return Ok(ClipPath::Shape(s, b));
    }
    let b = expect_keyword(p, GEOM_BOXES)?;
    if let Ok(s) = p.try_parse(parse_shape) {
        return Ok(ClipPath::Shape(s, Some(b)));
    }
    Ok(ClipPath::Box(b))
}

impl ClipPath {
    fn to_css(&self, d: &mut Printer) {
        match self {
            ClipPath::None => d.write_str("none"),
            ClipPath::Url(u) => crate::url::write_url(d, u),
            ClipPath::Box(b) => d.write_str(b),
            ClipPath::Shape(s, b) => {
                s.to_css(d);
                if let Some(b) = b {
                    if b != "border-box" {
                        d.write_char(' ');
                        d.write_str(b);
                    }
                }
            }
        }
    }
}

const MASK_ORIGINS: &[&str] = &["border-box", "padding-box", "content-box", "fill-box", "stroke-box", "view-box"];

fn parse_mask_layer(p: &mut Parser) -> PResult<Mask> {
    let mut image = None;
    let mut pos = None;
    let mut size = None;
    let mut repeat = None;
    let mut origin = None;
    let mut clip = None;
    let mut composite = None;
    let mut mode = None;
    loop {
        if image.is_none() {
            if let Ok(i) = p.try_parse(Image::parse) {
                image = Some(i);
                continue;
            }
        }
        if pos.is_none() {
            if let Ok(ps) = p.try_parse(Position::parse) {
                pos = Some(ps);
                size = p
                    .try_parse(|p| {
                        p.expect_delim('/')?;
                        crate::background::parse_size(p)
                    })
                    .ok();
                continue;
            }
        }
        if repeat.is_none() {
            if let Ok(r) = p.try_parse(crate::background::parse_repeat) {
                repeat = Some(r);
                continue;
            }
        }
        if origin.is_none() {
            if let Ok(o) = p.try_parse(|p| expect_keyword(p, MASK_ORIGINS)) {
                origin = Some(o);
                continue;
            }
        }
        if clip.is_none() {
            if let Ok(c) = p.try_parse(|p| {
                let mut v = MASK_ORIGINS.to_vec();
                v.push("no-clip");
                expect_keyword(p, &v)
            }) {
                clip = Some(c);
                continue;
            }
        }
        if composite.is_none() {
            if let Ok(c) = p.try_parse(|p| expect_keyword(p, &["add", "subtract", "intersect", "exclude"])) {
                composite = Some(c);
                continue;
            }
        }
        if mode.is_none() {
            if let Ok(m) = p.try_parse(|p| expect_keyword(p, &["alpha", "luminance", "match-source"])) {
                mode = Some(m);
                continue;
            }
        }
        break;
    }
    if clip.is_none() {
        if let Some(o) = &origin {
            clip = Some(o.clone());
        }
    }
    Ok(Mask {
        image: image.unwrap_or(Image::None),
        pos: pos.unwrap_or_else(Position::zero),
        size: size.unwrap_or(crate::background::BgSize::Explicit(crate::pvals::LPA::Auto, crate::pvals::LPA::Auto)),
        repeat: repeat.unwrap_or(crate::background::Repeat("repeat".into(), "repeat".into())),
        origin: origin.unwrap_or_else(|| "border-box".into()),
        clip: clip.unwrap_or_else(|| "border-box".into()),
        composite: composite.unwrap_or_else(|| "add".into()),
        mode: mode.unwrap_or_else(|| "match-source".into()),
    })
}

impl Mask {
    fn to_css(&self, d: &mut Printer) {
        self.image.to_css(d);
        if !self.pos.is_zero() || !self.size.is_default() {
            d.write_char(' ');
            self.pos.to_css(d);
            if !self.size.is_default() {
                d.delim('/', true);
                self.size.to_css(d);
            }
        }
        if !self.repeat.is_default() {
            d.write_char(' ');
            self.repeat.to_css(d);
        }
        if self.origin != "border-box" || self.clip != "border-box" {
            d.write_char(' ');
            d.write_str(&self.origin);
            if self.clip != self.origin {
                d.write_char(' ');
                d.write_str(&self.clip);
            }
        }
        if self.composite != "add" {
            d.write_char(' ');
            d.write_str(&self.composite);
        }
        if self.mode != "match-source" {
            d.write_char(' ');
            d.write_str(&self.mode);
        }
    }
}

impl EffectValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            EffectValue::Shadows(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            EffectValue::NoShadow | EffectValue::NoFilter => d.write_str("none"),
            EffectValue::Filters(v) => {
                for f in v {
                    f.to_css(d);
                }
            }
            EffectValue::Clip(c) => c.to_css(d),
            EffectValue::Masks(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            EffectValue::MaskImages(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            EffectValue::Keywords(v) => write_comma_list(d, v, |x, d| d.write_str(x)),
            EffectValue::MaskPositions(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            EffectValue::MaskSizes(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
            EffectValue::MaskRepeats(v) => write_comma_list(d, v, |x, d| x.to_css(d)),
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "box-shadow" | "text-shadow" => {
            if p.try_ident_matching("none") {
                Ok(EffectValue::NoShadow)
            } else {
                parse_comma_list(p, |p| parse_shadow(p, n == "box-shadow")).map(EffectValue::Shadows)
            }
        }
        "filter" | "backdrop-filter" => {
            if p.try_ident_matching("none") {
                Ok(EffectValue::NoFilter)
            } else {
                (|| {
                    let mut v = vec![parse_filter(p)?];
                    while let Ok(f) = p.try_parse(parse_filter) {
                        v.push(f);
                    }
                    Ok(EffectValue::Filters(v))
                })()
            }
        }
        "clip-path" => parse_clip_path(p).map(EffectValue::Clip),
        "mask" => parse_comma_list(p, parse_mask_layer).map(EffectValue::Masks),
        "mask-image" => parse_comma_list(p, Image::parse).map(EffectValue::MaskImages),
        "mask-mode" => parse_comma_list(p, |p| expect_keyword(p, &["alpha", "luminance", "match-source"])).map(EffectValue::Keywords),
        "mask-composite" => parse_comma_list(p, |p| expect_keyword(p, &["add", "subtract", "intersect", "exclude"])).map(EffectValue::Keywords),
        "mask-origin" => parse_comma_list(p, |p| expect_keyword(p, MASK_ORIGINS)).map(EffectValue::Keywords),
        "mask-clip" => parse_comma_list(p, |p| {
            let mut v = MASK_ORIGINS.to_vec();
            v.push("no-clip");
            expect_keyword(p, &v)
        })
        .map(EffectValue::Keywords),
        "mask-type" => return Some(expect_keyword(p, &["luminance", "alpha"]).map(Value::Ident)),
        "mask-position" => parse_comma_list(p, Position::parse).map(EffectValue::MaskPositions),
        "mask-size" => parse_comma_list(p, crate::background::parse_size).map(EffectValue::MaskSizes),
        "mask-repeat" => parse_comma_list(p, crate::background::parse_repeat).map(EffectValue::MaskRepeats),
        _ => return None,
    };
    Some(r.map(Value::Effect))
}

