}

const LINES: &[&str] = &["underline", "overline", "line-through", "blink", "spelling-error", "grammar-error"];
const DSTYLES: &[&str] = &["solid", "double", "dotted", "dashed", "wavy"];

fn parse_line(p: &mut Parser) -> PResult<Vec<String>> {
    if p.try_ident_matching("none") {
        return Ok(vec!["none".into()]);
    }
    let mut v: Vec<String> = Vec::new();
    while let Ok(k) = p.try_parse(|p| expect_keyword(p, LINES)) {
        if v.contains(&k) {
            return p.invalid();
        }
        v.push(k);
    }
    if v.is_empty() {
        return p.invalid();
    }
    Ok(v)
}

fn parse_thickness(p: &mut Parser) -> PResult<Thickness> {
    if p.try_ident_matching("auto") {
        return Ok(Thickness::Auto);
    }
    if p.try_ident_matching("from-font") {
        return Ok(Thickness::FromFont);
    }
    Ok(Thickness::V(parse_length_percentage(p)?))
}

impl Thickness {
    fn to_css(&self, d: &mut Printer) {
        match self {
            Thickness::Auto => d.write_str("auto"),
            Thickness::FromFont => d.write_str("from-font"),
            Thickness::V(v) => v.to_css(d),
        }
    }
}

fn parse_decoration(p: &mut Parser) -> PResult<TextValue> {
    let mut line = None;
    let mut thick = None;
    let mut style = None;
    let mut color = None;
    loop {
        if line.is_none() {
            if let Ok(l) = p.try_parse(parse_line) {
                line = Some(l);
                continue;
            }
        }
        if thick.is_none() {
            if let Ok(t) = p.try_parse(parse_thickness) {
                thick = Some(t);
                continue;
            }
        }
        if style.is_none() {
            if let Ok(s) = p.try_parse(|p| expect_keyword(p, DSTYLES)) {
                style = Some(s);
                continue;
            }
        }
        if color.is_none() {
            if let Ok(c) = p.try_parse(CssColor::parse) {
                color = Some(c);
                continue;
            }
        }
        break;
    }
    if line.is_none() && thick.is_none() && style.is_none() && color.is_none() {
        return p.invalid();
    }
    Ok(TextValue::Decoration(
        line.unwrap_or_else(|| vec!["none".into()]),
        thick.unwrap_or(Thickness::Auto),
        style.unwrap_or_else(|| "solid".into()),
        color.unwrap_or(CssColor::CurrentColor),
    ))
}

fn parse_emph_style(p: &mut Parser) -> PResult<EmphStyle> {
    if p.try_ident_matching("none") {
        return Ok(EmphStyle::None);
    }
    if let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
        return Ok(EmphStyle::Str(s));
    }
    let mut fill = None;
    let mut shape = None;
    loop {
        if fill.is_none() {
            if let Ok(f) = p.try_parse(|p| expect_keyword(p, &["filled", "open"])) {
                fill = Some(f);
                continue;
            }
        }
        if shape.is_none() {
            if let Ok(s) = p.try_parse(|p| expect_keyword(p, &["dot", "circle", "double-circle", "triangle", "sesame"])) {
                shape = Some(s);
                continue;
            }
        }
        break;
    }
    if fill.is_none() && shape.is_none() {
        return p.invalid();
    }
    Ok(EmphStyle::Kw(fill, shape))
}

impl EmphStyle {
    fn to_css(&self, d: &mut Printer) {
        match self {
            EmphStyle::None => d.write_str("none"),
            EmphStyle::Str(s) => d.write_string(s),
            EmphStyle::Kw(f, s) => {
                let mut sp = false;
                if let Some(f) = f {
                    if f != "filled" || s.is_none() {
                        d.write_str(f);
                        sp = true;
                    }
                }
                if let Some(s) = s {
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str(s);
                }
            }
        }
    }
}

impl TextValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            TextValue::Line(v) => {
                for (i, s) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_char(' ');
                    }
                    d.write_str(s);
                }
            }
            TextValue::Style(s) => d.write_str(s),
            TextValue::Thickness(t) => t.to_css(d),
            TextValue::Decoration(line, thick, style, color) => {
                for (i, s) in line.iter().enumerate() {
                    if i > 0 {
                        d.write_char(' ');
                    }
                    d.write_str(s);
                }
                if *thick != Thickness::Auto {
                    d.write_char(' ');
                    thick.to_css(d);
                }
                if style != "solid" {
                    d.write_char(' ');
                    d.write_str(style);
                }
                if *color != CssColor::CurrentColor {
                    d.write_char(' ');
                    color.to_css(d);
                }
            }
            TextValue::EmphStyle(s) => s.to_css(d),
            TextValue::Emphasis(s, c) => {
                s.to_css(d);
                if *c != CssColor::CurrentColor {
                    d.write_char(' ');
                    c.to_css(d);
                }
            }
            TextValue::EmphPosition(a, b) => {
                d.write_str(a);
                if b != "right" {
                    d.write_char(' ');
                    d.write_str(b);
                }
            }
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
