            loop {
                if style.is_none() {
                    if let Ok(s) = p.try_parse(parse_emph_style) {
                        style = Some(s);
                        continue;
                    }
                }
                if color.is_none() {
                    if let Ok(c) = p.try_parse(CssColor::parse) {
                        color = Some(c);
                        continue;
                    }
                }
                break;
            }
            if style.is_none() && color.is_none() {
                return p.invalid();
            }
            Ok(TextValue::Emphasis(style.unwrap_or(EmphStyle::None), color.unwrap_or(CssColor::CurrentColor)))
        })(),
        "text-emphasis-position" => (|| {
            let mut a = None;
