use crate::image::Image;
use crate::parser::*;
use crate::printer::Printer;
use crate::properties::*;
use crate::tokenizer::Token;

#[derive(Clone, Debug, PartialEq)]
pub enum LType {
    None,
    Ident(String),
    Str(String),
    Symbols(crate::tokenlist::TokenList),
}

#[derive(Clone, Debug, PartialEq)]
pub enum ListValue {
    Type(LType),
    Image(Image),
    Position(String),
    Shorthand(String, Image, LType),
}

fn parse_type(p: &mut Parser) -> PResult<LType> {
    if p.try_ident_matching("none") {
        return Ok(LType::None);
    }
    let loc = p.location();
    match p.next()?.clone() {
        Token::QuotedString(s) => Ok(LType::Str(s)),
        Token::Ident(s) => {
            let l = s.to_ascii_lowercase();
            if matches!(l.as_str(), "inherit" | "initial" | "unset" | "default" | "revert" | "revert-layer") {
                return Err(p.err_at(ErrorKind::InvalidValue, loc));
            }
            Ok(LType::Ident(s))
        }
        Token::Function(f) if f.eq_ignore_ascii_case("symbols") => Ok(LType::Symbols(p.parse_nested_block(crate::tokenlist::TokenList::parse)?)),
        t => Err(p.err_at(ErrorKind::UnexpectedToken(t), loc)),
    }
}

impl LType {
    fn to_css(&self, d: &mut Printer) {
        match self {
            LType::None => d.write_str("none"),
            LType::Ident(s) => crate::css_modules::write_local_ident_kind(d, s, crate::css_modules::Kind::CounterStyle),
            LType::Str(s) => d.write_string(s),
            LType::Symbols(tl) => {
                d.write_str("symbols(");
                tl.to_css(d, false);
                d.write_char(')');
            }
        }
    }
    fn is_default(&self) -> bool {
        matches!(self, LType::Ident(s) if s == "disc")
    }
}

fn parse_shorthand(p: &mut Parser) -> PResult<ListValue> {
    let mut pos = None;
    let mut img = None;
    let mut ty = None;
    let mut nones = 0;
    loop {
        if p.try_ident_matching("none") {
            nones += 1;
            continue;
        }
        if pos.is_none() {
            if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["inside", "outside"])) {
                pos = Some(k);
                continue;
            }
        }
        if img.is_none() {
            if let Ok(i) = p.try_parse(Image::parse) {
                img = Some(i);
                continue;
            }
        }
        if ty.is_none() {
            if let Ok(t) = p.try_parse(parse_type) {
                ty = Some(t);
                continue;
            }
        }
        break;
    }
    if nones > 2 {
        return p.invalid();
    }
    let (img, ty) = match (img, ty, nones) {
        (i, t, 0) => (i.unwrap_or(Image::None), t.unwrap_or(LType::Ident("disc".into()))),
        (None, None, _) => (Image::None, LType::None),
        (Some(i), None, 1) => (i, LType::None),
        (None, Some(t), 1) => (Image::None, t),
        _ => return p.invalid(),
    };
    Ok(ListValue::Shorthand(pos.unwrap_or_else(|| "outside".into()), img, ty))
}

impl ListValue {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            ListValue::Type(t) => t.to_css(d),
            ListValue::Image(i) => i.to_css(d),
            ListValue::Position(p) => d.write_str(p),
            ListValue::Shorthand(pos, img, ty) => {
                let mut sp = false;
                if pos != "outside" || (*img == Image::None && ty.is_default()) {
                    d.write_str(pos);
                    sp = true;
                }
                if *img != Image::None {
                    if sp {
                        d.write_char(' ');
                    }
                    img.to_css(d);
                    sp = true;
                }
                if !ty.is_default() {
                    if sp {
                        d.write_char(' ');
                    }
                    ty.to_css(d);
                }
            }
        }
    }
}

pub fn parse(n: &str, p: &mut Parser) -> Option<PResult<Value>> {
    let r = match n {
        "list-style-type" => parse_type(p).map(ListValue::Type),
        "list-style-image" => Image::parse(p).map(ListValue::Image),
        "list-style-position" => expect_keyword(p, &["inside", "outside"]).map(ListValue::Position),
        "list-style" => parse_shorthand(p),
        _ => return None,
    };
    Some(r.map(Value::List))
}

#[derive(Default)]
pub struct ListHandler {
    pos: Option<String>,
    img: Option<Image>,
    ty: Option<LType>,
    has_any: bool,
}

fn lp(name: &str, v: ListValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::List(v))
}

impl ListHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (pos, img, ty) = (self.pos.take(), self.img.take(), self.ty.take());
        if let (Some(p), Some(i), Some(t)) = (&pos, &img, &ty) {
            out.push(lp("list-style", ListValue::Shorthand(p.clone(), i.clone(), t.clone())));
            return;
        }
        if let Some(t) = ty {
            out.push(lp("list-style-type", ListValue::Type(t)));
        }
        if let Some(i) = img {
            out.push(lp("list-style-image", ListValue::Image(i)));
        }
        if let Some(p) = pos {
            out.push(lp("list-style-position", ListValue::Position(p)));
        }
    }
}

impl crate::handlers::Handler for ListHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !id.name.starts_with("list-style") {
            return false;
        }
        match p {
            Property::Val(_, Value::List(v)) => {
                self.has_any = true;
                match v {
                    ListValue::Type(t) => self.ty = Some(t.clone()),
                    ListValue::Image(i) => self.img = Some(i.clone()),
                    ListValue::Position(x) => self.pos = Some(x.clone()),
                    ListValue::Shorthand(a, b, c) => {
                        self.pos = Some(a.clone());
                        self.img = Some(b.clone());
                        self.ty = Some(c.clone());
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
