pub enum DisplayValue {
    Kw(String),
    Pair(String, String, bool),
    Overflow(String, String),
}

const DISPLAY_KW: &[&str] = &[
    "none", "contents", "table-row-group", "table-header-group", "table-footer-group", "table-row", "table-cell",
    "table-column-group", "table-column", "table-caption", "ruby-base", "ruby-text", "ruby-base-container",
    "ruby-text-container", "-webkit-box", "-moz-box", "-webkit-inline-box", "-moz-inline-box", "-webkit-flex",
    "-ms-flexbox", "-webkit-inline-flex", "-ms-inline-flexbox", "-ms-grid", "-ms-inline-grid",
];

fn parse_display(p: &mut Parser) -> PResult<DisplayValue> {
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, DISPLAY_KW)) {
        return Ok(DisplayValue::Kw(k));
    }
    // legacy single keywords
    if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["inline-block", "inline-table", "inline-flex", "inline-grid", "inline-list-item"])) {
        return Ok(match k.as_str() {
            "inline-block" => DisplayValue::Pair("inline".into(), "flow-root".into(), false),
            "inline-table" => DisplayValue::Pair("inline".into(), "table".into(), false),
            "inline-flex" => DisplayValue::Pair("inline".into(), "flex".into(), false),
            "inline-grid" => DisplayValue::Pair("inline".into(), "grid".into(), false),
            _ => DisplayValue::Pair("inline".into(), "flow".into(), true),
        });
    }
    let mut outside = None;
    let mut inside = None;
    let mut list = false;
    loop {
        if outside.is_none() {
            if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["block", "inline", "run-in"])) {
                outside = Some(k);
                continue;
            }
        }
        if inside.is_none() {
            if let Ok(k) = p.try_parse(|p| expect_keyword(p, &["flow", "flow-root", "table", "flex", "grid", "ruby", "math"])) {
                inside = Some(k);
                continue;
            }
        }
        if !list && p.try_ident_matching("list-item") {
            list = true;
            continue;
        }
        break;
    }
    if outside.is_none() && inside.is_none() && !list {
        return p.invalid();
    }
    let inside_v = inside.clone().unwrap_or_else(|| "flow".into());
    if list && !(inside_v == "flow" || inside_v == "flow-root") {
        return p.invalid();
    }
    let outside_v = outside.unwrap_or_else(|| if inside.as_deref() == Some("ruby") { "inline".into() } else { "block".into() });
    Ok(DisplayValue::Pair(outside_v, inside_v, list))
}

impl DisplayValue {
    pub fn to_css(&self, d: &mut Printer, _prefix: u8) {
        match self {
            DisplayValue::Kw(k) => d.write_str(k),
            DisplayValue::Overflow(x, y) => {
                d.write_str(x);
                if x != y {
                    d.write_char(' ');
                    d.write_str(y);
                }
            }
            DisplayValue::Pair(o, i, list) => {
                let (o, i) = (o.as_str(), i.as_str());
                if *list {
                    if o == "block" && i == "flow" {
                        d.write_str("list-item");
                        return;
                    }
                    let mut sp = false;
                    if o != "block" {
                        d.write_str(o);
                        sp = true;
                    }
                    if i != "flow" {
                        if sp {
                            d.write_char(' ');
                        }
                        d.write_str(i);
                        sp = true;
                    }
                    if sp {
                        d.write_char(' ');
                    }
                    d.write_str("list-item");
                    return;
                }
                let s = match (o, i) {
                    ("inline", "flow-root") => "inline-block".to_string(),
                    ("inline", "flex") => "inline-flex".to_string(),
                    ("inline", "grid") => "inline-grid".to_string(),
                    ("inline", "table") => "inline-table".to_string(),
                    ("inline", "flow") => "inline".to_string(),
                    ("inline", "ruby") => "ruby".to_string(),
                    ("block", "flow") => "block".to_string(),
                    ("block", "ruby") => "block ruby".to_string(),
                    ("block", "math") => "block math".to_string(),
                    ("inline", "math") => "math".to_string(),
                    ("block", x) => x.to_string(),
                    ("run-in", "flow") => "run-in".to_string(),
                    (a, b) => format!("{} {}", a, b),
                };
                d.write_str(&s);
            }
        }
    }
}

