            ListValue::Position(p) => d.write_str(p),
            ListValue::Shorthand(pos, img, ty) => {
                let mut sp = false;
                if pos != "outside" || (*img == Image::None && ty.is_default()) {
                    d.write_str(pos);
                    sp = true;
                }
                if *img != Image::None {
                    if sp {
                        d.write_char(' ');
                    }
                    img.to_css(d);
                    sp = true;
                }
