        "list-style-position" => expect_keyword(p, &["inside", "outside"]).map(ListValue::Position),
        "list-style" => parse_shorthand(p),
        _ => return None,
    };
    Some(r.map(Value::List))
}

#[derive(Default)]
pub struct ListHandler {
    pos: Option<String>,
    img: Option<Image>,
    ty: Option<LType>,
    has_any: bool,
}

fn lp(name: &str, v: ListValue) -> Property {
    Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::List(v))
}

impl ListHandler {
    fn flush(&mut self, out: &mut Vec<Property>) {
        if !self.has_any {
            return;
        }
        self.has_any = false;
        let (pos, img, ty) = (self.pos.take(), self.img.take(), self.ty.take());
        if let (Some(p), Some(i), Some(t)) = (&pos, &img, &ty) {
            out.push(lp("list-style", ListValue::Shorthand(p.clone(), i.clone(), t.clone())));
            return;
        }
        if let Some(t) = ty {
            out.push(lp("list-style-type", ListValue::Type(t)));
        }
        if let Some(i) = img {
            out.push(lp("list-style-image", ListValue::Image(i)));
        }
        if let Some(p) = pos {
            out.push(lp("list-style-position", ListValue::Position(p)));
        }
    }
}

impl crate::handlers::Handler for ListHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        let id = match p.id() {
            Some(i) => i,
            None => return false,
        };
        if !id.name.starts_with("list-style") {
            return false;
        }
        match p {
            Property::Val(_, Value::List(v)) => {
                self.has_any = true;
                match v {
                    ListValue::Type(t) => self.ty = Some(t.clone()),
                    ListValue::Image(i) => self.img = Some(i.clone()),
                    ListValue::Position(x) => self.pos = Some(x.clone()),
                    ListValue::Shorthand(a, b, c) => {
                        self.pos = Some(a.clone());
                        self.img = Some(b.clone());
                        self.ty = Some(c.clone());
                    }
                }
            }
            _ => {
                self.flush(out);
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        self.flush(out);
    }
}
