cat > fontface.rs <<'EOF'
// @font-face, @font-palette-values, @font-feature-values
use crate::decl::*;
use crate::parser::*;
use crate::printer::Printer;
use crate::properties::{PropId, Property, Value};
use crate::rules::FontFeatureValuesRule;
use crate::tokenizer::Token;

#[derive(Clone, Debug, PartialEq)]
pub enum Source {
    Url(String, Option<String>, Vec<String>),
    Local(String),
}

#[derive(Clone, Debug, PartialEq)]
pub enum FFValue {
    Src(Vec<Source>),
    Family(String),
    Weight(Vec<crate::font::Weight>),
    Style(crate::font::FStyle, Option<crate::values::NumVal>),
    Stretch(Vec<crate::font::Stretch>),
    Range(Vec<(u32, u32)>),
}

fn parse_family_name(p: &mut Parser) -> PResult<String> {
    if let Ok(s) = p.try_parse(|p| p.expect_string().map(|s| s.to_string())) {
        return Ok(s);
    }
    let mut name = p.expect_ident_cloned()?;
    while let Ok(s) = p.try_parse(|p| p.expect_ident_cloned()) {
        name.push(' ');
        name.push_str(&s);
    }
    Ok(name)
}

fn parse_source(p: &mut Parser) -> PResult<Source> {
    if let Ok(n) = p.try_parse(|p| {
        p.expect_function_matching("local")?;
        p.parse_nested_block(parse_family_name)
    }) {
        return Ok(Source::Local(n));
    }
    let u = p.expect_url()?;
    let fmt = p
        .try_parse(|p| {
            p.expect_function_matching("format")?;
            p.parse_nested_block(|p| Ok(p.expect_ident_or_string()?.to_string()))
        })
        .ok();
    let tech = p
        .try_parse(|p| {
            p.expect_function_matching("tech")?;
            p.parse_nested_block(|p| {
                let mut v = Vec::new();
                loop {
                    v.push(p.expect_ident()?.to_string());
                    if !p.try_comma() {
                        break;
                    }
                }
                Ok(v)
            })
        })
        .unwrap_or_default();
    Ok(Source::Url(u, fmt, tech))
}

fn parse_hex_range(s: &str) -> Option<(u32, u32)> {
    let s = s.trim();
    let rest = s.strip_prefix("U+").or_else(|| s.strip_prefix("u+"))?;
    if let Some((a, b)) = rest.split_once('-') {
        let a = u32::from_str_radix(a, 16).ok()?;
        let b = u32::from_str_radix(b, 16).ok()?;
        if a > b || b > 0x10FFFF || a > 0x10FFFF {
            return None;
        }
        return Some((a, b));
    }
    if rest.contains('?') {
        let lo = rest.replace('?', "0");
        let hi = rest.replace('?', "F");
        let a = u32::from_str_radix(&lo, 16).ok()?;
        let b = u32::from_str_radix(&hi, 16).ok()?;
        return Some((a, b));
    }
    let a = u32::from_str_radix(rest, 16).ok()?;
    Some((a, a))
}

fn parse_ranges(p: &mut Parser) -> PResult<Vec<(u32, u32)>> {
    let mut v = Vec::new();
    loop {
        let r = p.parse_until_before(D_COMMA, |p| {
            p.skip_whitespace();
            let start = p.byte_pos();
            while p.next_including_whitespace_and_comments().is_ok() {}
            let end = p.byte_pos_end();
            let text: String = p.src[start..end].chars().filter(|c| !c.is_whitespace()).collect();
            parse_hex_range(&text).ok_or_else(|| p.err(ErrorKind::InvalidValue))
        })?;
        v.push(r);
        if !p.try_comma() {
            break;
        }
    }
    Ok(v)
}

fn write_range(d: &mut Printer, start: u32, end: u32) {
    if start != end {
        let mut shift: i32 = 24;
        let mut mask: u32 = 0xf << shift;
        while shift > 0 {
            let c1 = start & mask;
            let c2 = end & mask;
            if c1 != c2 {
                break;
            }
            mask >>= 4;
            shift -= 4;
        }
        shift += 4;
        let rmask: u32 = (1u32 << shift) - 1;
        if start & rmask == 0 && end & rmask == rmask {
            let s = (start & !rmask) >> shift;
            if s != 0 {
                d.write_str(&format!("U+{:X}", s));
            } else {
                d.write_str("U+");
            }
            while shift > 0 {
                d.write_char('?');
                shift -= 4;
            }
            return;
        }
    }
    d.write_str(&format!("U+{:X}", start));
    if end != start {
        d.write_str(&format!("-{:X}", end));
    }
}

impl FFValue {
    pub fn to_css(&self, d: &mut Printer) {
        match self {
            FFValue::Src(v) => {
                for (i, s) in v.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    match s {
                        Source::Local(n) => {
                            d.write_str("local(");
                            crate::font::write_family_name(d, n);
                            d.write_char(')');
                        }
                        Source::Url(u, f, t) => {
                            crate::url::write_url(d, u);
                            if let Some(f) = f {
                                d.whitespace();
                                d.write_str("format(");
                                d.write_string(f);
                                d.write_char(')');
                            }
                            if !t.is_empty() {
                                d.whitespace();
                                d.write_str("tech(");
                                for (j, x) in t.iter().enumerate() {
                                    if j > 0 {
                                        d.delim(',', false);
                                    }
                                    d.write_str(x);
                                }
                                d.write_char(')');
                            }
                        }
                    }
                }
            }
            FFValue::Family(f) => crate::font::write_family_name(d, f),
            FFValue::Weight(v) => {
                for (i, w) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_char(' ');
                    }
                    w.to_css(d);
                }
            }
            FFValue::Style(s, a2) => {
                s.to_css(d);
                if let Some(a2) = a2 {
                    if let crate::font::FStyle::Oblique(Some(_)) = s {
                        d.write_char(' ');
                        a2.to_css(d);
                    }
                }
            }
            FFValue::Stretch(v) => {
                for (i, w) in v.iter().enumerate() {
                    if i > 0 {
                        d.write_char(' ');
                    }
                    w.to_css(d);
                }
            }
            FFValue::Range(v) => {
                for (i, (a, b)) in v.iter().enumerate() {
                    if i > 0 {
                        d.delim(',', false);
                    }
                    write_range(d, *a, *b);
                }
            }
        }
    }
}

fn parse_ff_value(name: &str, p: &mut Parser) -> PResult<FFValue> {
    match name {
        "src" => Ok(FFValue::Src(crate::easing::parse_comma_list(p, parse_source)?)),
        "font-family" => Ok(FFValue::Family(parse_family_name(p)?)),
        "font-weight" => {
            let a = crate::font::parse_weight(p)?;
            let mut v = vec![a];
            if let Ok(b) = p.try_parse(crate::font::parse_weight) {
                v.push(b);
            }
            Ok(FFValue::Weight(v))
        }
        "font-style" => {
            let s = crate::font::parse_style(p)?;
            let a2 = if matches!(s, crate::font::FStyle::Oblique(Some(_))) { p.try_parse(|p| crate::values::parse_angle(p, false)).ok() } else { None };
            Ok(FFValue::Style(s, a2))
        }
        "font-stretch" => {
            let a = crate::font::parse_stretch(p)?;
            let mut v = vec![a];
            if let Ok(b) = p.try_parse(crate::font::parse_stretch) {
                v.push(b);
            }
            Ok(FFValue::Stretch(v))
        }
        "unicode-range" => Ok(FFValue::Range(parse_ranges(p)?)),
        _ => p.invalid(),
    }
}

pub fn parse_font_face_block(p: &mut Parser, warnings: &mut Vec<ParseError>) -> PResult<DeclBlock> {
    let mut block = DeclBlock::default();
    loop {
        p.skip_whitespace();
        let loc = p.location();
        let t = match p.next_including_whitespace_and_comments() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        match t {
            Token::Semicolon => continue,
            Token::Ident(name) => {
                let lname = name.to_ascii_lowercase();
                let r = p.parse_until_after(D_SEMI, |p| {
                    p.expect_colon()?;
                    let st = p.state();
                    let v = p.parse_until_before(D_BANG, |p| Ok(p.try_parse(|p| parse_ff_value(&lname, p)).ok()))?;
                    if let Some(v) = v {
                        let important = p.try_parse(|p| { p.expect_delim('!')?; p.expect_ident_matching("important") }).is_ok();
                        p.expect_exhausted()?;
                        return Ok((Property::Val(PropId::new(crate::handler_list::lookup_static(&lname), crate::prefixes::NONE), Value::FontFace(v)), important));
                    }
                    p.reset(st);
                    let tl = p.parse_until_before(D_BANG, crate::tokenlist::TokenList::parse)?;
                    let important = p.try_parse(|p| { p.expect_delim('!')?; p.expect_ident_matching("important") }).is_ok();
                    p.expect_exhausted()?;
                    Ok((Property::Unknown(name.clone(), tl), important))
                });
                match r {
                    Ok((prop, imp)) => {
                        if imp {
                            block.important.push(prop);
                        } else {
                            block.decls.push(prop);
                        }
                    }
                    Err(e) => {
                        if crate::options::error_recovery() {
                            warnings.push(e);
                        } else {
                            return Err(e);
                        }
                    }
                }
            }
            t => {
                let e = p.err_at(ErrorKind::UnexpectedToken(t), loc);
                let _ = p.parse_until_after(D_SEMI, |_| Ok(()));
                if crate::options::error_recovery() {
                    warnings.push(e);
                } else {
                    return Err(e);
                }
            }
        }
    }
    Ok(block)
}

pub fn parse_font_palette_block(p: &mut Parser, warnings: &mut Vec<ParseError>) -> PResult<DeclBlock> {
    parse_declaration_list(p, warnings)
}

pub fn parse_family_list(p: &mut Parser) -> PResult<Vec<String>> {
    let mut v = Vec::new();
    loop {
        v.push(parse_family_name(p)?);
        if !p.try_comma() {
            break;
        }
    }
    Ok(v)
}

pub fn parse_ffv_body(p: &mut Parser) -> PResult<Vec<(String, Vec<(String, Vec<i32>)>)>> {
    let mut out = Vec::new();
    loop {
        p.skip_whitespace();
        let t = match p.next() {
            Ok(t) => t.clone(),
            Err(_) => break,
        };
        if let Token::AtKeyword(name) = t {
            p.parse_until_before(D_CURLY | D_SEMI, |_| Ok(()))?;
            match p.next() {
                Ok(Token::CurlyBracketBlock) => {}
                _ => continue,
            }
            let entries = p.parse_nested_block(|p| {
                let mut v = Vec::new();
                loop {
                    p.skip_whitespace();
                    let n = match p.next() {
                        Ok(Token::Ident(n)) => n.clone(),
                        Ok(_) => continue,
                        Err(_) => break,
                    };
                    let vals = p.parse_until_after(D_SEMI, |p| {
                        p.expect_colon()?;
                        let mut nums = Vec::new();
                        while let Ok(i) = p.try_parse(|p| p.expect_integer()) {
                            nums.push(i);
                        }
                        Ok(nums)
                    })?;
                    v.push((n, vals));
                }
                Ok(v)
            })?;
            out.push((name.to_ascii_lowercase(), entries));
        }
    }
    Ok(out)
}

pub fn ffv_to_css(r: &FontFeatureValuesRule, d: &mut Printer) {
    d.write_str("@font-feature-values ");
    for (i, f) in r.families.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        crate::font::write_family_name(d, f);
    }
    d.whitespace();
    d.write_char('{');
    for (name, entries) in &r.blocks {
        d.newline();
        d.write_char('@');
        d.write_str(name);
        d.write_char('{');
        d.indent();
        let n = entries.len();
        for (i, (k, vals)) in entries.iter().enumerate() {
            d.newline();
            d.write_ident(k);
            d.delim(':', false);
            for (j, v) in vals.iter().enumerate() {
                if j > 0 {
                    d.write_char(' ');
                }
                d.write_str(&v.to_string());
