use crate::parser::*;
use crate::properties::Value;

thread_local! {
    pub static CURRENT_SELECTORS: RefCell<Option<crate::selectors::SelectorList>> = RefCell::new(None);
}

pub fn set_current_selectors(s: &crate::selectors::SelectorList) {
    CURRENT_SELECTORS.with(|c| *c.borrow_mut() = Some(s.clone()));
}

#[derive(Clone, Debug, PartialEq)]
pub struct Composes {
    pub names: Vec<String>,
    pub from: Option<Option<String>>, // None = local, Some(None) = global, Some(Some(spec)) = file
}

pub fn parse_composes(p: &mut Parser) -> PResult<Value> {
    let mut list = Vec::new();
    loop {
        let mut names = Vec::new();
        while let Ok(n) = p.try_parse(|p| {
            let loc = p.location();
            let s = p.expect_ident()?.to_string();
            if s.eq_ignore_ascii_case("from") {
                return Err(p.err_at(ErrorKind::InvalidValue, loc));
            }
            Ok(s)
        }) {
            names.push(n);
        }
        if names.is_empty() {
            return p.invalid();
        }
        let from = if p.try_ident_matching("from") {
            if p.try_ident_matching("global") {
                Some(None)
            } else {
                Some(Some(p.expect_string()?.to_string()))
            }
        } else {
            None
        };
        list.push(Composes { names, from });
        if !p.try_comma() {
            break;
        }
    }
    Ok(Value::Composes(list))
}

pub fn write_composes(d: &mut Printer, v: &[Composes]) {
    for (i, c) in v.iter().enumerate() {
        if i > 0 {
            d.delim(',', false);
        }
        for (j, n) in c.names.iter().enumerate() {
            if j > 0 {
                d.write_char(' ');
            }
            d.write_ident(n);
        }
        match &c.from {
            None => {}
            Some(None) => d.write_str(" from global"),
            Some(Some(s)) => {
                d.write_str(" from ");
                d.write_string(s);
            }
        }
    }
}

pub fn handle_composes(p: &crate::properties::Property) {
    let list = match p {
        crate::properties::Property::Val(_, Value::Composes(l)) => l.clone(),
        _ => return,
    };
    let sels = CURRENT_SELECTORS.with(|c| c.borrow().clone());
    let sels = match sels {
        Some(s) => s,
        None => return,
    };
    for sel in &sels.0 {
        let class = match sel.0.as_slice() {
            [crate::selectors::Comp::S(crate::selectors::Simple::Class(c))] => c.clone(),
            _ => {
                crate::errors_panic::panic_debug(
                    &format!(
                        "Error {{ kind: InvalidComposesSelector, loc: Some(ErrorLocation {{ filename: {:?}, line: 0, column: 1 }}) }}",
                        crate::options::OPTS.with(|o| o.borrow().filename.clone())
                    ),
                    214,
                    10,
                );
            }
        };
        for c in &list {
            for n in &c.names {
                match &c.from {
                    None => add_composes(&class, "local", &local_name(n), None),
                    Some(None) => add_composes(&class, "global", n, None),
                    Some(Some(spec)) => add_composes(&class, "dependency", n, Some(spec.clone())),
                }
            }
        }
    }
}
