import subprocess, sys, json, re
sys.path.insert(0, '/tmp')
from bprobe import V, run
# returns per-browser list of (version, prefixes set) where prefixes are detected by regex on output
def scan(css, detect):
    out = {}
    for b, vs in V.items():
        segs = []
        prev = None
        for v in vs:
            r = run(css, f'{b} {v}')
            if r == 'ERR': continue
            s = detect(r)
            if s != prev:
                segs.append((v, s))
                prev = s
        out[b] = segs
    return out
def prefixes_in(prop):
    def d(r):
        s = set()
        for pre in ['webkit','moz','ms','o']:
            if re.search(r'(^|[;{])-' + pre + '-' + re.escape(prop) + ':', r): s.add(pre)
        return tuple(sorted(s))
    return d
def ranges(segs, vs, pre):
    # convert segments into list of (start, end_exclusive) where pre present
    res = []
    cur = None
    for v, s in segs:
        if pre in s and cur is None: cur = v
        if pre not in s and cur is not None:
            res.append((cur, v)); cur = None
    if cur is not None: res.append((cur, None))
    return res
if __name__ == '__main__':
    feats = json.loads(sys.argv[1])
    result = {}
    for name, css, prop in feats:
        sc = scan(css, prefixes_in(prop))
        entry = {}
        for b, segs in sc.items():
            for pre in ['webkit','moz','ms','o']:
                r = ranges(segs, V[b], pre)
                if r: entry.setdefault(pre, {})[b] = r
        result[name] = entry
        print(name, json.dumps(entry), flush=True)
