        }
    }
    Selector(out)
}

fn replace_in_list(l: &SelectorList, parent: &SelectorList) -> SelectorList {
    SelectorList(l.0.iter().map(|s| replace_in_selector(s, parent)).collect())
}

fn replace_in_simple(s: &Simple, parent: &SelectorList) -> Simple {
    match s {
        Simple::Not(l) => Simple::Not(replace_in_list(l, parent)),
        Simple::Is(l) => Simple::Is(replace_in_list(l, parent)),
        Simple::Where(l) => Simple::Where(replace_in_list(l, parent)),
        Simple::Has(l) => Simple::Has(replace_in_list(l, parent)),
        Simple::Any(p, l) => Simple::Any(p.clone(), replace_in_list(l, parent)),
        other => other.clone(),
    }
}
