use crate::prefixes::*;
use crate::properties::*;

pub fn target_list() -> Option<[Option<u32>; 9]> {
    let b = crate::targets::targets()?;
    Some([b.chrome, b.firefox, b.safari, b.ios_saf, b.edge, b.ie, b.opera, b.samsung, b.android])
}

pub fn feature_prefixes(feature: &str) -> u8 {
    let list = match target_list() {
        Some(l) => l,
        None => return 0,
    };
    let mut out = 0;
    for (pre, bi, s, e) in crate::prefix_data::ranges(feature) {
        if let Some(ver) = list[*bi] {
            if ver >= *s && ver < *e {
                out |= *pre;
            }
        }
    }
    out
}

