        "backface-visibility" => "backface-visibility",
        "animation" | "animation-name" | "animation-duration" | "animation-timing-function" | "animation-iteration-count"
        | "animation-direction" | "animation-play-state" | "animation-delay" | "animation-fill-mode" => "animation",
        "box-shadow" => "box-shadow",
        "border-radius" | "border-top-left-radius" | "border-top-right-radius" | "border-bottom-left-radius" | "border-bottom-right-radius" => "border-radius",
