// Color fallbacks for browser targets
use crate::color::{CssColor, Space};
use crate::properties::*;
use std::cell::RefCell;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Level {
    Rgb,
    P3,
    Lab,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Mode {
    None,
    Collect,
    Convert(Level),
    Final,
}

thread_local! {
    pub static MODE: RefCell<Mode> = RefCell::new(Mode::None);
    pub static COLLECTED: RefCell<Vec<CssColor>> = RefCell::new(Vec::new());
}

pub fn mode() -> Mode {
    MODE.with(|m| *m.borrow())
}

fn set_mode(m: Mode) -> Mode {
    MODE.with(|x| std::mem::replace(&mut *x.borrow_mut(), m))
}

/// Called from CssColor::to_css; returns a converted color if needed
pub fn transform_color(c: &CssColor) -> Option<CssColor> {
    match mode() {
        Mode::None => None,
        Mode::Collect => {
            COLLECTED.with(|v| v.borrow_mut().push(c.clone()));
            None
        }
        Mode::Convert(level) => match c {
            CssColor::Space(sp, _, _) => match level {
                Level::Rgb => Some(c.to_rgba()),
                Level::P3 => {
                    if *sp == Space::DisplayP3 {
                        None
                    } else {
                        Some(c.to_p3())
                    }
                }
                Level::Lab => match sp {
                    Space::Oklab | Space::Oklch => Some(c.to_lab()),
                    _ => None,
                },
            },
            _ => None,
        },
        Mode::Final => match c {
            CssColor::Space(Space::Oklab, ..) | CssColor::Space(Space::Oklch, ..) => {
                if !all_support(crate::targets::Feature::OklabColors) {
                    Some(c.to_lab())
                } else {
                    None
                }
            }
            _ => None,
        },
    }
}

fn browsers() -> Option<[Option<u32>; 9]> {
    crate::prefixer::target_list()
}

fn all_support(f: crate::targets::Feature) -> bool {
    crate::targets::supports(f)
}

fn p3_support(idx: usize, ver: u32) -> bool {
    use crate::targets::v;
    match idx {
        2 => ver >= v(10, 1, 0),
        3 => ver >= v(11, 0, 0),
        _ => false,
    }
}

fn lab_support(idx: usize, ver: u32) -> bool {
    crate::targets::browser_supports(crate::targets::Feature::LabColors, idx, ver)
}

/// Compute (fallback levels, needs_final_conversion) for a color
fn color_needs(c: &CssColor) -> Vec<Level> {
    let b = match browsers() {
        Some(b) => b,
        None => return vec![],
    };
    let (sp, is_lab_family) = match c {
        CssColor::Space(sp, ..) => (*sp, matches!(sp, Space::Lab | Space::Lch | Space::Oklab | Space::Oklch)),
        _ => return vec![],
    };
    let needs = match sp {
        Space::Lab | Space::Lch => !all_support(crate::targets::Feature::LabColors),
        Space::Oklab | Space::Oklch => !all_support(crate::targets::Feature::OklabColors) && !all_support(crate::targets::Feature::LabColors),
        Space::DisplayP3 => !all_p3(&b),
        _ => !all_support(crate::targets::Feature::ColorFunction),
    };
    if !needs {
        return vec![];
    }
    let mut out = Vec::new();
    if !all_p3(&b) {
        out.push(Level::Rgb);
    }
    if sp != Space::DisplayP3 {
        let mut p3_not_lab = false;
        let mut lab_not_p3 = false;
        for (i, v) in b.iter().enumerate() {
            if let Some(v) = v {
                let p3 = p3_support(i, *v);
                let lab = lab_support(i, *v);
                if p3 && !lab {
                    p3_not_lab = true;
                }
                if lab && !p3 {
                    lab_not_p3 = true;
                }
            }
        }
        if p3_not_lab && !lab_not_p3 {
            out.push(Level::P3);
        }
    }
    let _ = is_lab_family;
    out
}

fn all_p3(b: &[Option<u32>; 9]) -> bool {
    b.iter().enumerate().all(|(i, v)| match v {
        Some(v) => p3_support(i, *v),
        None => true,
    })
}

pub fn collect_colors(p: &Property) -> Vec<CssColor> {
    COLLECTED.with(|v| v.borrow_mut().clear());
    let prev = set_mode(Mode::Collect);
    let mut d = crate::printer::Printer::new(true);
    p.to_css(&mut d, false);
    set_mode(prev);
    COLLECTED.with(|v| std::mem::take(&mut *v.borrow_mut()))
}

/// Expand a property into fallbacks + final
pub fn expand(p: &Property) -> Vec<Property> {
    if browsers().is_none() {
        return vec![p.clone()];
    }
    match p {
        Property::Val(id, _) if id.name != "composes" => {}
        _ => return vec![p.clone()],
    }
    let colors = collect_colors(p);
    if colors.is_empty() {
        return vec![p.clone()];
    }
    let mut levels: Vec<Level> = Vec::new();
    let mut final_conv = false;
    for c in &colors {
        for l in color_needs(c) {
            if !levels.contains(&l) {
                levels.push(l);
            }
        }
        if let CssColor::Space(Space::Oklab, ..) | CssColor::Space(Space::Oklch, ..) = c {
            if !all_support(crate::targets::Feature::OklabColors) {
                final_conv = true;
            }
        }
    }
    let mut out = Vec::new();
    for l in [Level::Rgb, Level::P3] {
        if levels.contains(&l) {
            out.push(Property::Fallback(Box::new(p.clone()), l));
        }
    }
    if final_conv {
        out.push(Property::Final(Box::new(p.clone())));
    } else {
        out.push(p.clone());
    }
    out
}

pub fn needs_fallbacks(p: &Property) -> bool {
    expand(p).len() > 1
}

pub fn print_with_mode(p: &Property, m: Mode, d: &mut crate::printer::Printer, important: bool) {
    let prev = set_mode(m);
    p.to_css(d, important);
    set_mode(prev);
}

/// Add fallback declarations (e.g. for colors) to `out` before returning the main property.
pub fn with_fallbacks(p: &Property, _out: &mut Vec<Property>) -> Property {
    p.clone()
}

pub fn push_background_with_fallbacks(out: &mut Vec<Property>, layers: Vec<crate::background::Background>) {
    out.push(Property::Val(PropId::new("background", crate::prefixes::NONE), Value::Background(layers)));
}

pub fn push_color_prop(out: &mut Vec<Property>, name: &str, c: crate::color::CssColor) {
    out.push(Property::Val(PropId::new(crate::handler_list::lookup_static(name), crate::prefixes::NONE), Value::Color(c)));
}

pub fn push_bg_images(out: &mut Vec<Property>, imgs: Vec<crate::image::Image>) {
    out.push(Property::Val(
        PropId::new("background-image", crate::prefixes::NONE),
        Value::BgLayers(crate::background::BgLonghand::Image(imgs)),
    ));
}

/// Final pass: expand color fallbacks
pub fn apply(list: &mut Vec<Property>) {
    if browsers().is_none() {
        return;
    }
    let input = std::mem::take(list);
    for p in input {
        match &p {
            Property::NoFallback(inner) => {
                let e = expand(inner);
                list.push(e.last().unwrap().clone());
            }
            _ => list.extend(expand(&p)),
        }
    }
}
