// Selector compatibility and vendor-prefixed variants
use crate::prefixes::*;
use crate::rules::StyleRule;
use crate::selectors::*;

fn pseudo_feature(s: &Simple) -> Option<&'static str> {
    match s {
        Simple::PseudoElement(n) => match n.as_str() {
            "placeholder" => Some("sel-placeholder"),
            "selection" => Some("sel-selection"),
            "backdrop" => Some("sel-backdrop"),
            "file-selector-button" => Some("sel-file-selector-button"),
            _ => None,
        },
        Simple::PseudoClass(n) => match n.as_str() {
            "fullscreen" => Some("sel-fullscreen"),
            "any-link" => Some("sel-any-link"),
            "read-only" => Some("sel-read-only"),
            "read-write" => Some("sel-read-write"),
            "placeholder-shown" => Some("sel-placeholder-shown"),
            "autofill" => Some("sel-autofill"),
            _ => None,
        },
        Simple::Is(_) => Some("sel-is"),
        _ => None,
    }
}

fn prefixed_name(s: &Simple, pre: u8) -> Simple {
    match s {
        Simple::PseudoElement(n) => {
            let r = match (n.as_str(), pre) {
                ("placeholder", WEBKIT) => "-webkit-input-placeholder",
                ("placeholder", MOZ) => "-moz-placeholder",
                ("placeholder", MS) => "-ms-input-placeholder",
                ("selection", MOZ) => "-moz-selection",
                ("backdrop", WEBKIT) => "-webkit-backdrop",
                ("backdrop", MS) => "-ms-backdrop",
                ("file-selector-button", WEBKIT) => "-webkit-file-upload-button",
                ("file-selector-button", MS) => "-ms-browse",
                _ => return s.clone(),
            };
            Simple::PseudoElement(r.to_string())
        }
        Simple::PseudoClass(n) => {
            let r = match (n.as_str(), pre) {
                ("fullscreen", WEBKIT) => "-webkit-full-screen",
                ("fullscreen", MOZ) => "-moz-full-screen",
                ("fullscreen", MS) => "-ms-fullscreen",
                ("any-link", WEBKIT) => "-webkit-any-link",
                ("any-link", MOZ) => "-moz-any-link",
                ("read-only", MOZ) => "-moz-read-only",
                ("read-write", MOZ) => "-moz-read-write",
                ("placeholder-shown", MOZ) => "-moz-placeholder-shown",
                ("placeholder-shown", MS) => "-ms-placeholder-shown",
                ("autofill", WEBKIT) => "-webkit-autofill",
                _ => return s.clone(),
            };
            Simple::PseudoClass(r.to_string())
        }
        Simple::Is(l) => {
            let l2 = SelectorList(l.0.iter().map(|x| prefix_selector(x, pre)).collect());
            match pre {
                WEBKIT => Simple::Any("-webkit-".into(), l2),
                MOZ => Simple::Any("-moz-".into(), l2),
                _ => Simple::Is(l2),
            }
        }
        Simple::Not(l) => Simple::Not(SelectorList(l.0.iter().map(|x| prefix_selector(x, pre)).collect())),
        Simple::Where(l) => Simple::Where(SelectorList(l.0.iter().map(|x| prefix_selector(x, pre)).collect())),
        Simple::Has(l) => Simple::Has(SelectorList(l.0.iter().map(|x| prefix_selector(x, pre)).collect())),
        other => other.clone(),
    }
}

fn prefix_selector(s: &Selector, pre: u8) -> Selector {
    Selector(
        s.0.iter()
