        }
    };
    let src: &'static str = Box::leak(src.into_boxed_str());
    let toks: &'static [crate::tokenizer::Tok] = Box::leak(crate::tokenizer::tokenize(src).into_boxed_slice());
    let mut p = crate::parser::Parser::new(toks, src);
    let rules = match parse_stylesheet(&mut p) {
        Ok(r) => r,
        Err(e) => crate::errors_panic::panic_debug(
            &format!(
                "Error {{ kind: {}, loc: Some(ErrorLocation {{ filename: {:?}, line: {}, column: {} }}) }}",
                crate::errors::kind_debug(&e.kind),
                path.to_string_lossy(),
                e.line,
                e.col
            ),
            180,
            46,
        ),
    };
    expand(path, rules, seen)
}

fn expand(path: &Path, rules: Vec<CssRule>, seen: &mut Vec<PathBuf>) -> Vec<CssRule> {
    let dir = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    let mut out = Vec::new();
    for r in rules {
        match r {
            CssRule::Import(imp) if !imp.url.contains("://") && !imp.url.starts_with("data:") => {
                let target = dir.join(&imp.url);
                let canon = std::fs::canonicalize(&target).unwrap_or(target.clone());
                if seen.contains(&canon) {
                    continue;
                }
                seen.push(canon);
                let mut inner = load(&target, seen);
                if let Some(layer) = &imp.layer {
                    inner = vec![CssRule::LayerBlock(layer.clone(), inner, imp.loc.clone())];
                }
                if !imp.media.0.is_empty() {
                    inner = vec![CssRule::Media(imp.media.clone(), inner, imp.loc.clone())];
                }
                if let Some(s) = &imp.supports {
                    inner = vec![CssRule::Supports(s.clone(), inner, imp.loc.clone())];
                }
                out.extend(inner);
            }
            other => out.push(other),
        }
    }
    out
}

pub fn bundle(fname: &str, rules: Vec<CssRule>) -> Vec<CssRule> {
    let path = Path::new(fname);
    let mut seen = vec![std::fs::canonicalize(path).unwrap_or(path.to_path_buf())];
    expand(path, rules, &mut seen)
}
