pub struct PositionHandler {
    cur: Option<Property>,
    webkit_sticky: bool,
}

impl crate::handlers::Handler for PositionHandler {
    fn handle(&mut self, p: &Property, out: &mut Vec<Property>, _imp: bool) -> bool {
        if !p.name_is("position") {
            return false;
        }
        match p {
            Property::Val(_, Value::Ident(k)) => {
                if k == "-webkit-sticky" {
                    self.webkit_sticky = true;
                    self.cur = Some(p.clone());
                    return true;
                }
                if k == "sticky" && self.webkit_sticky && crate::targets::targets().is_none() {
                    if let Some(c) = self.cur.take() {
                        out.push(c);
                    }
                }
                self.webkit_sticky = false;
                self.cur = Some(p.clone());
            }
            _ => {
                if let Some(c) = self.cur.take() {
                    out.push(c);
                }
                out.push(p.clone());
            }
        }
        true
    }
    fn finalize(&mut self, out: &mut Vec<Property>, _imp: bool) {
        if let Some(c) = self.cur.take() {
            out.push(c);
        }
    }
}''')
